async function withDeadline<T>(
  promise: Promise<T>,
  timeoutMs: number,
  fallback: T,
  label: string
): Promise<T> {
  if (timeoutMs <= 0) return fallback;

  let timer: ReturnType<typeof setTimeout> | null = null;

  try {
    return await Promise.race([
      promise,
      new Promise<T>((resolve) => {
        timer = setTimeout(() => {
          console.log(
            "[AIShopping] V34.CORE120 deadline reached:",
            label,
            timeoutMs
          );
          resolve(fallback);
        }, timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function withAbortableDeadline<T>(
  operation: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  fallback: T,
  label: string
): Promise<T> {
  if (timeoutMs <= 0) return fallback;

  const controller = new AbortController();
  let timer: ReturnType<typeof setTimeout> | null = null;

  const operationPromise = operation(controller.signal).catch((error) => {
    if (controller.signal.aborted) return fallback;
    throw error;
  });

  try {
    return await Promise.race([
      operationPromise,
      new Promise<T>((resolve) => {
        timer = setTimeout(() => {
          controller.abort();
          console.log(
            "[AIShopping] V34.CORE120 abortable deadline reached:",
            label,
            timeoutMs
          );
          resolve(fallback);
        }, timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
    // Also abort after a successful outer operation. Inner branches may have
    // already returned a fallback from withDeadline while their fetch is still
    // running. Closing the shared signal guarantees that no discovery or
    // verification request survives the phase that owned it.
    if (!controller.signal.aborted) controller.abort();
  }
}

async function withAbortableDeadlineSnapshot<T>(
  operation: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  fallbackFactory: () => T,
  label: string
): Promise<T> {
  if (timeoutMs <= 0) return fallbackFactory();

  const controller = new AbortController();
  let timer: ReturnType<typeof setTimeout> | null = null;

  const operationPromise = operation(controller.signal).catch((error) => {
    if (controller.signal.aborted) return fallbackFactory();
    throw error;
  });

  try {
    return await Promise.race([
      operationPromise,
      new Promise<T>((resolve) => {
        timer = setTimeout(() => {
          controller.abort();
          console.log(
            "[AIShopping] V34.CORE120 abortable snapshot deadline reached:",
            label,
            timeoutMs
          );
          resolve(fallbackFactory());
        }, timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
    if (!controller.signal.aborted) controller.abort();
  }
}

