function parseJinaSearchMarkdown(markdown: string): SearchResult[] {
  const results: SearchResult[] = [];
  const seen = new Set<string>();

  // Standard search-engine/Jina links.
  const linkRe = /\[([^\]]{3,240})\]\((https?:\/\/[^)\s]+)\)/gi;
  let match: RegExpExecArray | null;

  while ((match = linkRe.exec(markdown)) !== null) {
    const name = cleanTitle(decodeHtml(match[1]));
    const url = unwrapSearchEngineUrl(match[2]);

    if (!url || !name || !isProbablyRealOfferUrl(url)) continue;

    const host = (() => {
      try {
        return new URL(url).hostname.toLowerCase();
      } catch {
        return "";
      }
    })();

    if (
      host.includes("google.") ||
      host.includes("gstatic.") ||
      host.includes("googleusercontent.") ||
      host.includes("accounts.google.") ||
      host.includes("support.google.")
    ) {
      continue;
    }

    const key = normalizeUrl(url);
    if (!key || seen.has(key)) continue;

    const context = markdown.slice(
      Math.max(0, match.index - 300),
      Math.min(markdown.length, match.index + match[0].length + 1200)
    );

    const snippet = normalizeText(
      context
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/[#*_`]/g, " ")
    ).slice(0, 1200);

    seen.add(key);

    results.push({
      url: key,
      name,
      snippet,
      source: "JinaGoogle",
      searchRank: results.length,
    });

    if (results.length >= MAX_SEARCH_RESULTS_PER_ENGINE) break;
  }

  return results;
}


function titleFromMarketplaceUrl(url: string): string {
  try {
    const parsed = new URL(url);
    const host = parsed.hostname.replace(/^www\./, "").toLowerCase();
    const path = decodeURIComponent(parsed.pathname);

    if (host === "olx.pl") {
      const slug =
        path.match(/\/d\/(?:oferta|ogloszenie)\/([^/]+)/i)?.[1] ?? "";

      if (slug) {
        return cleanTitle(
          slug
            .replace(/-CID\d+-ID[^/.]+(?:\.html)?$/i, "")
            .replace(/\.html$/i, "")
            .replace(/-/g, " ")
        );
      }
    }

    if (host === "allegro.pl") {
      const slug =
        path.match(/\/(?:oferta|produkt)\/([^/]+)/i)?.[1] ?? "";

      if (slug) {
        return cleanTitle(
          slug
            .replace(/-\d+$/g, "")
            .replace(/-/g, " ")
        );
      }
    }

    if (host === "allegrolokalnie.pl") {
      const slug =
        path.match(/\/oferta\/([^/]+)/i)?.[1] ?? "";

      if (slug) {
        return cleanTitle(
          slug.replace(/-/g, " ")
        );
      }
    }

    return "";
  } catch {
    return "";
  }
}


function cleanDirectMarketplaceResultName(
  nameRaw: string,
  url: string
): string {
  let name = normalizeText(nameRaw);

  const cutMarkers = [
    " Producent:",
    " Marka:",
    " Kod producenta:",
    " Komunikacja bezprzewodowa:",
    " Wibracje:",
    " Kup teraz",
    " Sprzedający:",
    " Często sprzedaje",
  ];

  let cutAt = name.length;

  for (const marker of cutMarkers) {
    const index = name.indexOf(marker);
    if (index >= 0 && index < cutAt) {
      cutAt = index;
    }
  }

  // V34.CORE125: Allegro Lokalnie occasionally flattens the entire structured
  // attribute block into one <a> label. Keep those facts in the bounded card
  // snippet, where HARD verification can use them, but stop the user-facing
  // result name at the first unambiguous marketplace field label. Without this
  // boundary a name could end with a certification field and an unrelated
  // display amount even though the same card separately exposes the payable `Kup teraz`
  // amount. This is presentation/identity cleanup only; price selection still
  // runs against the original URL-bounded card.
  const structuredFieldBoundary = name.search(
    /\s(?:opcje\s+sim|model\s+telefonu|waga\s+produktu(?:\s+z\s+opakowaniem\s+jednostkowym)?|certyfikaty\s+zgodno(?:ś|s)ci|kod\s+producenta|numer\s+katalogowy|marka|typ)\s*:/iu
  );

  if (structuredFieldBoundary >= 0 && structuredFieldBoundary < cutAt) {
    cutAt = structuredFieldBoundary;
  }

  name = cleanTitle(name.slice(0, cutAt));

  if (name.length >= 5) {
    return name;
  }

  return titleFromMarketplaceUrl(url);
}

function normalizeMatchText(value: string): string {
  return normalizeText(value)
    .toLowerCase()
    .replace(/ł/g, "l")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}


type IphoneVariant = "pro-max" | "pro" | "plus" | "base" | null;

type IphoneSpec = {
  generation: string | null;
  variant: IphoneVariant;
  storageGb: number | null;
};

function extractIphoneSpec(valueRaw: string): IphoneSpec | null {
  const text = normalizeMatchText(valueRaw);

  if (!text.includes("iphone")) return null;

  const generationMatch = text.match(/\biphone\s*-?\s*(\d{1,2})\b/i);
  const generation = generationMatch?.[1] ?? null;

  let variant: IphoneVariant = null;

  if (/\bpro\s*max\b/i.test(text)) {
    variant = "pro-max";
  } else if (/\bpro\b/i.test(text)) {
    variant = "pro";
  } else if (/\bplus\b/i.test(text)) {
    variant = "plus";
  } else if (generation) {
    variant = "base";
  }

  let storageGb: number | null = null;

  const gbMatch = text.match(/\b(64|128|256|512)\s*g(?:b)?\b/i);
  if (gbMatch) {
    storageGb = Number(gbMatch[1]);
  } else {
    const tbMatch = text.match(/\b(1|2)\s*tb\b/i);
    if (tbMatch) {
      storageGb = Number(tbMatch[1]) * 1024;
    }
  }

  return {
    generation,
    variant,
    storageGb,
  };
}

type GenericPhoneSiblingVariant =
  | "ultra"
  | "plus"
  | "fe"
  | "pro-max"
  | "pro"
  | "max"
  | "mini"
  | "base";

function getGenericRequestedPhoneModelToken(parsed: ParsedQuery): string | null {
  if (parsed.category !== "phone") return null;

  const unitLike = /^(?:\d+(?:[.,]\d+)?(?:gb|tb|mah|ah|hz|w|v)|\d+g)$/i;
  const candidates = parsed.intent.strongIdentityTerms
    .map((term) => compactUniversalModelCode(term))
    .filter(Boolean)
    .filter((term) => !unitLike.test(term))
    .filter((term) => /[a-z]/i.test(term) && /\d/.test(term))
    .filter((term) => term.length >= 3)
    .sort((a, b) => b.length - a.length);

  // iPhone has its own richer generation/variant parser below. Keeping it
  // separate avoids changing already-tested iPhone behavior.
  return candidates.find((term) => !/^iphone\d+/i.test(term)) ?? null;
}

type GenericPhoneSiblingVariantMention = {
  variant: GenericPhoneSiblingVariant;
  index: number;
};

function genericPhoneSiblingVariantFromSuffix(
  suffixRaw: string
): GenericPhoneSiblingVariant {
  const rawSuffix = normalizeText(suffixRaw ?? "").toLowerCase();
  if (!rawSuffix) return "base";
  if (rawSuffix === "+" || rawSuffix === "plus") return "plus";
  if (/^pro(?:\s|[-_./])*max$/i.test(rawSuffix)) return "pro-max";
  if (rawSuffix === "ultra") return "ultra";
  if (rawSuffix === "fe") return "fe";
  if (rawSuffix === "pro") return "pro";
  if (rawSuffix === "max") return "max";
  if (rawSuffix === "mini") return "mini";
  return "base";
}

function extractGenericPhoneSiblingVariantMentions(
  valueRaw: string,
  modelTokenRaw: string
): GenericPhoneSiblingVariantMention[] {
  const text = normalizeMatchText(valueRaw);
  const modelToken = compactUniversalModelCode(modelTokenRaw);
  if (!modelToken) return [];

  const escaped = escapeRegExp(modelToken);
  const modelPattern = new RegExp(
    `(?:^|[^a-z0-9])(${escaped})(?:(?:\\s|[-_./]){0,3}(\\+|ultra|plus|fe|pro(?:\\s|[-_./]){0,3}max|pro|max|mini))?(?=$|[^a-z0-9])`,
    "gi"
  );

  const mentions: GenericPhoneSiblingVariantMention[] = [];
  for (const match of text.matchAll(modelPattern)) {
    const full = match[0] ?? "";
    const token = match[1] ?? "";
    const tokenOffset = Math.max(0, full.toLowerCase().indexOf(token.toLowerCase()));
    mentions.push({
      variant: genericPhoneSiblingVariantFromSuffix(match[2] ?? ""),
      index: (match.index ?? 0) + tokenOffset,
    });
  }

  return mentions;
}

function extractGenericPhoneSiblingVariant(
  valueRaw: string,
  modelTokenRaw: string
): GenericPhoneSiblingVariant | null {
  // Keep the legacy first-occurrence semantics for ordinary title/URL checks.
  // CORE96 additionally exposes all bounded mentions so exact manufacturer-code
  // references can avoid misreading flattened family tables.
  return extractGenericPhoneSiblingVariantMentions(valueRaw, modelTokenRaw)[0]?.variant ?? null;
}

function hasGenericPhoneSiblingVariantMismatch(
  titleRaw: string,
  contentRaw: string,
  urlRaw: string,
  parsed: ParsedQuery
): boolean {
  if (parsed.category !== "phone") return false;

  const modelToken = getGenericRequestedPhoneModelToken(parsed);
  if (!modelToken) return false;

  let decodedUrl = urlRaw;
  try {
    decodedUrl = decodeURIComponent(urlRaw);
  } catch {
    // Keep malformed URL text as-is.
  }

  const requestedVariant = extractGenericPhoneSiblingVariant(
    parsed.queryText,
    modelToken
  );
  let candidateVariant = extractGenericPhoneSiblingVariant(
    `${titleRaw} ${decodedUrl}`,
    modelToken
  );

  // CORE93: some retailer headings collapse a sibling name ("Family X")
  // while the product description directly underneath correctly says
  // "Family X+ / Plus / Ultra / Pro / Max". Read only an early bounded
  // product-content slice and require the exact requested family token with
  // the adjacent suffix; this avoids recommendation-tail contamination.
  const boundedContent = normalizeText(contentRaw).slice(0, 18_000);
  const contentVariant = extractGenericPhoneSiblingVariant(boundedContent, modelToken);
  if (contentVariant && contentVariant !== "base") {
    candidateVariant = contentVariant;
  }

  if (!requestedVariant || !candidateVariant) return false;
  return requestedVariant !== candidateVariant;
}

function extractGenericPhoneManufacturerCodeTokens(
  valueRaw: string,
  parsed: ParsedQuery
): string[] {
  if (parsed.category !== "phone") return [];

  const raw = String(valueRaw ?? "");
  const requestedModel = compactUniversalModelCode(
    getGenericRequestedPhoneModelToken(parsed) ?? ""
  );
  const candidates: string[] = [];

  const add = (value: string) => {
    const cleaned = value
      .toUpperCase()
      .replace(/^[^A-Z0-9]+|[^A-Z0-9-]+$/g, "")
      .trim();
    const compact = compactUniversalModelCode(cleaned);
    if (!cleaned || compact.length < 4 || compact === requestedModel) return;
    if ((compact.match(/\d/g) ?? []).length < 3) return;
    if (/^(?:\d+(?:GB|TB|MAH|W|HZ)|\d+G|5G|4G|3G)$/i.test(compact)) return;
    if (/^(?:19|20)\d{2}$/.test(compact)) return;
    candidates.push(cleaned);
  };

  // Parenthesised and labelled identifiers are much stronger than arbitrary
  // numbers in a phone title. Keep the fallback token grammar bounded and
  // require a real alpha+numeric manufacturer-code shape.
  for (const match of raw.matchAll(/\(([^()]{3,24})\)/g)) add(match[1]);
  for (const match of raw.matchAll(
    /\b(?:model|model\s+number|kod\s+modelu|symbol|mpn|part\s+number)\s*[:#-]?\s*([a-z]{0,5}[- ]?[a-z]{1,5}[- ]?\d{3,7}[a-z0-9-]{0,5})\b/giu
  )) add(match[1]);
  for (const match of raw.matchAll(
    /\b([a-z]{0,4}-?[a-z]{1,4}-?\d{3,6}[a-z0-9-]{0,4})\b/giu
  )) add(match[1]);

  return Array.from(new Set(candidates)).slice(0, 3);
}

function referenceResultPhoneSiblingVariantForCode(
  result: SearchResult,
  parsed: ParsedQuery,
  modelToken: string,
  codeRaw: string
): GenericPhoneSiblingVariant | null {
  let evidence = normalizeText(`${result.name} ${result.snippet} ${result.url}`);
  if (!evidence) return null;

  try {
    evidence = decodeURIComponent(evidence);
  } catch {
    // Keep the raw evidence.
  }

  const code = compactUniversalModelCode(codeRaw);
  if (!code || !compactUniversalModelCode(evidence).includes(code)) return null;

  const brand = normalizeMatchText(parsed.brand ?? "");
  if (brand && !universalEvidenceHasBoundedIdentityTerm(brand, normalizeMatchText(evidence))) {
    return null;
  }

  // CORE96: search-engine snippets can flatten product-family tables such as
  // "X20, X20+, X20 Ultra — AB731, AB742, AB758". Taking the first family
  // occurrence would incorrectly label every code as the base model. Resolve
  // only when the exact code is locally associated with one unambiguous model
  // variant, or when the entire bounded field contains only one variant.
  const fields = [result.url, result.name, result.snippet]
    .map((value) => {
      let field = normalizeText(value);
      try {
        field = decodeURIComponent(field);
      } catch {
        // Keep raw field text.
      }
      return field;
    })
    .filter(Boolean);

  const codeNeedle = normalizeMatchText(codeRaw);
  for (const field of fields) {
    const normalizedField = normalizeMatchText(field);
    const codeIndex = normalizedField.indexOf(codeNeedle.toLowerCase());
    if (codeIndex < 0) continue;

    const mentions = extractGenericPhoneSiblingVariantMentions(field, modelToken);
    if (mentions.length === 0) continue;

    const localMentions = mentions.filter((mention) =>
      Math.abs(mention.index - codeIndex) <= 96
    );
    const localVariants = Array.from(new Set(localMentions.map((mention) => mention.variant)));
    if (localVariants.length === 1) return localVariants[0];
    if (localVariants.length > 1) continue;

    const allVariants = Array.from(new Set(mentions.map((mention) => mention.variant)));
    if (allVariants.length === 1) return allVariants[0];
  }

  return null;
}

function buildGenericPhoneManufacturerCodeSiblingReferenceQueries(
  codeRaw: string,
  parsed: ParsedQuery,
  modelTokenRaw: string
): string[] {
  const code = normalizeText(codeRaw);
  const brand = normalizeText(parsed.brand ?? "");
  const modelToken = normalizeText(modelTokenRaw);
  if (!code || !brand || !modelToken) return [];

  const queries = [
    normalizeText(`"${code}" ${brand} ${modelToken}`),
    // CORE93: seller labels can misname a sibling while the manufacturer code
    // itself is correct. A broader exact-code + brand query is therefore run in
    // parallel with the model-constrained query so authoritative references are
    // not hidden by the seller's incorrect family label.
    normalizeText(`"${code}" ${brand}`),
    normalizeText(`"${code}" ${brand} plus ultra fe pro max mini`),
  ];

  // When the parsed brand safely resembles a normal web-domain label, add one
  // bounded official-domain-shaped lookup. The result is NOT trusted merely
  // because this query was used: acceptance below still calls
  // isOfficialBrandHostForParsed() on the returned URL. Brands whose official
  // domain does not follow brand.com simply fall back to the two generic lanes.
  const brandDomainLabel = compactUniversalModelCode(brand);
  if (/^[a-z][a-z0-9-]{2,30}$/i.test(brandDomainLabel)) {
    queries.push(
      normalizeText(`site:${brandDomainLabel}.com "${code}"`)
    );
  }

  return Array.from(new Set(queries.filter(Boolean))).slice(0, 4);
}

async function hasGenericPhoneManufacturerCodeSiblingConflict(
  titleRaw: string,
  contentRaw: string,
  parsed: ParsedQuery,
  externalSignal?: AbortSignal
): Promise<boolean> {
  if (parsed.category !== "phone" || externalSignal?.aborted) return false;

  const modelToken = getGenericRequestedPhoneModelToken(parsed);
  if (!modelToken) return false;
  const requestedVariant = extractGenericPhoneSiblingVariant(parsed.queryText, modelToken);
  if (!requestedVariant) return false;

  const bounded = `${titleRaw} ${normalizeText(contentRaw).slice(0, 6_000)}`;
  const codes = extractGenericPhoneManufacturerCodeTokens(bounded, parsed);
  if (codes.length === 0) return false;

  let anyPositiveResolution = false;

  for (const code of codes.slice(0, 2)) {
    if (externalSignal?.aborted) return true;
    const queries = buildGenericPhoneManufacturerCodeSiblingReferenceQueries(
      code,
      parsed,
      modelToken
    );
    if (queries.length === 0) continue;

    const references = await withAbortableDeadline(
      async (signal) => {
        const combined = externalSignal
          ? AbortSignal.any([externalSignal, signal])
          : signal;

        const chunks = await Promise.all(
          queries.flatMap((query) => [
            searchBingRssReference(query, combined),
            searchBingReference(query, combined),
          ])
        );
        return dedupeSearchResultsByUrl(chunks.flat()).slice(0, 36);
      },
      1_250,
      [] as SearchResult[],
      `phone manufacturer-code sibling reference: ${code}`
    );

    const byVariant = new Map<GenericPhoneSiblingVariant, Set<string>>();
    let officialConflict = false;
    let officialMatch = false;

    for (const result of references) {
      const variant = referenceResultPhoneSiblingVariantForCode(
        result,
        parsed,
        modelToken,
        code
      );
      if (!variant) continue;

      const host = getResultHostname(result.url) || "unknown";
      if (!byVariant.has(variant)) byVariant.set(variant, new Set());
      byVariant.get(variant)!.add(host);

      if (isOfficialBrandHostForParsed(host, parsed)) {
        if (variant === requestedVariant) officialMatch = true;
        else officialConflict = true;
      }
    }

    const conflictingVariants = Array.from(byVariant.entries())
      .filter(([variant, hosts]) => variant !== requestedVariant && hosts.size >= 2)
      .map(([variant]) => variant);
    const matchingHosts = byVariant.get(requestedVariant)?.size ?? 0;

    if (officialConflict || conflictingVariants.length > 0) {
      console.log("[AIShopping] V34.CORE120 phone manufacturer-code sibling conflict:", {
        code,
        requestedVariant,
        conflictingVariants,
        referenceCount: references.length,
        queryCount: queries.length,
      });
      return true;
    }

    if (officialMatch || matchingHosts >= 2) {
      anyPositiveResolution = true;
      console.log("[AIShopping] V34.CORE120 phone manufacturer-code exact-model proof:", {
        code,
        requestedVariant,
        officialMatch,
        matchingHosts,
        referenceCount: references.length,
      });
    }
  }

  if (anyPositiveResolution) return false;

  // CORE96 safety rule: an explicit manufacturer code on a strict phone-model
  // listing is stronger than the seller's human-readable family label. If no
  // authoritative/independent evidence can bind that code to the requested
  // variant, do not let the code fail open. This may reduce recall when search
  // references are unavailable, but it prevents a mislabeled sibling SKU from
  // being served as an exact phone model.
  console.log("[AIShopping] V34.CORE120 phone manufacturer-code unresolved:", {
    codes: codes.slice(0, 2),
    requestedVariant,
  });
  return true;
}

function isPhoneAccessoryOrWrongVariant(
  titleRaw: string,
  contentRaw: string,
  urlRaw: string,
  parsed: ParsedQuery
): boolean {
  if (parsed.category !== "phone" || parsed.intent.accessoryIntent) return false;

  const title = normalizeMatchText(titleRaw);

  let decodedUrl = urlRaw;
  try {
    decodedUrl = decodeURIComponent(urlRaw);
  } catch {
    // Keep the original URL when it contains malformed escape sequences.
  }

  const url = normalizeMatchText(decodedUrl);
  const titleAndUrl = `${title} ${url}`;

  // V32.12: phone searches must return the phone itself, not a spare part or
  // accessory that merely contains the requested model name.
  const strongAccessorySignals = [
    "ekran do iphone",
    "wyswietlacz do iphone",
    "display do iphone",
    "lcd do iphone",
    "digitizer",
    "szybka do iphone",
    "szklo hartowane",
    "szklo ochronne",
    "folia ochronna",
    "aparat tylny iphone",
    "aparat tylny do iphone",
    "kamera tylna do iphone",
    "korpus obudowa",
    "korpus do iphone",
    "obudowa do iphone",
    "tylna klapka",
    "plecki do iphone",
    "back glass",
    "bateria do iphone",
    "akumulator do iphone",
    "ladowarka do iphone",
    "kabel do iphone",
    "uchwyt do iphone",
    "etui do iphone",
    "case for iphone",
    "flex do iphone",
    "tasma do iphone",
    "plyta glowna iphone",
    "motherboard iphone",
    "glosnik do iphone",
    "mikrofon do iphone",
    "port ladowania",
    "zlacze ladowania",
  ];

  if (strongAccessorySignals.some((signal) => titleAndUrl.includes(signal))) {
    return true;
  }

  // Strong accessory nouns at the beginning of a listing are also enough to
  // reject it. This catches e.g. "ORYGINALNY Ekran do iPhone 14 Pro".
  if (
    /^(?:oryginalny\s+|original\s+)?(?:ekran|wyswietlacz|display|lcd|digitizer|korpus|obudowa|aparat tylny|kamera tylna|etui|szklo|folia|bateria|akumulator|ladowarka|kabel|uchwyt|plyta glowna)\b/i.test(title)
  ) {
    return true;
  }

  // V32.12: exact non-iPhone phone families also need sibling protection.
  // A request for a base generation must not silently accept an explicit
  // Plus/Ultra/FE/Pro/Max/Mini listing just because the shared model token is
  // present. The comparison is title/URL-bound and does not use page
  // recommendations.
  if (hasGenericPhoneSiblingVariantMismatch(titleRaw, contentRaw, urlRaw, parsed)) {
    return true;
  }

  const requested = extractIphoneSpec(parsed.queryText);
  if (!requested || !requested.generation) return false;

  // For exact iPhone-family queries, compare against the concrete listing
  // title/URL. We intentionally do not use the whole page body here because
  // shop pages often mention other iPhone generations in recommendations.
  const candidate = extractIphoneSpec(`${titleRaw} ${decodedUrl}`);
  if (!candidate || !candidate.generation) return false;

  if (candidate.generation !== requested.generation) {
    return true;
  }

  if (
    requested.variant &&
    candidate.variant &&
    candidate.variant !== requested.variant
  ) {
    return true;
  }

  // If the requested storage is explicit and the listing itself explicitly
  // states a different storage, reject it. If the listing omits storage, keep
  // it for verification instead of guessing.
  if (
    requested.storageGb !== null &&
    candidate.storageGb !== null &&
    candidate.storageGb !== requested.storageGb
  ) {
    return true;
  }

  return false;
}


function stripExplicitUnusedConditionPhrases(textRaw: string): string {
  return normalizeMatchText(textRaw)
    .replace(
      /\b(?:nigdy\s+)?nie\s*uzywan(?:y|a|e|ym|ych)?\b/giu,
      " "
    )
    .replace(
      /\bnieuzywan(?:y|a|e|ym|ych)?\b/giu,
      " "
    );
}

function hasClearUsedProductSignals(
  titleRaw: string,
  contentRaw: string
): boolean {
  // V34.CORE120: Polish "nie używane / nieużywane" is explicit absence of
  // prior use. Remove that negated phrase before looking for the positive
  // token "używane", otherwise a genuinely unused listing is classified as
  // used merely because the substring remains present.
  const title = stripExplicitUnusedConditionPhrases(titleRaw);
  const content = stripExplicitUnusedConditionPhrases(contentRaw);

  const directTitleSignals = [
    "uzywany",
    "uzywana",
    "uzywane",
    "malo uzywany",
    "malo uzywana",
    "jak nowy",
    "jak nowa",
    "stan bdb",
    "stan bardzo dobry",
    "bardzo dobry stan",
    "slady uzytkowania",
    "sladow uzytkowania",
    "pierwszy wlasciciel",
    "jedyny wlasciciel",
    "kondycja baterii",
    "kondycji baterii",
    "% kondycji",
    "refurbished",
    "odnowiony",
    "odnowiona",
    "po zwrocie",
    "po ekspozycji",
    "powystawowy",
    "powystawowa",
    "powystawowe",
    "ekspozycyjny",
    "ekspozycyjna",
    "ekspozycyjne",
    "ex-display",
    "display model",
    "demo unit",
    "demo model",
    "outlet",
  ];

  if (
    directTitleSignals.some((signal) =>
      universalScopeHasBoundedNegativeTerm(title, signal)
    )
  ) {
    return true;
  }

  // Rich retailer pages contain global navigation such as "Outlet", reviews
  // and recommendation cards. Those words do not describe the concrete item.
  // Outside the title, accept only explicit condition phrases or unmistakable
  // listing-specific evidence.
  // V32.12: remove explicit *absence* of wear before testing used-product
  // evidence. "brak śladów użytkowania" and "bez śladów użytkowania"
  // describe a new/unused-looking item and must not trigger the positive
  // "ślady użytkowania" detector below.
  const usedEvidenceContent = content
    .replace(
      /\b(?:brak|bez|zero)\s+(?:jakichkolwiek\s+)?(?:sladow|slady|oznak)\s+uzytkowania\b/giu,
      " "
    )
    .replace(
      /\b(?:nie\s+ma|nie\s+posiada|nie\s+widac)\s+(?:zadnych\s+|jakichkolwiek\s+)?(?:sladow|slady|oznak)\s+uzytkowania\b/giu,
      " "
    );

  const contextualUsedPatterns = [
    /\b(?:stan|condition|kondycja|status)\s*(?::|-)?\s*(?:produktu\s*)?(?:uzywany|uzywana|uzywane|used|refurbished|odnowiony|odnowiona|outlet|powystawowy|powystawowa|powystawowe|ekspozycyjny|ekspozycyjna|ekspozycyjne|ex[-\s]?display)\b/iu,
    /\b(?:produkt|przedmiot|towar|urzadzenie)\s+(?:jest\s+)?(?:uzywany|uzywana|uzywane|used|refurbished|odnowiony|odnowiona|po\s+zwrocie|po\s+ekspozycji|powystawowy|powystawowa|powystawowe|ekspozycyjny|ekspozycyjna|ekspozycyjne|ex[-\s]?display|display\s+model|demo\s+(?:unit|model))\b/iu,
    /\b(?:malo\s+uzywany|malo\s+uzywana|jak\s+nowy|jak\s+nowa|stan\s+bdb|stan\s+bardzo\s+dobry|bardzo\s+dobry\s+stan)\b/iu,
    /\b(?:slady|sladow)\s+uzytkowania\b/iu,
    /\b(?:pierwszy|jedyny)\s+wlasciciel\b/iu,
    /\b(?:kondycja|kondycji)\s+baterii\b/iu,
    /\b\d{1,3}\s*%\s+kondycji\b/iu,
  ];

  return contextualUsedPatterns.some((pattern) => pattern.test(usedEvidenceContent));
}

function hasExplicitRequestedConditionInTitle(
  titleRaw: string,
  condition: Condition
): boolean {
  if (!condition) return false;

  const title = normalizeMatchText(titleRaw);
  const explicitUnused =
    /\b(?:nigdy\s+)?nie\s*uzywan(?:y|a|e|ym|ych)?\b/iu.test(title) ||
    /\bnieuzywan(?:y|a|e|ym|ych)?\b/iu.test(title);

  if (condition === "new") {
    return (
      explicitUnused ||
      (
        /\b(?:fabrycznie\s+)?(?:nowy|nowa|nowe|new|brand\s+new|sealed)\b/iu.test(title) &&
        !/\bjak\s+(?:nowy|nowa|nowe)\b/iu.test(title)
      )
    );
  }

  if (explicitUnused) return false;

  const usedTitle = stripExplicitUnusedConditionPhrases(title);
  return (
    /\b(?:uzywany|uzywana|uzywane|malo\s+uzywany|malo\s+uzywana|used|preowned|pre-owned|refurbished|odnowiony|odnowiona)\b/iu.test(usedTitle) ||
    /\b(?:jak\s+now\w*|stan\s+bdb|stan\s+bardzo\s+dobry|bardzo\s+dobry\s+stan)\b/iu.test(usedTitle) ||
    /\b\d{1,2}\s*(?:rok|roku|lata|lat|miesiac|miesiace|miesiecy)\s+uzywan\w*\b/iu.test(usedTitle)
  );
}

function isControllerAccessoryOrWrongProduct(
  titleRaw: string,
  urlRaw: string
): boolean {
  const title = normalizeMatchText(titleRaw);
  const url = normalizeMatchText(urlRaw);

  // This legacy guard is intentionally CONTROLLER-scoped. It is called by
  // several low-level marketplace parsers before ParsedQuery is available,
  // so generic words such as `bateria` and capacity tokens such as `1TB`
  // must never classify unrelated products (laptops, phones, power tools...)
  // as controller accessories. Require controller/console context first; the
  // category-aware verifier later applies this function again for controller
  // requests, preserving the original safety behavior.
  const controllerContext = /\b(?:dualshock(?:\s*4)?|dualsense|gamepad|kontroler|controller|pad(?:a|em|y|ow)?|playstation\s*[45]|ps\s*[45]|xbox)\b/iu.test(
    `${title} ${url}`
  );
  if (!controllerContext) return false;

  const accessorySignals = [
    "stacja ladujaca",
    "ladowarka do pada",
    "ladowarka dualshock",
    "podwojna ladowarka",
    "stacja dokujaca",
    "charging station",
    "charging dock",
    "dock station",
    "bateria",
    "battery",
    "akumulator",
    "etui",
    "silicone cover",
    "silicon cover",
    "skin case",
    "pokrowiec",
    "obudowa",
    "shell",
    "tasma laczaca",
    "tasma do pada",
    "kabel do pada",
    "przewod do pada",
    "analog do pada",
    "modul analog",
    "joystick module",
    "nakladki na analogi",
    "gripy",
    "czesc zamienna",
    "czesci zamienne",
    "replacement part",
    "na czesci",
    "do naprawy",
    "akumulatory i ladowarki",
    "akumulatory i ładowarki",
    "kategoria akumulatory",
    "ladowarki do konsol",
    "ładowarki do konsol",
    "lip1522",
    "mah li ion",
    "li ion 3 7v",
    "silicone cover",
    "laser carving",
  ];

  if (accessorySignals.some((signal) => title.includes(signal) || url.includes(signal))) {
    return true;
  }

  const mainControllerSignal =
    title.includes("dualshock 4") ||
    title.includes("dualsense") ||
    title.startsWith("pad ") ||
    title.startsWith("kontroler ") ||
    title.startsWith("controller ") ||
    title.includes(" pad ") ||
    title.includes(" kontroler ");

  const consoleSignals = [
    "konsola ps4",
    "ps4 slim konsola",
    "playstation 4 slim",
    "ps4 pro playstation",
    "konsola playstation 4",
    "konsola sony playstation 4",
    "500gb",
    "860gb",
    "1tb",
    "14 gier",
  ];

  const consoleLike = consoleSignals.some(
    (signal) => title.includes(signal) || url.includes(signal)
  );

  if (consoleLike && !mainControllerSignal) {
    return true;
  }

  const strongConsoleBundleSignals = [
    "sony ps4 slim",
    "ps4 slim ",
    "playstation 4 slim",
    "ps4 pro ",
    "konsola ps4",
    "konsola playstation 4",
    "ps4 cuh ",
    "jailbreak",
  ];

  if (
    strongConsoleBundleSignals.some(
      (signal) =>
        title.startsWith(signal) ||
        url.includes(signal.replace(/ /g, "-"))
    )
  ) {
    return true;
  }

  // If the URL itself clearly points to a console bundle, reject even when
  // the OLX image alt accidentally contains "pad".
  const urlConsoleSignals = [
    "/konsola-",
    "/ps4-slim-konsola-",
    "/konsola-sony-playstation-4",
    "/ps4-pro-playstation-4",
    "/konsola-playstation-4",
  ];

  if (urlConsoleSignals.some((signal) => url.includes(signal))) {
    return true;
  }

  return false;
}

function extractBoundedOlxSearchCardMarkdown(
  markdown: string,
  matchStart: number,
  matchEnd: number,
  currentUrlRaw: string
): string {
  if (!markdown || matchStart < 0) return "";

  const currentUrl = normalizeUrl(currentUrlRaw);
  if (!currentUrl) return "";

  const slice = markdown.slice(
    matchStart,
    Math.min(markdown.length, matchStart + 7_000)
  );

  if (!slice) return "";

  const minimumEnd = Math.max(0, matchEnd - matchStart);
  let end = slice.length;

  // V34.CORE120: OLX/Jina can render price + state either AFTER the textual
  // title link or between the image link and the textual title link. Keep a
  // strictly card-bounded look-behind, beginning only after the previous
  // card's "Obserwuj" marker. This recovers legitimate title-bound prices
  // without ever borrowing a neighbouring card's amount.
  const lookBehindStart = Math.max(0, matchStart - 2_400);
  const lookBehind = markdown.slice(lookBehindStart, matchStart);
  let prefixStart = matchStart;
  const observeRe = /\bObserwuj\b/giu;
  let observeMatch: RegExpExecArray | null;
  let lastObserveEnd = -1;
  while ((observeMatch = observeRe.exec(lookBehind)) !== null) {
    lastObserveEnd = observeRe.lastIndex;
  }
  if (lastObserveEnd >= 0) {
    prefixStart = lookBehindStart + lastObserveEnd;
  }

  // Szukamy następnego INNEGO ogłoszenia. Obsługujemy zarówno absolutne, jak
  // i względne /d/oferta/... linki, bo reader zmienia format zależnie od
  // aktualnego renderu OLX.
  const offerUrlRe =
    /(?:https?:\/\/(?:www\.)?olx\.pl)?\/d\/(?:oferta|ogloszenie)\/[^\s)\]]+/giu;

  let urlMatch: RegExpExecArray | null;

  while ((urlMatch = offerUrlRe.exec(slice)) !== null) {
    if (urlMatch.index < minimumEnd) continue;

    let candidate = "";
    try {
      candidate = normalizeUrl(
        new URL(urlMatch[0], "https://www.olx.pl").toString()
      );
    } catch {
      candidate = "";
    }

    if (!candidate || candidate === currentUrl) continue;

    const previousImageStart = slice.lastIndexOf("![", urlMatch.index);
    end =
      previousImageStart > minimumEnd
        ? previousImageStart
        : urlMatch.index;
    break;
  }

  const absoluteEnd = matchStart + Math.max(minimumEnd, end);
  return markdown.slice(prefixStart, Math.min(markdown.length, absoluteEnd));
}

function extractBoundedAllegroLokalnieCardText(
  text: string,
  matchStart: number,
  matchEnd: number,
  currentUrlRaw: string
): string {
  if (!text || matchStart < 0) return "";

  const slice = text.slice(
    matchStart,
    Math.min(text.length, matchStart + 7_000)
  );
  if (!slice) return "";

  const currentUrl = normalizeUrl(currentUrlRaw);
  const minimumEnd = Math.max(0, matchEnd - matchStart);
  let end = slice.length;
  const offerUrlRe =
    /(?:https?:\/\/(?:www\.)?allegrolokalnie\.pl)?\/oferta\/[a-z0-9][a-z0-9-]{4,220}/giu;

  let urlMatch: RegExpExecArray | null;
  while ((urlMatch = offerUrlRe.exec(slice)) !== null) {
    if (urlMatch.index < minimumEnd) continue;

    let absolute = "";
    try {
      absolute = new URL(
        urlMatch[0],
        "https://allegrolokalnie.pl"
      ).toString();
    } catch {
      continue;
    }

    const candidate = normalizeUrl(absolute);
    if (!candidate || !currentUrl || candidate === currentUrl) continue;

    const previousImageStart = slice.lastIndexOf("![", urlMatch.index);
    end = previousImageStart > minimumEnd
      ? previousImageStart
      : urlMatch.index;
    break;
  }

  return slice.slice(0, Math.max(minimumEnd, end));
}

function extractOlxTitleAnchoredMarkdownCard(
  markdown: string,
  visibleTitleRaw: string,
  urlAnchorIndex: number | null = null,
  boundedContextRaw = ""
): string {
  const visibleTitle = normalizeText(decodeHtml(visibleTitleRaw));
  if (!markdown || visibleTitle.length < 5) return "";

  const cleanMarkdownText = (valueRaw: string): string =>
    normalizeText(
      decodeHtml(valueRaw)
        .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/[#*_`]/g, " ")
    );

  // Bind the title to THIS URL occurrence instead of searching the entire OLX
  // landing. The title usually sits immediately before the href, while price,
  // state and location sit after it. We keep only the tail beginning at the
  // LAST matching title before the current URL and append the already
  // URL-bounded context (which stops before the next offer URL).
  if (urlAnchorIndex !== null && Number.isFinite(urlAnchorIndex)) {
    // parseDirectMarketplaceMarkdown passes matchStart at the beginning of the
    // current markdown link, so the URL-bounded context already starts with
    // this card and stops before the next offer. Prepending text from before
    // matchStart can re-introduce the previous identical-title card; use the
    // known visible title + current bounded context only.
    const afterPlain = cleanMarkdownText(
      boundedContextRaw || markdown.slice(
        Math.max(0, urlAnchorIndex),
        Math.min(markdown.length, urlAnchorIndex + 4200)
      )
    );

    let card = normalizeText(`${visibleTitle} ${afterPlain}`);
    const observeIndex = card.toLowerCase().indexOf("obserwuj");
    if (observeIndex > visibleTitle.length) {
      card = card.slice(0, observeIndex + "obserwuj".length);
    }

    return card.slice(0, 1800);
  }

  // Legacy fallback for callers without a URL anchor.
  const plain = cleanMarkdownText(markdown);
  if (!plain) return "";

  const haystack = plain.toLowerCase();
  const needle = visibleTitle.toLowerCase();
  let cursor = 0;
  let best = "";
  let bestScore = -1;

  while (cursor < haystack.length) {
    const index = haystack.indexOf(needle, cursor);
    if (index < 0) break;

    let card = plain.slice(index, Math.min(plain.length, index + 1100));
    const observeIndex = card.toLowerCase().indexOf("obserwuj");
    if (observeIndex > 0) {
      card = card.slice(0, observeIndex + "obserwuj".length);
    }

    const price = extractFirstBoundedOlxCardPrice(card);
    const condition = /\b(?:nowe|nowy|nowa|uzywane|uzywany|uzywana)\b/iu.test(
      normalizeMatchText(card)
    );
    const score =
      (price.price !== null ? 4 : 0) +
      (condition ? 2 : 0) +
      Math.min(2, card.length / 350);

    if (score > bestScore) {
      best = card;
      bestScore = score;
    }

    cursor = index + Math.max(1, needle.length);
  }

  return normalizeText(best).slice(0, 1600);
}



// V34.CORE120 REAL-MARKDOWN URL WINDOW BINDING:
// Some OLX reader renders omit the visible "Obserwuj" token and expose only
// image/text links for each concrete /d/oferta/ URL. In that real layout the
// older observe-bound and textual-link parsers can discover the listing URL
// but fail to bind the price, forcing a slow listing read.
//
// This parser treats the ordered concrete offer URLs themselves as card
// boundaries. For one listing, the trusted tail begins AFTER the LAST
// occurrence of that SAME offer URL and ends BEFORE the FIRST occurrence of a
// DIFFERENT offer URL. Therefore:
//   - model numbers inside the linked title are before the trusted price scope,
//   - a neighbour card's price is beyond the hard URL boundary,
//   - repeated image + text links to the same listing are harmless,
//   - product identity is still checked later by the universal matcher.
//
// It only emits a structural result when a real, non-shipping price is visible
// in that bounded tail. Unpriced listings remain available through the legacy
// parsers and the capped slow-reader lane.
function parseOlxUrlWindowReaderCards(markdown: string): SearchResult[] {
  if (!markdown) return [];

  const occurrenceRe =
    /(?:https?:\/\/(?:www\.)?olx\.pl)?\/d\/(?:oferta|ogloszenie)\/[^\s)\]}>"']+/giu;

  const occurrences: Array<{
    url: string;
    start: number;
    end: number;
  }> = [];

  let match: RegExpExecArray | null;
  while ((match = occurrenceRe.exec(markdown)) !== null) {
    let absolute = "";
    try {
      absolute = new URL(match[0], "https://www.olx.pl").toString();
    } catch {
      continue;
    }

    const url = normalizeUrl(unwrapSearchEngineUrl(absolute));
    if (!url) continue;

    try {
      const parsed = new URL(url);
      const host = parsed.hostname.replace(/^www\./, "").toLowerCase();
      const path = parsed.pathname.toLowerCase();
      if (
        host !== "olx.pl" ||
        !(path.startsWith("/d/oferta/") || path.startsWith("/d/ogloszenie/"))
      ) {
        continue;
      }
    } catch {
      continue;
    }

    occurrences.push({
      url,
      start: match.index,
      end: occurrenceRe.lastIndex,
    });
  }

  if (occurrences.length === 0) return [];

  const results: SearchResult[] = [];
  const seen = new Set<string>();

  const cleanTail = (valueRaw: string): string =>
    normalizeText(
      decodeHtml(valueRaw)
        .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/https?:\/\/\S+/giu, " ")
        .replace(/[#*_`]/g, " ")
    );

  for (let i = 0; i < occurrences.length; i++) {
    const first = occurrences[i];
    if (seen.has(first.url)) continue;

    let boundaryIndex = markdown.length;
    let lastSameOccurrence = first;
    let cursor = i + 1;

    while (cursor < occurrences.length) {
      const next = occurrences[cursor];
      if (next.url !== first.url) {
        // The URL literal sits at the END of a markdown anchor. Cut before
        // that next anchor's visible label as well, otherwise the current
        // card could inherit neighbour identity/spec text even though its
        // price is still URL-bounded.
        const lookBehindStart = Math.max(
          lastSameOccurrence.end,
          next.start - 900
        );
        const beforeNextUrl = markdown.slice(
          lookBehindStart,
          next.start
        );
        const nextLabelStart = beforeNextUrl.lastIndexOf("[");
        boundaryIndex =
          nextLabelStart >= 0
            ? lookBehindStart + nextLabelStart
            : next.start;
        break;
      }
      lastSameOccurrence = next;
      cursor += 1;
    }

    // The price scope starts after the LAST duplicate link to the same offer.
    // This permanently separates numeric model tokens in image/text labels
    // from the following price.
    const tailRaw = markdown.slice(
      lastSameOccurrence.end,
      Math.min(boundaryIndex, lastSameOccurrence.end + 2_200)
    );
    const plainTail = cleanTail(tailRaw).slice(0, 1_500);
    if (!plainTail) {
      seen.add(first.url);
      continue;
    }

    const boundedPrice = extractFirstBoundedOlxCardPrice(plainTail);
    if (boundedPrice.price === null || !boundedPrice.currency) {
      seen.add(first.url);
      continue;
    }

    const name = cleanTitle(titleFromMarketplaceUrl(first.url));
    if (!name || name.length < 5) {
      seen.add(first.url);
      continue;
    }

    const snippet = normalizeText(
      `AIOLXCARDSTART ${name} AIOLXSTRUCTURALBOUND AIOLXRAWSTART AIOLXTITLEEND ${plainTail} AIOLXCARDEND`
    ).slice(0, 3_600);

    results.push({
      url: first.url,
      name,
      snippet,
      source: "OLXDirect",
      searchRank: results.length,
    });
    seen.add(first.url);

    console.log(
      "[AIShopping] V34.CORE120 OLX url-window card price:",
      name,
      boundedPrice.price,
      boundedPrice.currency,
      "condition=",
      extractOlxDirectBoundCondition(snippet, name)
    );
  }

  return results;
}


// V34.CORE120 MARKETPLACE CARD BINDING:
// OLX reader output normally terminates every search card with "Obserwuj".
// Instead of deciding price ownership only from fuzzy title-vs-URL identity,
// first segment the markdown structurally: previous Obserwuj -> current
// Obserwuj. A segment is trustworthy only when every OLX offer URL inside it
// normalizes to ONE concrete listing. Image + text links to the same listing
// are therefore fine, while a segment containing two different listings is
// deliberately rejected. This makes title punctuation/extra seller wording
// irrelevant without ever borrowing a neighbour card's price.
function parseOlxObserveBoundReaderCards(markdown: string): SearchResult[] {
  if (!markdown) return [];

  const results: SearchResult[] = [];
  const seen = new Set<string>();
  const observeMatches = Array.from(markdown.matchAll(/\bObserwuj\b/giu));
  if (observeMatches.length === 0) return results;

  const offerUrlRe =
    /(?:https?:\/\/(?:www\.)?olx\.pl)?\/d\/(?:oferta|ogloszenie)\/[^\s)\]}>"']+/giu;
  const textLinkRe =
    /\[([^\]]{5,500})\]\(((?:https?:\/\/(?:www\.)?olx\.pl)?\/d\/(?:oferta|ogloszenie)\/[^)\s]+)\)/giu;

  let segmentStart = 0;

  for (const observe of observeMatches) {
    const observeIndex = observe.index ?? -1;
    if (observeIndex < 0) continue;

    const segmentEnd = Math.min(
      markdown.length,
      observeIndex + String(observe[0] ?? "Obserwuj").length
    );
    let rawSegment = markdown.slice(segmentStart, segmentEnd);
    segmentStart = segmentEnd;

    if (!rawSegment) continue;
    if (rawSegment.length > 12_000) {
      rawSegment = rawSegment.slice(-12_000);
    }

    const normalizedUrls: string[] = [];
    let urlMatch: RegExpExecArray | null;
    offerUrlRe.lastIndex = 0;
    while ((urlMatch = offerUrlRe.exec(rawSegment)) !== null) {
      let absolute = "";
      try {
        absolute = new URL(urlMatch[0], "https://www.olx.pl").toString();
      } catch {
        continue;
      }
      const normalized = normalizeUrl(unwrapSearchEngineUrl(absolute));
      if (!normalized) continue;
      try {
        const parsed = new URL(normalized);
        const host = parsed.hostname.replace(/^www\./, "").toLowerCase();
        const path = parsed.pathname.toLowerCase();
        if (
          host !== "olx.pl" ||
          !(path.startsWith("/d/oferta/") || path.startsWith("/d/ogloszenie/"))
        ) {
          continue;
        }
      } catch {
        continue;
      }
      normalizedUrls.push(normalized);
    }

    const uniqueUrls = Array.from(new Set(normalizedUrls));
    if (uniqueUrls.length !== 1) continue;

    const url = uniqueUrls[0];
    if (seen.has(url)) continue;

    const urlTitle = cleanTitle(titleFromMarketplaceUrl(url));
    const textTitles: Array<{ title: string; end: number }> = [];
    let titleMatch: RegExpExecArray | null;
    textLinkRe.lastIndex = 0;
    while ((titleMatch = textLinkRe.exec(rawSegment)) !== null) {
      let absolute = "";
      try {
        absolute = new URL(titleMatch[2], "https://www.olx.pl").toString();
      } catch {
        continue;
      }
      if (normalizeUrl(unwrapSearchEngineUrl(absolute)) !== url) continue;

      const title = cleanTitle(
        decodeHtml(titleMatch[1] ?? "")
          .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
          .replace(/^Image\s*\d+\s*:\s*/i, "")
          .replace(/[#*_`]/g, " ")
      );
      if (!title || title.length < 5 || title.toLowerCase() === "obserwuj") continue;
      textTitles.push({ title, end: textLinkRe.lastIndex });
    }

    const scoreTitle = (title: string): number => {
      const expected = new Set(
        normalizeOlxCardIdentity(urlTitle || title)
          .split(/\s+/)
          .filter((token) => token.length >= 2)
      );
      const actual = new Set(
        normalizeOlxCardIdentity(title)
          .split(/\s+/)
          .filter((token) => token.length >= 2)
      );
      const overlap = expected.size > 0
        ? [...expected].filter((token) => actual.has(token)).length / expected.size
        : 0;
      return Math.round(overlap * 100) + Math.min(40, title.length / 8);
    };

    const selectedTitle = [...textTitles]
      .sort((a, b) => scoreTitle(b.title) - scoreTitle(a.title))[0];
    if (!selectedTitle) continue;

    const visibleTitle = selectedTitle.title;
    const name = urlTitle || visibleTitle;
    if (!name || name.length < 5) continue;

    // Start the raw price/state scope AFTER the textual offer anchor. This is
    // the same numeric-identity firewall used by the sequential OLX parser:
    // a model code at the end of the title can never merge with the following
    // price into a fake grouped number after markdown normalization.
    const rawTail = rawSegment.slice(selectedTitle.end);
    const plainTail = normalizeText(
      decodeHtml(rawTail)
        .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/[#*_`]/g, " ")
    ).slice(0, 3_200);

    const snippet = normalizeText(
      `AIOLXCARDSTART ${name} AIOLXSTRUCTURALBOUND AIOLXRAWSTART ${visibleTitle} AIOLXTITLEEND ${plainTail} AIOLXCARDEND`
    ).slice(0, 5_200);

    // Structural uniqueness proves only card -> URL ownership. Product
    // identity is still checked later by the universal product matcher.
    const boundedPrice = extractFirstBoundedOlxCardPrice(
      extractMarkedOlxSearchCardRaw(snippet)
    );

    seen.add(url);
    results.push({
      url,
      name,
      snippet,
      source: "OLXDirect",
      searchRank: results.length,
    });

    if (boundedPrice.price !== null && boundedPrice.currency) {
      console.log(
        "[AIShopping] V34.CORE120 OLX observe-bound card price:",
        name,
        boundedPrice.price,
        boundedPrice.currency
      );
    }
  }

  return results;
}

// Allegro Lokalnie reader markdown can expose relative /oferta/... links.
// The legacy generic markdown parser only scanned absolute hrefs, so a valid
// 200 response could contain concrete cards while discovery returned zero.
// This sequential parser is intentionally small: textual offer anchor -> next
// different textual offer anchor, with price/condition kept inside that slice.
function parseAllegroLokalnieSequentialReaderCards(markdown: string): SearchResult[] {
  if (!markdown) return [];

  const results: SearchResult[] = [];
  const seen = new Set<string>();
  const offerLinkRe =
    /\[([^\]]{5,500})\]\(((?:https?:\/\/(?:www\.)?allegrolokalnie\.pl)?\/oferta\/[a-z0-9][a-z0-9-]{4,220})\)/giu;

  const anchors: Array<{ nameRaw: string; url: string; start: number; end: number }> = [];
  let match: RegExpExecArray | null;
  while ((match = offerLinkRe.exec(markdown)) !== null) {
    const title = normalizeText(match[1] ?? "");
    if (!title || title.startsWith("!")) continue;
    let absolute = "";
    try {
      absolute = new URL(match[2], "https://allegrolokalnie.pl").toString();
    } catch {
      continue;
    }
    const url = normalizeUrl(unwrapSearchEngineUrl(absolute));
    if (!url) continue;
    anchors.push({ nameRaw: title, url, start: match.index, end: offerLinkRe.lastIndex });
  }

  for (let index = 0; index < anchors.length; index++) {
    const anchor = anchors[index];
    if (seen.has(anchor.url)) continue;

    let nextDifferentStart = markdown.length;
    for (let j = index + 1; j < anchors.length; j++) {
      if (anchors[j].url !== anchor.url) {
        nextDifferentStart = anchors[j].start;
        break;
      }
    }

    const name = cleanDirectMarketplaceResultName(
      cleanTitle(decodeHtml(anchor.nameRaw).replace(/[#*_`]/g, " ")) || titleFromMarketplaceUrl(anchor.url),
      anchor.url
    );
    if (!name || name.length < 5) continue;

    const cardMarkdown = markdown.slice(
      anchor.start,
      Math.min(nextDifferentStart, anchor.start + 5_000)
    );
    const plainCard = normalizeText(
      decodeHtml(cardMarkdown)
        .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/[#*_`]/g, " ")
    ).slice(0, 2_400);
    const snippet = normalizeText(`${name} ${plainCard}`).slice(0, 3_000);

    const price = extractAllegroLokalnieBoundPrice(snippet, name);
    if (
      price.price === null ||
      !price.currency
    ) {
      continue;
    }

    seen.add(anchor.url);
    results.push({
      url: anchor.url,
      name,
      snippet,
      source: "AllegroLokalnieDirect",
      searchRank: results.length,
    });
  }

  return results;
}

function parseOlxSequentialReaderCards(markdown: string): SearchResult[] {
  const results: SearchResult[] = [];
  const seen = new Set<string>();

  // V32.12 independent OLX reader fallback. Jina/reader output usually emits
  // the concrete textual offer link followed by that card's price, condition
  // and location. Image anchors can appear before it and may carry duplicated
  // alt text, so this parser deliberately ignores image links and slices only
  // from one textual OLX offer link to the next textual OLX offer link.
  const offerLinkRe =
    /\[([^\]]{5,500})\]\(((?:https?:\/\/(?:www\.)?olx\.pl)?\/d\/(?:oferta|ogloszenie)\/[^)\s]+)\)/giu;

  const anchors: Array<{
    nameRaw: string;
    urlRaw: string;
    start: number;
    end: number;
  }> = [];

  let match: RegExpExecArray | null;
  while ((match = offerLinkRe.exec(markdown)) !== null) {
    const rawLabel = normalizeText(match[1] ?? "");
    if (!rawLabel || rawLabel.startsWith("!")) continue;

    anchors.push({
      nameRaw: rawLabel,
      urlRaw: match[2],
      start: match.index,
      end: offerLinkRe.lastIndex,
    });
  }

  for (let index = 0; index < anchors.length; index++) {
    const anchor = anchors[index];
    let absoluteAnchorUrl = "";
    try {
      absoluteAnchorUrl = new URL(
        anchor.urlRaw,
        "https://www.olx.pl"
      ).toString();
    } catch {
      absoluteAnchorUrl = anchor.urlRaw;
    }

    const url = normalizeUrl(unwrapSearchEngineUrl(absoluteAnchorUrl));
    if (!url || seen.has(url)) continue;

    let parsedUrl: URL;
    try {
      parsedUrl = new URL(url);
    } catch {
      continue;
    }

    const host = parsedUrl.hostname.replace(/^www\./, "").toLowerCase();
    const path = parsedUrl.pathname.toLowerCase();
    if (
      host !== "olx.pl" ||
      !(path.startsWith("/d/oferta/") || path.startsWith("/d/ogloszenie/"))
    ) {
      continue;
    }

    const visibleTitle = cleanTitle(
      decodeHtml(anchor.nameRaw)
        .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
        .replace(/^Image\s*\d+\s*:\s*/i, "")
        .replace(/[#*_`]/g, " ")
    );
    const urlTitle = titleFromMarketplaceUrl(url);
    const name = urlTitle || visibleTitle;
    if (!name || name.length < 5) continue;

    const nextStart = anchors[index + 1]?.start ?? markdown.length;
    // Start AFTER the textual offer anchor. If the title ends with a numeric
    // model code (for example a numeric set/model code) and the next token is the card price
    // (for example 330 zł), flattening the whole markdown card can create a
    // false grouped number such as a model-code followed by a card price. The explicit title-end
    // sentinel keeps identity digits permanently separated from price digits.
    const rawCardTail = markdown.slice(
      anchor.end,
      Math.min(nextStart, anchor.end + 4_500)
    );
    const plainTail = normalizeText(
      decodeHtml(rawCardTail)
        .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/[#*_`]/g, " ")
    ).slice(0, 2_200);

    const snippet = normalizeText(
      `AIOLXCARDSTART ${name} AIOLXRAWSTART ${visibleTitle} AIOLXTITLEEND ${plainTail} AIOLXCARDEND`
    ).slice(0, 4_200);

    if (!isMarkedOlxCardBoundToProduct(snippet, name)) continue;

    // The fallback remains useful even if this card lacks a price; final
    // verification can still read the concrete listing. Cards with a bound
    // price are preferred when the two OLX parsers are merged below.
    seen.add(url);
    results.push({
      url,
      name,
      snippet,
      source: "OLXDirect",
      searchRank: results.length,
    });
  }

  return results;
}

function extractBoundedCeneoMarkdownCard(
  markdown: string,
  anchorStart: number,
  anchorEnd: number,
  currentUrlKey: string
): string {
  let end = Math.min(markdown.length, anchorStart + 5_000);
  const linkRe = /\]\(((?:https?:\/\/(?:www\.)?ceneo\.pl)?\/\d+(?:[^)\s]*)?)\)/giu;
  linkRe.lastIndex = Math.max(anchorEnd, anchorStart);

  let match: RegExpExecArray | null;
  while ((match = linkRe.exec(markdown)) !== null) {
    let absolute = "";
    try {
      absolute = new URL(match[1], "https://www.ceneo.pl").toString();
    } catch {
      continue;
    }

    const nextKey = normalizeUrl(unwrapSearchEngineUrl(absolute));
    if (!nextKey || nextKey === currentUrlKey) continue;

    end = Math.min(end, match.index);
    break;
  }

  return markdown.slice(anchorStart, end);
}

function parseDirectMarketplaceMarkdown(
  markdown: string,
  source: string
): SearchResult[] {
  const results: SearchResult[] = [];
  const seen = new Set<string>();
  // V32.12: OLX reader pages can expose the same offer URL twice: first as an
  // image link with a noisy/repeated alt text and later as the actual textual
  // title link. Keep the strongest same-URL card instead of letting the first
  // occurrence permanently win. Other marketplace parsers keep first-hit
  // dedupe because their anchor text is already stable.
  const olxResultIndexByUrl = new Map<string, number>();
  const olxResultQualityByUrl = new Map<string, number>();

  const push = (
    nameRaw: string,
    urlRaw: string,
    index: number,
    matchEnd: number
  ) => {
    const url = unwrapSearchEngineUrl(urlRaw);
    if (!url) return;

    let parsedUrl: URL;

    try {
      parsedUrl = new URL(url);
    } catch {
      return;
    }

    const host = parsedUrl.hostname.replace(/^www\./, "").toLowerCase();
    const path = parsedUrl.pathname.toLowerCase();

    const isOlxListing =
      host === "olx.pl" &&
      (path.startsWith("/d/oferta/") || path.startsWith("/d/ogloszenie/"));

    const isCeneoProduct =
      host === "ceneo.pl" &&
      /^\/\d+/.test(path);

    const isAllegroProduct =
      host === "allegro.pl" &&
      (path.includes("/oferta/") || path.includes("/produkt/"));

    const isAllegroLokalnieProduct =
      host === "allegrolokalnie.pl" &&
      path.startsWith("/oferta/") &&
      path.split("/").filter(Boolean).length === 2;

    if (source === "OLXDirect" && !isOlxListing) return;
    if (source === "CeneoDirect" && !isCeneoProduct) return;
    if (source === "AllegroDirect" && !isAllegroProduct) return;
    if (
      source === "AllegroLokalnieDirect" &&
      !isAllegroLokalnieProduct
    ) {
      return;
    }

    if (
      source !== "OLXDirect" &&
      source !== "CeneoDirect" &&
      source !== "AllegroDirect" &&
      source !== "AllegroLokalnieDirect"
    ) {
      return;
    }

    const markdownName = cleanTitle(
      decodeHtml(
        nameRaw
          .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
          .replace(/^Image\s*\d+\s*:\s*/i, "")
          .replace(/^!\s*/, "")
      )
    );

    const urlName = titleFromMarketplaceUrl(url);

    // OLX image alt text can be incorrectly repeated between neighbouring
    // listings. URL slug is safer for identifying the actual listing.
    const rawName =
      source === "OLXDirect"
        ? (urlName || markdownName)
        : (markdownName || urlName);

    const name =
      source === "AllegroLokalnieDirect"
        ? cleanDirectMarketplaceResultName(
            rawName,
            url
          )
        : source === "CeneoDirect"
          ? cleanCeneoDirectResultName(rawName)
          : rawName;

    if (!name || name.length < 5) return;

    if (
      (source === "OLXDirect" ||
        source === "AllegroLokalnieDirect") &&
      isControllerAccessoryOrWrongProduct(name, url)
    ) {
      return;
    }

    const key = normalizeUrl(url);
    if (!key) return;
    if (source !== "OLXDirect" && seen.has(key)) return;

    const boundedOlxContext =
      source === "OLXDirect"
        ? extractBoundedOlxSearchCardMarkdown(
            markdown,
            index,
            matchEnd,
            key
          )
        : "";

    const titleAnchoredOlxContext =
      source === "OLXDirect"
        ? extractOlxTitleAnchoredMarkdownCard(
            markdown,
            markdownName || name,
            index,
            boundedOlxContext
          )
        : "";

    // Reader markdown can place the image URL before the textual card. The
    // URL-bounded slice may then stop at the next image URL before reaching
    // this listing's title/price. Prefer exact-title anchoring when available.
    const context =
      source === "OLXDirect"
        ? (titleAnchoredOlxContext || boundedOlxContext)
        : source === "AllegroLokalnieDirect"
          ? extractBoundedAllegroLokalnieCardText(
              markdown,
              index,
              matchEnd,
              key
            )
          : source === "CeneoDirect"
            ? extractBoundedCeneoMarkdownCard(
                markdown,
                index,
                matchEnd,
                key
              )
            : markdown.slice(
                Math.max(0, index - 250),
                Math.min(markdown.length, index + 1900)
              );

    const snippet = normalizeText(
      context
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
        .replace(/[#*_`]/g, " ")
    ).slice(0, 1800);

    const olxBoundAnchorTitle =
      source === "OLXDirect" && markdownName
        ? normalizeText(markdownName).slice(0, 420)
        : "";

    const finalSnippet =
      source === "OLXDirect"
        ? normalizeText(
            `AIOLXCARDSTART ${name} AIOLXRAWSTART ${olxBoundAnchorTitle} ${snippet} AIOLXCARDEND`
          ).slice(0, 4200)
        : normalizeText(
            `${name} ${snippet}`
          ).slice(0, 2200);

    if (
      source === "AllegroLokalnieDirect" &&
      !(
        /(?:\d{1,3}(?:[ .]\d{3})+|\d{1,7})(?:\s*[.,]\s*\d{1,2})?\s*zł/i.test(finalSnippet) ||
        /kup\s+teraz/i.test(finalSnippet)
      )
    ) {
      return;
    }

    const candidate: SearchResult = {
      url: key,
      name,
      snippet: finalSnippet,
      source,
      searchRank: results.length,
    };

    if (source === "OLXDirect") {
      const expectedIdentity = normalizeOlxCardIdentity(urlName || name);
      const visibleIdentity = normalizeOlxCardIdentity(markdownName);
      const rawCard = extractMarkedOlxSearchCardRaw(finalSnippet);
      const boundToProduct = isMarkedOlxCardBoundToProduct(
        finalSnippet,
        urlName || name
      );
      const boundedPrice = boundToProduct
        ? extractFirstBoundedOlxCardPrice(rawCard)
        : { price: null, currency: null };
      const boundedCondition = boundToProduct
        ? extractOlxDirectBoundCondition(finalSnippet, urlName || name)
        : null;

      const expectedTokens = new Set(
        expectedIdentity.split(/\s+/).filter((token) => token.length >= 2)
      );
      const visibleTokens = new Set(
        visibleIdentity.split(/\s+/).filter((token) => token.length >= 2)
      );
      const visibleOverlap = expectedTokens.size > 0
        ? [...expectedTokens].filter((token) => visibleTokens.has(token)).length / expectedTokens.size
        : 0;

      const quality =
        (boundToProduct ? 140 : 0) +
        (boundedPrice.price !== null && boundedPrice.currency ? 90 : 0) +
        (boundedCondition ? 24 : 0) +
        Math.round(visibleOverlap * 60) +
        (markdownName ? 6 : 0);

      const existingIndex = olxResultIndexByUrl.get(key);
      const existingQuality = olxResultQualityByUrl.get(key) ?? -1;

      if (existingIndex !== undefined) {
        if (quality <= existingQuality) return;

        candidate.searchRank = results[existingIndex]?.searchRank ?? existingIndex;
        results[existingIndex] = candidate;
        olxResultQualityByUrl.set(key, quality);
        return;
      }

      seen.add(key);
      olxResultIndexByUrl.set(key, results.length);
      olxResultQualityByUrl.set(key, quality);
      results.push(candidate);
      return;
    }

    seen.add(key);
    results.push(candidate);
  };

  const nestedImageLinkRe =
    /\[\s*!\[([^\]]{3,500})\]\((https?:\/\/[^)\s]+)\)\s*\]\((https?:\/\/[^)\s]+)\)/gi;

  let match: RegExpExecArray | null;

  const normalLinkRe =
    /\[([^\]]{5,500})\]\((https?:\/\/[^)\s]+)\)/gi;

  // V32.12: on OLX, the visible text link is a stronger card identity anchor
  // than the image alt link. Scan it first; quality-aware same-URL replacement
  // below still lets a later occurrence win when it is demonstrably stronger.
  if (source === "OLXDirect") {
    while ((match = normalLinkRe.exec(markdown)) !== null) {
      push(match[1], match[2], match.index, normalLinkRe.lastIndex);
    }

    while ((match = nestedImageLinkRe.exec(markdown)) !== null) {
      push(match[1], match[3], match.index, nestedImageLinkRe.lastIndex);
    }
  } else {
    while ((match = nestedImageLinkRe.exec(markdown)) !== null) {
      push(match[1], match[3], match.index, nestedImageLinkRe.lastIndex);
    }

    while ((match = normalLinkRe.exec(markdown)) !== null) {
      push(match[1], match[2], match.index, normalLinkRe.lastIndex);
    }
  }

  if (source === "OLXDirect") {
    const urlWindow = parseOlxUrlWindowReaderCards(markdown);
    const observeBound = parseOlxObserveBoundReaderCards(markdown);
    const sequential = parseOlxSequentialReaderCards(markdown);
    const mergedByUrl = new Map<string, SearchResult>();

    const olxCardQuality = (result: SearchResult): number => {
      const bound = isMarkedOlxCardBoundToProduct(
        result.snippet,
        result.name
      );
      const raw = extractMarkedOlxSearchCardRaw(result.snippet);
      const price = bound
        ? extractFirstBoundedOlxCardPrice(raw)
        : { price: null, currency: null };
      const condition = bound
        ? extractOlxDirectBoundCondition(result.snippet, result.name)
        : null;

      return (bound ? 100 : 0) +
        (price.price !== null && price.currency ? 80 : 0) +
        (condition ? 20 : 0);
    };

    // Prefer the independent textual-link reader on equal confidence. Its
    // card tail starts after the title anchor, so numeric model identifiers
    // cannot be accidentally grouped with the following price. The legacy
    // parser still replaces it when it has strictly stronger bound evidence.
    for (const candidate of [...urlWindow, ...observeBound, ...sequential, ...results]) {
      const key = normalizeUrl(candidate.url);
      if (!key) continue;

      const existing = mergedByUrl.get(key);
      if (!existing || olxCardQuality(candidate) > olxCardQuality(existing)) {
        mergedByUrl.set(key, { ...candidate, url: key });
      }
    }

    const merged = [...mergedByUrl.values()]
      .sort((a, b) => a.searchRank - b.searchRank)
      .map((result, index) => ({ ...result, searchRank: index }));

    const cardsWithBoundPrice = merged.filter((result) => {
      if (!isMarkedOlxCardBoundToProduct(result.snippet, result.name)) {
        return false;
      }
      const price = extractFirstBoundedOlxCardPrice(
        extractMarkedOlxSearchCardRaw(result.snippet)
      );
      return price.price !== null && Boolean(price.currency);
    }).length;

    console.log(
      "[AIShopping] V34.CORE120 OLX markdown cards with title-bound price:",
      cardsWithBoundPrice,
      "/",
      merged.length,
      "urlWindow=",
      urlWindow.length,
      "observeBound=",
      observeBound.length,
      "sequential=",
      sequential.length
    );

    return merged.slice(0, MAX_SEARCH_RESULTS_PER_ENGINE);
  }

  if (source === "AllegroLokalnieDirect") {
    const sequential = parseAllegroLokalnieSequentialReaderCards(markdown);
    const mergedByUrl = new Map<string, SearchResult>();

    const quality = (result: SearchResult): number => {
      const price = extractAllegroLokalnieBoundPrice(
        `${result.name} ${result.snippet}`,
        result.name
      );
      const condition = extractTrustedConditionFromText(
        extractMarketplaceCardContext(
          `${result.name} ${result.snippet}`,
          result.name,
          1900
        ) || `${result.name} ${result.snippet}`
      );
      return (price.price !== null && price.currency ? 100 : 0) + (condition ? 20 : 0);
    };

    for (const candidate of [...sequential, ...results]) {
      const key = normalizeUrl(candidate.url);
      if (!key) continue;
      const existing = mergedByUrl.get(key);
      if (!existing || quality(candidate) > quality(existing)) {
        mergedByUrl.set(key, { ...candidate, url: key });
      }
    }

    const merged = [...mergedByUrl.values()]
      .sort((a, b) => a.searchRank - b.searchRank)
      .map((result, index) => ({ ...result, searchRank: index }));

    console.log(
      "[AIShopping] V34.CORE120 Allegro Lokalnie sequential cards:",
      sequential.length,
      "merged=",
      merged.length
    );

    return merged.slice(0, MAX_SEARCH_RESULTS_PER_ENGINE);
  }

  return results.slice(0, MAX_SEARCH_RESULTS_PER_ENGINE);
}



function parseAllegroLokalnieEmbeddedHtml(
  html: string,
  pageUrl: string
): SearchResult[] {
  const results: SearchResult[] = [];
  const seen = new Set<string>();

  // Allegro Lokalnie can render offer cards inside embedded application state
  // instead of normal <a href="..."> anchors. Decode the most common JSON/
  // Next.js escaping forms, then scan only for first-party /oferta/<slug> URLs.
  const decoded = decodeHtml(html)
    .replace(/\\u002F/gi, "/")
    .replace(/\\u0026/gi, "&")
    .replace(/\\\//g, "/");

  const pageKey = normalizeUrl(pageUrl);
  const offerUrlRe = /(?:https?:\/\/allegrolokalnie\.pl)?\/oferta\/([a-z0-9][a-z0-9-]{4,220})/giu;

  let match: RegExpExecArray | null;

  while ((match = offerUrlRe.exec(decoded)) !== null) {
    const slug = match[1];
    if (!slug) continue;

    let absoluteUrl = "";
    try {
      absoluteUrl = new URL(`/oferta/${slug}`, "https://allegrolokalnie.pl").toString();
    } catch {
      continue;
    }

    const normalizedUrl = normalizeUrl(absoluteUrl);
    if (!normalizedUrl || normalizedUrl === pageKey || seen.has(normalizedUrl)) {
      continue;
    }

    const name = cleanDirectMarketplaceResultName(
      titleFromMarketplaceUrl(normalizedUrl),
      normalizedUrl
    );

    if (!name || name.length < 5) continue;

    if (isControllerAccessoryOrWrongProduct(name, normalizedUrl)) {
      continue;
    }

    // Bind card context to the concrete embedded offer URL. This avoids using
    // a random price from another card on the same landing/search page.
    const rawContext = decoded.slice(
      Math.max(0, match.index - 900),
      Math.min(decoded.length, match.index + match[0].length + 2600)
    );

    const context = normalizeText(
      rawContext
        .replace(/[{}[\]"']/g, " ")
        .replace(/\\n|\\r|\\t/g, " ")
        .replace(/\\+/g, " ")
    ).slice(0, 2600);

    const priceMatch = context.match(
      /(?:^|[^\d])((?:\d{1,3}(?:[ .]\d{3})+|\d{1,7})(?:\s*[.,]\s*\d{1,2})?)\s*(?:zł|PLN)(?=$|[^\p{L}\p{N}_])/iu
    );

    const hasBuyingSignal =
      Boolean(priceMatch) ||
      /kup\s+teraz|licytuj|oferta|sprzedam/iu.test(context);

    if (!hasBuyingSignal) continue;

    const snippet = normalizeText(`${name} ${context}`).slice(0, 2600);

    seen.add(normalizedUrl);
    results.push({
      url: normalizedUrl,
      name,
      snippet,
      source: "AllegroLokalnieDirect",
      searchRank: results.length,
    });

    if (results.length >= MAX_SEARCH_RESULTS_PER_ENGINE) break;
  }

  return results;
}


function parseOlxDirectHtml(
  html: string,
  pageUrl: string
): SearchResult[] {
  const results: SearchResult[] = [];
  const seen = new Set<string>();

  // V32.12: OLX category/search pages can expose concrete listing URLs in the
  // normal/embedded HTML even when the reader is temporarily slow. Decode the
  // common JSON/Next escaping forms first, then bind each URL to a local card
  // window. This is a generic OLX listing parser; it contains no category,
  // brand, model or SKU-specific product logic.
  const decoded = decodeHtml(html)
    .replace(/\\u002F/gi, "/")
    .replace(/\\u0026/gi, "&")
    .replace(/\\\//g, "/");

  const pageKey = normalizeUrl(pageUrl);
  const offerUrlRe = /(?:https?:\/\/(?:www\.)?olx\.pl)?\/d\/(?:oferta|ogloszenie)\/[a-z0-9][a-z0-9-]{4,240}(?:\.html)?/giu;

  const occurrences: Array<{
    url: string;
    index: number;
    matchEnd: number;
  }> = [];

  let match: RegExpExecArray | null;
  while ((match = offerUrlRe.exec(decoded)) !== null) {
    let absolute = "";
    try {
      absolute = new URL(match[0], "https://www.olx.pl").toString();
    } catch {
      continue;
    }

    const normalizedUrl = normalizeUrl(absolute);
    if (!normalizedUrl || normalizedUrl === pageKey) continue;

    let parsedUrl: URL;
    try {
      parsedUrl = new URL(normalizedUrl);
    } catch {
      continue;
    }

    const host = parsedUrl.hostname.replace(/^www\./, "").toLowerCase();
    const path = parsedUrl.pathname.toLowerCase();
    if (
      host !== "olx.pl" ||
      !(path.startsWith("/d/oferta/") || path.startsWith("/d/ogloszenie/"))
    ) {
      continue;
    }

    // The same listing may appear several times inside one card (image/title,
    // JSON state, tracking payload). Keep the first position only so adjacent
    // listing boundaries remain meaningful and price bleed is minimized.
    if (occurrences.some((entry) => entry.url === normalizedUrl)) continue;

    occurrences.push({
      url: normalizedUrl,
      index: match.index,
      matchEnd: offerUrlRe.lastIndex,
    });

    if (occurrences.length >= MAX_SEARCH_RESULTS_PER_ENGINE * 3) break;
  }

  for (let i = 0; i < occurrences.length; i += 1) {
    const current = occurrences[i];
    const next = occurrences[i + 1];
    if (!current || seen.has(current.url)) continue;

    const urlName = titleFromMarketplaceUrl(current.url);
    if (!urlName || urlName.length < 5) continue;

    if (isControllerAccessoryOrWrongProduct(urlName, current.url)) continue;

    const start = Math.max(0, current.index - 1400);
    const end = Math.min(
      decoded.length,
      next
        ? Math.max(current.matchEnd + 500, next.index - 40)
        : current.matchEnd + 4200
    );

    const rawContext = decoded.slice(start, end);
    const plainContext = normalizeText(
      extractTagText(
        rawContext
          .replace(/\\n|\\r|\\t/g, " ")
          .replace(/\\+/g, " ")
      )
    ).slice(0, 3000);

    // Embedded state is sometimes mostly text after tag stripping; keep a
    // compact fallback derived from the raw context as well.
    const embeddedContext = normalizeText(
      rawContext
        .replace(/[{}\[\]"']/g, " ")
        .replace(/\\n|\\r|\\t/g, " ")
        .replace(/<[^>]+>/g, " ")
        .replace(/\\+/g, " ")
    ).slice(0, 2600);

    const context = normalizeText(`${plainContext} ${embeddedContext}`).slice(0, 3800);
    const snippet = normalizeText(
      `AIOLXCARDSTART ${urlName} AIOLXRAWSTART ${context} AIOLXCARDEND`
    ).slice(0, 4200);

    seen.add(current.url);
    results.push({
      url: current.url,
      name: urlName,
      snippet,
      source: "OLXDirect",
      searchRank: results.length,
    });

    if (results.length >= MAX_SEARCH_RESULTS_PER_ENGINE) break;
  }

  console.log(
    "[AIShopping] V34.CORE120 OLX direct HTML cards:",
    results.length,
    "occurrences=",
    occurrences.length
  );

  return results;
}

function extractQuotedHtmlAttribute(
  attrsRaw: string,
  attributeName: string
): string {
  const attrs = attrsRaw || "";
  const name = escapeRegExp(attributeName);
  const doubleQuoted = attrs.match(
    new RegExp(`\\b${name}\\s*=\\s*"([^"\\r\\n]{1,1200})"`, "i")
  );
  if (doubleQuoted?.[1]) return doubleQuoted[1];

  const singleQuoted = attrs.match(
    new RegExp(`\\b${name}\\s*=\\s*'([^'\\r\\n]{1,1200})'`, "i")
  );
  return singleQuoted?.[1] ?? "";
}

function getCeneoCandidateTextQualityScore(valueRaw: string): number {
  const cleaned = cleanCeneoDirectResultName(valueRaw);
  const normalized = normalizeMatchText(cleaned);
  if (!normalized || normalized.length < 5) return -1_000;

  // CTA / navigation labels are common title/aria-label values on Ceneo cards.
  // They must never outrank the visible product tile text.
  if (
    /^(?:id[zź] do sklepu|przejd[zź] do sklepu|porownaj ceny|porównaj ceny|zobacz ofert[eę]|zobacz oferty|sprawdz ceny|sprawd[zź] cen[eę]|dodaj do ulubionych|opinie|oferty|produkt)$/iu.test(cleaned.trim())
  ) {
    return -900;
  }

  let score = 0;
  const words = normalized.split(/\s+/).filter(Boolean);
  score += Math.min(28, cleaned.length / 5);
  score += Math.min(16, words.length * 2);
  if (/\d/.test(normalized)) score += 8;
  if (/[a-z].*\d|\d.*[a-z]/i.test(normalized)) score += 8;
  if (/\b(?:zł|pln|od)\b/i.test(normalized)) score -= 2;
  if (/\b(?:sklep|oferta|oferty|opinie|porownaj|porównaj)\b/i.test(normalized) && words.length <= 5) score -= 15;
  return score;
}

function chooseCeneoDirectResultName(
  attributeTitleRaw: string,
  innerTextRaw: string,
  urlTitleRaw: string,
  extraCandidatesRaw: string[] = []
): string {
  const candidates = [attributeTitleRaw, innerTextRaw, ...extraCandidatesRaw, urlTitleRaw]
    .map((value, rank) => ({
      value: cleanCeneoDirectResultName(value),
      rank,
      score: getCeneoCandidateTextQualityScore(value),
    }))
    .filter(({ value }) => value.length >= 5)
    .sort((a, b) => b.score - a.score || a.rank - b.rank);

  return candidates[0]?.value ?? "";
}

function extractBoundedCeneoSearchCardHtml(
  html: string,
  matchStart: number,
  matchEnd: number,
  currentUrlRaw: string
): string {
  if (!html || matchStart < 0) return "";

  const currentUrl = normalizeUrl(currentUrlRaw);
  if (!currentUrl) return "";

  const slice = html.slice(
    matchStart,
    Math.min(html.length, matchStart + 12_000)
  );
  if (!slice) return "";

  const minimumEnd = Math.max(0, matchEnd - matchStart);
  let end = slice.length;
  const anchorRe = /<a\b([^>]*?)href=["']([^"']+)["']([^>]*)>/giu;
  let anchorMatch: RegExpExecArray | null;

  while ((anchorMatch = anchorRe.exec(slice)) !== null) {
    if (anchorMatch.index < minimumEnd) continue;

    let candidateUrl = "";
    try {
      candidateUrl = normalizeUrl(
        new URL(decodeHtml(anchorMatch[2]).trim(), currentUrl).toString()
      );
    } catch {
      candidateUrl = "";
    }
    if (!candidateUrl || candidateUrl === currentUrl) continue;

    try {
      const candidate = new URL(candidateUrl);
      const host = candidate.hostname.replace(/^www\./, "").toLowerCase();
      if (host === "ceneo.pl" && /^\/\d+/.test(candidate.pathname)) {
        end = anchorMatch.index;
        break;
      }
    } catch {
      // Ignore malformed neighbouring anchors; the hard 12k bound still holds.
    }
  }

  return slice.slice(0, Math.max(minimumEnd, end));
}

function extractCeneoSearchCardNameCandidates(
  cardHtml: string,
  currentUrlRaw: string
): string[] {
  if (!cardHtml) return [];

  const currentUrl = normalizeUrl(currentUrlRaw);
  const candidates: string[] = [];
  const push = (valueRaw: string) => {
    const value = cleanCeneoDirectResultName(valueRaw);
    if (value.length >= 5) candidates.push(value);
  };

  const quotedAttributeRe =
    /\b(?:aria-label|title|alt|data-product-name|data-productname|data-name)\s*=\s*(["'])([\s\S]*?)\1/giu;
  for (const attribute of cardHtml.matchAll(quotedAttributeRe)) {
    push(decodeHtml(attribute[2] ?? ""));
  }

  const anchorRe =
    /<a\b([^>]*?)href=["']([^"']+)["']([^>]*)>([\s\S]*?)<\/a>/giu;
  let anchorMatch: RegExpExecArray | null;
  while ((anchorMatch = anchorRe.exec(cardHtml)) !== null) {
    let candidateUrl = "";
    try {
      candidateUrl = normalizeUrl(
        new URL(decodeHtml(anchorMatch[2]).trim(), currentUrl || "https://www.ceneo.pl").toString()
      );
    } catch {
      candidateUrl = "";
    }
    if (!candidateUrl || candidateUrl !== currentUrl) continue;

    const attrs = `${anchorMatch[1]} ${anchorMatch[3]}`;
    push(extractQuotedHtmlAttribute(attrs, "aria-label"));
    push(extractQuotedHtmlAttribute(attrs, "title"));
    push(cleanTitle(extractTagText(anchorMatch[4])));

    const altRe = /\balt\s*=\s*(["'])([\s\S]*?)\1/giu;
    for (const alt of anchorMatch[4].matchAll(altRe)) {
      push(decodeHtml(alt[2] ?? ""));
    }
  }

  const headingRe = /<(?:h2|h3|h4|strong)\b[^>]*>([\s\S]*?)<\/(?:h2|h3|h4|strong)>/giu;
  for (const heading of cardHtml.matchAll(headingRe)) {
    push(cleanTitle(extractTagText(heading[1])));
  }

  return Array.from(new Set(candidates));
}

function isUsableCeneoDirectResultName(valueRaw: string): boolean {
  const value = cleanCeneoDirectResultName(valueRaw);
  const normalized = normalizeMatchText(value);
  if (!normalized || value.length < 5) return false;
  if (/^\d{5,14}$/.test(normalized)) return false;
  return getCeneoCandidateTextQualityScore(value) >= 16;
}

function parseDirectMarketplaceHtml(
  html: string,
  pageUrl: string,
  source: string
): SearchResult[] {
  const results: SearchResult[] = [];
  const seen = new Set<string>();

  const pageKey = normalizeUrl(pageUrl);

  const anchorRe =
    /<a\b([^>]*?)href=["']([^"']+)["']([^>]*)>([\s\S]*?)<\/a>/giu;

  let match: RegExpExecArray | null;

  while ((match = anchorRe.exec(html)) !== null) {
    const hrefRaw = decodeHtml(match[2]).trim();
    if (!hrefRaw) continue;

    let absoluteUrl = "";

    try {
      absoluteUrl = new URL(hrefRaw, pageUrl).toString();
    } catch {
      continue;
    }

    const normalizedUrl = normalizeUrl(absoluteUrl);
    if (!normalizedUrl || normalizedUrl === pageKey) continue;

    let parsedUrl: URL;

    try {
      parsedUrl = new URL(normalizedUrl);
    } catch {
      continue;
    }

    const host = parsedUrl.hostname
      .replace(/^www\./, "")
      .toLowerCase();

    const path = parsedUrl.pathname.toLowerCase();

    const isAllegroProduct =
      host === "allegro.pl" &&
      path.includes("/oferta/");

    const isAllegroLokalnieProduct =
      host === "allegrolokalnie.pl" &&
      path.startsWith("/oferta/") &&
      path.split("/").filter(Boolean).length === 2;

    const isCeneoProduct =
      host === "ceneo.pl" &&
      /^\/\d+/.test(path);

    if (source === "AllegroDirect" && !isAllegroProduct) {
      continue;
    }

    if (
      source === "AllegroLokalnieDirect" &&
      !isAllegroLokalnieProduct
    ) {
      continue;
    }

    if (source === "CeneoDirect" && !isCeneoProduct) {
      continue;
    }

    if (
      source !== "AllegroDirect" &&
      source !== "AllegroLokalnieDirect" &&
      source !== "CeneoDirect"
    ) {
      continue;
    }

    if (seen.has(normalizedUrl)) continue;

    const attrs = `${match[1]} ${match[3]}`;

    // V32.12: respect the quote character that actually opened the HTML
    // attribute. The previous ["']...[^"'] parser truncated a double-quoted
    // title at an apostrophe inside a brand name.
    const ariaLabelValue = extractQuotedHtmlAttribute(attrs, "aria-label");
    const titleValue = extractQuotedHtmlAttribute(attrs, "title");

    const innerText = cleanTitle(
      extractTagText(match[4])
    );

    const attributeTitle = cleanTitle(
      decodeHtml(ariaLabelValue || titleValue || "")
    );

    const urlTitle =
      titleFromMarketplaceUrl(normalizedUrl);

    // Ceneo commonly renders the FIRST /<productId> anchor as an image and a
    // later anchor to the SAME URL as the visible product title. CORE76 could
    // accept the numeric URL id as the name, mark the URL as seen, and then
    // discard the real title anchor. Recover the whole current card first and
    // choose the strongest name from same-card text/alt/title attributes.
    const ceneoBoundedCardHtml =
      source === "CeneoDirect"
        ? extractBoundedCeneoSearchCardHtml(
            html,
            match.index,
            match.index + match[0].length,
            normalizedUrl
          )
        : "";
    const ceneoCardNameCandidates =
      source === "CeneoDirect"
        ? extractCeneoSearchCardNameCandidates(
            ceneoBoundedCardHtml,
            normalizedUrl
          )
        : [];

    const rawName =
      source === "CeneoDirect"
        ? chooseCeneoDirectResultName(
            attributeTitle,
            innerText,
            urlTitle,
            ceneoCardNameCandidates
          )
        : innerText.length >= 5
          ? innerText
          : attributeTitle.length >= 5
            ? attributeTitle
            : urlTitle;

    const name =
      source === "AllegroLokalnieDirect"
        ? cleanDirectMarketplaceResultName(
            rawName,
            normalizedUrl
          )
        : rawName;

    if (!name || name.length < 5) continue;
    if (source === "CeneoDirect" && !isUsableCeneoDirectResultName(name)) {
      // Deliberately do NOT mark the URL as seen. A later textual anchor for
      // the same product may still carry the real product name.
      continue;
    }

    if (
      isControllerAccessoryOrWrongProduct(
        name,
        normalizedUrl
      )
    ) {
      continue;
    }

    const contextBefore =
      source === "CeneoDirect" ? 260 : 800;
    const contextAfter =
      source === "CeneoDirect" ? 1050 : 3000;

    const rawContext =
      source === "CeneoDirect"
        ? ceneoBoundedCardHtml
        : source === "AllegroLokalnieDirect"
          ? extractBoundedAllegroLokalnieCardText(
              html,
              match.index,
              match.index + match[0].length,
              normalizedUrl
            )
          : html.slice(
              Math.max(0, match.index - contextBefore),
              Math.min(
                html.length,
                match.index + match[0].length + contextAfter
              )
            );

    const context = normalizeText(
      extractTagText(rawContext)
    ).slice(0, source === "CeneoDirect" ? 1800 : 2600);

    // Listing cards should usually have price / buy-now context nearby.
    // Allegro itself can sometimes omit it in SSR, so this is strict only
    // for Allegro Lokalnie where the listing page exposes it reliably.
    if (
      source === "AllegroLokalnieDirect" &&
      !(
        /(?:\d{1,3}(?:[ .]\d{3})+|\d{1,7})(?:\s*[.,]\s*\d{1,2})?\s*zł/i.test(context) ||
        /kup\s+teraz/i.test(context)
      )
    ) {
      continue;
    }

    seen.add(normalizedUrl);

    results.push({
      url: normalizedUrl,
      name,
      snippet: normalizeText(
        `${name} ${context}`
      ).slice(0, 2600),
      source,
      searchRank: results.length,
    });

    const sourceResultLimit =
      source === "AllegroLokalnieDirect"
        ? MAX_ALLEGRO_LOKALNIE_DIRECT_RESULTS
        : MAX_SEARCH_RESULTS_PER_ENGINE;

    if (results.length >= sourceResultLimit) {
      break;
    }
  }

  return results;
}

async function searchGoogleViaJina(
  query: string,
  externalSignal?: AbortSignal
): Promise<SearchResult[]> {
  try {
    const googleUrl =
      `https://www.google.com/search?q=${encodeURIComponent(query)}` +
      `&hl=pl&gl=pl&num=10`;

    const markdown = await fetchViaJina(
      googleUrl,
      Math.max(SEARCH_TIMEOUT_MS, 15000),
      true,
      externalSignal
    );

    // V32.12: an abortable deadline may intentionally stop this reader after
    // the caller has moved on. Do not emit a misleading late "empty result"
    // log after cancellation.
    if (externalSignal?.aborted) return [];

    if (!markdown) {
      console.log("[AIShopping] Jina Google: empty result");
      return [];
    }

    if (isBlockedOrChallengePage(markdown)) {
      console.log("[AIShopping] Jina Google: challenge page");
      return [];
    }

    const results = parseJinaSearchMarkdown(markdown);

    console.log(
      "[AIShopping] Jina Google results:",
      results.length,
      "query=",
      query
    );

    return results;
  } catch (error) {
    console.error("[AIShopping] Jina Google error:", error);
    return [];
  }
}

function addSiteQueries(
  queries: string[],
  parsed: ParsedQuery
): string[] {
  // buildSearchQueries already contains targeted site: queries.
  // Add only a small number of fallback site queries to avoid flooding
  // Bing/DDG with the same request.
  const domains = getQueryPreferredDomains(parsed)
    .slice(0, parsed.country === "PL" ? 8 : 4);

  const base = buildRetailerDiscoveryQuery(parsed);

  const siteQueries = domains.map(
    (domain) => `site:${getRetailerProductSiteScope(domain)} ${base}`
  );

  return Array.from(new Set([...queries, ...siteQueries]));
}



function getUniversalRequestedBrandAliases(parsed: ParsedQuery): string[] {
  if (!parsed.brand) return [];

  const brand = normalizeMatchText(parsed.brand);

  if (parsed.category === "gpu" && brand === "nvidia") {
    return ["nvidia", "geforce", "rtx"];
  }

  if (parsed.category === "gpu" && brand === "amd") {
    return ["amd", "radeon"];
  }

  if (brand === "apple" && parsed.category === "phone") {
    return ["apple", "iphone"];
  }

  if (brand === "apple" && parsed.category === "tablet") {
    return ["apple", "ipad"];
  }

  if (["console", "controller"].includes(parsed.category ?? "") && brand === "sony") {
    return ["sony", "playstation", "ps5", "ps4"];
  }

  if (["console", "controller"].includes(parsed.category ?? "") && brand === "microsoft") {
    return ["microsoft", "xbox"];
  }

  // V32.12: punctuation is not product identity. Retailers routinely render
  // the same manufacturer as e.g. "A'B", "A B" or "AB". Keep the literal
  // normalized form, plus bounded spaced/compact equivalents. This is only a
  // brand-alias expansion; model/category gates stay unchanged.
  const spaced = normalizeText(brand.replace(/[^\p{L}\p{N}]+/gu, " "))
    .toLowerCase();
  const compact = brand.replace(/[^\p{L}\p{N}]+/gu, "");

  return Array.from(
    new Set(
      [brand, spaced, compact]
        .map((value) => normalizeMatchText(value))
        .filter((value) => value.length >= 2)
    )
  );
}

type VerifiedBrandConflictAssessment = {
  conflict: boolean;
  claims: string[];
  reason: string | null;
};

function getGenericStructuredNameTokens(parsed: ParsedQuery): Set<string> {
  return new Set(
    [
      ...parsed.intent.identityTerms,
      ...parsed.intent.qualifierTerms,
      parsed.intent.productPhrase,
      parsed.product,
      parsed.category ?? "",
      "produkt",
      "product",
      "przedmiot",
      "urzadzenie",
      "device",
      "power",
      "bank",
      "fast",
      "charge",
      "charger",
      "charging",
      "wireless",
      "smart",
      "nowy",
      "nowa",
      "nowe",
      "oryginalny",
      "oryginalna",
      "original",
      "model",
      "typ",
      "type",
      "wersja",
      "version",
      "seria",
      "series",
    ]
      .flatMap((value) => normalizeMatchText(value).split(/\s+/))
      .filter((value) => value.length >= 2)
  );
}

function countBoundedIdentityOccurrences(
  textRaw: string,
  tokenRaw: string
): number {
  const text = normalizeMatchText(textRaw);
  const token = normalizeMatchText(tokenRaw).trim();
  if (!text || !token) return 0;

  const pattern = new RegExp(
    `(?:^|[^\\p{L}\\p{N}_])${escapeRegExp(token)}(?=$|[^\\p{L}\\p{N}_])`,
    "giu"
  );

  return Array.from(text.matchAll(pattern)).length;
}

function evaluateVerifiedBrandConflict(
  parsed: ParsedQuery,
  titleRaw: string,
  trustedDescriptionRaw: string
): VerifiedBrandConflictAssessment {
  if (
    !parsed.brand ||
    !trustedDescriptionRaw ||
    !isBrandExplicitlyRequested(parsed.brand, parsed.queryText)
  ) {
    return { conflict: false, claims: [], reason: null };
  }

  const description = normalizeMatchText(trustedDescriptionRaw);
  const title = normalizeMatchText(titleRaw);
  const requestedAliases = getUniversalRequestedBrandAliases(parsed)
    .map(normalizeMatchText)
    .filter(Boolean);

  const segmentHasRequestedBrand = (segmentRaw: string): boolean => {
    const segment = normalizeMatchText(segmentRaw);
    return requestedAliases.some((alias) =>
      universalEvidenceHasBoundedIdentityTerm(alias, segment)
    );
  };

  const genericTokens = getGenericStructuredNameTokens(parsed);
  const claims: string[] = [];

  // „Marka/Producent/Brand/Manufacturer” są jednoznacznymi polami. Bierzemy
  // kilka kolejnych słów, aby nie pomylić nazwy firmy „Shenzhen Baseus...” z
  // obcą marką tylko dlatego, że pierwszym słowem jest miejscowość.
  const strongLabelRe =
    /\b(?:marka|producent|brand|manufacturer)\s*[:=\-]\s*((?:[\p{L}\p{N}._+\-]+\s*){1,7})/giu;

  for (const match of description.matchAll(strongLabelRe)) {
    const segment = normalizeText(match[1] ?? "");
    if (!segment || segmentHasRequestedBrand(segment)) continue;

    const candidate = normalizeMatchText(segment).split(/\s+/)[0] ?? "";
    if (!candidate || candidate.length < 2 || genericTokens.has(candidate)) continue;

    claims.push(candidate);
  }

  if (claims.length > 0) {
    return {
      conflict: true,
      claims: Array.from(new Set(claims)),
      reason: "structured-brand-or-manufacturer-conflict",
    };
  }

  // Pole „Nazwa” może zaczynać się marką albo modelem. Traktujemy je jako
  // konflikt dopiero, gdy obca nazwa powtarza się w zweryfikowanym opisie,
  // nie występuje w tytule (więc nie jest znanym modelem oferty), a żądana
  // marka nie pojawia się w opisie. To wykrywa błędnie podpisane ogłoszenia,
  // nie wymagając listy marek ani reguły dla konkretnego produktu.
  const descriptionHasRequestedBrand = requestedAliases.some((alias) =>
    universalEvidenceHasBoundedIdentityTerm(alias, description)
  );

  if (!descriptionHasRequestedBrand) {
    const nameLabelRe =
      /\b(?:nazwa\s+produktu|product\s+name|nazwa)\s*[:=\-]\s*((?:[\p{L}\p{N}._+\-]+\s*){1,8})/giu;

    for (const match of description.matchAll(nameLabelRe)) {
      const segment = normalizeText(match[1] ?? "");
      if (!segment || segmentHasRequestedBrand(segment)) continue;

      const candidate = normalizeMatchText(segment)
        .split(/\s+/)
        .find(
          (token) =>
            token.length >= 3 &&
            !genericTokens.has(token) &&
            !/^\d/.test(token)
        );

      if (!candidate) continue;
      if (universalEvidenceHasBoundedIdentityTerm(candidate, title)) continue;

      if (countBoundedIdentityOccurrences(description, candidate) >= 2) {
        claims.push(candidate);
      }
    }
  }

  return claims.length > 0
    ? {
        conflict: true,
        claims: Array.from(new Set(claims)),
        reason: "repeated-alternative-product-name",
      }
    : { conflict: false, claims: [], reason: null };
}

function universalEvidenceHasBoundedIdentityTerm(
  termRaw: string,
  evidenceRaw: string
): boolean {
  const term = normalizeMatchText(termRaw).trim();
  const evidence = normalizeMatchText(evidenceRaw);

  if (!term || !evidence) return false;

  // Numeric model generations must be bounded. This prevents an iPhone "15"
  // query from matching a review count, percentage or a number embedded in a
  // completely different model.
  if (/^\d{1,6}$/.test(term)) {
    const numeric = new RegExp(
      `(?:^|[^0-9])${escapeRegExp(term)}(?=$|[^0-9])`,
      "i"
    );
    return numeric.test(evidence);
  }

  if (/^[a-z0-9+\-]{2,32}$/.test(term)) {
    const token = new RegExp(
      `(?:^|[^a-z0-9])${escapeRegExp(term)}(?=$|[^a-z0-9])`,
      "i"
    );
    if (token.test(evidence)) return true;
  }

  // Model codes are written inconsistently across shops:
  // WH1000XM5, WH 1000XM5, AX-55/AX55. For concrete alphanumeric codes,
  // compare a punctuation-free representation as an additional safe path.
  if (isUniversalModelCodeToken(term)) {
    const compactTerm = compactUniversalModelCode(term);
    const compactEvidence = compactUniversalModelCode(evidence);
    if (compactTerm.length >= 4 && compactEvidence.includes(compactTerm)) {
      return true;
    }
  }

  return (
    evidence.includes(term) ||
    phraseMorphologicallyMatches(term, evidence)
  );
}

function cleanCeneoDirectResultName(valueRaw: string): string {
  let value = cleanTitle(decodeHtml(valueRaw));

  // Ceneo anchors often wrap the entire product tile. Keep only the actual
  // product name and cut review counts / prices / trend widgets that follow it.
  // This prevents model numbers from being "proved" by e.g. "(15) reviews".
  value = value
    .replace(/\s*\(\d{1,7}\)\s+(?=od\s|\d|najni[zż]sza|$)[\s\S]*$/iu, "")
    .replace(/\s+od\s+(?:\d{1,3}(?:[ .]\d{3})+|\d{1,7})(?:\s*[.,]\s*\d{1,2})?\s*(?:zł|pln)\b[\s\S]*$/iu, "")
    .replace(/\s+\d{1,3}\s*%\s+najni[zż]sza\s+cena[\s\S]*$/iu, "")
    .replace(/\s+najni[zż]sza\s+cena\s+z\s+30\s+dni[\s\S]*$/iu, "")
    .replace(/\s+produkty\s+z\s+trendem\s+cenowym[\s\S]*$/iu, "")
    .replace(/\s+/g, " ")
    .trim();

  return value.slice(0, 420);
}

function filterCeneoDirectCandidates(
  results: SearchResult[],
  parsed: ParsedQuery
): SearchResult[] {
  if (results.length === 0) return results;

  const platformIdentityTerm = normalizeMatchText(parsed.platform ?? "");
  const brandIdentityTerm = normalizeMatchText(parsed.brand ?? "");
  const softMerchandisingQualifierTerms = new Set(
    parsed.intent.qualifierTerms
      .filter(isSoftMerchandisingQualifierTerm)
      .map((term) => normalizeMatchText(term))
  );
  const effectiveStrongIdentityTerms = parsed.intent.strongIdentityTerms.filter((term) => {
    const normalized = normalizeMatchText(term);
    return (
      normalized !== platformIdentityTerm &&
      normalized !== brandIdentityTerm &&
      !isUniversalCategoryIdentityTerm(term, parsed) &&
      !softMerchandisingQualifierTerms.has(normalized)
    );
  });
  const modelLikeTerms = effectiveStrongIdentityTerms.filter((term) => /\d/.test(term));
  const nonNumericIdentityTerms = parsed.intent.identityTerms.filter((term) => {
    const normalized = normalizeMatchText(term);
    return (
      !/\d/.test(term) &&
      term.length >= 3 &&
      normalized !== platformIdentityTerm &&
      normalized !== brandIdentityTerm &&
      !softMerchandisingQualifierTerms.has(normalized)
    );
  });
  const brandAliases = getUniversalRequestedBrandAliases(parsed);
  const normalizedQuery = normalizeMatchText(parsed.queryText);
  const explicitBrand =
    brandAliases.length > 0 &&
    isBrandExplicitlyRequested(parsed.brand, parsed.queryText);
  const brandFamilyRequested =
    brandAliases.length > 0 &&
    brandAliases.some((alias) =>
      universalEvidenceHasBoundedIdentityTerm(alias, normalizedQuery)
    );
  const requireBrandFamilyInTitle = explicitBrand || brandFamilyRequested;
  const rejectionReasons = new Map<string, number>();
  const reject = (reason: string): false => {
    rejectionReasons.set(reason, (rejectionReasons.get(reason) ?? 0) + 1);
    return false;
  };

  const ceneoFamilyAlias = getCeneoExactModelFamilySearchAlias(parsed);
  if (ceneoFamilyAlias && results.length <= 24) {
    console.log(
      "[AIShopping] V34.CORE120 Ceneo local-card candidates:",
      results.slice(0, 12).map((result) => result.name)
    );
  }

  const filtered = results.filter((result) => {
    const title = normalizeMatchText(result.name);
    const localEvidence = normalizeMatchText(`${result.name} ${result.snippet}`);

    if (!isUsableCeneoDirectResultName(result.name)) {
      return reject("unusable-name");
    }

    const ownTitleHardConflict = parsed.intent.required.some(
      (requirement) =>
        requirement.hard &&
        hasConflictingHardRequirementInTitle(
          requirement,
          result.name,
          parsed.intent.required
        )
    );
    if (ownTitleHardConflict) return reject("own-title-hard-conflict");

    if (modelLikeTerms.length > 0) {
      const matchedModelTerms = modelLikeTerms.filter((term) =>
        universalEvidenceHasBoundedIdentityTerm(term, title)
      );
      if (matchedModelTerms.length < modelLikeTerms.length) {
        return reject("missing-model-identity");
      }
      if (
        nonNumericIdentityTerms.length > 0 &&
        !nonNumericIdentityTerms.some((term) =>
          openWorldIdentityTermMatches(term, title, parsed)
        )
      ) {
        return reject("missing-nonnumeric-identity");
      }
    }

    if (requireBrandFamilyInTitle) {
      const titleHasBrand = brandAliases.some((alias) =>
        universalEvidenceHasBoundedIdentityTerm(alias, title)
      );
      const localCardHasBrand = brandAliases.some((alias) =>
        universalEvidenceHasBoundedIdentityTerm(alias, localEvidence)
      );
      if (
        !titleHasBrand &&
        !localCardHasBrand &&
        !hasStrongBrandlessDiscoveryIdentity(
          result.name,
          result.snippet,
          result.url,
          parsed,
          result.source
        )
      ) {
        return reject("brand-family-mismatch");
      }
    }

    const classMatch = parsed.category
      ? hasUniversalCategoryEvidence(localEvidence, parsed)
      : false;
    const identityMatch = parsed.intent.identityTerms.some((term) =>
      !softMerchandisingQualifierTerms.has(normalizeMatchText(term)) &&
      openWorldIdentityTermMatches(term, title, parsed)
    );
    const strongIdentityMatch = effectiveStrongIdentityTerms.some((term) =>
      universalEvidenceHasBoundedIdentityTerm(term, title) ||
      titleContainsUniversalModelCode(title, term)
    );

    if (effectiveStrongIdentityTerms.length > 0 && !strongIdentityMatch) {
      return reject("missing-strong-identity");
    }

    const accepted = parsed.intent.openWorld
      ? identityMatch || strongIdentityMatch
      : classMatch || identityMatch || strongIdentityMatch;
    return accepted || reject("no-category-or-identity-anchor");
  });

  console.log(
    "[AIShopping] V34.CORE120 Ceneo local-card filter:",
    `${filtered.length}/${results.length}`,
    "query=",
    buildMarketplaceDiscoveryQuery(parsed),
    "rejections=",
    Object.fromEntries(rejectionReasons)
  );
  if (filtered.length === 0 && results.length > 0) {
    console.log(
      "[AIShopping] V34.CORE120 Ceneo rejected-card samples:",
      results.slice(0, 10).map((result) => ({
        name: result.name,
        url: result.url,
        snippet: normalizeText(result.snippet).slice(0, 220),
      }))
    );
  }

  return filtered;
}



function asOlxApiRecord(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function flattenOlxApiValue(value: unknown): string {
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return normalizeText(String(value));
  }

  if (Array.isArray(value)) {
    return normalizeText(value.map(flattenOlxApiValue).filter(Boolean).join(" "));
  }

  const record = asOlxApiRecord(value);
  if (!record) return "";

  const preferredKeys = [
    "label",
    "value",
    "key",
    "normalizedValue",
    "normalized_value",
    "name",
  ];
  const parts: string[] = [];

  for (const key of preferredKeys) {
    const nested = record[key];
    if (nested === undefined || nested === null) continue;
    if (typeof nested === "object" && nested === value) continue;
    const flattened = typeof nested === "object"
      ? (() => {
          const nestedRecord = asOlxApiRecord(nested);
          if (!nestedRecord) return flattenOlxApiValue(nested);
          return normalizeText(
            ["label", "value", "key", "normalizedValue", "normalized_value"]
              .map((nestedKey) => nestedRecord[nestedKey])
              .filter((item) => item !== undefined && item !== null)
              .map((item) => String(item))
              .join(" ")
          );
        })()
      : normalizeText(String(nested));
    if (flattened) parts.push(flattened);
  }

  return normalizeText(Array.from(new Set(parts)).join(" "));
}

function getOlxApiOfferArray(payload: unknown): unknown[] {
  const root = asOlxApiRecord(payload);
  if (!root) return [];

  if (Array.isArray(root.data)) return root.data;
  if (Array.isArray(root.offers)) return root.offers;

  const data = asOlxApiRecord(root.data);
  if (!data) return [];
  if (Array.isArray(data.offers)) return data.offers;

  const compatible = asOlxApiRecord(data.clientCompatibleListings);
  if (compatible && Array.isArray(compatible.data)) return compatible.data;

  const listing = asOlxApiRecord(data.listing);
  if (listing && Array.isArray(listing.ads)) return listing.ads;

  return [];
}

function getOlxApiPrice(offer: Record<string, unknown>): PriceInfo {
  const parseCurrency = (value: unknown): string | null => {
    if (typeof value !== "string") return null;
    return normalizeCurrency(value);
  };

  const parsePriceValue = (value: unknown): number | null => {
    if (typeof value === "number" && Number.isFinite(value) && value > 0) return value;
    if (typeof value !== "string") return null;
    const match = value.match(/(\d{1,3}(?:[ .]\d{3})+|\d{1,8})(?:\s*[.,]\s*(\d{1,2}))?/u);
    if (!match) return null;
    const whole = match[1]?.replace(/[ .]/g, "") ?? "";
    const cents = match[2] ? `.${match[2]}` : "";
    const parsed = Number(`${whole}${cents}`);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
  };

  const directPrice = asOlxApiRecord(offer.price);
  if (directPrice) {
    const regularPrice = asOlxApiRecord(directPrice.regularPrice);
    const price =
      parsePriceValue(directPrice.value) ??
      parsePriceValue(directPrice.label) ??
      parsePriceValue(directPrice.displayValue) ??
      parsePriceValue(regularPrice?.value) ??
      parsePriceValue(regularPrice?.label);
    const currency =
      parseCurrency(directPrice.currency) ??
      parseCurrency(regularPrice?.currency) ??
      (price !== null ? "PLN" : null);
    if (price !== null && currency) return { price, currency };
  }

  const params = Array.isArray(offer.params) ? offer.params : [];
  for (const paramRaw of params) {
    const param = asOlxApiRecord(paramRaw);
    if (!param) continue;
    const key = normalizeMatchText(String(param.key ?? param.name ?? ""));
    if (key !== "price" && key !== "cena") continue;

    const valueRecord = asOlxApiRecord(param.value);
    const price =
      parsePriceValue(valueRecord?.value) ??
      parsePriceValue(valueRecord?.label) ??
      parsePriceValue(param.value) ??
      parsePriceValue(param.normalizedValue) ??
      parsePriceValue(param.normalized_value);
    const currency =
      parseCurrency(valueRecord?.currency) ??
      parseCurrency(param.currency) ??
      (price !== null ? "PLN" : null);

    if (price !== null && currency) return { price, currency };
  }

  return { price: null, currency: null };
}

function getOlxApiCondition(offer: Record<string, unknown>): Condition {
  const directCondition = asOlxApiRecord(offer.condition);
  const directText = normalizeMatchText(
    `${directCondition?.key ?? ""} ${directCondition?.label ?? ""} ${offer.condition ?? ""}`
  );

  const fromText = (text: string): Condition => {
    const normalized = normalizeMatchText(text);
    if (/\b(?:used|uzywan\w*|refurbished|odnowion\w*)\b/iu.test(normalized)) return "used";
    if (/\b(?:new|now\w*|nieuzywan\w*|fabrycznie\s+now\w*)\b/iu.test(normalized) && !/\bjak\s+now\w*\b/iu.test(normalized)) return "new";
    return null;
  };

  const direct = fromText(directText);
  if (direct) return direct;

  const params = Array.isArray(offer.params) ? offer.params : [];
  for (const paramRaw of params) {
    const param = asOlxApiRecord(paramRaw);
    if (!param) continue;
    const key = normalizeMatchText(String(param.key ?? param.name ?? ""));
    const paramText = normalizeText(
      `${param.name ?? ""} ${param.key ?? ""} ${flattenOlxApiValue(param.value)} ${param.normalizedValue ?? ""} ${param.normalized_value ?? ""}`
    );
    if (!/(?:condition|state|stan|status)/iu.test(key) && !/\b(?:stan|condition)\b/iu.test(paramText)) continue;
    const condition = fromText(paramText);
    if (condition) return condition;
  }

  return null;
}

function getOlxApiCanonicalUrl(offer: Record<string, unknown>): string {
  const candidates = [offer.url, offer.offer_url, offer.offerUrl, offer.href];
  for (const candidate of candidates) {
    if (typeof candidate !== "string") continue;
    const raw = candidate.startsWith("/") ? `https://www.olx.pl${candidate}` : candidate;
    const normalized = normalizeUrl(raw);
    if (normalized && getResultHostname(normalized) === "olx.pl" && isProbablyRealOfferUrl(normalized)) {
      return normalized;
    }
  }
  return "";
}

function parseOlxPublicApiResponse(
  payload: unknown,
  parsed: ParsedQuery
): SearchResult[] {
  const offers = getOlxApiOfferArray(payload);
  const results: SearchResult[] = [];
  const seen = new Set<string>();

  for (const offerRaw of offers) {
    const offer = asOlxApiRecord(offerRaw);
    if (!offer) continue;

    const status = normalizeMatchText(String(offer.status ?? ""));
    if (status && !/\b(?:active|aktywn\w*)\b/iu.test(status)) continue;

    const url = getOlxApiCanonicalUrl(offer);
    if (!url || seen.has(url)) continue;

    const title = normalizeText(String(offer.title ?? offer.name ?? ""));
    if (!title) continue;

    const descriptionRaw = typeof offer.description === "string" ? offer.description : "";
    const description = normalizeText(stripHtml(descriptionRaw)).slice(0, 2600);
    const price = getOlxApiPrice(offer);
    const condition = getOlxApiCondition(offer);

    const params = Array.isArray(offer.params) ? offer.params : [];
    const paramText = normalizeText(
      params
        .map((paramRaw) => {
          const param = asOlxApiRecord(paramRaw);
          if (!param) return "";
          const name = normalizeText(String(param.name ?? param.key ?? ""));
          const value = flattenOlxApiValue(param.value ?? param.normalizedValue ?? param.normalized_value);
          return normalizeText(`${name}${name && value ? ": " : ""}${value}`);
        })
        .filter(Boolean)
        .join(" | ")
    ).slice(0, 1800);

    // V34.CORE121: OLX public JSON `params` are structured fields bound to
    // THIS concrete listing. Preserve only HARD keys explicitly evidenced by
    // those fields. The free-form seller description remains ineligible, so a
    // colour/size/spec mentioned in unrelated prose cannot become HARD proof.
    const structuredRequirementProofKeys = parsed.intent.required
      .filter((requirement) => requirement.hard)
      .filter((requirement) =>
        requirementHasEvidenceInContext(
          requirement,
          paramText,
          parsed.intent.required
        )
      )
      .map((requirement) => requirement.key);

    const priceText = price.price !== null && price.currency
      ? `Cena: ${price.price} ${price.currency}`
      : "";
    const conditionText = condition === "new"
      ? "Stan: Nowe"
      : condition === "used"
        ? "Stan: Używane"
        : "";

    const snippet = normalizeText(
      `AIOLXCARDSTART ${title} AIOLXRAWSTART ${title} ${priceText} ${conditionText} ${paramText} ${description} AIOLXCARDEND`
    ).slice(0, 6200);

    const candidate: SearchResult = {
      url,
      name: title,
      snippet,
      source: "OLXDirect",
      searchRank: results.length,
      catalogRequirementProofKeys: structuredRequirementProofKeys,
    };

    // API search can contain promoted/fuzzy neighbours. Keep discovery broad,
    // but move exact hard-identity candidates to the front before the global
    // per-engine cap so a correct offer cannot be pushed out by loose matches.
    const identity = evaluateUniversalProductMatch(
      candidate.name,
      candidate.snippet,
      candidate.url,
      parsed,
      "discovery",
      candidate.source
    );

    if (!identity.pass && identity.score < 42) continue;

    seen.add(url);
    results.push(candidate);
  }

  const hardRequirements = parsed.intent.required.filter((requirement) => requirement.hard);
  const priority = (result: SearchResult) => {
    const match = evaluateUniversalProductMatch(
      result.name,
      result.snippet,
      result.url,
      parsed,
      "discovery",
      result.source
    );
    const evidence = normalizeMatchText(`${result.name} ${result.snippet}`);
    const hardProofs = hardRequirements.filter((requirement) =>
      requirementHasEvidence(requirement, evidence)
    ).length;
    const condition = extractOlxDirectBoundCondition(result.snippet, result.name);
    const conditionFit = parsed.condition
      ? condition === parsed.condition
        ? 2
        : condition === null
          ? 1
          : 0
      : 1;
    const price = getSilentDiscoveryPrice(result, parsed).price;
    const budgetFit =
      price !== null && parsed.maxPrice !== null
        ? price <= parsed.maxPrice
          ? 2
          : 0
        : price !== null
          ? 1
          : 0;

    return { match, hardProofs, conditionFit, price, budgetFit };
  };

  return results
    .sort((a, b) => {
      const aPriority = priority(a);
      const bPriority = priority(b);
      if (bPriority.match.pass !== aPriority.match.pass) {
        return Number(bPriority.match.pass) - Number(aPriority.match.pass);
      }
      if (bPriority.hardProofs !== aPriority.hardProofs) {
        return bPriority.hardProofs - aPriority.hardProofs;
      }
      if (bPriority.conditionFit !== aPriority.conditionFit) {
        return bPriority.conditionFit - aPriority.conditionFit;
      }
      if (bPriority.budgetFit !== aPriority.budgetFit) {
        return bPriority.budgetFit - aPriority.budgetFit;
      }
      if (bPriority.match.score !== aPriority.match.score) {
        return bPriority.match.score - aPriority.match.score;
      }
      if ((aPriority.price !== null) !== (bPriority.price !== null)) {
        return aPriority.price !== null ? -1 : 1;
      }
      if (aPriority.price !== null && bPriority.price !== null && aPriority.price !== bPriority.price) {
        return aPriority.price - bPriority.price;
      }
      return a.searchRank - b.searchRank;
    })
    .slice(0, MAX_SEARCH_RESULTS_PER_ENGINE)
    .map((result, index) => ({ ...result, searchRank: index }));
}

function buildOlxPublicApiSearchQuery(parsed: ParsedQuery): string {
  return normalizeText(
    buildSurfacePreservingProductQueries(parsed)[0] ||
    buildUniversalPreciseDiscoveryCore(parsed) ||
    getCompactExactModelDiscoveryCore(parsed) ||
    parsed.intent.searchBase ||
    parsed.intent.productPhrase ||
    parsed.queryText
  );
}

async function searchOlxPublicJsonApi(
  parsed: ParsedQuery,
  queryRaw: string,
  signal?: AbortSignal
): Promise<SearchResult[]> {
  if (parsed.country !== "PL") return [];
  const query = normalizeText(queryRaw);
  if (!query) return [];

  const apiUrl =
    `https://www.olx.pl/api/v1/offers/?offset=0&limit=40&query=${encodeURIComponent(query)}` +
    `&filter_refiners=spell_checker&suggest_filters=true`;

  type OlxPublicApiAttempt = {
    status: number | null;
    payload: unknown | null;
    errorName: string | null;
  };

  const runAttempt = async (timeoutMs: number): Promise<OlxPublicApiAttempt> => {
    if (signal?.aborted) {
      return { status: null, payload: null, errorName: "AbortError" };
    }

    const attemptSignal = signal
      ? AbortSignal.any([signal, AbortSignal.timeout(timeoutMs)])
      : AbortSignal.timeout(timeoutMs);

    try {
      const response = await fetch(apiUrl, {
        cache: "no-store",
        signal: attemptSignal,
        headers: {
          Accept: "application/json, text/plain, */*",
          "Accept-Language": "pl-PL,pl;q=0.9,en;q=0.7",
          "User-Agent":
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36",
          Referer: "https://www.olx.pl/",
        },
      });

      if (!response.ok) {
        return {
          status: response.status,
          payload: null,
          errorName: null,
        };
      }

      return {
        status: response.status,
        payload: await response.json(),
        errorName: null,
      };
    } catch (error) {
      return {
        status: null,
        payload: null,
        errorName: error instanceof Error ? error.name : "unknown",
      };
    }
  };

  // V34.CORE123: the old single 3.3 s attempt could spend the whole lane on
  // one transient socket stall. Split the unchanged lane into two attempts.
  // Retry network/408/5xx only; 403/429 remain policy/rate-limit signals and a
  // healthy 200 with zero matching cards is a real parsed result, not a retry.
  let attempt = await runAttempt(1_850);
  const shouldRetry =
    !signal?.aborted &&
    attempt.payload === null &&
    (
      attempt.status === null ||
      attempt.status === 408 ||
      (attempt.status !== null && attempt.status >= 500)
    );

  if (shouldRetry) {
    console.log(
      "[AIShopping] V34.CORE123 OLX public JSON transient retry:",
      attempt.status ?? attempt.errorName ?? "network",
      "query=",
      query
    );
    await sleep(80, signal);
    if (!signal?.aborted) {
      attempt = await runAttempt(1_200);
    }
  }

  if (signal?.aborted) return [];

  if (attempt.payload === null) {
    console.log(
      "[AIShopping] V34.CORE123 OLX public JSON unavailable:",
      attempt.status ?? attempt.errorName ?? "network",
      "query=",
      query
    );
    return [];
  }

  const results = parseOlxPublicApiResponse(attempt.payload, parsed);

  console.log(
    "[AIShopping] V34.CORE123 OLX public JSON results:",
    results.length,
    "query=",
    query,
    "priced=",
    results.filter((result) => getSilentDiscoveryPrice(result, parsed).price !== null).length
  );

  return results;
}

const OLX_CATEGORY_SEARCH_BASES: Readonly<Record<string, string>> = {
  // Category-level routes only. These are not model/SKU shortcuts: OLX itself
  // indexes the same query much more reliably inside the correct taxonomy.
  // Keep the map conservative and expand it only when a stable OLX category
  // path is known.
  lens: "https://www.olx.pl/elektronika/fotografia/obiektywy/",
  guitar: "https://www.olx.pl/muzyka-edukacja/instrumenty/gitary/",
  chair: "https://www.olx.pl/dom-ogrod/meble/krzesla/",
  construction_toy: "https://www.olx.pl/dla-dzieci/zabawki/klocki/",
  phone: "https://www.olx.pl/elektronika/telefony/smartfony-telefony-komorkowe/",
  headphones: "https://www.olx.pl/elektronika/sprzet-audio/sluchawki/",
  perfume: "https://www.olx.pl/zdrowie-i-uroda/perfumy/",
};

function buildOlxCategoryScopedSearchUrl(
  parsed: ParsedQuery,
  slug: string
): string | null {
  if (!parsed.category || !slug) return null;

  const base = OLX_CATEGORY_SEARCH_BASES[parsed.category];
  if (!base) return null;

  return `${base}q-${encodeURIComponent(slug)}/`;
}

function buildCeneoPrimarySearchQuery(
  parsed: ParsedQuery,
  fallbackQueryRaw = ""
): string {
  // CORE78: relational minimum/maximum values are SEARCH HINTS only for
  // Ceneo. They improve the comparison engine's candidate set without
  // changing comparator semantics in final verification. A query hint of
  // 16GB/1TB/144Hz may still return and accept 32GB/2TB/165Hz.
  const relationalHintTerms = parsed.intent.required
    .filter((requirement) =>
      requirement.hard &&
      Boolean(requirement.comparison) &&
      !isRequirementDiscoverySearchEligible(requirement)
    )
    .slice(0, 3)
    .map(requirementDiscoveryHintTerm)
    .filter(Boolean);

  const baseQuery =
    buildUniversalExactDiscoveryQuery(parsed) ||
    normalizeText(fallbackQueryRaw) ||
    parsed.intent.searchBase ||
    parsed.intent.productPhrase;

  const normalizedBase = normalizeMatchText(baseQuery);
  const missingRelationalHints = relationalHintTerms.filter(
    (term) =>
      term &&
      !normalizedBase.includes(normalizeMatchText(term))
  );

  return normalizeText(
    `${baseQuery} ${missingRelationalHints.join(" ")}`
  );
}

function buildCeneoHardVariantSearchQuery(parsed: ParsedQuery): string {
  const hardTerms = parsed.intent.required
    .filter((requirement) => requirement.hard)
    .slice(0, 4)
    .map(requirementDiscoveryHintTerm)
    .filter(Boolean);

  if (hardTerms.length < 2) return "";

  return normalizeText(
    `${buildProductSearchBase(parsed)} ${hardTerms.join(" ")}`
  );
}

// V34.CORE120 RANGE-RELAXED + BUDGET-AWARE DISCOVERY
// Relational thresholds are verification constraints, not exact product
// identities. Search engines can misread a threshold as a model token or
// overfit to the exact number and miss products that are better than the
// requested minimum. Keep equality facts, omit relational numbers, and use
// the price ceiling only as a ranking hint. Final verification is unchanged.
function buildRangeRelaxedBudgetSearchQuery(parsed: ParsedQuery): string {
  const hardRequirements = parsed.intent.required.filter((item) => item.hard);
  const hasRelationalHard = hardRequirements.some((item) => {
    const comparison = universalRequirementComparison(item);
    return comparison === "gte" || comparison === "lte";
  });
  if (!hasRelationalHard) return "";

  const coverageCore = normalizeText(
    getUniversalCoverageDiscoveryCore(parsed) ||
    buildProductSearchBase(parsed) ||
    parsed.intent.searchBase ||
    parsed.intent.productPhrase
  );
  if (!coverageCore) return "";

  const semanticIdentity =
    buildSemanticProductIdentityDiscoveryAlternates(parsed, coverageCore)[0] ||
    buildProductSearchBase(parsed) ||
    coverageCore;

  const normalizedIdentity = normalizeMatchText(semanticIdentity);
  const equalityTerms = hardRequirements
    .filter((item) => universalRequirementComparison(item) === "eq")
    .map(requirementDiscoveryHintTerm)
    .filter(Boolean)
    .filter((term) => !normalizedIdentity.includes(normalizeMatchText(term)))
    .slice(0, 4);

  const budgetHint =
    Number.isFinite(parsed.maxPrice) && Number(parsed.maxPrice) > 0
      ? parsed.country === "PL"
        ? `do ${Math.floor(Number(parsed.maxPrice))} zl`
        : `under ${Math.floor(Number(parsed.maxPrice))}`
      : "";

  return normalizeText(
    `${semanticIdentity} ${equalityTerms.join(" ")} ${budgetHint}`
  );
}

function buildCeneoStableLaptopFacetUrl(parsed: ParsedQuery): string | null {
  if (parsed.category !== "laptop") return null;

  const gpuRequirement = parsed.intent.required.find((requirement) =>
    requirement.hard &&
    requirement.key === "gpu_model" &&
    universalRequirementComparison(requirement) === "eq"
  );
  if (!gpuRequirement) return null;

  const value = normalizeText(gpuRequirement.value).toUpperCase();
  if (!value) return null;

  let facetValue = "";

  const nvidia = value.match(
    /\b(?:NVIDIA\s+)?(?:GEFORCE\s+)?(RTX|GTX)\s*([0-9]{3,4})(?:\s*(TI|SUPER))?\b/i
  );
  if (nvidia) {
    facetValue = `GeForce_${nvidia[1].toUpperCase()}_${nvidia[2]}${
      nvidia[3] ? `_${nvidia[3].toUpperCase()}` : ""
    }`;
  }

  if (!facetValue) {
    const amd = value.match(
      /\b(?:AMD\s+)?(?:RADEON\s+)?RX\s*([0-9]{4})(?:\s*(XT|XTX|M|S))?\b/i
    );
    if (amd) {
      facetValue = `Radeon_RX_${amd[1]}${
        amd[2] ? `_${amd[2].toUpperCase()}` : ""
      }`;
    }
  }

  if (!facetValue) {
    const intel = value.match(
      /\b(?:INTEL\s+)?ARC\s*([A-Z][0-9]{3})\b/i
    );
    if (intel) facetValue = `Arc_${intel[1].toUpperCase()}`;
  }

  if (!facetValue) return null;

  // V34.CORE120: Ceneo exposes stable category facets for exact GPU models.
  // This is a source-adapter acceleration only: it is generated from the
  // parsed generic gpu_model requirement, never a benchmark SKU/price/product.
  // Relational RAM/storage/refresh requirements are intentionally NOT encoded
  // as exact facets because doing so could hide valid 32GB/2TB/165Hz offers.
  return `https://www.ceneo.pl/Laptopy/${encodeURIComponent(
    `Model_karty_graficznej:${facetValue}`
  )}.htm`;
}

function buildCeneoStablePhoneFacetUrl(parsed: ParsedQuery): string | null {
  if (parsed.category !== "phone" || !parsed.brand) return null;

  const storageRequirement = parsed.intent.required.find((requirement) =>
    requirement.hard &&
    requirement.key === "storage" &&
    universalRequirementComparison(requirement) === "eq"
  );
  if (!storageRequirement) return null;

  const storageGb = parseUniversalCapacityToGb(storageRequirement.value);
  if (storageGb === null || !Number.isFinite(storageGb) || storageGb <= 0) return null;
  const roundedStorageGb = Math.round(storageGb);
  if (Math.abs(storageGb - roundedStorageGb) > 0.001) return null;

  const brandFacet = normalizeMatchText(parsed.brand)
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("_");
  if (!brandFacet) return null;

  // Broad brand+storage facet is intentionally NOT an exact model shortcut.
  // It improves recall when Ceneo's text-search landing is empty; the normal
  // product/model/variant verifier still decides which cards may pass.
  return `https://www.ceneo.pl/Smartfony/${encodeURIComponent(`p:${brandFacet}`)}/${encodeURIComponent(
    `Pamiec_wewnetrzna:${roundedStorageGb}_GB`
  )}.htm`;
}

async function searchDirectMarketplacePages(
  parsed: ParsedQuery,
  externalSignal?: AbortSignal,
  onPartialResults?: (results: SearchResult[]) => void
): Promise<SearchResult[]> {
  if (parsed.country !== "PL") return [];

  const relaxedProductQuery = buildMarketplaceDiscoveryQuery(parsed);
  const preciseProductQuery = buildUniversalPreciseDiscoveryCore(parsed);
  const attributeAwareProductQuery =
    getUniversalPreciseDiscoveryRequirements(parsed).length > 0
      ? preciseProductQuery
      : relaxedProductQuery;

  // V34.CORE120: never collapse an already parsed product/variant to a broader
  // platform family. The precise surface may carry V2, Pro/Max, generation,
  // memory or another distinction needed by marketplace search.
  const productQuery = attributeAwareProductQuery;

  const canonicalSlugQuery = productQuery;

  // V32.12: direct marketplaces get both the user's cleaned surface form and
  // normalized technical aliases. This preserves distinctions in marketplace
  // indexing such as 50mm/50 mm, 18V/18 V and 15kg/15 kg while the local
  // verifier still enforces the same structured requirements afterwards.
  const surfaceMarketplaceQueries = buildSurfacePreservingProductQueries(parsed);
  const primaryMarketplaceQuery = surfaceMarketplaceQueries[0] || productQuery;

  const conditionAwareMarketplaceQueries =
    parsed.condition === "used"
      ? [
          `${primaryMarketplaceQuery} używany`,
          `${primaryMarketplaceQuery} stan używany`,
        ]
      : parsed.condition === "new"
        ? [
            `${primaryMarketplaceQuery} nowy`,
            `${primaryMarketplaceQuery} stan nowy`,
          ]
        : [];

  const uniqueSearchQueries = (values: string[], limit: number): string[] => {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const valueRaw of values) {
      const value = normalizeText(valueRaw);
      const key = normalizeMatchText(value);
      if (!value || !key || seen.has(key)) continue;
      seen.add(key);
      out.push(value);
      if (out.length >= limit) break;
    }
    return out;
  };

  // V32.12: one direct Allegro Lokalnie landing per search. Multiple parallel
  // same-host landings caused avoidable HTTP 429 bursts. Prefer the precise,
  // surface-preserving product query; condition is still enforced during
  // discovery/verification, so recall is not tied to a seller writing "nowy"
  // in the title. This is universal and applies to every category.
  const originalAwareMarketplaceQuery = parsed.original === true
    ? normalizeText(`${primaryMarketplaceQuery} oryginalny`)
    : "";
  const peerMarketplaceQuery = normalizeText(
    `${primaryMarketplaceQuery} ${parsed.condition === "new" ? "nowy" : parsed.condition === "used" ? "uzywany" : ""} ${parsed.original === true ? "oryginalny" : ""}`
  );

  const constraintSeparatedMarketplaceQuery =
    buildConstraintSeparatedMarketplaceDiscoveryQuery(parsed);

  // V34.CORE120: exact-model marketplace discovery starts from the compact
  // brand+model identity, not from the full natural-language product surface.
  // Real marketplaces often return zero cards for a verbose class+model phrase
  // even though the same exact model has live offers. Constraints and product
  // class remain strict downstream filters; they do not belong in the landing
  // query when a concrete model identity is already known.
  const directMarketplaceIdentityCore = normalizeText(
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed) ||
    ""
  );
  const allegroLokalnieQueries = uniqueSearchQueries([
    directMarketplaceIdentityCore,
    constraintSeparatedMarketplaceQuery,
    ...surfaceMarketplaceQueries,
    productQuery,
    relaxedProductQuery,
    peerMarketplaceQuery,
    ...conditionAwareMarketplaceQueries,
    originalAwareMarketplaceQuery,
    ...buildCategorySynonymDiscoveryQueries(parsed),
  ], 1);


  if (surfaceMarketplaceQueries.length > 0) {
    console.log(
      "[AIShopping] V34.CORE120 surface-preserving marketplace aliases:",
      surfaceMarketplaceQueries
    );
  }

  const compactExactModelCore = getCompactExactModelDiscoveryCore(parsed);
  const namedVariantDiscoveryCore = getNamedVariantDiscoveryCore(parsed);
  const discoveryModelCore = compactExactModelCore || namedVariantDiscoveryCore;
  const compactExactModelCodeAlias = getCompactExactModelCodeAlias(parsed);
  const standaloneExactModelTokenAlias = getStandaloneExactModelTokenAlias(parsed);
  const ceneoNamedVariantAlias = getCeneoNamedVariantSearchAlias(parsed);
  const ceneoExactModelFamilyAlias =
    getCeneoExactModelFamilySearchAlias(parsed);
  const compactMarketplaceQuery =
    discoveryModelCore || primaryMarketplaceQuery || canonicalSlugQuery;

  if (discoveryModelCore) {
    console.log(
      "[AIShopping] V34.CORE120 exact-model discovery aliases:",
      {
        core: compactExactModelCore || null,
        variantCore: namedVariantDiscoveryCore || null,
        code: compactExactModelCodeAlias || null,
        standaloneCode: standaloneExactModelTokenAlias || null,
        ceneoVariant: ceneoNamedVariantAlias || null,
        ceneoFamily: ceneoExactModelFamilyAlias || null,
      }
    );
  }

  const slug = compactMarketplaceQuery
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "");
  const peerSlug = (peerMarketplaceQuery || compactMarketplaceQuery)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "");
  const constraintSeparatedMarketplaceSlug =
    (constraintSeparatedMarketplaceQuery || compactMarketplaceQuery)
      .toLowerCase()
      .replace(/[^\p{L}\p{N}]+/gu, "-")
      .replace(/^-+|-+$/g, "");

  const allegroLokalnieSeoLandingUrls: string[] = [];


  const highCounterfeitCautionLane =
    parsed.original === true && parsed.category === "perfume";

  // V34.CORE120: category-scoped OLX is useful, but real traffic shows that a
  // taxonomy landing and a generic landing can fail independently. Build one
  // generic fallback from the user-visible product surface. When hard variant
  // requirements exist, keep them in that fallback (e.g. storage/color or
  // volume/type) instead of collapsing to an overly broad model token.
  const hasOlxCategoryRoute = Boolean(
    parsed.category && OLX_CATEGORY_SEARCH_BASES[parsed.category]
  );
  const hasHardMarketplaceRequirements = parsed.intent.required.some(
    (requirement) => requirement.hard
  );
  const olxGenericFallbackQuery = normalizeText(
    hasHardMarketplaceRequirements
      ? (surfaceMarketplaceQueries[0] || preciseProductQuery || compactMarketplaceQuery)
      : compactMarketplaceQuery
  );
  const olxGenericFallbackSlug = olxGenericFallbackQuery
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "");
  const shouldAddGenericOlxFallback = Boolean(
    hasOlxCategoryRoute &&
    olxGenericFallbackSlug &&
    (compactExactModelCore || hasHardMarketplaceRequirements || highCounterfeitCautionLane)
  );

  // V34.CORE120: exact-model searches may need a compact generic OLX landing
  // even when the category-aware/full-surface landing is empty or throttled.
  // Only add it when all non-class hard requirements are already encoded in
  // the model identity; storage/color/size/volume variants therefore keep the
  // more precise surface query while model-contained voltage/code terms can
  // safely use the compact fallback.
  const normalizedDiscoveryModelCore = normalizeMatchText(discoveryModelCore || "");
  const hasUnencodedHardMarketplaceRequirement = parsed.intent.required.some((requirement) => {
    if (!requirement.hard || requirement.key === "tool_type") return false;
    const aliases = [requirement.value, ...requirement.aliases]
      .map((alias) => normalizeMatchText(alias))
      .filter(Boolean);
    return !aliases.some((alias) => normalizedDiscoveryModelCore.includes(alias));
  });
  const olxCompactExactFallbackSlug = (discoveryModelCore || "")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "");
  const shouldAddCompactExactOlxFallback = Boolean(
    discoveryModelCore &&
    olxCompactExactFallbackSlug &&
    !hasUnencodedHardMarketplaceRequirement &&
    olxCompactExactFallbackSlug !== constraintSeparatedMarketplaceSlug &&
    olxCompactExactFallbackSlug !== olxGenericFallbackSlug
  );

  // CORE78: `/oferty/<slug>` is a promotional/offers landing on current Ceneo,
  // not a reliable query-result route. Live CORE78 returned 15 completely
  // unrelated cards from that path even though the URL contained the requested
  // laptop terms. Use Ceneo's real search landing for EVERY ordinary direct
  // query, carrying the parsed product identity plus hard discovery terms.
  // Final merchant/spec/condition/price gates remain unchanged.
  const ceneoPrimarySearchQuery = buildCeneoPrimarySearchQuery(
    parsed,
    constraintSeparatedMarketplaceQuery ||
      primaryMarketplaceQuery ||
      compactMarketplaceQuery
  );
  const ceneoHardVariantSearchQuery =
    !discoveryModelCore &&
    parsed.intent.required.filter((requirement) => requirement.hard).length >= 2
      ? buildCeneoHardVariantSearchQuery(parsed)
      : "";
  const ceneoRangeRelaxedBudgetSearchQuery =
    !discoveryModelCore
      ? buildRangeRelaxedBudgetSearchQuery(parsed)
      : "";
  const ceneoStableFacetUrl = buildCeneoStableLaptopFacetUrl(parsed);
  const ceneoStablePhoneFacetUrl = buildCeneoStablePhoneFacetUrl(parsed);

  const urls: Array<{
    source: string;
    url: string;
  }> = [
    {
      source: "AllegroDirect",
      url:
        "https://allegro.pl/listing?string=" +
        encodeURIComponent(
          constraintSeparatedMarketplaceQuery ||
          primaryMarketplaceQuery ||
          peerMarketplaceQuery
        ),
    },

    ...allegroLokalnieQueries.map(
      (query) => ({
        source: "AllegroLokalnieDirect",
        url:
          "https://allegrolokalnie.pl/oferty/q/" +
          encodeURIComponent(query),
      })
    ),

    ...allegroLokalnieSeoLandingUrls.map(
      (url) => ({
        source: "AllegroLokalnieDirect",
        url,
      })
    ),

    {
      source: "OLXDirect",
      url:
        // For an exact construction-set model code, a broad Dla Dzieci route
        // keeps the correct taxonomy while the compact brand+model anchor
        // avoids a fragile, over-specific landing.
        (parsed.category === "construction_toy" && compactExactModelCore
          ? `https://www.olx.pl/dla-dzieci/q-${encodeURIComponent(slug)}/`
          : buildOlxCategoryScopedSearchUrl(
              parsed,
              constraintSeparatedMarketplaceSlug || peerSlug
            )) ??
        ("https://www.olx.pl/oferty/q-" +
          encodeURIComponent(constraintSeparatedMarketplaceSlug || peerSlug) +
          "/"),
    },

    // V34.CORE120 OLX source redundancy: category and generic landings are
    // independently throttled/slow. Race one generic surface-preserving
    // landing whenever the request has an exact model or hard variant
    // requirements. This is discovery-only; downstream identity/spec/state
    // and originality gates remain unchanged.
    ...(shouldAddGenericOlxFallback
      ? [{
          source: "OLXDirect",
          url: `https://www.olx.pl/oferty/q-${encodeURIComponent(olxGenericFallbackSlug)}/`,
        }]
      : []),

    ...(shouldAddCompactExactOlxFallback
      ? [{
          source: "OLXDirect",
          url: `https://www.olx.pl/oferty/q-${encodeURIComponent(olxCompactExactFallbackSlug)}/`,
        }]
      : []),

    {
      source: "CeneoDirect",
      url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
        ceneoPrimarySearchQuery || compactMarketplaceQuery
      )}`,
    },

    // V34.CORE120: comparison search landings can be parser-empty for a quoted
    // phrase while the same query without quoting returns concrete products.
    // Race exactly one unquoted, query-derived hard-variant landing for
    // non-exact-model searches. This is discovery only; every candidate still
    // passes the unchanged product/HARD/price/availability verifier.
    ...(ceneoHardVariantSearchQuery &&
        normalizeMatchText(ceneoHardVariantSearchQuery) !==
          normalizeMatchText(ceneoPrimarySearchQuery)
      ? [{
          source: "CeneoDirect",
          url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
            ceneoHardVariantSearchQuery
          )}`,
        }]
      : []),

    // V34.CORE120: one range-relaxed, price-aware comparison landing.
    // It is discovery only; all original HARD, budget, availability and
    // condition checks still run on concrete offers.
    ...(ceneoRangeRelaxedBudgetSearchQuery &&
        normalizeMatchText(ceneoRangeRelaxedBudgetSearchQuery) !==
          normalizeMatchText(ceneoPrimarySearchQuery) &&
        normalizeMatchText(ceneoRangeRelaxedBudgetSearchQuery) !==
          normalizeMatchText(ceneoHardVariantSearchQuery)
      ? [{
          source: "CeneoDirect",
          url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
            ceneoRangeRelaxedBudgetSearchQuery
          )}`,
        }]
      : []),

    // V34.CORE120: current Ceneo search and category-facet surfaces can fail
    // independently. For laptop queries with an exact GPU model, run one
    // stable, query-derived facet landing in parallel. It is still discovery
    // only; product identity, relational HARD values, price and availability
    // remain subject to the ordinary verifier.
    ...(ceneoStableFacetUrl
      ? [{ source: "CeneoDirect", url: ceneoStableFacetUrl }]
      : []),

    ...(ceneoStablePhoneFacetUrl
      ? [{ source: "CeneoDirect", url: ceneoStablePhoneFacetUrl }]
      : []),

    // V32.12 exact-model rescue: Ceneo frequently resolves the compact model
    // code much better than a full natural-language slug. This is still only
    // discovery; merchant identity/accessory/condition/price gates are unchanged.
    ...(compactExactModelCore
      ? [{
          source: "CeneoDirect",
          url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
            compactExactModelCodeAlias || slug
          )}`,
        }]
      : []),

    // V32.12 exact-model phrase rescue: retailer/comparison search engines do
    // not always index a concatenated code such as "loq15irx9" even when the
    // human-readable model family "Lenovo LOQ 15IRX9" has concrete product
    // pages. Query the full compact discovery core as an independent path.
    // This is discovery-only and never weakens final model/spec/price gates.
    ...(compactExactModelCore
      ? [{
          source: "CeneoDirect",
          url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
            compactExactModelCore
          )}`,
        }]
      : []),

    // Also try the strongest standalone model token when it differs from the
    // legacy compact manufacturer code. This preserves ECAM/LEGO/S24 behavior
    // while adding a generic route for family+chassis forms like LOQ 15IRX9.
    ...(standaloneExactModelTokenAlias &&
        normalizeMatchText(standaloneExactModelTokenAlias) !==
          normalizeMatchText(compactExactModelCodeAlias)
      ? [{
          source: "CeneoDirect",
          url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
            standaloneExactModelTokenAlias
          )}`,
        }]
      : []),

    // V32.12 named-variant rescue: some families have no strong SKU token
    // but are indexed precisely by family + generation/version (for example
    // "DualShock 4 V2"). This is discovery only; final identity gates stay strict.
    ...(ceneoNamedVariantAlias && !compactExactModelCore
      ? [{
          source: "CeneoDirect",
          url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
            ceneoNamedVariantAlias
          )}`,
        }]
      : []),

    // V32.12 exact-model family rescue: code-only Ceneo search pages can be
    // dominated by spare parts that merely mention the target model. When the
    // query also contains a named family/line, issue one additional bounded
    // Ceneo search using brand + family + compact model code. Final identity,
    // accessory, condition and budget gates remain unchanged.
    ...(ceneoExactModelFamilyAlias
      ? [{
          source: "CeneoDirect",
          url: `https://www.ceneo.pl/;szukaj-${encodeURIComponent(
            ceneoExactModelFamilyAlias
          )}`,
        }]
      : []),
  ];

  const ceneoReaderFallbackUrl =
    ceneoStableFacetUrl ||
    urls.find((entry) => entry.source === "CeneoDirect")?.url ||
    null;

  if (highCounterfeitCautionLane) {
    console.log(
      "[AIShopping] V34.CORE120 high-counterfeit marketplace caution lane enabled: peer offers require strict verification and cannot win with low originality"
    );
  }

  const olxDirectUrl = urls.find((entry) => entry.source === "OLXDirect")?.url ?? null;
  // V34.CORE123: redundant OLX landings keep independent direct+retry lanes,
  // but only the primary landing may occupy the globally throttled Jina queue.
  // OLX public JSON is already a third independent lane. This prevents two
  // failing OLX landings from starving Allegro Lokalnie's single reader slot.
  const olxReaderFallbackUrl = olxDirectUrl;
  const olxCategoryScoped = Boolean(
    olxDirectUrl &&
    parsed.category &&
    OLX_CATEGORY_SEARCH_BASES[parsed.category]
  );

  if (olxDirectUrl) {
    console.log(
      "[AIShopping] V34.CORE120 OLX discovery route:",
      olxCategoryScoped ? "category-scoped" : "generic",
      parsed.category ?? "unknown",
      olxDirectUrl
    );
  }

  console.log(
    "[AIShopping] V34.CORE120 direct marketplace URLs:",
    urls
  );

  // Only one Allegro Lokalnie landing page is allowed to use the reader
  // fallback. Some queries generate both a precise and relaxed URL; letting
  // both fall back simultaneously would waste the global discovery budget and
  // increase the chance of reader throttling.
  const allegroLokalnieReaderFallbackUrl =
    urls.find((entry) => entry.source === "AllegroLokalnieDirect")?.url ?? null;

  const processSource = async (
    source: string,
    url: string,
    sourceSignal: AbortSignal | undefined = externalSignal
  ): Promise<SearchResult[]> => {
    try {
      let parsedResults: SearchResult[] = [];
      let directStatus: number | null = null;
      type DirectHtmlResponse = {
        status: number;
        html: string;
        finalUrl: string;
      };
      let transientDirectRetryPromise: Promise<DirectHtmlResponse | null> | null = null;

      const parseDirectResponse = (
        direct: DirectHtmlResponse,
        lane: "primary" | "transient-retry"
      ): SearchResult[] => {
        if (direct.status >= 400 || !direct.html) return [];

        const htmlResults =
          source === "OLXDirect"
            ? parseOlxDirectHtml(
                direct.html,
                direct.finalUrl || url
              )
            : parseDirectMarketplaceHtml(
                direct.html,
                direct.finalUrl || url,
                source
              );

        const embeddedResults =
          source === "AllegroLokalnieDirect"
            ? parseAllegroLokalnieEmbeddedHtml(
                direct.html,
                direct.finalUrl || url
              )
            : [];

        let combined = [
          ...htmlResults,
          ...embeddedResults,
        ];

        if (source === "CeneoDirect") {
          combined = filterCeneoDirectCandidates(combined, parsed);
        }

        console.log(
          lane === "primary"
            ? "[AIShopping] V34.CORE123 direct HTML results:"
            : "[AIShopping] V34.CORE123 direct HTML transient retry results:",
          source,
          htmlResults.length,
          "embedded=",
          embeddedResults.length,
          "status=",
          direct.status
        );

        return combined;
      };

      const collectTransientDirectRetry = async (): Promise<number> => {
        const retryPromise = transientDirectRetryPromise;
        transientDirectRetryPromise = null;
        if (!retryPromise) return 0;

        const retry = await retryPromise;
        if (sourceSignal?.aborted) return 0;

        if (retry && retry.status < 400 && retry.html) {
          const retryResults = parseDirectResponse(retry, "transient-retry");
          parsedResults = [
            ...parsedResults,
            ...retryResults,
          ];
          return retryResults.length;
        }

        console.log(
          "[AIShopping] V34.CORE123 direct HTML transient retry unavailable:",
          source,
          retry?.status ?? "network"
        );
        return 0;
      };

      const canUseDirectHtml =
        source === "AllegroDirect" ||
        source === "AllegroLokalnieDirect" ||
        source === "OLXDirect" ||
        source === "CeneoDirect";

      if (canUseDirectHtml) {
        const direct = await fetchHtml(
          url,
          source === "OLXDirect"
            ? 1_450
            : source === "AllegroLokalnieDirect"
              ? 1_550
              : source === "CeneoDirect"
                ? 3_500
                : 3_800,
          sourceSignal
        );
        directStatus = direct?.status ?? null;

        // V34.CORE120: once the direct-marketplace phase is cancelled, skip
        // synchronous card extraction from a response that arrived too late.
        if (sourceSignal?.aborted) return [];

        if (direct && direct.status < 400 && direct.html) {
          parsedResults = parseDirectResponse(direct, "primary");
        } else {
          console.log(
            "[AIShopping] V34.CORE123 direct HTML unavailable:",
            source,
            direct?.status ?? "network"
          );
        }

        const directFailureIsTransient =
          !direct ||
          direct.status === 408 ||
          direct.status >= 500;
        const sourceHasBoundedRetryLane =
          source === "OLXDirect" ||
          (
            source === "AllegroLokalnieDirect" &&
            url === allegroLokalnieReaderFallbackUrl
          );

        // V34.CORE123: start one shorter direct retry now, but do not await it
        // serially. The source's existing reader fallback below races it, so a
        // dead socket cannot consume the reader window and neither attempt can
        // extend the 6.15 s outer marketplace phase.
        if (
          parsedResults.length === 0 &&
          directFailureIsTransient &&
          sourceHasBoundedRetryLane &&
          !sourceSignal?.aborted
        ) {
          transientDirectRetryPromise = (async () => {
            await sleep(120, sourceSignal);
            if (sourceSignal?.aborted) return null;
            return fetchHtml(
              url,
              source === "OLXDirect" ? 1_250 : 1_350,
              sourceSignal
            );
          })();
        }
      }

      // V34.CORE120 Allegro Lokalnie resilience: 403/429/network still use the
      // single bounded reader fallback, but so does a 200 page that yielded
      // zero cards for a concrete product identity. A 200/0 can mean parser
      // drift/application-state rendering, not an actually empty marketplace.
      const deferSlowAllegroLokalnieReaderForHighConstraint =
        source === "AllegroLokalnieDirect" &&
        isV34Core164HighConstraintRetailIntent(parsed);
      const shouldUseAllegroLokalnieReader =
        source === "AllegroLokalnieDirect" &&
        !deferSlowAllegroLokalnieReaderForHighConstraint &&
        shouldUseAllegroLokalnieReaderOnEmptyDirectPage(
          parsed,
          directStatus,
          parsedResults.length,
          url === allegroLokalnieReaderFallbackUrl
        );

      if (
        deferSlowAllegroLokalnieReaderForHighConstraint &&
        parsedResults.length === 0
      ) {
        await collectTransientDirectRetry();
        console.log(
          "[AIShopping] V34.CORE166 Allegro Lokalnie slow reader deferred for high-constraint retail intent:",
          url,
          "results=",
          parsedResults.length
        );
      }

      if (shouldUseAllegroLokalnieReader) {
        const [markdown] = await Promise.all([
          withDeadline(
            fetchViaJina(
              url,
              4_000,
              false,
              sourceSignal
            ),
            4_300,
            "",
            `direct Jina ${source}`
          ),
          collectTransientDirectRetry(),
        ]);

        if (sourceSignal?.aborted) return parsedResults;

        if (markdown && !isBlockedOrChallengePage(markdown)) {
          const markdownResults = parseDirectMarketplaceMarkdown(
            markdown,
            source
          );

          parsedResults = [
            ...parsedResults,
            ...markdownResults,
          ];

          console.log(
            "[AIShopping] V34.CORE120 direct Jina rescue results:",
            source,
            markdownResults.length,
            "afterStatus=",
            directStatus ?? "network"
          );
        } else {
          console.log(
            "[AIShopping] V34.CORE120 direct Jina rescue unavailable:",
            source,
            "afterStatus=",
            directStatus ?? "network"
          );
        }
      }

      const shouldUseCeneoReader =
        source === "CeneoDirect" &&
        shouldUseCeneoReaderOnEmptyDirectPage(
          directStatus,
          parsedResults.length,
          Boolean(ceneoReaderFallbackUrl && url === ceneoReaderFallbackUrl)
        );

      if (shouldUseCeneoReader) {
        // V34.CORE120: a parser-empty Ceneo page first uses a search-index path
        // that can recover concrete /productId URLs without waiting for a full
        // reader render. This is strictly discovery-only: recovered URLs still
        // pass the ordinary Ceneo product, merchant, HARD, price, condition and
        // availability verification. Only if the index path yields nothing do
        // we spend the slower bounded reader retry.
        const indexedResults = await withDeadline(
          searchCeneoIndexedEmptyPageFallback(
            parsed,
            1_950,
            sourceSignal
          ),
          2_050,
          [] as SearchResult[],
          `Ceneo indexed ${source} empty-page rescue`
        );

        if (sourceSignal?.aborted) return parsedResults;

        if (indexedResults.length > 0) {
          parsedResults = indexedResults;
          console.log(
            "[AIShopping] V34.CORE120 Ceneo indexed rescue selected:",
            indexedResults.length,
            "afterStatus=",
            directStatus ?? "network",
            url
          );
        } else if (shouldV34Core164SkipCeneoEmptyPageReader(parsed)) {
          console.log(
            "[AIShopping] V34.CORE164 Ceneo empty-page reader skipped for high-constraint retail intent:",
            url
          );
        } else {
          // One bounded reader retry only after the independent index path is
          // empty. Keep it shorter than CORE81 because verification/recovery
          // are more valuable than waiting on a repeatedly slow reader.
          const markdown = await withDeadline(
            fetchViaJina(
              url,
              1_650,
              false,
              sourceSignal
            ),
            1_850,
            "",
            `direct Jina ${source} empty-page rescue`
          );

          if (sourceSignal?.aborted) return parsedResults;

          const readerResults = parseCeneoReaderRecoveryResults(
            markdown,
            parsed
          );

          if (readerResults.length > 0) {
            parsedResults = readerResults;
            console.log(
              "[AIShopping] V34.CORE120 Ceneo reader empty-page rescue:",
              readerResults.length,
              "afterStatus=",
              directStatus ?? "network",
              url
            );
          } else {
            console.log(
              "[AIShopping] V34.CORE120 Ceneo empty-page rescue unavailable:",
              "afterStatus=",
              directStatus ?? "network",
              url
            );
          }
        }
      }

      // V32.12 OLX resilience: try the category/search HTML first. When it
      // already exposes concrete listing URLs we preserve those candidates and
      // do not spend several more seconds on the reader. Only an empty HTML
      // parse falls back to Jina. This removes a single-reader dependency while
      // keeping the existing Jina path as a safety net.
      if (source === "OLXDirect") {
        if (parsedResults.length > 0) {
          console.log(
            "[AIShopping] V34.CORE120 skipped OLX Jina landing; direct HTML cards available:",
            parsedResults.length
          );
        } else if (url !== olxReaderFallbackUrl) {
          await collectTransientDirectRetry();
          console.log(
            parsedResults.length > 0
              ? "[AIShopping] V34.CORE123 secondary OLX direct retry recovered:"
              : "[AIShopping] V34.CORE123 skipped duplicate OLX Jina landing:",
            url,
            "results=",
            parsedResults.length
          );
        } else {
          const jinaTimeout = 4_250;
          const jinaDeadline = 4_500;

          const [markdown] = await Promise.all([
            withDeadline(
              fetchViaJina(
                url,
                jinaTimeout,
                true,
                sourceSignal
              ),
              jinaDeadline,
              "",
              `direct Jina ${source}`
            ),
            collectTransientDirectRetry(),
          ]);

          if (sourceSignal?.aborted) return parsedResults;

          if (
            markdown &&
            !isBlockedOrChallengePage(markdown)
          ) {
            const markdownResults =
              parseDirectMarketplaceMarkdown(
                markdown,
                source
              );

            parsedResults = [
              ...parsedResults,
              ...markdownResults,
            ];

            console.log(
              "[AIShopping] V34.CORE120 direct Jina results:",
              source,
              markdownResults.length
            );
          } else {
            console.log(
              "[AIShopping] V34.CORE120 direct marketplace unavailable:",
              source,
              url
            );
          }
        }
      }

      console.log(
        "[AIShopping] V34.CORE120 direct marketplace combined:",
        source,
        parsedResults.length,
        url
      );

      return parsedResults;
    } catch (error) {
      console.error(
        "[AIShopping] V34.CORE120 direct marketplace error:",
        source,
        error
      );
      return [];
    }
  };

  // Each source settles independently. Exact-model OLX intentionally has two
  // redundant landings, but waiting for BOTH after one already returned a full
  // concrete result set only burns discovery time. Race OLX redundancy and keep
  // the first useful landing; every distinct non-OLX source still runs normally.
  const sourceBudgetFor = (source: string): number =>
    source === "AllegroLokalnieDirect"
      ? 7_600
      : source === "OLXDirect"
        ? 6_650
        : source === "CeneoDirect"
          ? 6_300
          : 4_100;

  const runBoundedSource = (
    entry: { source: string; url: string },
    signal: AbortSignal | undefined = externalSignal
  ): Promise<SearchResult[]> =>
    withAbortableDeadline(
      (sourceDeadlineSignal) =>
        processSource(
          entry.source,
          entry.url,
          signal
            ? AbortSignal.any([signal, sourceDeadlineSignal])
            : sourceDeadlineSignal
        ),
      sourceBudgetFor(entry.source),
      [] as SearchResult[],
      `direct source ${entry.source}`
    ).then((chunk) => {
      if (chunk.length > 0) onPartialResults?.(chunk);
      return chunk;
    });

  const olxEntries = urls.filter((entry) => entry.source === "OLXDirect");
  const nonOlxEntries = urls.filter((entry) => entry.source !== "OLXDirect");

  const nonOlxChunksPromise = Promise.all(
    nonOlxEntries.map((entry) => runBoundedSource(entry))
  );

  // V34.CORE120 PRIMARY OLX DATA LANE: OLX's own public JSON search endpoint
  // returns one atomic object per listing (title/description/params/price).
  // Run it independently from legacy HTML/Jina. If the outer marketplace
  // branch is cancelled, onPartialResults snapshots the completed JSON cards.
  const olxPublicApiQuery = buildOlxPublicApiSearchQuery(parsed);
  const olxPublicApiPromise = withAbortableDeadline(
    (apiDeadlineSignal) =>
      searchOlxPublicJsonApi(
        parsed,
        olxPublicApiQuery,
        externalSignal
          ? AbortSignal.any([externalSignal, apiDeadlineSignal])
          : apiDeadlineSignal
      ),
    3_300,
    [] as SearchResult[],
    "OLX public JSON discovery"
  ).then((chunk) => {
    if (chunk.length > 0) onPartialResults?.(chunk);
    return chunk;
  });

  const olxChunkPromise: Promise<SearchResult[]> = (async () => {
    if (olxEntries.length === 0) return [];

    // V34.CORE166: for branded, multi-HARD retail requests the OLX public API
    // is stronger evidence than a rendered search landing: every result is one
    // atomic listing object with title/description/params/price. Do not spend
    // another 4-6 seconds reading the same search landing when that API already
    // produced priced cards. If the API is empty/unavailable, preserve the old
    // HTML/Jina path as a fallback. This changes scheduling only.
    if (isV34Core164HighConstraintRetailIntent(parsed)) {
      const apiCards = await olxPublicApiPromise;
      if (apiCards.length > 0) {
        console.log(
          "[AIShopping] V34.CORE166 OLX legacy landing skipped; public JSON cards available:",
          apiCards.length
        );
        return [];
      }
      console.log(
        "[AIShopping] V34.CORE166 OLX public JSON empty; legacy landing fallback enabled"
      );
    }

    if (olxEntries.length === 1) return runBoundedSource(olxEntries[0]);

    const localController = new AbortController();
    const raceSignal = externalSignal
      ? AbortSignal.any([externalSignal, localController.signal])
      : localController.signal;

    try {
      return await new Promise<SearchResult[]>((resolve) => {
        let settled = 0;
        let resolved = false;

        const finishEmptyIfDone = () => {
          if (!resolved && settled >= olxEntries.length) {
            resolved = true;
            resolve([]);
          }
        };

        for (const entry of olxEntries) {
          runBoundedSource(entry, raceSignal)
            .then((chunk) => {
              settled += 1;

              if (!resolved && chunk.length > 0) {
                resolved = true;
                console.log(
                  "[AIShopping] V34.CORE120 OLX first-useful landing won:",
                  entry.url,
                  "results=",
                  chunk.length
                );
                resolve(chunk);
                localController.abort();
                return;
              }

              finishEmptyIfDone();
            })
            .catch(() => {
              settled += 1;
              finishEmptyIfDone();
            });
        }
      });
    } finally {
      if (!localController.signal.aborted) localController.abort();
    }
  })();

  const [nonOlxChunks, olxChunk, olxPublicApiChunk] = await Promise.all([
    nonOlxChunksPromise,
    olxChunkPromise,
    olxPublicApiPromise,
  ]);

  // API cards go first during URL dedupe because they have the strongest
  // listing ownership: price/condition/spec text came from the same JSON object.
  const chunks = [
    ...(olxPublicApiChunk.length > 0 ? [olxPublicApiChunk] : []),
    ...nonOlxChunks,
    ...(olxChunk.length > 0 ? [olxChunk] : []),
  ];

  const results: SearchResult[] = [];
  const globalSeen = new Set<string>();

  for (const chunk of chunks) {
    for (const result of chunk) {
      const key = normalizeUrl(result.url);
      if (!key || globalSeen.has(key)) continue;

      globalSeen.add(key);
      results.push({
        ...result,
        url: key,
      });
    }
  }

  console.log(
    "[AIShopping] V34.CORE120 direct marketplace source mix:",
    Object.fromEntries(
      results.reduce((map, result) => {
        map.set(
          result.source,
          (map.get(result.source) ?? 0) + 1
        );
        return map;
      }, new Map<string, number>())
    )
  );

  return results;
}

function mergePartialMarketplaceSnapshot(
  target: SearchResult[],
  seen: Set<string>,
  results: SearchResult[]
): void {
  for (const result of results) {
    const key = normalizeUrl(result.url);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    target.push({ ...result, url: key });
  }
}

function shouldScanRetailerRescueSeeds(
  primaryVerificationReady: boolean,
  primaryIdentityReady: boolean,
  primaryHardCoverageReady: boolean
): boolean {
  return !primaryVerificationReady && !(primaryIdentityReady && primaryHardCoverageReady);
}

function shouldRunPrimaryMarketplaceIndexRescue(
  primaryVerificationReady: boolean,
  directMarketplaceResultCount: number,
  likelyConcreteCoverageHosts: number,
  coverageDiscoveryCoreRaw: string | null
): boolean {
  if (!normalizeText(coverageDiscoveryCoreRaw ?? "")) return false;
  if (likelyConcreteCoverageHosts >= 3) return false;

  // V34.CORE124: verification readiness answers "can we show at least one
  // offer?"; it does not answer "did the marketplace portfolio work?". When
  // every direct marketplace lane returned zero, one verified retailer must
  // not suppress the already-bounded public-index rescue. If direct
  // marketplaces produced anything, preserve CORE123's fast path.
  return !primaryVerificationReady || directMarketplaceResultCount === 0;
}

function getTargetedRetailerQueryLimit(parsed: ParsedQuery): number {
  // Keep enough site diversity to include the matched vertical plus universal
  // marketplaces, but do not fan out dozens of duplicate lexical variants in
  // the same request. Direct retailer adapters remain independent from this cap.
  if (parsed.original && parsed.category === "perfume") return 18;
  if (isV34Core164HighConstraintRetailIntent(parsed)) return 14;
  return 20;
}

function buildSemanticProductIdentityDiscoveryAlternates(
  parsed: ParsedQuery,
  coverageCoreRaw: string | null
): string[] {
  const coverageCore = normalizeText(coverageCoreRaw ?? "");
  if (!coverageCore) return [];

  // V34.CORE120: category-level lexical equivalence for construction-toy car
  // searches. This is intentionally narrow: it only substitutes the generic
  // automobile noun and never injects a brand, model, SKU or benchmark value.
  const requestsConstructionToyCar =
    parsed.category === "construction_toy" &&
    parsed.intent.qualifierTerms.some((term) =>
      universalTokensMorphologicallyEquivalent(
        normalizeMatchText(term),
        "samochod"
      )
    );

  if (!requestsConstructionToyCar) return [];

  const normalized = normalizeMatchText(coverageCore);
  if (!universalEvidenceHasBoundedIdentityTerm("samochod", normalized)) {
    return [];
  }

  return Array.from(new Set([
    normalizeText(normalized.replace(/\bsamochod\b/giu, "auto")),
    normalizeText(normalized.replace(/\bsamochod\b/giu, "car")),
  ].filter(Boolean))).slice(0, 2);
}

async function runSearch(
  queries: string[],
  parsed: ParsedQuery,
  discoverySignal?: AbortSignal,
  staticReferenceCandidateSink?: SearchResult[]
): Promise<SearchResult[]> {
  const discoveryStartedAt = Date.now();
  const allQueries = addSiteQueries(queries, parsed);

  const nonSiteQueries = Array.from(
    new Set(
      allQueries.filter(
        (query) => !query.trim().toLowerCase().startsWith("site:")
      )
    )
  );

  // For open-world searches, never spend the whole three-query budget on
  // lexical variants such as "beton", "1 kg beton", "beton 1 kg". At least
  // one branch must carry explicit shopping intent so the search engine
  // surfaces real retailers instead of articles, dictionaries and forums.
  const hasHardUniversalRequirements =
    getUniversalPreciseDiscoveryRequirements(parsed).length > 0;
  const exactAttributeQuery = buildUniversalExactDiscoveryQuery(parsed);
  const preciseShoppingQuery = normalizeText(
    `${buildUniversalPreciseDiscoveryCore(parsed)} cena sklep`
  );
  const alternativePreciseCore =
    buildUniversalAlternativePreciseDiscoveryCore(parsed);
  const alternativePreciseShoppingQuery = alternativePreciseCore
    ? normalizeText(`${alternativePreciseCore} cena sklep`)
    : "";
  const relaxedRetailDiscoveryQuery = normalizeText(
    `${quoteSearchTerm(buildProductSearchBase(parsed))} sklep`
  );
  const phrasePreservingQueries =
    buildUniversalPhrasePreservingQueries(parsed);
  const phrasePreservingGenericQueries = hasHardUniversalRequirements
    ? phrasePreservingQueries.slice(0, 1)
    : phrasePreservingQueries;

  const compactExactModelCore = getCompactExactModelDiscoveryCore(parsed);
  const namedVariantDiscoveryCore = getNamedVariantDiscoveryCore(parsed);
  const discoveryModelCore = compactExactModelCore || namedVariantDiscoveryCore;
  const coverageDiscoveryCore = getUniversalCoverageDiscoveryCore(parsed);
  const automotiveDiscoveryQueries = buildAutomotiveDiscoveryQueries(parsed);
  const exactModelGenericQuery = discoveryModelCore
    ? `${quoteSearchTerm(discoveryModelCore)} ${parsed.country === "PL" ? "cena sklep kup Polska" : "price shop buy"}`
    : "";
  const exactModelFootprintQuery =
    buildExactModelHardSpecFootprintQuery(parsed);
  const exactModelReferenceFootprintQuery =
    buildExactModelReferenceFootprintQuery(parsed);
  const primaryHardLexicalRecoveryQueries = hasHardUniversalRequirements
    ? buildHardCoverageLexicalRecoveryQueries(
        parsed,
        coverageDiscoveryCore,
        [],
        0
      )
    : [];
  const primaryHardLexicalAlternateQuery =
    primaryHardLexicalRecoveryQueries[1] ?? "";
  const semanticIdentityDiscoveryAlternates =
    buildSemanticProductIdentityDiscoveryAlternates(
      parsed,
      coverageDiscoveryCore
    );
  const rangeRelaxedBudgetQuery =
    buildRangeRelaxedBudgetSearchQuery(parsed);
  const semanticHardRequirementTerms = getUniversalPreciseDiscoveryRequirements(parsed)
    .slice(0, 4)
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .join(" ");
  const semanticIdentityGenericQueries = semanticIdentityDiscoveryAlternates.map(
    (core) => normalizeText(
      `${quoteSearchTerm(core)} ${semanticHardRequirementTerms} cena sklep kup`
    )
  );
  const semanticIdentityTargetedQueries = semanticIdentityDiscoveryAlternates
    .slice(0, 1)
    .flatMap((core) =>
      getIntentPrimaryRetailerDomains(parsed)
        .slice(0, 6)
        .map((host) =>
          normalizeText(
            `site:${getRetailerProductSiteScope(host)} ${core} ${semanticHardRequirementTerms}`
          )
        )
    );

  const genericQueries = parsed.category === "auto_part" && automotiveDiscoveryQueries.length > 0
    ? Array.from(new Set([
        ...automotiveDiscoveryQueries,
        ...nonSiteQueries,
      ].filter(Boolean))).slice(0, 4)
    : hasHardUniversalRequirements
    ? Array.from(new Set([
        exactModelGenericQuery,
        exactModelFootprintQuery,
        ...phrasePreservingGenericQueries,
        rangeRelaxedBudgetQuery
          ? `${quoteSearchTerm(rangeRelaxedBudgetQuery)} cena sklep kup`
          : "",
        exactAttributeQuery,
        alternativePreciseShoppingQuery || preciseShoppingQuery,
        ...semanticIdentityGenericQueries,
        primaryHardLexicalAlternateQuery,
        relaxedRetailDiscoveryQuery,
        preciseShoppingQuery,
        nonSiteQueries[0] ?? parsed.intent.searchBase,
        nonSiteQueries[1] ?? parsed.intent.normalizedQuery,
      ].filter(Boolean))).slice(0, 4)
    : parsed.intent.openWorld
      ? Array.from(new Set([
          exactModelGenericQuery,
          exactModelFootprintQuery,
          ...phrasePreservingQueries,
          nonSiteQueries[0] ?? parsed.intent.searchBase,
          nonSiteQueries[1] ?? parsed.intent.normalizedQuery,
          nonSiteQueries.find((query) => /\bcena\s+sklep\b/i.test(query))
            ?? `${parsed.intent.searchBase} cena sklep kup`,
        ].filter(Boolean))).slice(0, 4)
      : Array.from(new Set([
          exactModelGenericQuery,
          exactModelFootprintQuery,
          ...nonSiteQueries,
        ].filter(Boolean))).slice(0, 3);

  // V32.12 searches broadly, but every network branch has its own short budget.
  // This lets us query many retailers in parallel without allowing one slow
  // source to delay the whole response.
  const targetedQueryLimit = getTargetedRetailerQueryLimit(parsed);

  const ceneoPriorityPreflightAttempted =
    V34_CENEO_PRIORITY_PREFLIGHT.get(parsed)?.attempted === true;

  const targetedQueries = Array.from(
    new Set([
      ...buildAutomotiveTargetedRetailerQueries(parsed),
      ...semanticIdentityTargetedQueries,
      ...allQueries.filter(
        (query) => query.trim().toLowerCase().startsWith("site:")
      ),
      ...buildTargetedRetailerQueries(parsed),
    ])
  )
    .filter((query) =>
      !(
        ceneoPriorityPreflightAttempted &&
        getSiteQueryRequestedHost(query) === "ceneo.pl"
      )
    )
    .slice(0, targetedQueryLimit);

  console.log(
    "[AIShopping] V34.CORE120 generic search queries:",
    genericQueries
  );
  if (primaryHardLexicalAlternateQuery) {
    console.log(
      "[AIShopping] V34.CORE120 primary HARD lexical alternate:",
      primaryHardLexicalAlternateQuery
    );
  }
  if (semanticIdentityGenericQueries.length > 0) {
    console.log(
      "[AIShopping] V34.CORE120 semantic identity discovery alternates:",
      semanticIdentityGenericQueries
    );
  }

  console.log(
    "[AIShopping] V34.CORE120 retail verticals:",
    getRetailVerticalMatches(parsed).map(({ profile, score }) => ({
      id: profile.id,
      score,
      primaryDomains: getRetailVerticalPrimaryDomains(profile),
      configuredDomainCount: profile.domains.length,
    }))
  );

  console.log(
    "[AIShopping] V34.CORE120 targeted retailer queries:",
    targetedQueries
  );

  // V34.CORE120 PARTIAL MARKETPLACE PRESERVATION:
  // One useful OLX/Allegro Lokalnie/Ceneo branch must not disappear merely
  // because a slower sibling source is still running when the outer primary
  // discovery deadline expires. Publish each completed source chunk into a
  // deduplicated snapshot and return that snapshot on timeout. This changes
  // only orchestration; every product/variant/condition/price gate below is
  // unchanged.
  const partialDirectMarketplace: SearchResult[] = [];
  const partialDirectMarketplaceSeen = new Set<string>();
  const collectPartialDirectMarketplace = (results: SearchResult[]) =>
    mergePartialMarketplaceSnapshot(
      partialDirectMarketplace,
      partialDirectMarketplaceSeen,
      results
    );

  // V34.CORE120: the retailer mesh has the same partial-result contract as
  // marketplaces. This is crucial for universal search because fast first-party
  // stores often finish with dozens of concrete products while one blocked peer
  // is still waiting on a reader.
  const partialDirectRetailerCatalog: SearchResult[] = [];
  const partialDirectRetailerCatalogSeen = new Set<string>();
  const collectPartialDirectRetailerCatalog = (results: SearchResult[]) =>
    mergePartialMarketplaceSnapshot(
      partialDirectRetailerCatalog,
      partialDirectRetailerCatalogSeen,
      results
    );

  const directPromise = withAbortableDeadlineSnapshot(
    (phaseSignal) =>
      searchDirectMarketplacePages(
        parsed,
        discoverySignal
          ? AbortSignal.any([discoverySignal, phaseSignal])
          : phaseSignal,
        collectPartialDirectMarketplace
      ),
    Math.min(PRIMARY_DISCOVERY_BUDGET_MS, 6_150),
    () => {
      if (partialDirectMarketplace.length > 0) {
        console.log(
          "[AIShopping] V34.CORE120 preserve partial direct marketplace discovery:",
          partialDirectMarketplace.length
        );
      }
      return [...partialDirectMarketplace];
    },
    "direct marketplace discovery"
  );

  const directRetailerCatalogPromise = withAbortableDeadlineSnapshot(
    (phaseSignal) =>
      searchDirectRetailerCatalogPagesCore164(
        parsed,
        discoverySignal
          ? AbortSignal.any([discoverySignal, phaseSignal])
          : phaseSignal,
        collectPartialDirectRetailerCatalog
      ),
    // V34.CORE120: internal adapters are capped around 5.55 s. Give the mesh
    // enough room to settle normally, while the snapshot still guarantees that
    // a late sibling cannot erase earlier products. This remains inside the
    // ~7.55 s discovery-network ceiling and the global 20 s hard route budget.
    Math.min(
      PRIMARY_DISCOVERY_BUDGET_MS,
      getV34Core164DirectRetailerMeshBudgetMs(parsed)
    ),
    () => {
      if (partialDirectRetailerCatalog.length > 0) {
        console.log(
          "[AIShopping] V34.CORE120 preserve partial direct retailer mesh:",
          partialDirectRetailerCatalog.length
        );
      }
      return [...partialDirectRetailerCatalog];
    },
    "direct retailer catalog discovery"
  );

  const genericPromise = Promise.all(
    genericQueries.map(async (query, index) => {
      // V32.12: a compact exact-model query gets one independent DuckDuckGo
      // branch in parallel with Bing. Bing RSS can return only shallow brand
      // pages for rare/older SKUs even when concrete store/listing URLs exist.
      // One bounded second engine materially improves recall without adding
      // serial latency or introducing any SKU/category-specific rule.
      const useExactModelDuck =
        Boolean(discoveryModelCore) &&
        index <= (exactModelFootprintQuery ? 1 : 0);
      const useHardQueryDuck =
        index === 0 &&
        parsed.intent.required.some((requirement) => requirement.hard);
      const duckPromise =
        (parsed.intent.openWorld && index === 0) ||
        useExactModelDuck ||
        useHardQueryDuck
        ? withDeadline(
            searchDuckDuckGo(query, discoverySignal),
            discoveryModelCore || useHardQueryDuck ? 2_300 : 2_600,
            [] as SearchResult[],
            `DuckDuckGo generic: ${query}`
          )
        : Promise.resolve([] as SearchResult[]);

      const [bing, bingRss, duck] = await Promise.all([
        withDeadline(
          searchBing(query, discoverySignal),
          3_350,
          [] as SearchResult[],
          `Bing generic: ${query}`
        ),
        withDeadline(
          searchBingRss(query, discoverySignal),
          3_350,
          [] as SearchResult[],
          `Bing RSS generic: ${query}`
        ),
        duckPromise,
      ]);

      return [...bing, ...bingRss, ...duck];
    })
  );

  const directAdapterHosts = new Set(
    V28_DIRECT_RETAILER_CATALOG_ADAPTERS.map((adapter) => adapter.host)
  );
  const secondaryDirectoryHtmlHosts = getIntentVerticalAcceleratorDomains(parsed)
    .filter((host) => directAdapterHosts.has(host))
    .filter((host) => !getIntentPrimaryRetailerDomains(parsed).includes(host))
    .slice(0, 3);

  // CORE137: exact/model-like intents may spend a very small HTML-search wave
  // on the SAME rotated secondary stores already admitted by the site-query
  // builder. Previously those hosts were usually RSS-only, which made the large
  // Store Mesh nominally configured but weakly reachable. No new verifier trust
  // is granted and no extra secondary domain beyond the 2/3/4 cap is selected.
  const secondaryCoverageLimit =
    getIntentSecondaryRetailerCoverageLimit(parsed);
  const exactModelSecondaryHtmlHosts =
    secondaryCoverageLimit > 0
      ? getIntentSecondaryRetailerDomains(
          parsed,
          Math.min(3, secondaryCoverageLimit)
        )
      : [];
  const targetedHtmlRetailerHosts = new Set([
    ...getTargetedPrimaryRetailerDiscoveryDomains(parsed),
    ...secondaryDirectoryHtmlHosts,
    ...exactModelSecondaryHtmlHosts,
  ]);

  if (exactModelSecondaryHtmlHosts.length > 0) {
    console.log(
      "[AIShopping] V34.CORE164 secondary retailer hosts:",
      exactModelSecondaryHtmlHosts
    );
  }

  console.log(
    "[AIShopping] V34.CORE120 targeted HTML retailer hosts:",
    [...targetedHtmlRetailerHosts]
  );

  const targetedPromise = Promise.all(
    targetedQueries.map(async (query, index) => {
      // V32.12: reserve HTML-search capacity for both universal marketplaces
      // and the first retailer domains of the matched vertical. Previously the
      // first eight slots were almost entirely marketplaces/comparison sites,
      // leaving real stores on RSS-only discovery even when Bing HTML knew the
      // concrete product URL.
      const siteHost = getSiteQueryRequestedHost(query);
      const useHtml =
        index < 8 ||
        Boolean(siteHost && targetedHtmlRetailerHosts.has(siteHost));

      if (useHtml) {
        const [bing, bingRss] = await Promise.all([
          withDeadline(
            searchBing(query, discoverySignal),
            3_350,
            [] as SearchResult[],
            `Bing targeted: ${query}`
          ),
          withDeadline(
            searchBingRss(query, discoverySignal),
            3_350,
            [] as SearchResult[],
            `Bing RSS targeted: ${query}`
          ),
        ]);

        return enforceSiteQueryHostFidelity(query, [...bing, ...bingRss]);
      }

      const rss = await withDeadline(
        searchBingRss(query, discoverySignal),
        3_350,
        [] as SearchResult[],
        `Bing RSS retailer: ${query}`
      );

      return enforceSiteQueryHostFidelity(query, rss);
    })
  );

  // V32.12 keeps Google/Jina out of the normal discovery fan-out. A single
  // bounded exact-model footprint rescue is allowed only when the primary
  // phase still has sparse concrete commerce coverage, preserving Jina capacity for
  // product-page verification in normal searches.
  // V32.12 PARTIAL-RESULT SAFETY: every child branch already has its own
  // deadline. Do not wrap their Promise.all in another fallback that can erase
  // 50 already-finished offers just because the last source finishes a moment
  // later. We wait for the independently bounded children and keep each
  // branch's own [] fallback only for that branch.
  const [
    directMarketplace,
    directRetailerCatalog,
    genericChunks,
    targetedChunks,
  ] = await Promise.all([
    directPromise,
    directRetailerCatalogPromise,
    genericPromise,
    targetedPromise,
  ]);

  console.log(
    "[AIShopping] V34.CORE120 primary discovery settled ms:",
    Date.now() - discoveryStartedAt,
    {
      directMarketplace: directMarketplace.length,
      directRetailerCatalog: directRetailerCatalog.length,
      generic: genericChunks.flat().length,
      targeted: targetedChunks.flat().length,
    }
  );

  let all = [
    ...directMarketplace,
    ...directRetailerCatalog,
    ...genericChunks.flat(),
    ...targetedChunks.flat(),
  ];

  const primaryVerificationReady = hasVerificationReadyDiscoveryCandidate(
    all,
    parsed
  );
  const primaryIdentityReady = hasStrongIdentityDiscoveryCandidate(all, parsed);
  const primaryHardCoverageReady =
    countLikelyConcreteCoverageHosts(all, parsed, 1) > 0;
  const primaryCompleteHardCoverageReady =
    hasCompleteTrustedHardCoverageDiscoveryCandidate(all, parsed);

  // CORE106: blocked-retailer recovery must happen while verification time still
  // exists, not after a broad zero-result wave. It returns only concrete indexed
  // URLs (or hydrated retailer cards); final verification remains fail-closed.
  if (
    !primaryVerificationReady &&
    !primaryCompleteHardCoverageReady &&
    !discoverySignal?.aborted
  ) {
    const earlyIndexedBudgetMs = Math.min(
      1_550,
      Math.max(
        0,
        getEffectiveDiscoveryNetworkBudgetMs(parsed) -
          (Date.now() - discoveryStartedAt) -
          250
      )
    );
    if (earlyIndexedBudgetMs >= 750) {
      const earlyIndexed = await searchBlockedFirstPartyIndexedProducts(
        parsed,
        coverageDiscoveryCore,
        all,
        earlyIndexedBudgetMs,
        discoverySignal
      );
      if (earlyIndexed.length > 0) {
        all = [...all, ...earlyIndexed];
      }
    }
  }

  if (primaryCompleteHardCoverageReady && !primaryVerificationReady) {
    console.log(
      "[AIShopping] V34.CORE120 complete HARD-footprint primary candidate: preserving verifier budget"
    );
  }

  if (primaryVerificationReady) {
    console.log(
      "[AIShopping] V34.CORE120 verification-ready primary candidate: preserving verification budget"
    );
  }

  // V32.12 COVERAGE EXPANSION WAVE
  // Primary discovery is intentionally broad, but search-engine result quality
  // can vary per query/day. If fewer than four concrete commerce hosts are
  // visible, spend only the remaining discovery budget on a second independent
  // engine with different shopping phrasing. This is recall-only: the normal
  // domain/product/variant/condition/originality gates below remain unchanged.
  const effectiveDiscoveryBudgetMs = getEffectiveDiscoveryBudgetMs(parsed);
  const primaryLikelyCoverageHosts = countLikelyConcreteCoverageHosts(
    all,
    parsed,
    4
  );
  const coverageElapsedMs = Date.now() - discoveryStartedAt;
  const coverageRemainingMs = Math.max(
    0,
    getEffectiveDiscoveryNetworkBudgetMs(parsed) - coverageElapsedMs - 250
  );
  const openWorldSpecialistRescuePriority =
    parsed.intent.openWorld && getRetailVerticalMatches(parsed).length === 0;
  // V34.CORE166: "we can verify one offer" is not the same as "coverage is
  // healthy" for a precise branded bundle/spec request. When fewer than three
  // trustworthy hosts expose the requested brand + HARD footprint, allow one
  // bounded cross-store expansion wave even if a single exact candidate is
  // already verification-ready. Final acceptance remains unchanged.
  const highConstraintSparseCoverage =
    isV34Core164HighConstraintRetailIntent(parsed) &&
    primaryLikelyCoverageHosts < 3;
  const coverageNeedsExpansion =
    (
      (!primaryVerificationReady && !primaryCompleteHardCoverageReady) ||
      highConstraintSparseCoverage
    ) &&
    primaryLikelyCoverageHosts < 4 &&
    !openWorldSpecialistRescuePriority;

  if (openWorldSpecialistRescuePriority && primaryLikelyCoverageHosts < 4) {
    console.log(
      "[AIShopping] V34.CORE120 open-world specialist rescue priority:",
      { primaryLikelyCoverageHosts, savedGenericExpansionBudget: true }
    );
  }

  if (
    coverageNeedsExpansion &&
    !discoverySignal?.aborted &&
    coverageRemainingMs >= 800
  ) {
    const alreadyUsedDuckQuery = normalizeMatchText(genericQueries[0] ?? "");
    const exactHostCoverageQueries = buildCoverageExactHostQueries(
      parsed,
      coverageDiscoveryCore,
      all
    ).slice(0, 4);
    const genericCoverageQueries = buildCoverageExpansionQueries(
      parsed,
      coverageDiscoveryCore
    ).filter(
      (query) => normalizeMatchText(query) !== alreadyUsedDuckQuery
    );
    const hardCoverageLexicalQueries =
      !primaryCompleteHardCoverageReady
        ? buildHardCoverageLexicalRecoveryQueries(
            parsed,
            coverageDiscoveryCore,
            all,
            2
          )
        : [];
    const comparisonIndexQueries =
      primaryLikelyCoverageHosts < 3
        ? buildExactModelComparisonIndexQueries(parsed, discoveryModelCore)
        : [];
    const comparisonIndexLabelQueries =
      primaryLikelyCoverageHosts < 3
        ? buildExactModelComparisonLabelQueries(parsed, discoveryModelCore)
        : [];
    const retailerHostLabelQueries =
      primaryLikelyCoverageHosts < 3 && coverageDiscoveryCore
        ? exactHostCoverageQueries
            .slice(0, 2)
            .map((siteQuery) => {
              const host = getSiteQueryRequestedHost(siteQuery);
              return host
                ? {
                    host,
                    query: buildExactModelHostLabelQuery(
                      parsed,
                      coverageDiscoveryCore,
                      host
                    ),
                  }
                : null;
            })
            .filter(
              (item): item is { host: string; query: string } =>
                Boolean(item?.query)
            )
        : [];

    // V32.12: the first-party mesh already spends its direct budget on the
    // highest-priority adapters. Sparse exact-model coverage should use the
    // cheap host-label index path on *different* vertical retailers instead of
    // repeatedly asking only the same blocked stores. This stays fully generic:
    // hosts come from the matched retail vertical, never from product/SKU rules.
    const directMeshHosts = new Set(
      buildDirectRetailerCatalogRequests(parsed).map(({ adapter }) => adapter.host)
    );
    const coveredQualifiedHosts = getLikelyConcreteCoverageHostSet(all, parsed);
    const secondaryRetailerHostLabelQueries =
      primaryLikelyCoverageHosts < 3 && coverageDiscoveryCore
        ? getIntentVerticalAcceleratorDomains(parsed)
            .filter((host) =>
              !directMeshHosts.has(host) &&
              !coveredQualifiedHosts.has(host)
            )
            .slice(0, 3)
            .map((host) => ({
              host,
              query: buildExactModelHostLabelQuery(parsed, coverageDiscoveryCore, host),
            }))
            .filter(({ query }) => Boolean(query))
        : [];

    const hostLabelCoverageQueries = [
      ...comparisonIndexLabelQueries.slice(0, 1),
      ...retailerHostLabelQueries.slice(0, 2),
      ...secondaryRetailerHostLabelQueries.slice(0, 3),
    ];
    const coverageQueries = exactHostCoverageQueries.length > 0
      ? Array.from(new Set([
          ...hardCoverageLexicalQueries.slice(0, 3),
          ...exactHostCoverageQueries.slice(0, 2),
          ...comparisonIndexQueries.slice(0, 1),
          ...genericCoverageQueries.slice(0, 1),
        ])).slice(0, 7)
      : Array.from(new Set([
          ...hardCoverageLexicalQueries.slice(0, 4),
          ...comparisonIndexQueries.slice(0, 1),
          ...genericCoverageQueries.slice(0, 2),
        ])).slice(0, 6);

    const coverageWaveBudgetMs = Math.min(4_200, coverageRemainingMs);
    const coverageWaveStartedAt = Date.now();

    if (coverageQueries.length > 0) {
      console.log("[AIShopping] V34.CORE120 coverage expansion wave:", {
        primaryLikelyHosts: primaryLikelyCoverageHosts,
        diversityTarget: 3,
        budgetMs: coverageWaveBudgetMs,
        exactHostQueries: exactHostCoverageQueries,
        hardCoverageLexicalQueries,
        comparisonIndexQueries,
        hostLabelQueries: hostLabelCoverageQueries,
        queries: coverageQueries,
      });

      // V32.12: keep the coverage wave cheap. The previous version launched
      // a Google/Jina reader here before we had ranked the retailer seeds
      // already returned by Bing/DDG. On zero-coverage searches that single
      // slow reader could consume the remaining discovery budget and starve
      // dynamic retailer rescue. First finish the cheap host-targeted wave;
      // the reader reference rescue now runs only AFTER retailer rescue.
      const coverageChunks = await Promise.all([
        ...coverageQueries.map(async (query) => {
          const siteHost = getSiteQueryRequestedHost(query);

          if (siteHost) {
            const useComparisonDuck =
              siteHost === "ceneo.pl" && Boolean(discoveryModelCore);
            const [bing, bingRss, duck] = await Promise.all([
              withDeadline(
                searchBing(query, discoverySignal),
                coverageWaveBudgetMs,
                [] as SearchResult[],
                `Bing exact-host coverage: ${query}`
              ),
              withDeadline(
                searchBingRss(query, discoverySignal),
                coverageWaveBudgetMs,
                [] as SearchResult[],
                `Bing RSS exact-host coverage: ${query}`
              ),
              useComparisonDuck
                ? withDeadline(
                    searchDuckDuckGo(query, discoverySignal),
                    Math.min(1_450, coverageWaveBudgetMs),
                    [] as SearchResult[],
                    `DuckDuckGo comparison-index coverage: ${query}`
                  )
                : Promise.resolve([] as SearchResult[]),
            ]);

            const faithful = enforceSiteQueryHostFidelity(
              query,
              [...bing, ...bingRss, ...duck]
            );

            if (useComparisonDuck) {
              console.log(
                "[AIShopping] V34.CORE120 comparison-index coverage:",
                siteHost,
                faithful.length,
                "query=",
                query
              );
            }

            return faithful;
          }

          const [bing, duck] = await Promise.all([
            withDeadline(
              searchBing(query, discoverySignal),
              coverageWaveBudgetMs,
              [] as SearchResult[],
              `Bing coverage: ${query}`
            ),
            withDeadline(
              searchDuckDuckGo(query, discoverySignal),
              coverageWaveBudgetMs,
              [] as SearchResult[],
              `DuckDuckGo coverage: ${query}`
            ),
          ]);

          return [...bing, ...duck];
        }),
        ...hostLabelCoverageQueries.map(({ host, query }) =>
          searchHostLabelIndexCoverage(
            query,
            host,
            Math.min(1_550, coverageWaveBudgetMs),
            discoverySignal
          )
        ),
      ]);

      const coverageResults = dedupeSearchResultsByUrl(coverageChunks.flat());
      if (coverageResults.length > 0) {
        all = [...all, ...coverageResults];
      }

      console.log("[AIShopping] V34.CORE120 coverage expansion results:", {
        results: coverageResults.length,
        elapsedMs: Date.now() - coverageWaveStartedAt,
        highConstraintSparseCoverage,
      });
    }
  } else {
    console.log("[AIShopping] V34.CORE120 coverage expansion skipped:", {
      primaryLikelyHosts: primaryLikelyCoverageHosts,
      remainingMs: coverageRemainingMs,
      marketplaceCautionLane:
        parsed.original === true && parsed.category === "perfume",
    });
  }


  // V34.CORE124 MARKETPLACE INDEX RESCUE.
  // Direct marketplace HTML is frequently 403 while public indexes still know
  // concrete offer/product URLs. Recover only exact concrete Allegro/Ceneo URLs
  // and run them through the normal verifier; snippets are never trusted as
  // final price/condition/originality proof. CORE124 also runs this bounded
  // lane when every direct marketplace transport returned zero, even if one
  // retailer card is already ready. It remains disabled once three concrete
  // commerce hosts are visible or any direct marketplace lane succeeded.
  const primaryMarketplaceCoverageHosts = countLikelyConcreteCoverageHosts(
    all,
    parsed,
    3
  );
  const shouldRunMarketplaceIndexRescue = shouldRunPrimaryMarketplaceIndexRescue(
    primaryVerificationReady,
    directMarketplace.length,
    primaryMarketplaceCoverageHosts,
    coverageDiscoveryCore
  );

  if (shouldRunMarketplaceIndexRescue) {
    const marketplaceIndexRemainingMs = Math.max(
      0,
      effectiveDiscoveryBudgetMs - (Date.now() - discoveryStartedAt) - 500
    );
    if (marketplaceIndexRemainingMs >= 900) {
      if (primaryVerificationReady && directMarketplace.length === 0) {
        console.log(
          "[AIShopping] V34.CORE124 marketplace outage index rescue activated:",
          {
            concreteHosts: primaryMarketplaceCoverageHosts,
            remainingMs: marketplaceIndexRemainingMs,
            directMarketplaceResults: directMarketplace.length,
          }
        );
      }

      const marketplaceIndexed = await withAbortableDeadline(
        (signal) => searchIndexedMarketplaceProductRescue(
          parsed,
          coverageDiscoveryCore,
          Math.min(2_100, marketplaceIndexRemainingMs),
          discoverySignal ? AbortSignal.any([discoverySignal, signal]) : signal
        ),
        Math.min(2_250, marketplaceIndexRemainingMs),
        [] as SearchResult[],
        "indexed marketplace product rescue"
      );
      if (marketplaceIndexed.length > 0) {
        all = dedupeSearchResultsByUrl([...all, ...marketplaceIndexed]);
      }
    }
  }

  // V32.17 BLOCKED FIRST-PARTY INDEX RESCUE.
  // A first-party catalog that returns 403/429 or times out is not necessarily
  // absent from the market. Before crawling generic retailer landings, ask the
  // public indexes for exact product URLs on only those failed direct-mesh
  // hosts, then hydrate the product page itself into retailer-owned evidence.
  // Search snippets never become trusted proof by themselves.
  const blockedFirstPartyIndexedDiscoveryCore = normalizeText(
    discoveryModelCore ||
    (!primaryCompleteHardCoverageReady ? coverageDiscoveryCore : "")
  );

  if (
    !primaryVerificationReady &&
    !primaryCompleteHardCoverageReady &&
    countLikelyConcreteCoverageHosts(all, parsed, 3) < 3 &&
    blockedFirstPartyIndexedDiscoveryCore
  ) {
    const blockedIndexRemainingMs = Math.max(
      0,
      effectiveDiscoveryBudgetMs - (Date.now() - discoveryStartedAt) - 450
    );
    if (blockedIndexRemainingMs >= 1_200) {
      const blockedIndexStartedAt = Date.now();
      const blockedIndexedProducts = await withAbortableDeadline(
        (signal) => searchBlockedFirstPartyIndexedProducts(
          parsed,
          blockedFirstPartyIndexedDiscoveryCore,
          all,
          Math.min(3_600, blockedIndexRemainingMs),
          discoverySignal
            ? AbortSignal.any([discoverySignal, signal])
            : signal
        ),
        Math.min(3_800, blockedIndexRemainingMs),
        [] as SearchResult[],
        "blocked first-party indexed product rescue"
      );

      if (blockedIndexedProducts.length > 0) {
        all = dedupeSearchResultsByUrl([...all, ...blockedIndexedProducts]);
      }

      console.log(
        "[AIShopping] V34.CORE120 blocked first-party indexed rescue results:",
        { results: blockedIndexedProducts.length, elapsedMs: Date.now() - blockedIndexStartedAt }
      );
    }
  }

  // V32.12 DYNAMIC RETAILER RESCUE
  // Search engines often reveal a specialist shop only as a shallow
  // landing/category page. The domain is useful, but the landing URL is not an
  // offer. Rescue now does two things in parallel:
  //   1) precise site: search with strict host fidelity;
  //   2) a lightweight same-domain crawl of the discovered landing page to
  //      extract concrete product links.
  // This remains product-agnostic and works for any specialist retailer.
  const rescueDomainScores = new Map<string, number>();
  const rescueLandingResults = new Map<string, SearchResult[]>();
  const rescueSeedScanStartedAt = Date.now();
  const rescueSeedSeen = new Set<string>();
  const runRetailerRescueSeedScan = shouldScanRetailerRescueSeeds(
    primaryVerificationReady,
    primaryIdentityReady,
    primaryCompleteHardCoverageReady
  );

  if (!runRetailerRescueSeedScan) {
    console.log(
      "[AIShopping] V34.CORE120 retailer rescue seed scan skipped: primary verification/hard-coverage ready"
    );
  }

  for (const result of runRetailerRescueSeedScan ? all : []) {
    const normalizedSeedUrl = normalizeUrl(result.url);
    if (!normalizedSeedUrl) continue;

    let rescueSeedKey = normalizedSeedUrl;
    try {
      const seedUrl = new URL(normalizedSeedUrl);
      rescueSeedKey = `${seedUrl.hostname.replace(/^www\./, "")}${seedUrl.pathname}`.toLowerCase();
    } catch {}
    if (rescueSeedSeen.has(rescueSeedKey)) continue;
    rescueSeedSeen.add(rescueSeedKey);

    const host = getResultHostname(normalizedSeedUrl);
    if (!host) continue;

    // V32.12 cheap-equivalent rescue gates. getRetailerLandingRescueScore()
    // already rejects non-.pl hosts for Poland-first searches, while universal
    // marketplaces are removed from ranked rescue domains later. Skip both
    // classes BEFORE expensive category/morphology checks. This does not change
    // which rescue hosts can win; it only avoids spending CPU on impossible
    // candidates such as foreign editorial/search results.
    if (
      parsed.country === "PL" &&
      !host.endsWith(".pl") &&
      !isConfiguredCommerceDomain(normalizedSeedUrl)
    ) continue;
    if (V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((marketplaceHost) => String(marketplaceHost) === host)) continue;

    // The rescue scan is an optimization pass, not the product search itself.
    // Preserve a deterministic verification reserve even when an engine emits
    // hundreds of noisy URLs that trigger expensive universal match logic.
    if (Date.now() - rescueSeedScanStartedAt >= RETAILER_RESCUE_SEED_SCAN_BUDGET_MS) {
      console.log(
        "[AIShopping] V34.CORE120 retailer rescue seed scan budget reached:",
        Date.now() - rescueSeedScanStartedAt,
        "unique=",
        rescueSeedSeen.size,
        "hosts=",
        rescueDomainScores.size
      );
      break;
    }

    const seedResult = { ...result, url: normalizedSeedUrl };
    const score = getRetailerLandingRescueScore(seedResult, parsed);
    if (score < 0) continue;

    // Only hosts that pass the cheap retailer-rescue scorer reach the expensive
    // universal product-class/category checks.
    const allowed = isAllowedSearchDomainForQuery(normalizedSeedUrl, parsed);

    // A wrong-category retailer landing should not become a crawl seed merely
    // because its host is trusted. Example class: a smartwatch query finding a
    // retailer's Samsung *smartphone* category. This check uses the same
    // category profile as final matching and is therefore generic across
    // retailers/brands.
    const seedClassReason = evaluateUniversalProductClass(
      seedResult.name,
      `${seedResult.name} ${seedResult.snippet}`,
      seedResult.url,
      parsed,
      seedResult.source
    );
    if (seedClassReason === "incompatible-product-class") continue;

    const categorySeed = isLikelyOpenWorldCategoryOrCollectionResult(seedResult, parsed);
    const configuredLandingSeed =
      isConfiguredCommerceDomain(normalizedSeedUrl) &&
      !looksLikeRescuedRetailerProductCandidate(
        { ...seedResult, source: "RetailerRescue" },
        parsed,
        host
      );

    // A configured retailer can expose a deep brand/collection URL such as
    // /pl/b/<brand>/... that superficially looks product-like to a generic URL
    // heuristic. Treat it as a rescue seed whenever it cannot itself satisfy
    // the concrete-product matcher. This is domain-agnostic and lets the
    // same-domain crawl discover real product cards without ever presenting
    // the landing page as an offer.
    if (allowed && !categorySeed && !configuredLandingSeed) continue;

    rescueDomainScores.set(host, Math.max(score, rescueDomainScores.get(host) ?? -1));

    const bucket = rescueLandingResults.get(host) ?? [];
    bucket.push(seedResult);
    rescueLandingResults.set(host, bucket);
  }

  console.log(
    "[AIShopping] V34.CORE120 retailer rescue seed scan ms:",
    Date.now() - rescueSeedScanStartedAt,
    "unique=",
    rescueSeedSeen.size,
    "hosts=",
    rescueDomainScores.size
  );

  const rescueDomainLimit =
    primaryVerificationReady || (primaryIdentityReady && primaryCompleteHardCoverageReady)
      ? 0
      : parsed.intent.openWorld
      ? 5
      : parsed.intent.required.some((requirement) => requirement.hard)
        ? 6
        : 4;

  const hardOriginalPerfumeRescue =
    parsed.original === true && parsed.category === "perfume";
  const configuredCommerceHosts = new Set(getConfiguredCommerceDomains());
  const marketplaceRescueHosts = new Set<string>(
    V28_UNIVERSAL_MARKETPLACE_DOMAINS.map((host) => String(host))
  );

  const rankedRescueDomains = [...rescueDomainScores.entries()]
    // Universal marketplaces already have dedicated discovery paths and
    // targeted site queries. Crawling their landing pages again as if they
    // were specialist retailers duplicates work and can spend 2-3 seconds on
    // OLX/Allegro Lokalnie timeouts. Keep dynamic retailer rescue for actual
    // retailer/manufacturer domains.
    .filter(([host]) => !marketplaceRescueHosts.has(host))
    // For an explicit-original perfume request, editorial/community domains
    // cannot establish retailer authenticity and only consume the bounded
    // specialist-rescue budget. Marketplace discovery has its own caution lane;
    // dynamic retailer rescue stays focused on configured commerce hosts.
    .filter(([host]) =>
      !hardOriginalPerfumeRescue || configuredCommerceHosts.has(host)
    )
    .sort((a, b) => b[1] - a[1]);

  const exactModelVerticalPriority = getCompactExactModelDiscoveryCore(parsed)
    ? getIntentVerticalAcceleratorDomains(parsed)
        .filter((host) => rescueDomainScores.has(host))
        .slice(0, 2)
    : [];

  const rescueDomains = Array.from(new Set([
    ...exactModelVerticalPriority,
    ...rankedRescueDomains.map(([host]) => host),
  ])).slice(0, rescueDomainLimit);

  const rescuedRetailerHosts = new Set(rescueDomains);
  const discoveryElapsedBeforeRescue = Date.now() - discoveryStartedAt;
  const rescueBudgetCeilingMs = hardOriginalPerfumeRescue
    ? 5_200
    : getCompactExactModelDiscoveryCore(parsed)
      ? primaryLikelyCoverageHosts === 0
        // V32.12: keep dynamic retailer rescue useful but bounded. On exact
        // zero-coverage searches we deliberately preserve ~2-3 s for the
        // independent reference-index reader instead of letting six shallow
        // retailer landings consume the entire extended discovery window.
        ? 1_450
        : 1_600
      : 1_650;
  const rescueBudgetMs = Math.min(
    rescueBudgetCeilingMs,
    Math.max(
      0,
      getEffectiveDiscoveryNetworkBudgetMs(parsed) - discoveryElapsedBeforeRescue - 200
    )
  );

  if (
    !discoverySignal?.aborted &&
    rescueDomains.length > 0 &&
    rescueBudgetMs >= 850
  ) {
    const rescueBase = parsed.category === "auto_part"
      ? (buildAutomotiveDiscoveryQueries(parsed)[0] ?? buildRetailerDiscoveryQuery(parsed))
      : buildRetailerDiscoveryQuery(parsed);

    console.log(
      "[AIShopping] V34.CORE120 dynamic retailer rescue domains:",
      rescueDomains,
      "budget=",
      rescueBudgetMs
    );

    // V32.12: preserve completed rescue hosts independently. A slow Rossmann,
    // Hebe or future specialist shop must never zero-out results already
    // returned by another rescued domain.
    const rescueChunks = await Promise.all(
      rescueDomains.map(async (host, hostIndex) => {
          const hostRescueStartedAt = Date.now();
          const rescueModelTerm = parsed.intent.strongIdentityTerms
            .filter((term) => /\d/.test(term))
            .filter((term) => normalizeMatchText(term) !== normalizeMatchText(parsed.platform ?? ""))
            .sort((a, b) => b.length - a.length)[0] ?? "";

          const hardRequirementTerms = parsed.intent.required
            .filter((item) => item.hard)
            .slice(0, 4)
            .map(requirementPrimarySearchTerm)
            .join(" ");
          const familyRequirementTerms = parsed.intent.required
            .filter((item) => item.hard)
            .filter((item) =>
              !(parsed.category === "perfume" && item.key === "volume")
            )
            .slice(0, 3)
            .map(requirementPrimarySearchTerm)
            .join(" ");
          const alternativePreciseRescueBase =
            buildUniversalAlternativePreciseDiscoveryCore(parsed);
          const categoryAcceleratorRescueBase =
            getCategoryAcceleratorDomains(parsed.category).includes(host)
              ? buildCategoryAcceleratorPreciseDiscoveryCore(parsed)
              : "";
          const preciseRescueBase = parsed.category === "auto_part"
            ? (buildAutomotiveDiscoveryQueries(parsed)[0] ?? normalizeText(`${parsed.intent.productPhrase} ${hardRequirementTerms}`))
            : normalizeText(`${parsed.intent.productPhrase} ${hardRequirementTerms}`);
          const rescueSiteScope = getRetailerProductSiteScope(host);
          const relaxedQuery = `site:${rescueSiteScope} ${
            categoryAcceleratorRescueBase ||
            alternativePreciseRescueBase ||
            preciseRescueBase ||
            parsed.intent.searchBase ||
            rescueBase
          }`;
          const exactQuery = rescueModelTerm
            ? `site:${rescueSiteScope} "${rescueModelTerm.replace(/"/g, " ")}" ${normalizeText(parsed.brand ?? "")}`.trim()
            : parsed.intent.productPhrase
              ? `site:${rescueSiteScope} "${parsed.intent.productPhrase.replace(/"/g, " ")}" ${hardRequirementTerms}`.trim()
              : relaxedQuery;

          // V32.12: product-path site: queries can be too restrictive for
          // canonical multi-variant pages. A host-wide family query gives the
          // search engine permission to return a brand-family/collection page,
          // which is then used ONLY as a crawl seed, never as a final offer.
          const familyQuery = parsed.intent.productPhrase
            ? `site:${host} "${parsed.intent.productPhrase.replace(/"/g, " ")}" ${familyRequirementTerms}`.trim()
            : `site:${host} ${rescueBase}`;
          const hostLabelQuery = coverageDiscoveryCore
            ? buildExactModelHostLabelQuery(parsed, coverageDiscoveryCore, host)
            : normalizeText(`${quoteSearchTerm(parsed.intent.productPhrase)} ${host} ${hardRequirementTerms}`);

          const perCallBudget = Math.min(
            hardOriginalPerfumeRescue ? 4_850 : 2_700,
            rescueBudgetMs
          );

          const existingCrawlSeeds = rescueLandingResults.get(host) ?? [];

          if (hardOriginalPerfumeRescue) {
            // For explicit-original perfume searches the peer marketplaces are
            // deliberately skipped. Search retailer-owned pages first, then
            // spend the remaining bounded time crawling the BEST fresh family
            // page discovered by search. This avoids wasting the whole rescue
            // window reading a broad /brand/ landing before we know a much more
            // specific /brand/family/ seed exists.
            const searchBudget = Math.min(2_250, perCallBudget);
            const [bing, bingRss, familyRss, hostLabelIndexed] = await Promise.all([
              withDeadline(
                searchBing(exactQuery, discoverySignal),
                searchBudget,
                [] as SearchResult[],
                `Bing retailer rescue: ${host}`
              ),
              withDeadline(
                searchBingRss(relaxedQuery, discoverySignal),
                searchBudget,
                [] as SearchResult[],
                `Bing RSS retailer rescue: ${host}`
              ),
              withDeadline(
                searchBingRss(familyQuery, discoverySignal),
                searchBudget,
                [] as SearchResult[],
                `Bing RSS family rescue: ${host}`
              ),
              hostLabelQuery
                ? searchHostLabelIndexCoverage(
                    hostLabelQuery,
                    host,
                    Math.min(1_450, searchBudget),
                    discoverySignal
                  )
                : Promise.resolve([] as SearchResult[]),
            ]);

            const hostFaithfulRaw = [...bing, ...bingRss, ...familyRss, ...hostLabelIndexed]
              .filter((result) => retailerHostMatchesDomain(getResultHostname(result.url), host))
              .map((result) => ({ ...result, source: "RetailerRescue" as const }));

            const hostFaithfulSearchResults = hostFaithfulRaw.filter((result) =>
              looksLikeRescuedRetailerProductCandidate(result, parsed, host)
            );

            const seedMap = new Map<string, SearchResult>();
            for (const seed of [...hostFaithfulRaw, ...existingCrawlSeeds]) {
              if (looksLikeRescuedRetailerProductCandidate(seed, parsed, host)) {
                continue;
              }
              if (getRetailerLandingRescueScore(seed, parsed) < 0) continue;
              const key = normalizeUrl(seed.url);
              if (!key || seedMap.has(key)) continue;
              seedMap.set(key, { ...seed, url: key, source: "RetailerRescue" });
            }

            const crawlSeeds = [...seedMap.values()]
              .sort(
                (a, b) =>
                  getRetailerLandingRescueScore(b, parsed) -
                  getRetailerLandingRescueScore(a, parsed)
              )
              .slice(0, 3);

            const remainingForCrawl = Math.max(
              0,
              perCallBudget - (Date.now() - hostRescueStartedAt)
            );
            const crawled =
              crawlSeeds.length > 0 && remainingForCrawl >= 750
                ? await withDeadline(
                    crawlRescuedRetailerLandingPages(
                      host,
                      crawlSeeds,
                      parsed,
                      Math.min(3_850, remainingForCrawl),
                      discoverySignal
                    ),
                    Math.min(4_000, remainingForCrawl),
                    [] as SearchResult[],
                    `retailer family crawl: ${host}`
                  )
                : [];

            console.log(
              "[AIShopping] V34.CORE120 retailer rescue host:",
              host,
              "search=",
              hostFaithfulSearchResults.length,
              "crawl=",
              crawled.length,
              "freshSeeds=",
              Math.max(0, crawlSeeds.length - existingCrawlSeeds.length),
              "seeds=",
              crawlSeeds.length,
              "familyQuery=",
              familyQuery
            );

            return [...hostFaithfulSearchResults, ...crawled];
          }

          // Normal categories keep the established parallel strategy: search
          // and same-domain crawl start together so one slow source cannot
          // consume the fixed discovery window.
          const useExactModelDuckRescue =
            Boolean(discoveryModelCore) && hostIndex < 3;
          const circuitBreakDirectCrawl = shouldCircuitBreakDirectRetailerCrawl(
            parsed,
            host
          );
          if (circuitBreakDirectCrawl) {
            console.log(
              "[AIShopping] V34.CORE120 source-health circuit breaker: skip direct retailer crawl:",
              host
            );
          }

          const [[bing, bingRss, duck], hostLabelIndexed, crawled] = await Promise.all([
            Promise.all([
              withDeadline(
                searchBing(exactQuery, discoverySignal),
                Math.min(1_850, perCallBudget),
                [] as SearchResult[],
                `Bing retailer rescue: ${host}`
              ),
              withDeadline(
                searchBingRss(relaxedQuery, discoverySignal),
                Math.min(1_850, perCallBudget),
                [] as SearchResult[],
                `Bing RSS retailer rescue: ${host}`
              ),
              useExactModelDuckRescue
                ? withDeadline(
                    searchDuckDuckGo(exactQuery, discoverySignal),
                    Math.min(1_350, perCallBudget),
                    [] as SearchResult[],
                    `DuckDuckGo retailer rescue: ${host}`
                  )
                : Promise.resolve([] as SearchResult[]),
            ]),
            hostLabelQuery
              ? searchHostLabelIndexCoverage(
                  hostLabelQuery,
                  host,
                  Math.min(1_350, perCallBudget),
                  discoverySignal
                )
              : Promise.resolve([] as SearchResult[]),
            circuitBreakDirectCrawl
              ? Promise.resolve([] as SearchResult[])
              : withDeadline(
                  crawlRescuedRetailerLandingPages(
                    host,
                    existingCrawlSeeds,
                    parsed,
                    Math.min(2_450, perCallBudget),
                    discoverySignal
                  ),
                  Math.min(2_550, perCallBudget),
                  [] as SearchResult[],
                  `retailer deep crawl: ${host}`
                ),
          ]);

          const hostFaithfulRaw = [...bing, ...bingRss, ...duck, ...hostLabelIndexed]
            .filter((result) => retailerHostMatchesDomain(getResultHostname(result.url), host))
            .map((result) => ({ ...result, source: "RetailerRescue" as const }));

          const hostFaithfulSearchResults = hostFaithfulRaw.filter((result) =>
            looksLikeRescuedRetailerProductCandidate(result, parsed, host)
          );

          // V32.12: for normal categories, Bing/RSS may discover a much more
          // specific family/category landing than the shallow seed available
          // before rescue started. Reuse at most two such fresh same-domain
          // landings for one small second crawl, but only if the per-host time
          // budget still has room. This stays generic: no product/SKU routes.
          const existingSeedKeys = new Set(
            existingCrawlSeeds
              .map((seed) => normalizeUrl(seed.url))
              .filter(Boolean)
          );
          const freshSeedMap = new Map<string, SearchResult>();

          for (const seed of hostFaithfulRaw) {
            if (looksLikeRescuedRetailerProductCandidate(seed, parsed, host)) {
              continue;
            }
            if (getRetailerLandingRescueScore(seed, parsed) < 0) continue;

            const key = normalizeUrl(seed.url);
            if (!key || existingSeedKeys.has(key) || freshSeedMap.has(key)) {
              continue;
            }

            freshSeedMap.set(key, {
              ...seed,
              url: key,
              source: "RetailerRescue" as const,
            });
          }

          const freshCrawlSeeds = [...freshSeedMap.values()]
            .sort(
              (a, b) =>
                getRetailerLandingRescueScore(b, parsed) -
                getRetailerLandingRescueScore(a, parsed)
            )
            .slice(0, 2);

          const remainingForFreshCrawl = Math.max(
            0,
            perCallBudget - (Date.now() - hostRescueStartedAt)
          );
          const freshCrawled =
            !circuitBreakDirectCrawl &&
            freshCrawlSeeds.length > 0 && remainingForFreshCrawl >= 650
              ? await withDeadline(
                  crawlRescuedRetailerLandingPages(
                    host,
                    freshCrawlSeeds,
                    parsed,
                    Math.min(1_350, remainingForFreshCrawl),
                    discoverySignal
                  ),
                  Math.min(1_450, remainingForFreshCrawl),
                  [] as SearchResult[],
                  `retailer fresh-seed crawl: ${host}`
                )
              : [];

          console.log(
            "[AIShopping] V34.CORE120 retailer rescue host:",
            host,
            "search=",
            hostFaithfulSearchResults.length,
            "duck=",
            duck.length,
            "hostLabel=",
            hostLabelIndexed.length,
            "crawl=",
            crawled.length,
            "freshCrawl=",
            freshCrawled.length,
            "freshSeeds=",
            freshCrawlSeeds.length,
            "seeds=",
            existingCrawlSeeds.length
          );

          return [
            ...hostFaithfulSearchResults,
            ...crawled,
            ...freshCrawled,
          ];
        })
    );


    const rescuedResults = rescueChunks.flat();
    if (rescuedResults.length > 0) {
      all = [...all, ...rescuedResults];
    }

    console.log(
      "[AIShopping] V34.CORE120 dynamic retailer rescue results:",
      rescuedResults.length
    );
  }

  // V32.12 LATE EXACT-MODEL REFERENCE RESCUE
  // Only after the already-discovered retailer seeds had their chance do we
  // spend a reader request on the wider web. This prevents one slow Google
  // reader from starving first-party/dynamic retailer coverage. It activates
  // for exact-model searches that still have sparse commerce coverage (fewer
  // than three concrete hosts), and only while a meaningful part of the discovery budget remains.
  const concreteHostsAfterRetailerRescue = countLikelyConcreteCoverageHosts(
    all,
    parsed,
    3
  );
  const referenceRescueElapsedMs = Date.now() - discoveryStartedAt;
  const referenceRescueRemainingMs = Math.max(
    0,
    getEffectiveDiscoveryNetworkBudgetMs(parsed) - referenceRescueElapsedMs - 200
  );

  if (
    !primaryVerificationReady &&
    !primaryIdentityReady &&
    concreteHostsAfterRetailerRescue < 3 &&
    exactModelReferenceFootprintQuery &&
    !discoverySignal?.aborted &&
    referenceRescueRemainingMs >= 1_450
  ) {
    const referenceRescueBudgetMs = Math.min(
      3_600,
      referenceRescueRemainingMs
    );
    const referenceQuery =
      exactModelReferenceFootprintQuery ||
      exactModelFootprintQuery;
    const referenceRescueStartedAt = Date.now();
    const referenceComparisonLabel =
      buildExactModelComparisonLabelQueries(parsed, discoveryModelCore)[0] ?? null;
    const combineReferenceSignal = (innerSignal: AbortSignal): AbortSignal =>
      discoverySignal
        ? AbortSignal.any([discoverySignal, innerSignal])
        : innerSignal;

    console.log("[AIShopping] V34.CORE120 exact-model reference rescue:", {
      concreteHosts: concreteHostsAfterRetailerRescue,
      diversityTarget: 3,
      budgetMs: referenceRescueBudgetMs,
      query: referenceQuery,
      comparisonLabelQuery: referenceComparisonLabel?.query ?? null,
      engines: ["Bing", "BingRSS", "DuckDuckGo", "Google/Jina"],
    });

    // V32.12: the late reference rescue is no longer a single point of failure.
    // Run independent keyless indexes in parallel. The comparison-label branch
    // deliberately avoids site: syntax and filters the destination hostname
    // after retrieval, which helps old/unavailable canonical product pages
    // that search engines index but no longer surface for shopping queries.
    const engineBudgetMs = Math.min(1_900, referenceRescueBudgetMs);
    const googleBudgetMs = Math.min(2_300, referenceRescueBudgetMs);

    const [bingReference, rssReference, duckReference, comparisonReference, googleReference] =
      await Promise.all([
        withAbortableDeadline(
          (signal) => searchBing(referenceQuery, combineReferenceSignal(signal)),
          engineBudgetMs,
          [] as SearchResult[],
          "Bing late exact-model reference rescue"
        ),
        withAbortableDeadline(
          (signal) => searchBingRss(referenceQuery, combineReferenceSignal(signal)),
          engineBudgetMs,
          [] as SearchResult[],
          "Bing RSS late exact-model reference rescue"
        ),
        withAbortableDeadline(
          (signal) => searchDuckDuckGo(referenceQuery, combineReferenceSignal(signal)),
          engineBudgetMs,
          [] as SearchResult[],
          "DuckDuckGo late exact-model reference rescue"
        ),
        referenceComparisonLabel
          ? searchHostLabelIndexCoverage(
              referenceComparisonLabel.query,
              referenceComparisonLabel.host,
              Math.min(1_850, referenceRescueBudgetMs),
              discoverySignal
            )
          : Promise.resolve([] as SearchResult[]),
        withAbortableDeadline(
          (signal) =>
            searchGoogleViaJina(
              referenceQuery,
              combineReferenceSignal(signal)
            ),
          googleBudgetMs,
          [] as SearchResult[],
          "Jina Google late exact-model reference rescue"
        ),
      ]);

    const referenceResults = dedupeSearchResultsByUrl([
      ...bingReference,
      ...rssReference,
      ...duckReference,
      ...comparisonReference,
      ...googleReference,
    ]);

    if (referenceResults.length > 0) {
      all = [...all, ...referenceResults];
    }

    console.log("[AIShopping] V34.CORE120 exact-model reference rescue results:", {
      results: referenceResults.length,
      sourceMix: referenceResults.reduce<Record<string, number>>((acc, result) => {
        acc[result.source] = (acc[result.source] ?? 0) + 1;
        return acc;
      }, {}),
      elapsedMs: Date.now() - referenceRescueStartedAt,
    });
  } else {
    console.log("[AIShopping] V34.CORE120 exact-model reference rescue skipped:", {
      concreteHosts: concreteHostsAfterRetailerRescue,
      remainingMs: referenceRescueRemainingMs,
      hasQuery: Boolean(exactModelReferenceFootprintQuery),
    });
  }

  // V34.CORE120: static model reference discovery is a separate evidence lane.
  // Preserve exact-model retailer/manufacturer references from the RAW search
  // mesh even if they are later excluded from the offer portfolio (for example
  // because they are documentation pages or out-of-budget retailer products).
  if (staticReferenceCandidateSink) {
    const phrase = buildUniversalProofPhrase(
      parsed.intent.productPhrase || parsed.intent.searchBase,
      parsed
    );
    const exactModelAnchor = getUniversalExactModelAnchor(parsed, phrase);
    const rawReferenceSeen = new Set<string>();

    if (exactModelAnchor) {
      for (const rawResult of all) {
        const normalizedUrl = normalizeUrl(rawResult.url);
        if (!normalizedUrl) continue;

        const normalizedResult: SearchResult = {
          ...rawResult,
          url: normalizedUrl,
        };
        const key = normalizedUrl;
        if (rawReferenceSeen.has(key)) continue;

        const score = getExactModelStaticReferenceCandidateScore(
          normalizedResult,
          parsed,
          exactModelAnchor
        );
        if (score < 0) continue;

        rawReferenceSeen.add(key);
        staticReferenceCandidateSink.push(normalizedResult);
      }

      staticReferenceCandidateSink.sort(
        (a, b) =>
          getExactModelStaticReferenceCandidateScore(b, parsed, exactModelAnchor) -
            getExactModelStaticReferenceCandidateScore(a, parsed, exactModelAnchor) ||
          a.searchRank - b.searchRank
      );

      if (staticReferenceCandidateSink.length > 12) {
        staticReferenceCandidateSink.splice(12);
      }

      console.log(
        "[AIShopping] V34.CORE120 raw static-reference candidates:",
        staticReferenceCandidateSink.map((result) => ({
          host: getResultHostname(result.url),
          name: result.name,
          url: result.url,
        }))
      );
    }
  }

  const seen = new Set<string>();
  const deduped: SearchResult[] = [];

  let rejectedDomain = 0;
  let rejectedProduct = 0;
  let rejectedUrl = 0;

  const domainSamples: string[] = [];
  const productSamples: string[] = [];
  const acceptedSamples: string[] = [];
  const allowedDomainCounts = new Map<string, number>();
  const rejectedDomainCounts = new Map<string, number>();

  const validationStartedAt = Date.now();
  const prioritizedResults = [...all].sort(
    (a, b) =>
      getDiscoveryValidationPriority(b, parsed) -
        getDiscoveryValidationPriority(a, parsed) ||
      a.searchRank - b.searchRank
  );
  let cheapIdentityRejected = 0;
  let validationBudgetStopped = false;
  const validationAcceptedHosts = new Set<string>();

  for (const result of prioritizedResults) {
    const validationElapsedMs = Date.now() - validationStartedAt;
    const enoughDiverseAcceptedCandidates =
      deduped.length >= 12 && validationAcceptedHosts.size >= 3;
    if (
      validationElapsedMs >= DISCOVERY_VALIDATION_HARD_BUDGET_MS ||
      (validationElapsedMs >= DISCOVERY_VALIDATION_SOFT_BUDGET_MS && enoughDiverseAcceptedCandidates) ||
      deduped.length >= DISCOVERY_VALIDATION_ACCEPTED_TARGET
    ) {
      validationBudgetStopped = true;
      break;
    }

    // The same URL is often returned by HTML search, RSS and several targeted
    // queries. Normalize and deduplicate before product validation so one bad
    // category page is rejected and logged once instead of dozens of times.
    const normalized = normalizeUrl(result.url);

    if (!normalized) {
      rejectedUrl++;
      continue;
    }

    let dedupeKey = "";
    try {
      const parsedUrl = new URL(normalized);
      dedupeKey =
        `${parsedUrl.hostname.replace(/^www\./, "")}${parsedUrl.pathname}`
          .toLowerCase();
    } catch {
      rejectedUrl++;
      continue;
    }

    if (seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);

    const normalizedResult: SearchResult = {
      ...result,
      url: normalized,
    };

    let hostname = "unknown";
    try {
      hostname = new URL(normalized).hostname
        .replace(/^www\./, "")
        .toLowerCase();
    } catch {}

    const rescuedRetailerDomainAllowed =
      normalizedResult.source === "RetailerRescue" &&
      rescuedRetailerHosts.has(hostname) &&
      looksLikeRescuedRetailerProductCandidate(normalizedResult, parsed, hostname);

    if (
      !isAllowedSearchDomainForQuery(normalized, parsed) &&
      !rescuedRetailerDomainAllowed
    ) {
      rejectedDomain++;
      rejectedDomainCounts.set(
        hostname,
        (rejectedDomainCounts.get(hostname) ?? 0) + 1
      );

      if (domainSamples.length < 12) {
        domainSamples.push(`${normalizedResult.source} | ${hostname} | ${normalized}`);
      }
      continue;
    }

    allowedDomainCounts.set(
      hostname,
      (allowedDomainCounts.get(hostname) ?? 0) + 1
    );

    if (!hasCheapDiscoveryIdentitySignal(normalizedResult, parsed)) {
      cheapIdentityRejected++;
      rejectedProduct++;
      continue;
    }

    if (!looksLikeRequestedProduct(normalizedResult, parsed)) {
      rejectedProduct++;
      if (productSamples.length < 8) {
        productSamples.push(
          `${normalizedResult.source} | ${normalizedResult.name} | ${normalized}`
        );
      }
      continue;
    }

    if (acceptedSamples.length < 12) {
      acceptedSamples.push(
        `${normalizedResult.source} | ${normalizedResult.name} | ${normalized}`
      );
    }

    deduped.push(normalizedResult);
    if (hostname && hostname !== "unknown") validationAcceptedHosts.add(hostname);
  }

  console.log("[AIShopping] V34.CORE120 bounded discovery validation:", {
    raw: all.length,
    processed: seen.size,
    accepted: deduped.length,
    cheapIdentityRejected,
    elapsedMs: Date.now() - validationStartedAt,
    budgetStopped: validationBudgetStopped,
  });

  console.log(
    "[AIShopping] search source totals:",
    JSON.stringify({
      raw: all.length,
      deduped: deduped.length,
      rejectedDomain,
      rejectedProduct,
      rejectedUrl,
    })
  );

  console.log(
    "[AIShopping] allowed domain counts:",
    Object.fromEntries(allowedDomainCounts)
  );

  console.log(
    "[AIShopping] rejected domain counts:",
    Object.fromEntries(rejectedDomainCounts)
  );

  console.log(
    "[AIShopping] accepted samples:",
    acceptedSamples
  );

  console.log(
    "[AIShopping] V34.CORE120 discovered commercial hosts:",
    Object.fromEntries(
      deduped.reduce((map, result) => {
        const host = getResultHostname(result.url) || "unknown";
        map.set(host, (map.get(host) ?? 0) + 1);
        return map;
      }, new Map<string, number>())
    )
  );

  console.log(
    "[AIShopping] V34.CORE120 coverage after discovery:",
    getCoverageSnapshot(deduped, parsed)
  );

  console.log(
    "[AIShopping] V34.CORE120 open-web discovered hosts:",
    Object.fromEntries(
      deduped
        .filter(
          (result) =>
            !isPreferredSearchDomainForQuery(result.url, parsed)
        )
        .reduce((map, result) => {
          const host = getResultHostname(result.url) || "unknown";
          map.set(host, (map.get(host) ?? 0) + 1);
          return map;
        }, new Map<string, number>())
    )
  );

  console.log(
    "[AIShopping] rejected product samples:",
    productSamples
  );

  console.log(
    "[AIShopping] rejected domain samples:",
    domainSamples
  );

  console.log(
    "[AIShopping] V34.CORE120 Allegro + Allegro Lokalnie discovery:",
    deduped
      .filter((result) => {
        const host = getResultHostname(result.url);
        return (
          host === "allegro.pl" ||
          host === "allegrolokalnie.pl"
        );
      })
      .slice(0, 12)
      .map((result) => ({
        source: result.source,
        name: result.name,
        url: result.url,
      }))
  );

  console.log(
    "[AIShopping] V34.CORE120 discovery time ms:",
    Date.now() - discoveryStartedAt
  );

  return deduped;
}

function getCountryPenalty(url: string, country: Country): number {
  try {
    const hostname = new URL(url).hostname.toLowerCase();

    if (country === "PL") {
      const polishDomains = [
        ".pl",
        "allegro.pl",
        "mediaexpert.pl",
        "morele.net",
        "x-kom.pl",
        "empik.com",
      ];

      return polishDomains.some((domain) => hostname.includes(domain))
        ? 0
        : 25;
    }

    return 0;
  } catch {
    return 30;
  }
}


// CORE75: structured catalog-card price is accepted only when the existing
// product-aware price binder can independently re-bind the SAME amount to the
// SAME bounded product identity. This reuses the mature filters for budget
// ranges, financing, shipping, historical/reference prices and add-ons. It
// prevents a collection-level `do 5000 zł` control from becoming a product
// price while preserving legitimate close/current promo prices such as
// `Cena z kodem` on one first-party card.
function rebindStructuredRetailerCatalogCardPrice(
  result: SearchResult,
  requestedCondition: Condition = null
): PriceInfo {
  if (
    result.source !== "RetailerRescue" ||
    result.retailerOwnedCardEvidence !== true ||
    result.retailerCatalogCardAvailability === "unavailable"
  ) {
    return { price: null, currency: null };
  }

  const structured = result.retailerCatalogCardPrice;
  if (
    structured?.price === null ||
    structured?.price === undefined ||
    !structured.currency
  ) {
    return { price: null, currency: null };
  }

  const evidence = normalizeText(`${result.name} ${result.snippet}`).slice(0, 8_000);
  const rebound = extractPriceNearProductName(
    evidence,
    result.name,
    requestedCondition,
    false
  );

  if (
    rebound.price === null ||
    !rebound.currency ||
    rebound.currency !== structured.currency ||
    Math.abs(rebound.price - structured.price) > 0.011
  ) {
    return { price: null, currency: null };
  }

  return structured;
}


type TrustedRetailerCatalogCardEvidence = {
  price: number;
  currency: string;
  availability: "available" | "unknown" | "unavailable";
};

function getTrustedRetailerCatalogCardEvidence(
  result: SearchResult,
  parsed: ParsedQuery
): TrustedRetailerCatalogCardEvidence | null {
  if (
    result.source !== "RetailerRescue" ||
    result.retailerOwnedCardEvidence !== true ||
    !isConfiguredCommerceDomain(result.url) ||
    !isProbablyRealOfferUrl(result.url) ||
    isClearlyNonOfferAssetUrl(result.url) ||
    isLikelyOpenWorldCategoryOrCollectionResult(result, parsed)
  ) {
    return null;
  }

  const bound = rebindStructuredRetailerCatalogCardPrice(
    result,
    parsed.condition
  );
  if (bound.price === null || !bound.currency) {
    return null;
  }

  const availability =
    result.retailerCatalogCardAvailability ??
    getAvailabilityFromHtml(`${result.name} ${result.snippet}`);

  // An explicitly unavailable card can never be rescued by its visible price.
  if (availability === "unavailable") return null;

  const evidence = normalizeText(`${result.name} ${result.snippet}`).slice(0, 8_000);
  const explicitCondition = extractTrustedConditionFromText(evidence);
  if (
    parsed.condition &&
    explicitCondition &&
    explicitCondition !== parsed.condition
  ) {
    return null;
  }

  return {
    price: bound.price,
    currency: bound.currency,
    availability,
  };
}

function hasTrustedRetailerOwnedCardCheckoutEvidence(result: SearchResult): boolean {
  if (
    result.source !== "RetailerRescue" ||
    result.retailerOwnedCardEvidence !== true
  ) {
    return false;
  }

  const evidence = normalizeMatchText(`${result.name} ${result.snippet}`);
  if (!evidence) return false;

  if (
    /\b(?:produkt\s+(?:chwilowo\s+)?niedostepny|niedostepny|wyprzedany|brak\s+w\s+magazynie|sold\s+out|out\s+of\s+stock)\b/iu.test(evidence)
  ) {
    return false;
  }

  return /\b(?:kup\s+teraz|dodaj\s+do\s+koszyka|do\s+koszyka|zamow(?:\s+teraz)?|zamów(?:\s+teraz)?|przejdz\s+do\s+kasy|przejdź\s+do\s+kasy|checkout|add\s+to\s+cart|buy\s+now|order\s+now)\b/iu.test(evidence);
}

function extractSearchResultPrice(
  result: SearchResult,
  requestedCondition: Condition = null,
  debugLogging = true
): PriceInfo {
  // V32.12: a retailer-owned catalog card may contain many nearby prices.
  // Never run the generic whole-snippet parser for such a card; bind the price
  // to this concrete product name. If no local price is provable, leave it
  // unknown and let the concrete product page/Jina verification decide.
  if (
    result.source === "RetailerRescue" &&
    result.retailerOwnedCardEvidence === true
  ) {
    const reboundStructuredPrice = rebindStructuredRetailerCatalogCardPrice(
      result,
      requestedCondition
    );
    if (
      reboundStructuredPrice.price !== null &&
      reboundStructuredPrice.currency
    ) {
      return reboundStructuredPrice;
    }

    if (!hasTrustedRetailerOwnedCardCheckoutEvidence(result)) {
      return { price: null, currency: null };
    }

    return extractPriceNearProductName(
      `${result.name} ${result.snippet}`,
      result.name,
      requestedCondition
    );
  }

  // V18: search engines/marketplaces often put the price in Markdown
  // headings, on the same line as the listing title, or in a small
  // "price" label. We deliberately inspect the title first, then the
  // snippet, then source-specific patterns.
  const titlePrice = extractPriceFromText(result.name, requestedCondition, debugLogging);
  if (titlePrice.price !== null && titlePrice.currency) return titlePrice;

  const snippet = normalizeText(result.snippet);

  // OLX/Ceneo direct readers commonly return: "### title  ### 120 zł"
  // or "title | 120,00 zł". Search the first part before unrelated
  // navigation text can contaminate the candidate list.
  const focused = snippet.slice(0, 2200);
  const focusedPrice = extractPriceFromText(focused, requestedCondition, debugLogging);
  if (focusedPrice.price !== null && focusedPrice.currency) return focusedPrice;

  // A few sources separate currency and amount with HTML/Markdown.
  const compact = decodeHtml(
    `${result.name} ${result.snippet}`
  ).replace(/\s+/g, " ");

  const explicit = compact.match(
    /(?:cena|price|kup teraz|od)\s*[:\-]?\s*(\d{1,3}(?:[ .]\d{3})+(?:\s*[.,]\s*\d{1,2})?|\d{1,7}(?:\s*[.,]\s*\d{1,2})?)\s*(zł|PLN|€|EUR|USD|GBP|CZK|KČ)(?=$|[^\p{L}\p{N}_])/iu
  );

  if (explicit) {
    const price = parseNumber(explicit[1]);
    const currency = normalizeCurrency(explicit[2]);
    if (price !== null && currency) return { price, currency };
  }

  return { price: null, currency: null };
}


function extractGpuModelSignatures(raw: string): string[] {
  const text = normalizeMatchText(raw)
    .replace(/[_/\-]+/g, " ")
    // Retailers sometimes serialize the ™ glyph as a literal/fused "tm"
    // token (for example RTX™ 5060 -> rtxtm 5060). Treat that decoration as
    // non-semantic while keeping the exact model/suffix comparison strict.
    .replace(/\b(rtx|gtx|rx)\s*(?:tm|™|®)?\s*(?=\d{3,4}\b)/giu, "$1 ");
  const signatures: string[] = [];

  for (const match of text.matchAll(/\b(rtx|gtx)\s*(\d{3,4})(?:\s*(ti|super))?\b/giu)) {
    signatures.push(
      normalizeText(
        `${match[1].toLowerCase()} ${match[2]} ${match[3]?.toLowerCase() ?? ""}`
      ).toLowerCase()
    );
  }

  for (const match of text.matchAll(/\b(rx)\s*(\d{3,4})(?:\s*(xt|xtx))?\b/giu)) {
    signatures.push(
      normalizeText(
        `${match[1].toLowerCase()} ${match[2]} ${match[3]?.toLowerCase() ?? ""}`
      ).toLowerCase()
    );
  }

  return Array.from(new Set(signatures));
}

function extractGpuModelSignature(raw: string): string | null {
  return extractGpuModelSignatures(raw)[0] ?? null;
}

function isGpuWrongProduct(
  result: SearchResult,
  parsed: ParsedQuery
): boolean {
  if (parsed.category !== "gpu" || parsed.intent.accessoryIntent) return false;

  const title = normalizeMatchText(result.name);
  const combined = normalizeMatchText(
    `${result.name} ${result.snippet} ${result.url}`
  );

  const requestedModel = extractGpuModelSignature(parsed.queryText);
  const offeredModel = extractGpuModelSignature(result.name);

  // If the user named a concrete GPU model, a Ti/SUPER/XT variant is a
  // different product and must not be silently treated as equivalent.
  if (requestedModel) {
    if (!offeredModel || offeredModel !== requestedModel) {
      return true;
    }
  }

  // A GPU search is for the graphics card itself, not a laptop or a whole PC
  // that merely contains the requested GPU.
  const obviousSystemSignals = [
    "laptop",
    "notebook",
    "komputer gamingowy",
    "komputer do gier",
    "gaming pc",
    "pc gaming",
    "zestaw komputerowy",
    "desktop pc",
  ];

  if (obviousSystemSignals.some((signal) => title.includes(signal))) {
    return true;
  }

  const hasCpuSignal =
    /\b(?:ryzen\s*[3579](?:\s*\d{3,5}[a-z]{0,3})?|i[3579](?:[- ]?\d{4,5}[a-z]{0,3})?|core\s+i[3579])\b/i.test(title);
  const hasSystemParts =
    /\b(?:ram|ssd|nvme|windows\s*1[01]|win1[01])\b/i.test(title);

  if (hasCpuSignal && hasSystemParts) {
    return true;
  }

  // Some laptop/desktop titles omit the words "laptop" or "komputer".
  // If the title contains several whole-system specifications (RAM, SSD,
  // screen refresh rate, operating system), it is not a standalone GPU.
  const systemComponentHits = [
    /\b\d{1,3}\s*gb\s+ram\b/i,
    /\b(?:ssd|nvme)\b/i,
    /\b\d+(?:[.,]\d+)?\s*tb\b/i,
    /\b(?:windows\s*1[01]|win1[01])\b/i,
    /\b\d{2,3}\s*hz\b/i,
  ].filter((pattern) => pattern.test(title)).length;

  const explicitStandaloneGpuSignal =
    /\b(?:karta graficzna|graphics card|gddr\d?|vram)\b/i.test(title);

  if (!explicitStandaloneGpuSignal && systemComponentHits >= 2) {
    return true;
  }

  // Reject unrelated pages that happened to inherit GPU terms in a snippet.
  const gpuSignals = [
    "rtx",
    "gtx",
    "radeon",
    "geforce",
    "karta graficzna",
    "graphics card",
  ];

  if (!gpuSignals.some((signal) => combined.includes(signal))) {
    return true;
  }

  return false;
}

function queryExplicitlyAllowsDamagedProduct(parsed: ParsedQuery): boolean {
  const query = normalizeMatchText(parsed.queryText);

  return [
    "uszkodzon",
    "niesprawn",
    "do naprawy",
    "na czesci",
    "na części",
    "broken",
    "damaged",
    "for parts",
    "defective",
  ].some((signal) => query.includes(normalizeMatchText(signal)));
}

function isExplicitlyDamagedProduct(
  title: string,
  content: string,
  parsed: ParsedQuery
): boolean {
  if (queryExplicitlyAllowsDamagedProduct(parsed)) return false;

  const titleText = normalizeMatchText(title);
  const text = normalizeMatchText(`${title} ${content}`);

  const strongTitleSignals = [
    "uszkodzona",
    "uszkodzony",
    "uszkodzone",
    "niestabilna",
    "niestabilny",
    "niesprawna",
    "niesprawny",
    "niesprawne",
    "do naprawy",
    "na czesci",
    "broken",
    "damaged",
    "for parts",
    "defective",
  ];

  if (strongTitleSignals.some((signal) => titleText.includes(signal))) {
    return true;
  }

  const strongBodySignals = [
    "sprzedaje jako uszkodzon",
    "sprzedaję jako uszkodzon",
    "karta jest uszkodzon",
    "produkt jest uszkodzon",
    "sprzet jest uszkodzon",
    "sprzęt jest uszkodzon",
    "stan uszkodzone",
    "stan uszkodzony",
    "stan uszkodzona",
    "na czesci",
    "do naprawy",
    "nie dziala prawidlowo",
    "nie działa prawidłowo",
    "nie jest sprawn",
    "nie laduje sie",
    "nie ładuje się",
    "nie uruchamia sie",
    "nie uruchamia się",
    "for parts only",
  ];

  return strongBodySignals.some((signal) =>
    text.includes(normalizeMatchText(signal))
  );
}

function isGpuWholeSystemAfterVerification(
  title: string,
  content: string,
  url: string,
  parsed: ParsedQuery
): boolean {
  if (parsed.category !== "gpu") return false;

  const titleText = normalizeMatchText(title);
  const text = normalizeMatchText(`${title} ${content}`);
  const urlText = normalizeMatchText(url);

  const explicitWholeSystemSignals = [
    "laptop",
    "notebook",
    "komputer gamingowy",
    "komputer do gier",
    "gaming pc",
    "pc gaming",
    "zestaw komputerowy",
    "desktop pc",
  ];

  if (
    explicitWholeSystemSignals.some(
      (signal) => titleText.includes(signal) || text.includes(signal)
    )
  ) {
    return true;
  }

  if (
    urlText.includes("/laptopy/") ||
    urlText.includes("/laptop/") ||
    urlText.includes("/notebook")
  ) {
    return true;
  }

  const hasLaptopBreadcrumb =
    /\b(?:laptopy|notebooki)\b/i.test(text) &&
    !/\b(?:karta graficzna|graphics card)\b/i.test(titleText);

  if (hasLaptopBreadcrumb) return true;

  const hasCpuSignal =
    /\b(?:ryzen\s*[3579](?:\s*\d{3,5}[a-z]{0,3})?|i[3579](?:[- ]?\d{4,5}[a-z]{0,3})?|core\s+i[3579])\b/i.test(titleText);

  const systemComponentHits = [
    /\b\d{1,3}\s*gb\s+ram\b/i,
    /\b(?:ssd|nvme)\b/i,
    /\b\d+(?:[.,]\d+)?\s*tb\b/i,
    /\b(?:windows\s*1[01]|win1[01])\b/i,
    /\b\d{2,3}\s*hz\b/i,
  ].filter((pattern) => pattern.test(titleText)).length;

  const explicitStandaloneGpuSignal =
    /\b(?:karta graficzna|graphics card|gddr\d?|vram)\b/i.test(titleText);

  if (
    !explicitStandaloneGpuSignal &&
    (systemComponentHits >= 2 || (hasCpuSignal && systemComponentHits >= 1))
  ) {
    return true;
  }

  return false;
}


function isVacuumAccessoryOnlyTitle(
  titleRaw: string,
  urlRaw = ""
): boolean {
  const title = normalizeMatchText(titleRaw);
  const scope = normalizeMatchText(`${titleRaw} ${urlRaw}`);

  const strongAccessoryOnlyPatterns = [
    /\b(?:zestaw\s+)?akcesori[a-z]*\s+do\s+(?:robota|odkurzacza)\b/i,
    /\b(?:filtr|filtry|szczotka|szczotki|mop|mopy|worek|worki|bateria|akumulator|ladowarka|rura|ssawka|kolo|silnik)\s+do\s+(?:robota|odkurzacza|stacji)\b/i,
    /\bczesci\s+do\s+(?:robota|odkurzacza)\b/i,
    /\b(?:replacement|spare)\s+(?:filter|brush|mop|battery|parts?)\b/i,
  ];

  if (strongAccessoryOnlyPatterns.some((pattern) => pattern.test(scope))) {
    return true;
  }

  // A genuine robot bundle may legitimately say "+ akcesoria", "7 mopów",
  // "ze stacją" etc. Do not reject the main product just because extras are
  // included with it.
  if (hasRobotVacuumSignal(titleRaw)) {
    return false;
  }

  return /\b(?:akcesoria|filtr|filtry|szczotka|szczotki|mop|mopy|worek|worki|bateria|akumulator|ladowarka|rura|ssawka|czesci)\b/i.test(
    title
  );
}

function isGenericCeneoTitle(titleRaw: string): boolean {
  const title = normalizeMatchText(titleRaw);

  return (
    !title ||
    title === "ceneo" ||
    title.startsWith("ceneo porownanie cen") ||
    title.startsWith("ceneo - porownanie cen") ||
    title.includes("sklepy internetowe kup najtaniej")
  );
}

function hasReferenceOnlyPriceContext(valueRaw: string): boolean {
  const text = normalizeMatchText(valueRaw);

  return /\b(?:cena\s+katalogowa|cena\s+sugerowana|sugerowana\s+cena|cena\s+producenta|msrp|cena\s+nowego|nowy\s+kosztowal|nowy\s+kosztuje|wartosc\s+katalogowa)\b/i.test(
    text
  );
}

function hasFinancingOnlyPriceContext(valueRaw: string): boolean {
  const text = normalizeMatchText(valueRaw);

  // Shops frequently append a representative loan/instalment example to the
  // product page. Amounts such as "całkowita kwota pożyczki: 1000 zł" or
  // "10 rat po 100 zł" are not the product price and must never win merely
  // because they are accompanied by words such as "koszt" or "do zapłaty".
  return /\b(?:przyklad\s+reprezentatywny|kwota\s+pozyczki|pozyczk[aeyi]|rrso|oprocentowan[a-z]*|rat(?:a|y|ach|ami|e)?|miesieczn[a-z]*\s+rat|calkowit[a-z]*\s+koszt\s+kredyt|kredytowan[a-z]*|umow[a-z]*\s+o\s+kredyt|payu\s+s\.a\.|bank\s+s\.a\.)\b/i.test(
    text
  );
}

function hasFilterRangePriceContext(valueRaw: string): boolean {
  const text = normalizeMatchText(valueRaw);

  // Category pages expose price-facet boundaries next to real products, e.g.
  // "Cena filter 2 000 zł - 2 999,99 zł". Those boundaries describe a filter,
  // not any offer. Keep the rule language-agnostic enough for Polish stores.
  return (
    /\b(?:cena|price)\s+(?:filter|filtr[a-z]*)\b/i.test(text) ||
    /\b(?:zakres\s+cen|price\s+range|filtr[a-z]*\s+cen)\b/i.test(text)
  );
}

function hasVacuumMappingIntent(parsed: ParsedQuery): boolean {
  if (parsed.category !== "vacuum") return false;

  const query = normalizeMatchText(parsed.queryText);

  return /\b(?:mapuj[a-z]*|mapowan[a-z]*|lidar|nawigac[a-z]*|slam|smart\s*map[a-z]*|laserow[a-z]*)\b/i.test(
    query
  );
}

function hasRobotVacuumSignal(valueRaw: string): boolean {
  const text = normalizeMatchText(valueRaw);

  return /\b(?:robot(?:\s+(?:sprzatajacy|odkurzajacy|czyszczacy))?|robotyczn[a-z]*|odkurzacz\s+automatyczny|automatyczny\s+odkurzacz|robot\s+vacuum|roomba|roborock|deebot|dreame|ecovacs|irobot|xiaomi\s+robot|eufy|narwal|mova|viomi)\b/i.test(
    text
  );
}

function hasVacuumMappingEvidence(valueRaw: string): boolean {
  const text = normalizeMatchText(valueRaw);

  return /\b(?:mapuj[a-z]*|mapowan[a-z]*|mapa|mape|mapy|mapie|mapach|lidar|lds|vslam|visual\s+slam|d-?tof|tof|nawigac[a-z]*|navigation|slam|smart\s*map[a-z]*|mapping|imprint\s*smart\s*mapping|laserow[a-z]*|laser\s+navigation|skanowan[a-z]*\s+pomieszcz[a-z]*|plan[a-z]*\s+pomieszcz[a-z]*|zapamiet[a-z]*\s+map[a-z]*|tworzen[a-z]*\s+map[a-z]*)\b/i.test(
    text
  );
}

function hasStrongVacuumMappingIdentityEvidence(valueRaw: string): boolean {
  const text = normalizeMatchText(valueRaw);

  // V32.12: this is intentionally stricter than the full-page evidence matcher.
  // It is used for Ceneo product identity only, so generic recommendation text
  // from the same page cannot make a non-mapping model look relevant.
  return /\b(?:lidar|lds|vslam|slam|mapping|mapowan[a-z]*|mapuj[a-z]*|nawigac[a-z]*|navigation|laser(?:ow[a-z]*)?|laser)\b/i.test(
    text
  );
}

function hasNegativeVacuumMappingEvidence(valueRaw: string): boolean {
  const text = normalizeMatchText(valueRaw);

  return /\b(?:bez\s+(?:funkcji\s+)?mapowan[a-z]*|brak\s+(?:funkcji\s+)?mapowan[a-z]*|nie\s+mapuj[a-z]*|bez\s+lidar[a-z]*|bez\s+lidaru|brak\s+lidar[a-z]*|nie\s+(?:posiada|ma)\s+lidar[a-z]*|losow[a-z]*\s+nawigac[a-z]*|random\s+navigation)\b/i.test(
    text
  );
}

function buildVacuumFeatureProofPhrase(productNameRaw: string): string {
  let text = normalizeText(productNameRaw)
    .replace(/^\s*\d{5,9}\s+(?=[\p{L}])/u, " ")
    .replace(/\.html\b/giu, " ")
    .replace(/\|.*$/g, " ")
    .replace(/\b(?:robot\s+sprz[a-ząćęłńóśźż]*|robot\s+vacuum|odkurzacz\s+automatyczny|odkurzacz|automatyczny)\b/giu, " ")
    .replace(/\b(?:nowy|nowa|nowe|uzywany|używany|uzywana|używana|kompletny|kompletna|bialy|biały|czarny|czarna)\b/giu, " ")
    .replace(/\b(?:z\s+gwarancja\s+producenta|z\s+gwarancją\s+producenta|z\s+gwarancja|z\s+gwarancją|ze\s+stacja\s+bazowa|ze\s+stacją\s+bazową|ze\s+stacja|ze\s+stacją|stacja\s+bazowa|stacja\s+bazową|stacja\s+bazowa|akcesoria|gratisy|mopowanie|funkcja\s+mopowania|aktywne\s+mopowanie)\b/giu, " ")
    .replace(/\b(?:kup\s+teraz|do\s+negocjacji|promowane|sprzedajacy|sprzedający)\b/giu, " ")
    .replace(/[+|–—,:;]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // Keep brand + model, not seller fluff. Exact-phrase searches work much
  // better when the query is short and model-centric.
  if (text.length > 90) {
    text = text.slice(0, 90).replace(/\s+\S*$/, "").trim();
  }

  return text;
}


// ============================================================
// V32.12 UNIVERSAL REQUIREMENT EVIDENCE ENGINE
// ============================================================
// A seller title/description often omits technical capabilities that belong to
// the exact model (e.g. mapping, 165 Hz, Wi-Fi 6, OLED). Instead of creating a
// category-specific proof function for every product type, V32.12 can verify
// model-level requirements with one lightweight exact-model search.
//
// IMPORTANT: only model/spec capabilities may be proven externally. Listing-
// specific facts (colour, shoe/clothing size, bundle contents) must still be
// visible in the actual offer, because another listing of the same model may
// legitimately differ.

const universalBrandProofCache = new Map<string, Promise<string>>();

function extractUniversalSharedConcreteModelCode(titleRaw: string, urlRaw: string, parsed: ParsedQuery): string {
  const title = normalizeText(titleRaw);
  let decodedUrl = normalizeText(urlRaw);
  try { decodedUrl = decodeURIComponent(decodedUrl); } catch {}
  const titleNorm = normalizeMatchText(title);
  const urlNorm = normalizeMatchText(decodedUrl);
  const requirementNumbers = new Set<string>(parsed.intent.required.flatMap((requirement) => [requirement.value, ...requirement.aliases]).flatMap((value) => Array.from(String(value).matchAll(/\b\d{2,8}\b/g)).map((m) => m[0])));
  if (parsed.maxPrice !== null) requirementNumbers.add(String(Math.round(parsed.maxPrice)));
  const candidates = Array.from(titleNorm.matchAll(/\b[a-z0-9][a-z0-9._-]{2,23}\b/giu)).map((match) => ({ token: match[0], index: match.index ?? 0 })).filter(({ token }) => /\d/.test(token));
  const scored: Array<{code:string;score:number}> = [];
  for (const candidate of candidates) {
    const code = compactUniversalModelCode(candidate.token);
    if (!code || !urlNorm.includes(code)) continue;
    if (!(/[a-z]/i.test(code) && /\d/.test(code)) && !/^\d{4,8}$/.test(code)) continue;
    if (/^\d+$/.test(code) && requirementNumbers.has(code)) continue;
    const before = titleNorm.slice(Math.max(0, candidate.index - 36), candidate.index);
    const after = titleNorm.slice(candidate.index + candidate.token.length, candidate.index + candidate.token.length + 38);
    const around = `${before} ${candidate.token} ${after}`;
    let score = /[a-z]/i.test(code) && /\d/.test(code) ? 5 : 0;
    if (title.toLowerCase().includes(`(${candidate.token.toLowerCase()})`) || title.toLowerCase().includes(`[${candidate.token.toLowerCase()}]`)) score += 7;
    if (/\b(?:model|modelu|numer\s+produktu|product\s+(?:number|code)|kod|mpn|sku)\s*[:#-]?\s*$/iu.test(before)) score += 6;
    if (urlNorm.endsWith(code) || new RegExp(`${escapeRegExp(code)}(?:\.html?)?$`, "iu").test(urlNorm)) score += 4;
    if (/\b(?:element(?:ow|ów|y)?|szt|sztuk|gb|tb|hz|pa|kg|rpm|mbps|mb\s*\/\s*s|zl|pln)\b/iu.test(around)) score -= 8;
    if (/^\d{4}$/.test(code) && Number(code) >= 1900 && Number(code) <= 2100) score -= 5;
    score += Math.min(3, Math.floor(code.length / 4));
    scored.push({code,score});
  }
  scored.sort((a,b)=>b.score-a.score || b.code.length-a.code.length);
  return scored[0]?.score >= 3 ? scored[0].code : "";
}

function universalReferenceBindsCodeAndBrand(result: SearchResult, codeRaw: string, parsed: ParsedQuery): boolean {
  const code = compactUniversalModelCode(codeRaw);
  if (!code) return false;
  const evidence = normalizeMatchText(`${result.name} ${result.snippet} ${result.url}`);
  if (!compactUniversalModelCode(evidence).includes(code)) return false;
  const host = getResultHostname(result.url);
  if (host && isOfficialBrandHostForParsed(host, parsed)) return true;
  return getUniversalRequestedBrandAliases(parsed).some((alias) => universalEvidenceHasBoundedIdentityTerm(alias, evidence));
}

function extractExplicitRequestedBrandFromBoundEvidence(
  evidenceRaw: string,
  parsed: ParsedQuery
): string {
  if (!parsed.brand) return "";
  const evidence = normalizeMatchText(evidenceRaw);
  if (!evidence) return "";

  for (const aliasRaw of getUniversalRequestedBrandAliases(parsed)) {
    const alias = normalizeMatchText(aliasRaw);
    if (!alias) continue;
    const aliasPattern = escapeRegExp(alias).replace(/\\s\+/g, "\\s+");
    const labeled = new RegExp(
      `\\b(?:marka|brand|producent|manufacturer)\\s*(?::|=|-)?\\s*${aliasPattern}(?=$|[^a-z0-9])`,
      "iu"
    );
    if (labeled.test(evidence)) return normalizeText(parsed.brand);
  }

  return "";
}

async function findUniversalBrandProofViaSharedModelCode(productNameRaw: string, productUrlRaw: string, parsed: ParsedQuery, externalSignal?: AbortSignal): Promise<string> {
  if (!parsed.brand || parsed.category === "phone") return "";
  const code = extractUniversalSharedConcreteModelCode(productNameRaw, productUrlRaw, parsed);
  if (!code) return "";
  const brand = normalizeText(parsed.brand);
  const key = `${normalizeMatchText(brand)}::${code}`;
  const cached = universalBrandProofCache.get(key); if (cached) return cached;

  const promise = (async (): Promise<string> => {
    const domainLabel = normalizeMatchText(brand).replace(/[^a-z0-9]/g, "");
    const queries = Array.from(new Set([
      `"${code}" ${brand}`,
      domainLabel.length >= 3 ? `site:${domainLabel}.com "${code}"` : "",
    ].filter(Boolean)));

    const originalHost = getResultHostname(productUrlRaw);
    const independentHosts = new Set<string>();

    const evaluateResults = (results: SearchResult[]): string => {
      for (const result of results) {
        if (!universalReferenceBindsCodeAndBrand(result, code, parsed)) continue;
        const host = getResultHostname(result.url);
        if (!host) continue;

        if (isOfficialBrandHostForParsed(host, parsed)) {
          return normalizeText(`${brand} ${code}`);
        }

        if (host === originalHost) continue;

        const isPeerMarketplace = V28_UNIVERSAL_MARKETPLACE_DOMAINS.some(
          (marketplaceHost) => host === String(marketplaceHost)
        );
        const exactCategoryCommerceReference =
          !isPeerMarketplace &&
          isConfiguredCommerceDomain(result.url) &&
          evaluateUniversalProductMatch(
            result.name,
            result.snippet,
            result.url,
            parsed,
            "discovery",
            result.source
          ).pass;

        // One independent first-party commerce product page may prove brand
        // only when it binds the SAME concrete model code and requested class.
        if (exactCategoryCommerceReference) {
          return normalizeText(`${brand} ${code}`);
        }

        independentHosts.add(host);
        if (independentHosts.size >= 2) {
          return normalizeText(`${brand} ${code}`);
        }
      }

      return "";
    };

    // V34.CORE120: do not make a strong exact-model brand proof wait for the
    // slowest search engine. live runs had official/brand+code Bing
    // results already available, but Promise.all still waited for a late DDG
    // lane and the candidate hit the verifier deadline before those strong
    // results were consumed. Process the deterministic Bing/reference wave
    // first and return immediately on official/first-party proof.
    const primaryTasks: Array<Promise<SearchResult[]>> = [];
    for (const [queryIndex, query] of queries.entries()) {
      primaryTasks.push(
        withDeadline(searchBingRssReference(query, externalSignal), 1_750, [], `brand proof RSS ${code}`)
      );
      primaryTasks.push(
        withDeadline(searchBingReference(query, externalSignal), 1_750, [], `brand proof HTML ${code}`)
      );

      if (queryIndex === 0) {
        primaryTasks.push(
          withDeadline(searchBingRss(query, externalSignal), 1_500, [], `brand proof ordinary RSS ${code}`)
        );
        primaryTasks.push(
          withDeadline(searchBing(query, externalSignal), 1_500, [], `brand proof ordinary HTML ${code}`)
        );
      }
    }

    const primaryBatches = await Promise.all(primaryTasks);
    if (externalSignal?.aborted) return "";

    const primaryProof = evaluateResults(primaryBatches.flat());
    if (primaryProof) return primaryProof;

    // Independent-engine fallback is deliberately second-wave. It can add a
    // second host for consensus, but it can no longer block an already-sufficient
    // official/first-party exact-code proof.
    const strongestQuery = queries[0] ?? "";
    if (strongestQuery) {
      const fallback = await withDeadline(
        searchDuckDuckGo(strongestQuery, externalSignal),
        1_550,
        [],
        `brand proof DuckDuckGo ${code}`
      );
      if (externalSignal?.aborted) return "";

      const fallbackProof = evaluateResults(fallback);
      if (fallbackProof) return fallbackProof;
    }

    return independentHosts.size >= 2
      ? normalizeText(`${brand} ${code}`)
      : "";
  })();

  universalBrandProofCache.set(key, promise);
  return promise;
}

const universalRequirementProofCache = new Map<string, Promise<string>>();
// Empty network proof is transient (search engines throttle, snippets fluctuate).
// Never poison the exact-model cache indefinitely with an empty Promise result.
// A short cooldown prevents a verification fan-out from immediately launching
// duplicate retries, while still allowing a later candidate/request to recover.
const universalRequirementProofNegativeUntil = new Map<string, number>();

function canUseExternalProofForRequirement(requirement: UniversalRequirement): boolean {
  if (!requirement.hard) return false;
  if (requirement.kind === "color" || requirement.kind === "bundle") return false;

  // These values can legitimately vary between offers/configurations that share
  // the same product family/chassis name. They must stay bound to the concrete
  // listing and may never be borrowed from another page merely because the
  // model family matches. This is especially important for configurable
  // laptops/phones and for package-size/volume variants.
  if (
    [
      "shoe_size",
      "clothing_size",
      "battery_included",
      "battery_count",
      "ram",
      "storage",
      "vram",
      "gpu_model",
      "capacity",
      "volume",
      "package_weight",
      "serving_weight",
      "material",
    ].includes(requirement.key)
  ) {
    return false;
  }

  // Product class/type is a stable model-level fact when an exact model/SKU
  // anchor exists. The proof engine below refuses generic products and only
  // accepts exact-model-bound independent evidence, so a seller does not have
  // to repeat the full class name in every listing title.
  if (requirement.key === "tool_type") return true;

  return (
    requirement.kind === "feature" ||
    requirement.kind === "spec" ||
    requirement.kind === "compatibility" ||
    requirement.key === "screen_size"
  );
}

function buildUniversalProofPhrase(
  productNameRaw: string,
  parsed: ParsedQuery | null = null
): string {
  let text = normalizeText(productNameRaw)
    .replace(/\|.*$/g, " ")
    .replace(/\s+•\s+.*$/g, " ")
    .replace(/\s+-\s+(?:opinie|ceny|oferty).*$/giu, " ")
    .replace(/\b(?:kup\s+teraz|do\s+negocjacji|promowane|sprzedajacy|sprzedający|oferta|ogloszenie|ogłoszenie)\b/giu, " ")
    .replace(/\b(?:nowy|nowa|nowe|uzywany|używany|uzywana|używana|kompletny|kompletna)\b/giu, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!text) return "";

  const normalizedTokens = normalizeMatchText(text)
    .replace(/[^a-z0-9+\- ]/g, " ")
    .split(/\s+/)
    .filter(Boolean);

  const isSpecToken = (token: string) =>
    /^\d+(?:gb|tb|hz|v|w|mah|mm|cm|fps)$/i.test(token) ||
    /^(?:gddr|ddr)\d+$/i.test(token);

  // When the user's query contains a concrete identity/model term, prefer that
  // exact term over incidental spec tokens in the seller title. Example:
  // "RTX 4060 ... 8GB GDDR6" must anchor proof on 4060, not GDDR6.
  const requestedIdentityTerms = parsed
    ? Array.from(new Set([
        ...parsed.intent.strongIdentityTerms,
        ...parsed.intent.identityTerms,
      ]))
        .map(normalizeMatchText)
        .filter((term) => term.length >= 2 && !isSpecToken(term))
    : [];

  const canonicalRequestedModelTerm =
    findCanonicalRequestedModelTermInTokenWindow(
      normalizedTokens,
      requestedIdentityTerms
    );

  if (canonicalRequestedModelTerm && parsed) {
    const brandIdentity = normalizeMatchText(parsed.brand ?? "");
    const familyTerms = parsed.intent.qualifierTerms
      .map((term) => normalizeMatchText(term))
      .filter(Boolean)
      .filter((term) => !/\d/.test(term))
      .filter((term) => !UNIVERSAL_PROOF_STOP_WORDS.has(term))
      .filter((term) => term !== brandIdentity)
      .filter((term) => term.length >= 2 && term.length <= 24)
      .slice(0, 2);

    const canonicalIdentity = normalizeText(
      [brandIdentity, ...familyTerms, canonicalRequestedModelTerm]
        .filter(Boolean)
        .join(" ")
    );
    if (canonicalIdentity.length >= 4) return canonicalIdentity;
  }

  let modelIndex = -1;
  for (const requested of requestedIdentityTerms) {
    const idx = normalizedTokens.findIndex((token) => token === requested);
    if (idx >= 0 && /\d/.test(requested)) {
      modelIndex = idx;
      break;
    }
  }

  // Without a query-model anchor, prefer compact alphanumeric model tokens
  // (short and long alphanumeric model tokens), but ignore obvious specs such as GDDR6.
  if (modelIndex < 0) {
    modelIndex = normalizedTokens.findIndex(
      (token) =>
        !isSpecToken(token) &&
        /[a-z]/i.test(token) &&
        /\d/.test(token)
    );
  }

  if (modelIndex < 0) {
    modelIndex = normalizedTokens.findIndex(
      (token) => /^\d{1,5}$/.test(token) && !isSpecToken(token)
    );
  }

  if (modelIndex >= 0) {
    const modelToken = normalizedTokens[modelIndex];

    // V34.CORE120: build one canonical exact-model proof identity instead of
    // copying the +/-3 words around the code from a user/seller phrase. Words
    // such as "sama", "body", RAM/SSD labels or bundle descriptions are
    // search constraints, not model identity and can make a valid reference
    // page impossible to find. Keep brand + a small lexical family + exact code.
    if (parsed && modelToken) {
      const brandIdentity = normalizeMatchText(parsed.brand ?? "");
      const queryIdentityTerms = new Set(
        [
          ...parsed.intent.identityTerms,
          ...parsed.intent.strongIdentityTerms,
          ...parsed.intent.qualifierTerms,
          parsed.category ?? "",
        ]
          .map((term) => normalizeMatchText(term))
          .filter(Boolean)
      );

      // V34.CORE120: when the user did not name the candidate brand/family,
      // short model tokens can be dangerously ambiguous on the open web. Derive
      // a few lexical identity terms from the CONCRETE candidate title around
      // the model code instead of reducing the proof phrase to a generic
      // query qualifier + bare code.
      // This changes proof retrieval only; proof acceptance still has to bind
      // the exact model and the candidate identity below.
      const candidateIdentityTerms = normalizedTokens
        .slice(Math.max(0, modelIndex - 5), modelIndex)
        .filter((term) => !/\d/.test(term))
        .filter((term) => !UNIVERSAL_PROOF_STOP_WORDS.has(term))
        .filter((term) => !isSpecToken(term))
        .filter((term) => term !== brandIdentity)
        .filter((term) => !queryIdentityTerms.has(term))
        .filter((term) => term.length >= 3 && term.length <= 28)
        .slice(-4);

      const familyTerms = parsed.intent.qualifierTerms
        .map((term) => normalizeMatchText(term))
        .filter(Boolean)
        .filter((term) => !/\d/.test(term))
        .filter((term) => !UNIVERSAL_PROOF_STOP_WORDS.has(term))
        .filter((term) => !isSpecToken(term))
        .filter((term) => term !== brandIdentity)
        .filter((term) => term.length >= 2 && term.length <= 24)
        .slice(0, 2);

      const identityTerms = candidateIdentityTerms.length > 0
        ? candidateIdentityTerms
        : familyTerms;

      const canonicalIdentity = normalizeText(
        Array.from(new Set([brandIdentity, ...identityTerms, modelToken].filter(Boolean))).join(" ")
      );
      if (canonicalIdentity.length >= 4) return canonicalIdentity;
    }

    const from = Math.max(0, modelIndex - 3);
    const to = Math.min(normalizedTokens.length, modelIndex + 3);

    const compact = normalizedTokens
      .slice(from, to)
      .filter((token) => !UNIVERSAL_PROOF_STOP_WORDS.has(token))
      .filter((token) => !isSpecToken(token) || token === normalizedTokens[modelIndex])
      .join(" ")
      .trim();

    if (compact.length >= 4) return compact;
  }

  // No model number: only use a proof query when at least two distinctive
  // non-generic tokens survive. A bare generic product + brand is intentionally
  // not enough to prove a hard capability for a specific listing.
  const distinctive = normalizedTokens
    .filter((token) => !UNIVERSAL_PROOF_STOP_WORDS.has(token))
    .filter((token) => !isSpecToken(token))
    .slice(0, 6);

  if (distinctive.length < 2) return "";

  return distinctive.join(" ").slice(0, 100).trim();
}

const UNIVERSAL_PROOF_STOP_WORDS = new Set([
  "robot", "sprzatajacy", "sprzątający", "odkurzacz", "automatyczny",
  "karta", "graficzna", "telefon", "smartfon", "smartphone", "monitor",
  "telewizor", "tv", "laptop", "notebook", "sluchawki", "słuchawki",
  "mysz", "klawiatura", "ekspres", "buty", "krzeslo", "krzesło",
  "wiertarka", "wkretarka", "wkrętarka", "zestaw", "stacja", "bazowa",
  "bialy", "biały", "czarny", "czarna", "white", "black",
  "nowy", "nowa", "nowe", "uzywany", "używany",
  // Offer/bundle grammar is not part of exact model identity. These tokens
  // previously allowed bundle/query modifiers to poison exact-model proof queries.
  "sam", "sama", "samo", "same", "samą", "tylko", "only", "solo",
  "body", "bare", "korpus", "bez", "without",
  // Configuration labels describe one listing/configuration, not the chassis/SKU
  // identity used by the static proof engine. Values remain listing-bound below.
  "ram", "ssd", "nvme", "hdd", "storage", "dysk", "dysku", "pamiec", "pamięć",
  "ddr3", "ddr4", "ddr5", "dimm", "udimm", "sodimm", "cl", "mhz", "mts",
  "gpu", "vram",
  "z", "ze", "akcesoria", "gratisy", "gratis", "gwarancja", "producenta", "+",
  "kup", "teraz", "cena", "opinie", "oferty", "oferta"
]);

function getUniversalProofIdentityTerms(productNameRaw: string): string[] {
  const normalized = normalizeMatchText(productNameRaw);
  const tokens = normalized
    .replace(/[^a-z0-9+\- ]/g, " ")
    .split(/\s+/)
    .map((token) => token.trim())
    .filter((token) => token.length >= 2 && !UNIVERSAL_PROOF_STOP_WORDS.has(token));

  const modelLike = tokens.filter((token) => /\d/.test(token));
  const descriptive = tokens.filter((token) => !/\d/.test(token) && token.length >= 4);

  return Array.from(new Set([...modelLike, ...descriptive])).slice(0, 8);
}

function isUniversalRequirementDerivedModelToken(
  tokenRaw: string,
  parsed: ParsedQuery
): boolean {
  const token = normalizeMatchText(tokenRaw)
    .replace(/[^a-z0-9+\-]/giu, "")
    .toLowerCase();
  if (!token) return false;
  const compactToken = token.replace(/[^a-z0-9+]/giu, "");

  for (const requirement of parsed.intent.required) {
    const surfaces = [requirement.value, ...requirement.aliases];
    for (const surfaceRaw of surfaces) {
      const surfaceTokens = normalizeMatchText(surfaceRaw)
        .replace(/[^a-z0-9+\-]+/giu, " ")
        .split(/\s+/)
        .map((part) => part.replace(/[^a-z0-9+\-]/giu, "").toLowerCase())
        .filter(Boolean);
      if (surfaceTokens.includes(token)) return true;

      const compactSurface = normalizeMatchText(surfaceRaw)
        .replace(/[^a-z0-9+\-]/giu, "")
        .toLowerCase();
      if (compactSurface && compactSurface === token) return true;

      // CORE70: public retailer filter slugs frequently hyphenate a hard
      // requirement that was written with spaces (RTX 4060 -> rtx-4060).
      // Separator-only differences still describe the same requirement token;
      // this must not manufacture fake product/model specificity. Composite
      // model codes remain safe because 18V-55 != 18V after separator removal.
      const compactSurfaceNoSeparators = compactSurface.replace(
        /[^a-z0-9+]/giu,
        ""
      );
      if (
        compactToken &&
        compactSurfaceNoSeparators &&
        compactSurfaceNoSeparators === compactToken
      ) {
        return true;
      }
    }
  }

  return false;
}

function getUniversalExactModelAnchor(
  parsed: ParsedQuery,
  phraseRaw: string
): string {
  const isObviousSpecToken = (tokenRaw: string): boolean => {
    const token = normalizeMatchText(tokenRaw).replace(/\s+/g, "");
    return /^(?:\d+(?:gb|tb|mhz|mts|hz|v|w|mah|ah|mm|cm|ml|l)|cl\d+|\d+x\d+(?:gb|tb)|ddr\d+|gddr\d+)$/iu.test(token);
  };

  const candidates = Array.from(new Set([
    ...parsed.intent.qualifierTerms,
    ...parsed.intent.strongIdentityTerms,
    ...parsed.intent.identityTerms,
    ...getUniversalProofIdentityTerms(phraseRaw),
  ]))
    .map((value) => normalizeMatchText(value))
    .filter(Boolean)
    .filter((value) => /[a-z]/iu.test(value) && /\d/.test(value))
    .filter((value) => !isObviousSpecToken(value))
    // V34.CORE120: a fragment taken from a hard requirement (e.g. R16 from
    // 205/55 R16) is specification evidence, not a product MPN/model anchor.
    // Composite model tokens such as 18V-55 stay eligible because they are not
    // equal to the standalone requirement token 18V.
    .filter((value) => !isUniversalRequirementDerivedModelToken(value, parsed))
    .sort((a, b) => b.replace(/[^a-z0-9]/giu, "").length - a.replace(/[^a-z0-9]/giu, "").length);

  return candidates.find((value) => value.replace(/[^a-z0-9]/giu, "").length >= 3) ?? "";
}

function getBoundedUniversalModelReferenceScope(
  scopeRaw: string,
  phraseRaw: string,
  modelAnchorRaw: string
): string {
  const scope = normalizeText(scopeRaw);
  if (!scope) return "";

  // A concrete reference page may contain recommendations far below the
  // product. Only the head of the page is eligible and it must bind the exact
  // requested identity/model. This prevents a neighbouring recommendation
  // from lending specs to the current offer.
  const head = scope.slice(0, 42_000);
  const identityHead = head.slice(0, 12_000);
  const modelAnchor = normalizeMatchText(modelAnchorRaw);

  const identityBound = universalProofMatchesProductIdentity(
    phraseRaw,
    identityHead
  );
  const exactModelBound = Boolean(modelAnchor) &&
    titleContainsUniversalModelCode(identityHead, modelAnchor);

  return identityBound || exactModelBound ? head : "";
}

function universalProofMatchesProductIdentity(
  productNameRaw: string,
  evidenceRaw: string
): boolean {
  const evidence = normalizeMatchText(evidenceRaw);
  const terms = getUniversalProofIdentityTerms(productNameRaw);
  if (terms.length === 0) return false;

  const modelTerms = terms.filter((term) => /\d/.test(term));
  if (modelTerms.length > 0) {
    const modelMatches = modelTerms.filter((term) =>
      universalEvidenceHasBoundedIdentityTerm(term, evidence)
    ).length;

    if (modelMatches < Math.max(1, Math.ceil(modelTerms.length * 0.5))) {
      return false;
    }
  }

  const matched = terms.filter((term) =>
    universalEvidenceHasBoundedIdentityTerm(term, evidence)
  ).length;

  return matched >= Math.max(1, Math.min(2, terms.length));
}

function isWeakUniversalExternalProofAnchor(anchorRaw: string): boolean {
  const compact = compactUniversalModelCode(anchorRaw);
  if (!compact) return true;

  // Short alpha-numeric codes are routinely reused across unrelated product
  // categories. They are useful anchors only when the surrounding concrete
  // candidate identity is bound as well.
  return compact.length <= 4;
}

function universalProofResultBindsExactRequestedModel(
  proof: SearchResult,
  parsed: ParsedQuery,
  exactModelAnchorRaw: string,
  phraseRaw = ""
): boolean {
  const exactModelAnchor = normalizeMatchText(exactModelAnchorRaw);
  if (!exactModelAnchor) return false;

  const scope = normalizeText(`${proof.name} ${proof.snippet} ${proof.url}`);
  const normalizedScope = normalizeMatchText(scope);
  const weakAnchor = isWeakUniversalExternalProofAnchor(exactModelAnchor);
  const exactModelPresent = weakAnchor
    ? universalEvidenceHasBoundedIdentityTerm(exactModelAnchor, normalizedScope)
    : titleContainsUniversalModelCode(scope, exactModelAnchor);
  if (!scope || !exactModelPresent) {
    return false;
  }

  if (
    phraseRaw &&
    weakAnchor &&
    !universalProofMatchesProductIdentity(phraseRaw, scope)
  ) {
    return false;
  }

  const brand = normalizeMatchText(parsed.brand ?? "");
  if (
    brand &&
    !universalEvidenceHasBoundedIdentityTerm(brand, normalizedScope) &&
    !normalizedScope.replace(/[^a-z0-9]+/g, "").includes(
      brand.replace(/[^a-z0-9]+/g, "")
    )
  ) {
    return false;
  }

  // A result that explicitly names a conflicting sibling/family must never be
  // used as static evidence even if a recommendation/snippet also mentions the
  // requested code somewhere else.
  if (hasUniversalVariantMismatch(proof.name, parsed)) return false;
  if (getUniversalQualifierFamilyConflict(proof.name, parsed)) return false;

  return true;
}


type UniversalRequirementProofCollection = {
  chunks: string[];
  sources: string[];
  provenKeys: Set<string>;
};

function isTrustedUniversalStaticProofSearchResult(
  result: SearchResult,
  parsed: ParsedQuery
): boolean {
  const host = getResultHostname(result.url);
  if (!host || isBlockedOpenWebHost(host)) return false;

  if (isConfiguredCommerceDomain(result.url)) return true;
  if (isConcreteIndependentProductReferenceUrl(result.url, parsed)) return true;

  const brandCompact = compactUniversalModelCode(parsed.brand ?? "");
  const hostCompact = compactUniversalModelCode(host);
  const officialBrandHost =
    Boolean(brandCompact) &&
    brandCompact.length >= 3 &&
    hostCompact.includes(brandCompact);

  // Manufacturer search results often use opaque product IDs instead of a
  // model token in the URL (e.g. /products/?id=123). Requiring a product-like
  // path loses the strongest possible source. The collector below still
  // requires exact model + brand binding in title/snippet/URL before any fact
  // is accepted, so an official homepage/category page cannot lend specs.
  if (officialBrandHost) return true;

  return false;
}

type UniversalStaticRequirementVote = {
  requirement: UniversalRequirement;
  hosts: Set<string>;
  weight: number;
  evidence: string[];
  official: boolean;
  retailer: boolean;
};

function isOfficialBrandHostForParsed(hostRaw: string, parsed: ParsedQuery): boolean {
  const host = compactUniversalModelCode(hostRaw);
  const brand = compactUniversalModelCode(parsed.brand ?? "");
  return Boolean(host && brand && brand.length >= 3 && host.includes(brand));
}

function getUniversalStaticReferenceWeight(
  result: SearchResult,
  parsed: ParsedQuery
): number {
  const host = getResultHostname(result.url);
  if (!host) return 0;
  if (isOfficialBrandHostForParsed(host, parsed)) return 5;
  if (isConfiguredCommerceDomain(result.url) && isProbablyRealOfferUrl(result.url)) return 4;
  if (isConcreteIndependentProductReferenceUrl(result.url, parsed)) return 3;
  if (["ceneo.pl", "skapiec.pl", "nokaut.pl", "okazje.info"].includes(host)) return 2;
  return 1;
}

function buildCanonicalRequirementProofToken(requirement: UniversalRequirement): string {
  // Generate only tokens belonging to the requirement already proven by the
  // evidence graph. This synthetic tail never creates a new fact; it simply
  // makes downstream matchers deterministic across languages/wording.
  return normalizeText([
    requirementPrimarySearchTerm(requirement),
    requirement.value,
    ...requirement.aliases.slice(0, 2),
  ].filter(Boolean).join(" "));
}

function collectUniversalStaticRequirementConsensus(
  results: SearchResult[],
  requirements: UniversalRequirement[],
  parsed: ParsedQuery,
  phraseRaw: string,
  exactModelAnchorRaw: string
): UniversalRequirementProofCollection {
  const exactModelAnchor = normalizeMatchText(exactModelAnchorRaw);
  const votes = new Map<string, UniversalStaticRequirementVote>();
  const acceptedChunks: string[] = [];
  const acceptedSources: string[] = [];

  for (const result of results.slice(0, 80)) {
    const host = getResultHostname(result.url);
    if (!host || isBlockedOpenWebHost(host)) continue;
    if (!isTrustedUniversalStaticProofSearchResult(result, parsed)) continue;

    const evidence = normalizeText(`${result.name} ${result.snippet} ${result.url}`);
    if (!evidence) continue;

    const exactBound = exactModelAnchor
      ? universalProofResultBindsExactRequestedModel(result, parsed, exactModelAnchor, phraseRaw)
      : universalProofMatchesProductIdentity(phraseRaw, evidence);
    if (!exactBound) continue;

    const weight = getUniversalStaticReferenceWeight(result, parsed);
    if (weight <= 0) continue;

    const official = isOfficialBrandHostForParsed(host, parsed);
    const retailer = isConfiguredCommerceDomain(result.url);

    for (const requirement of requirements) {
      if (!requirementHasEvidence(requirement, evidence)) continue;
      const current = votes.get(requirement.key) ?? {
        requirement,
        hosts: new Set<string>(),
        weight: 0,
        evidence: [],
        official: false,
        retailer: false,
      };
      if (!current.hosts.has(host)) {
        current.hosts.add(host);
        current.weight += weight;
      }
      current.official ||= official;
      current.retailer ||= retailer;
      if (current.evidence.length < 3) current.evidence.push(evidence.slice(0, 2_500));
      votes.set(requirement.key, current);
    }
  }

  const provenKeys = new Set<string>();
  for (const vote of votes.values()) {
    // One exact-model manufacturer result is enough. One concrete configured
    // retailer exact-model result is also enough. Otherwise require host-diverse
    // corroboration, preventing a single noisy index result from defining a model.
    const proven =
      vote.official ||
      (vote.retailer && vote.weight >= 4) ||
      (vote.hosts.size >= 2 && vote.weight >= 4);
    if (!proven) continue;
    provenKeys.add(vote.requirement.key);
    acceptedChunks.push(...vote.evidence);
    acceptedChunks.push(buildCanonicalRequirementProofToken(vote.requirement));
    acceptedSources.push(
      `${vote.requirement.key} <= ${Array.from(vote.hosts).join(",")}`
    );
  }

  return {
    chunks: acceptedChunks.slice(0, 14),
    sources: acceptedSources.slice(0, 14),
    provenKeys,
  };
}

function isWeakVerificationPageTitle(titleRaw: string, urlRaw: string): boolean {
  const title = normalizeMatchText(titleRaw);
  if (!title) return true;
  const host = getResultHostname(urlRaw);
  const hostStem = normalizeMatchText(host.replace(/^www\./, "").split(".")[0] ?? "");
  if (title === hostStem || title === normalizeMatchText(host)) return true;
  if (/^(?:home|homepage|strona glowna|sklep|shop|store)$/iu.test(title)) return true;
  return title.length < 4;
}

function getListingBoundHardRequirements(parsed: ParsedQuery): UniversalRequirement[] {
  return parsed.intent.required.filter(
    (requirement) => requirement.hard && !canUseExternalProofForRequirement(requirement)
  );
}

function buildOfferEvidenceSummary(
  pageVerified: boolean,
  priceVerified: boolean,
  staticProof: string,
  result: SearchResult,
  parsed: ParsedQuery,
  strongIndexEvidence = false
): { tier: NonNullable<Offer["verificationTier"]>; confidence: number; summary: string[] } {
  const summary: string[] = [];
  let confidence = 35;
  if (titleContainsUniversalModelCode(`${result.name} ${result.url}`, getUniversalExactModelAnchor(parsed, parsed.intent.productPhrase))) {
    confidence += 18;
    summary.push("exact-model identity");
  }
  if (staticProof) {
    confidence += 18;
    summary.push("independent model facts");
  }
  if (priceVerified) {
    confidence += 20;
    summary.push("bound price");
  }
  if (pageVerified) {
    confidence += 15;
    summary.push("product page read");
  }
  if (strongIndexEvidence) {
    confidence += 12;
    summary.push("concrete marketplace index card");
  }
  const tier: NonNullable<Offer["verificationTier"]> = pageVerified && priceVerified
    ? "page-verified"
    : priceVerified
      ? "card-verified"
      : (staticProof || strongIndexEvidence)
        ? "strong-index"
        : "partial";
  return { tier, confidence: Math.max(0, Math.min(100, confidence)), summary };
}

function collectUniversalRequirementProofFromSearchResults(
  results: SearchResult[],
  requirements: UniversalRequirement[],
  parsed: ParsedQuery,
  phraseRaw: string,
  exactModelAnchorRaw: string
): UniversalRequirementProofCollection {
  const phrase = normalizeText(phraseRaw);
  const exactModelAnchor = normalizeMatchText(exactModelAnchorRaw);

  // V34.CORE120 evidence graph: prefer host-diverse consensus / official or
  // concrete retailer exact-model evidence. This makes static model facts
  // resilient to one blocked product page while keeping sibling-model safety.
  const consensus = collectUniversalStaticRequirementConsensus(
    results, requirements, parsed, phrase, exactModelAnchor
  );

  const chunks = [...consensus.chunks];
  const sources = [...consensus.sources];
  const provenKeys = new Set(consensus.provenKeys);
  const seenHosts = new Set<string>();

  // Preserve the previous strong single-result behavior as a fallback.
  for (const result of results.slice(0, 50)) {
    if (!isTrustedUniversalStaticProofSearchResult(result, parsed)) continue;
    const evidence = normalizeText(`${result.name} ${result.snippet} ${result.url}`);
    if (!evidence) continue;
    const exactModelBound = exactModelAnchor
      ? universalProofResultBindsExactRequestedModel(result, parsed, exactModelAnchor, phrase)
      : false;
    if (!exactModelBound && !universalProofMatchesProductIdentity(phrase, evidence)) continue;

    const matchedRequirements = requirements.filter((requirement) =>
      requirementHasEvidence(requirement, evidence)
    );
    if (matchedRequirements.length === 0) continue;

    const host = getResultHostname(result.url) || "unknown";
    const strongSingle =
      isOfficialBrandHostForParsed(host, parsed) ||
      (isConfiguredCommerceDomain(result.url) && isProbablyRealOfferUrl(result.url));
    if (!strongSingle) continue;

    for (const requirement of matchedRequirements) {
      provenKeys.add(requirement.key);
      chunks.push(buildCanonicalRequirementProofToken(requirement));
    }
    if (!seenHosts.has(host)) {
      chunks.push(evidence.slice(0, 2_800));
      sources.push(`${host} | ${result.name}`);
      seenHosts.add(host);
    }
  }

  return { chunks: chunks.slice(0, 18), sources: sources.slice(0, 18), provenKeys };
}

async function findUniversalRequirementProofViaSearch(
  productNameRaw: string,
  requirementsRaw: UniversalRequirement[],
  parsed: ParsedQuery,
  originalUrlRaw = "",
  externalSignal?: AbortSignal
): Promise<string> {
  const phrase = buildUniversalProofPhrase(productNameRaw, parsed);
  const exactModelAnchor = getUniversalExactModelAnchor(parsed, phrase);
  const requestedRequirements = requirementsRaw.filter(
    canUseExternalProofForRequirement
  );
  // For an exact model, build/cache one complete STATIC profile for the whole
  // user query rather than a separate network search for each candidate's
  // missing subset. This is both faster and more deterministic. Configurable
  // or listing-specific keys have already been excluded by the safety gate.
  const requirements = exactModelAnchor
    ? parsed.intent.required.filter(canUseExternalProofForRequirement)
    : requestedRequirements;

  if (phrase.length < 4 || requirements.length === 0) return "";

  const proofIdentityTerms = getUniversalProofIdentityTerms(phrase);
  const proofModelTerms = proofIdentityTerms.filter((term) => /\d/.test(term));

  // External proof still requires concrete model identity. Allow a lexical
  // named-model phrase only when it has distinctive terms plus a version signal.
  const namedDistinctiveTerms = proofIdentityTerms.filter((term) => !isUniversalCategoryIdentityTerm(term, parsed));
  const namedVersionSignal = /\b\d{1,3}(?:[.,]\d{1,2})?\b/iu.test(phrase) || /\b[a-z][a-z0-9]*-[a-z0-9-]*\b/iu.test(normalizeMatchText(phrase));
  const safeNamedModelPhrase = proofModelTerms.length === 0 && namedDistinctiveTerms.length >= 2 && namedVersionSignal;
  if (proofModelTerms.length === 0 && !safeNamedModelPhrase) return "";

  const proofTerms = Array.from(new Set(
    requirements
      .flatMap((requirement) => [requirementPrimarySearchTerm(requirement), ...requirement.aliases.slice(0, 6)])
      .map((value) => normalizeText(value))
      .filter(Boolean)
  )).slice(0, 8);

  // All offers carrying the same exact requested model share one static-spec
  // proof. This prevents four marketplace listings of the same SKU from
  // launching four identical web-search/hydration chains in parallel.
  // Cache by the full canonical product identity, not by the bare model token.
  // Different product families can legitimately reuse the same chassis/code
  // token; sharing proof across them would let one family lend static specs to
  // another request. buildUniversalProofPhrase already strips bundle grammar
  // while preserving brand/family/exact-model identity.
  const proofCacheIdentity = normalizeMatchText(phrase);
  const cacheKey = `${proofCacheIdentity}::${requirements.map((r) => r.key).sort().join(",")}`;
  const cached = universalRequirementProofCache.get(cacheKey);
  if (cached) return cached;

  const negativeUntil = universalRequirementProofNegativeUntil.get(cacheKey) ?? 0;
  if (negativeUntil > Date.now()) return "";
  if (negativeUntil) universalRequirementProofNegativeUntil.delete(cacheKey);

  const promise = (async () => {
    // Keep proof queries compact. V25.4 duplicated model tokens and appended
    // many weak synonyms, which often pushed useful manufacturer/spec pages out
    // of Bing results. Always keep each requirement's primary term, then add a
    // few non-ambiguous aliases. Identity is validated separately below.
    const primaryProofTerms = requirements
      .map(requirementPrimarySearchTerm)
      .map((value) => normalizeText(value))
      .filter(Boolean);

    const secondaryProofTerms = proofTerms
      .filter((value) => {
        const normalized = normalizeMatchText(value);
        return normalized.length >= 4 && !["map", "maps", "mapy", "tak", "yes"].includes(normalized);
      });

    // Keep proof search model-centric. A long synonym bag such as
    // "AX55 wifi 6 wi-fi 6 wifi6 802.11ax wifi 6e" can make the search
    // engine ignore the exact model. Use one natural primary requirement term
    // plus at most one genuinely different technical synonym.
    const primaryUnique = Array.from(new Set(primaryProofTerms));
    const primaryCompact = new Set(
      primaryUnique.map((value) => compactUniversalModelCode(value))
    );
    const primaryRoots = primaryUnique
      .map((value) => compactUniversalModelCode(value).slice(0, 4))
      .filter((value) => value.length >= 3);
    const distinctSecondary = secondaryProofTerms.find((value) => {
      const compact = compactUniversalModelCode(value);
      if (compact.length < 3 || primaryCompact.has(compact)) return false;
      return !primaryRoots.some((root) => compact.startsWith(root));
    });

    const conciseProofTerms = [
      ...primaryUnique.slice(0, 1),
      ...(distinctSecondary ? [distinctSecondary] : []),
    ];

    const cleanPhrase = phrase.replace(/"/g, " ").trim();
    const exactQuery = `"${cleanPhrase}" ${conciseProofTerms.join(" ")}`.trim();
    const relaxedQuery = `${cleanPhrase} ${primaryUnique.slice(0, 1).join(" ")}`.trim();

    const proofIdentityCore =
      exactModelAnchor && isWeakUniversalExternalProofAnchor(exactModelAnchor)
        ? cleanPhrase
        : exactModelAnchor.replace(/"/g, " ");

    const modelOnlyQuery = exactModelAnchor
      ? `"${proofIdentityCore}" ${normalizeText(parsed.brand ?? "")}`.trim()
      : "";

    // Build a small exact-model reference mesh. Search snippets frequently omit
    // one of the requested stable specs, so one monolithic query is brittle.
    // Instead run a few compact model+requirement RSS queries in parallel, plus
    // one general HTML query and two reference-oriented queries. This remains
    // product-agnostic: every term comes from the parsed exact model and the
    // user's hard requirements.
    const requirementQueries = requirements
      .slice(0, 3)
      .map((requirement) => {
        const primary = normalizeText(requirementPrimarySearchTerm(requirement));
        const alternative = normalizeText(
          requirementAlternativeSearchTerm(requirement) ?? ""
        );
        const term = alternative && normalizeMatchText(alternative) !== normalizeMatchText(primary)
          ? `${primary} ${alternative}`
          : primary;
        return exactModelAnchor
          ? `"${proofIdentityCore}" ${normalizeText(parsed.brand ?? "")} ${term}`.trim()
          : `"${cleanPhrase}" ${term}`.trim();
      })
      .filter(Boolean);

    const specificationQuery = exactModelAnchor
      ? `"${proofIdentityCore}" ${normalizeText(parsed.brand ?? "")} specyfikacja specification`.trim()
      : "";
    const comparisonLabelQuery = exactModelAnchor
      ? `"${proofIdentityCore}" ${normalizeText(parsed.brand ?? "")} ceneo`.trim()
      : "";

    const proofSearchTasks: Array<Promise<SearchResult[]>> = [
      withDeadline(
        searchBingRssReference(exactQuery),
        2_650,
        [] as SearchResult[],
        `universal proof RSS: ${phrase}`
      ),
      withDeadline(
        searchBingReference(relaxedQuery),
        2_650,
        [] as SearchResult[],
        `universal proof HTML: ${phrase}`
      ),
      ...(exactModelAnchor
        ? [withDeadline(
            searchDuckDuckGo(exactQuery, externalSignal),
            2_250,
            [] as SearchResult[],
            `universal proof DuckDuckGo: ${phrase}`
          )]
        : []),
    ];

    if (modelOnlyQuery) {
      proofSearchTasks.push(
        withDeadline(
          searchBingRssReference(modelOnlyQuery),
          2_450,
          [] as SearchResult[],
          `universal proof model-only RSS: ${exactModelAnchor}`
        )
      );
      // HTML SERP often exposes concrete product/reference URLs that RSS omits
      // or truncates. Hydration still requires exact model + brand locally, so
      // this adds recall without weakening acceptance.
      proofSearchTasks.push(
        withDeadline(
          searchBingReference(modelOnlyQuery),
          2_450,
          [] as SearchResult[],
          `universal proof model-only HTML: ${exactModelAnchor}`
        )
      );
    }

    for (const query of requirementQueries) {
      proofSearchTasks.push(
        withDeadline(
          searchBingRssReference(query),
          2_450,
          [] as SearchResult[],
          `universal proof requirement RSS: ${query}`
        )
      );
      proofSearchTasks.push(
        withDeadline(
          searchBingReference(query),
          2_450,
          [] as SearchResult[],
          `universal proof requirement HTML: ${query}`
        )
      );
    }

    if (exactModelAnchor) {
      const brandTerm = normalizeText(parsed.brand ?? "");
      const documentQueries = [
        `"${proofIdentityCore}" ${brandTerm} manual pdf`,
        `"${proofIdentityCore}" ${brandTerm} datasheet specifications`,
      ];
      for (const query of documentQueries) {
        proofSearchTasks.push(
          withDeadline(
            searchBingReference(query),
            2_450,
            [] as SearchResult[],
            `universal proof document HTML: ${query}`
          )
        );
      }
    }

    if (specificationQuery) {
      proofSearchTasks.push(
        withDeadline(
          searchBingRssReference(specificationQuery),
          2_450,
          [] as SearchResult[],
          `universal proof specification RSS: ${exactModelAnchor}`
        )
      );
    }

    if (comparisonLabelQuery) {
      proofSearchTasks.push(
        withDeadline(
          searchBingRssReference(comparisonLabelQuery),
          2_450,
          [] as SearchResult[],
          `universal proof comparison RSS: ${exactModelAnchor}`
        )
      );
    }

    // Every branch above has its own hard deadline and [] fallback. Do not
    // wrap the Promise.all in another race: an outer fallback could erase
    // already-completed proof chunks because one last engine finished late.
    const proofSearchChunks = await Promise.all(proofSearchTasks);

    const proofSeen = new Set<string>();
    const results = proofSearchChunks.flat().filter((result) => {
      const key = normalizeUrl(result.url) || `${result.name}|${result.snippet}`;
      if (proofSeen.has(key)) return false;
      proofSeen.add(key);
      return true;
    });

    const collected = collectUniversalRequirementProofFromSearchResults(
      results,
      requirements,
      parsed,
      phrase,
      exactModelAnchor
    );
    const chunks = [...collected.chunks];
    const sources = [...collected.sources];
    const provenKeys = new Set(collected.provenKeys);

    // Search snippets are often too short to repeat every stable spec of an
    // exact model. If some model-level requirements are still missing, hydrate
    // at most two concrete independent product references. This is NOT a price
    // source and never trusts category/home/news pages.
    if (
      provenKeys.size < requirements.length &&
      exactModelAnchor
    ) {
      const hydrated = await hydrateIndependentMpnProofCandidates(
        results,
        getResultHostname(originalUrlRaw),
        exactModelAnchor,
        parsed,
        phrase,
        externalSignal
      );

      for (const item of hydrated.slice(0, 4)) {
        const boundedScope = getBoundedUniversalModelReferenceScope(
          item.scope,
          phrase,
          exactModelAnchor
        );
        if (!boundedScope) continue;

        const matchedRequirements = requirements.filter((requirement) =>
          requirementHasEvidence(requirement, boundedScope)
        );
        if (matchedRequirements.length === 0) continue;

        for (const requirement of matchedRequirements) provenKeys.add(requirement.key);
        chunks.push(boundedScope.slice(0, 12_000));
        sources.push(
          `${getResultHostname(item.proof.url)} | hydrated-${item.transport} | ${item.proof.name}`
        );

        if (provenKeys.size >= requirements.length) break;
      }
    }

    const proof = normalizeText(chunks.join(" ")).slice(0, 30_000);

    console.log(
      "[AIShopping] V34.CORE120 universal requirement proof:",
      phrase,
      "provedKeys=",
      Array.from(provenKeys),
      "sources=",
      sources
    );

    return proof;
  })().catch((error) => {
    console.log(
      "[AIShopping] V34.CORE120 universal requirement proof search failed:",
      phrase,
      error
    );
    return "";
  });

  universalRequirementProofCache.set(cacheKey, promise);

  void promise.then((proof) => {
    if (proof.trim()) {
      universalRequirementProofNegativeUntil.delete(cacheKey);
      return;
    }

    // Only remove if this is still the same in-flight entry. A newer successful
    // retry must never be deleted by an older completion callback.
    if (universalRequirementProofCache.get(cacheKey) === promise) {
      universalRequirementProofCache.delete(cacheKey);
      universalRequirementProofNegativeUntil.set(cacheKey, Date.now() + 900);
    }
  }).catch(() => {
    if (universalRequirementProofCache.get(cacheKey) === promise) {
      universalRequirementProofCache.delete(cacheKey);
      universalRequirementProofNegativeUntil.set(cacheKey, Date.now() + 900);
    }
  });

  if (universalRequirementProofCache.size > 180) {
    const firstKey = universalRequirementProofCache.keys().next().value;
    if (typeof firstKey === "string") universalRequirementProofCache.delete(firstKey);
  }
  if (universalRequirementProofNegativeUntil.size > 180) {
    const firstKey = universalRequirementProofNegativeUntil.keys().next().value;
    if (typeof firstKey === "string") universalRequirementProofNegativeUntil.delete(firstKey);
  }

  return promise;
}

function sourceRequiresIndependentRequirementProof(urlRaw: string): boolean {
  const host = getResultHostname(urlRaw);
  // Aggregator product pages may contain recommendation cards/spec snippets for
  // neighbouring products. Exact-model external proof prevents cross-product
  // contamination without introducing category-specific exceptions.
  return host === "ceneo.pl";
}

const vacuumFeatureProofCache = new Map<string, Promise<string>>();

async function findVacuumMappingProofViaSearch(
  productNameRaw: string
): Promise<string> {
  const phrase = buildVacuumFeatureProofPhrase(productNameRaw);
  if (phrase.length < 4) return "";

  const cacheKey = normalizeMatchText(phrase);
  const cached = vacuumFeatureProofCache.get(cacheKey);
  if (cached) return cached;

  const promise = (async () => {
    const query = `"${phrase.replace(/"/g, " ")}" mapowanie lidar nawigacja mapping navigation`;

    const results = await withDeadline(
      searchBingRss(query),
      2_700,
      [] as SearchResult[],
      `vacuum mapping proof: ${phrase}`
    );

    const proofChunks: string[] = [];
    const proofSources: string[] = [];

    for (const result of results.slice(0, 8)) {
      const evidence = normalizeText(`${result.name} ${result.snippet}`);
      if (!evidence) continue;
      if (!hasVacuumMappingEvidence(evidence)) continue;
      if (hasNegativeVacuumMappingEvidence(evidence)) continue;

      proofChunks.push(evidence.slice(0, 1800));
      proofSources.push(`${getResultHostname(result.url)} | ${result.name}`);

      if (proofChunks.length >= 3) break;
    }

    const proof = normalizeText(proofChunks.join(" ")).slice(0, 6000);

    console.log(
      "[AIShopping] V34.CORE120 vacuum mapping proof via Bing RSS:",
      phrase,
      "proved=",
      Boolean(proof),
      proofSources
    );

    return proof;
  })().catch((error) => {
    console.log(
      "[AIShopping] V34.CORE120 vacuum mapping proof search failed:",
      phrase,
      error
    );
    return "";
  });

  vacuumFeatureProofCache.set(cacheKey, promise);

  // Prevent an unbounded module-level cache in a long-running dev/server process.
  if (vacuumFeatureProofCache.size > 120) {
    const firstKey = vacuumFeatureProofCache.keys().next().value;
    if (typeof firstKey === "string") vacuumFeatureProofCache.delete(firstKey);
  }

  return promise;
}

function isVacuumSearchMismatch(
  result: SearchResult,
  parsed: ParsedQuery
): boolean {
  if (parsed.category !== "vacuum" || parsed.intent.accessoryIntent) return false;

  // Discovery snippets from marketplace listing pages often contain text from
  // neighbouring offers. Use the result title + URL as the trustworthy fast
  // pre-filter so a "mapujący" neighbour cannot make a plain Makita relevant.
  const scope = `${result.name} ${result.url}`;
  const normalized = normalizeMatchText(scope);

  const hasVacuumProductSignal =
    /\b(?:odkurzacz|odkurzacze|vacuum|roomba|robot)\b/i.test(normalized);

  const trustedRobotCategoryProduct =
    result.source === "CeneoDirect" &&
    /^https?:\/\/(?:www\.)?ceneo\.pl\/\d+/i.test(result.url);

  // CeneoDirect here is parsed from the dedicated robot-vacuum landing page.
  // Product names such as "DREAME X40 ULTRA" do not contain the generic word
  // "robot", so do not reject them before we can inspect the actual product page.
  if (!hasVacuumProductSignal && !trustedRobotCategoryProduct) return true;

  if (hasVacuumMappingIntent(parsed)) {
    const hasRobotCandidate = hasRobotVacuumSignal(scope);
    const hasMappingCandidate = hasVacuumMappingEvidence(scope);

    // At discovery time either a robot signal, explicit mapping signal, or a
    // concrete product extracted from Ceneo's robot category is enough.
    // Full verification below still requires robot + mapping evidence.
    if (!hasRobotCandidate && !hasMappingCandidate && !trustedRobotCategoryProduct) {
      return true;
    }
  }

  return false;
}

function isVacuumFeatureMismatchAfterVerification(
  title: string,
  content: string,
  url: string,
  parsed: ParsedQuery
): boolean {
  if (parsed.category !== "vacuum" || parsed.intent.accessoryIntent) return false;

  const fullEvidence = `${title} ${content} ${url}`;

  if (hasVacuumMappingIntent(parsed)) {
    // A mapping vacuum is an autonomous robot. Require independent evidence
    // for both parts instead of trusting a seller who merely writes
    // "mapujący" in the title of a normal upright/wet vacuum.
    if (!hasRobotVacuumSignal(fullEvidence)) return true;
    if (!hasVacuumMappingEvidence(fullEvidence)) return true;
  }

  return false;
}


function extractMarketplaceCardContext(
  textRaw: string,
  productNameRaw: string,
  maxLength = 1500
): string {
  const text = normalizeText(
    decodeHtml(textRaw)
      .replace(/\u00a0/g, " ")
      .replace(/\u202f/g, " ")
  );

  const productName = normalizeText(decodeHtml(productNameRaw));
  if (!text || !productName) return "";

  const haystack = text.toLowerCase();
  const needle = productName.toLowerCase();
  const index = haystack.indexOf(needle);

  if (index < 0) return "";

  let card = text.slice(index, Math.min(text.length, index + maxLength));

  const sellerIndex = normalizeMatchText(card).indexOf("sprzedajacy:");
  if (sellerIndex > 0) {
    card = card.slice(0, sellerIndex);
  }

  return normalizeText(card);
}

function extractMarkedOlxSearchCard(textRaw: string): string {
  const text = normalizeText(
    decodeHtml(textRaw)
      .replace(/\u00a0/g, " ")
      .replace(/\u202f/g, " ")
  );

  const startMarker = "AIOLXCARDSTART";
  const endMarker = "AIOLXCARDEND";
  const start = text.indexOf(startMarker);
  if (start < 0) return "";

  const contentStart = start + startMarker.length;
  const end = text.indexOf(endMarker, contentStart);

  return normalizeText(
    text.slice(
      contentStart,
      end >= 0 ? end : Math.min(text.length, contentStart + 4_000)
    )
  );
}

function extractMarkedOlxSearchCardRaw(textRaw: string): string {
  const card = extractMarkedOlxSearchCard(textRaw);
  if (!card) return "";

  const rawMarker = "AIOLXRAWSTART";
  const rawStart = card.indexOf(rawMarker);
  if (rawStart < 0) return "";

  return normalizeText(card.slice(rawStart + rawMarker.length));
}

function normalizeOlxCardIdentity(valueRaw: string): string {
  return normalizeMatchText(valueRaw)
    // Keep technical identity stable when OLX/Jina/URL slugs rewrite
    // punctuation: 50 mm <-> 50mm and f/1.8 <-> f1.8 <-> f 1 8.
    .replace(/\bf\s*\/?\s*(\d{1,2})[.,]\s*(\d)\b/giu, " f$1$2 ")
    .replace(/\bf\s*(\d{1,2})\s+(\d)\b/giu, " f$1$2 ")
    // Battery kits are especially noisy in OLX URLs: 2x4.0Ah can become
    // 2x-4-0-ah while the visible card says 2 x 4,0 Ah. Canonicalize both
    // before identity voting so a valid card is not rejected as misbound.
    .replace(/\b(\d{1,2})\s*[x×]\s*(\d{1,3})[.,]\s*(\d)\s*ah\b/giu, "$1x$2$3ah")
    .replace(/\b(\d{1,2})\s*[x×]\s*(\d{1,3})\s+(\d)\s+ah\b/giu, "$1x$2$3ah")
    .replace(/\b(\d{1,4}(?:[.,]\d+)?)\s*(mm|cm|kg|g|ml|gb|tb|hz|v|w|ah)\b/giu, "$1$2")
    .replace(/\bimage\s+\d+\s*/giu, " ")
    // Seller-condition/authenticity adjectives are not product identity and
    // are often omitted from the visible card while remaining in the URL slug.
    .replace(/\b(?:nowy|nowa|nowe|uzywany|uzywana|uzywane|oryginalny|oryginalna|oryginalne|original|sealed|zafoliowany|zafoliowana|zafoliowane)\b/giu, " ")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function isMarkedOlxCardBoundToProduct(
  textRaw: string,
  productNameRaw: string
): boolean {
  const rawCard = extractMarkedOlxSearchCardRaw(textRaw);
  const expected = normalizeOlxCardIdentity(productNameRaw);
  const actual = normalizeOlxCardIdentity(rawCard);

  if (!rawCard || !expected || !actual) return false;

  const structurallyBound = extractMarkedOlxSearchCard(textRaw).includes(
    "AIOLXSTRUCTURALBOUND"
  );
  if (structurallyBound) return true;

  if (actual.includes(expected)) return true;

  // URL slugs often split technical decimals differently than the visible
  // title: `f1-8` -> `f1 8`, while the card says `f/1.8` -> `f 1 8`.
  // Compare a compact full-identity form before per-token numeric checks.
  const compactExpected = expected.replace(/\s+/g, "");
  const compactActual = actual.replace(/\s+/g, "");
  if (
    compactExpected.length >= 12 &&
    compactActual.includes(compactExpected)
  ) {
    return true;
  }

  const expectedTokens = Array.from(
    new Set(expected.split(/\s+/).filter((token) => token.length >= 2))
  );
  const actualTokens = new Set(actual.split(/\s+/).filter(Boolean));

  if (expectedTokens.length === 0) return false;

  // Liczby i jednostki w tytule są tożsamością wariantu. Karta 30 000 mAh
  // nie może udowodnić ceny/stanu linku 20 000 mAh, podobnie jak rozmiar 42
  // nie może zostać przypisany wariantowi 44.
  const numericTokens = expectedTokens.filter((token) => /\d/.test(token));
  if (numericTokens.some((token) => !actualTokens.has(token))) return false;

  const matched = expectedTokens.filter((token) => actualTokens.has(token));
  const required =
    expectedTokens.length <= 2
      ? expectedTokens.length
      : Math.ceil(expectedTokens.length * 0.72);

  return matched.length >= required;
}

function extractOlxDirectBoundCondition(
  textRaw: string,
  productNameRaw = ""
): Condition {
  const card = extractMarkedOlxSearchCard(textRaw);
  if (!card) return null;

  if (
    productNameRaw &&
    !isMarkedOlxCardBoundToProduct(textRaw, productNameRaw)
  ) {
    return null;
  }

  const normalized = normalizeMatchText(
    extractMarkedOlxSearchCardRaw(textRaw) || card
  );

  // Jeżeli tytuł sprzedawcy mówi „nowy”, ale pole stanu na tej samej karcie
  // mówi „używane”, wybieramy bezpieczniejszą informację o używanym stanie.
  if (
    /\b(?:stan\s*:?\s*)?(?:uzywane|uzywany|uzywana|refurbished|odnowiony|odnowiona)\b/iu.test(
      normalized
    )
  ) {
    return "used";
  }

  if (
    /\b(?:stan\s*:?\s*)?(?:nowe|nowy|nowa|fabrycznie\s+nowy|nieuzywany|nieuzywana|nieuzywane)\b/iu.test(
      normalized
    ) &&
    !/\bjak\s+(?:nowy|nowa|nowe)\b/iu.test(normalized)
  ) {
    return "new";
  }

  return null;
}

function extractFirstBoundedOlxCardPrice(cardRaw: string): PriceInfo {
  const card = normalizeText(cardRaw).replace(
    /(\d{1,3}(?:[ .]\d{3})*)\s+(\d{2})\s*(zł|PLN)/giu,
    (_match, whole, cents, currency) => `${whole},${cents} ${currency}`
  );

  const priceRe =
    /(?:cena\s*:?\s*|od\s+)?(\d{1,3}(?:[ .]\d{3})+(?:\s*[.,]\s*\d{1,2})?|\d{1,7}(?:\s*[.,]\s*\d{1,2})?)\s*(zł|PLN)(?=\s|$|[.,;:!?()[\]{}"'\/+\-])/giu;

  let match: RegExpExecArray | null;

  while ((match = priceRe.exec(card)) !== null) {
    const before = normalizeMatchText(
      card.slice(Math.max(0, match.index - 70), match.index)
    );

    if (
      before.includes("dostawa") ||
      before.includes("wysylka") ||
      before.includes("rata") ||
      hasReferenceOnlyPriceContext(before)
    ) {
      continue;
    }

    const price = parseNumber(match[1]);
    const currency = normalizeCurrency(match[2]);

    if (price !== null && price > 0 && currency) {
      return { price, currency };
    }
  }

  return { price: null, currency: null };
}

function extractOlxDirectBoundPrice(
  textRaw: string,
  productNameRaw: string,
  currentUrlRaw = ""
): PriceInfo {
  const text = normalizeText(
    decodeHtml(textRaw)
      .replace(/\u00a0/g, " ")
      .replace(/\u202f/g, " ")
  );
  const productName = normalizeText(decodeHtml(productNameRaw));
  if (!text || !productName) return { price: null, currency: null };

  const markedCard = extractMarkedOlxSearchCard(textRaw);

  if (markedCard) {
    if (!isMarkedOlxCardBoundToProduct(textRaw, productNameRaw)) {
      console.log(
        "[AIShopping] V34.CORE120 ignored misbound OLX search card:",
        productNameRaw
      );
      return { price: null, currency: null };
    }

    const rawMarkedCard =
      extractMarkedOlxSearchCardRaw(textRaw) || markedCard;

    const closePrice = extractPriceNearProductName(
      rawMarkedCard,
      productNameRaw
    );

    const boundedPrice =
      closePrice.price !== null && closePrice.currency
        ? closePrice
        : extractFirstBoundedOlxCardPrice(rawMarkedCard);

    if (boundedPrice.price !== null && boundedPrice.currency) {
      console.log(
        "[AIShopping] V34.CORE120 OLX marked-card price:",
        productNameRaw,
        boundedPrice.price,
        boundedPrice.currency,
        "condition=",
        extractOlxDirectBoundCondition(textRaw, productNameRaw)
      );
    }

    return boundedPrice;
  }

  const haystack = text.toLowerCase();
  const needleText = productName.toLowerCase();
  const start = haystack.indexOf(needleText);
  if (start < 0) return { price: null, currency: null };

  // OLX search snippets are a concatenation of many cards. Only inspect the
  // current card and stop before the next image/card or a different OLX offer
  // URL. This prevents a pot/rug/etc. from inheriting the price of a compressor
  // or another neighbouring result further in the search page.
  const afterStart = text.slice(start, Math.min(text.length, start + 1100));
  let end = afterStart.length;

  const boundaryPatterns = [
    /(?:^|\s)Image\s+\d+\s*:/giu,
    /!\[Image\s+\d+/giu,
    /(?:^|\s)(?:SPONSOROWANE|Promowane)(?:\s|$)/giu,
  ];

  for (const pattern of boundaryPatterns) {
    pattern.lastIndex = Math.min(productName.length, afterStart.length);
    const match = pattern.exec(afterStart);
    if (match && match.index > productName.length) end = Math.min(end, match.index);
  }

  const currentUrl = normalizeUrl(currentUrlRaw);
  const olxUrlRegex = /https?:\/\/(?:www\.)?olx\.pl\/d\/(?:oferta|ogloszenie)\/[^\s)\]]+/giu;
  let urlMatch: RegExpExecArray | null;
  while ((urlMatch = olxUrlRegex.exec(afterStart)) !== null) {
    if (urlMatch.index <= productName.length) continue;
    const candidate = normalizeUrl(urlMatch[0]);
    if (!candidate || !currentUrl || candidate !== currentUrl) {
      end = Math.min(end, urlMatch.index);
      break;
    }
  }

  const card = normalizeText(afterStart.slice(0, Math.max(productName.length, end)));
  if (!card) return { price: null, currency: null };

  const price = extractPriceNearProductName(card, productNameRaw);
  if (price.price !== null && price.currency) {
    console.log(
      "[AIShopping] V34.CORE120 OLX card-bound price:",
      productNameRaw,
      price.price,
      price.currency
    );
  }
  return price;
}

function extractAllegroLokalnieExplicitBoundPrice(
  textRaw: string,
  productNameRaw: string
): PriceInfo {
  const card = extractMarketplaceCardContext(
    textRaw,
    productNameRaw,
    2400
  );

  // Concrete Allegro Lokalnie pages can contain many unrelated monetary
  // amounts (fees, instalments, delivery widgets, recommendations). During
  // page/Jina verification we only trust the marketplace's own payable-price
  // grammar bound to the requested offer card: "Kup teraz" or "Ogłoszenie".
  // If that grammar is absent, return no price instead of guessing.
  if (!card) return { price: null, currency: null };

  const normalizedCard = card.replace(
    /(\d{1,3}(?:[ .]\d{3})*)\s+(\d{2})\s*(zł|PLN)/giu,
    (_match, whole, cents, currency) => `${whole},${cents} ${currency}`
  );

  const buyNowMatch = normalizedCard.match(
    /\bkup\s+teraz\s+(\d{1,3}(?:[ .]\d{3})+(?:\s*[.,]\s*\d{1,2})?|\d{1,7}(?:\s*[.,]\s*\d{1,2})?)\s*(zł|PLN)(?=\s|$|[.,;:!?()[\]{}"'\/+\-])/iu
  );

  if (buyNowMatch) {
    const price = parseNumber(buyNowMatch[1]);
    const currency = normalizeCurrency(buyNowMatch[2]);

    if (price !== null && currency) {
      console.log(
        "[AIShopping] V34.CORE120 Allegro Lokalnie buy-now price:",
        productNameRaw,
        price,
        currency
      );
      return { price, currency };
    }
  }

  const listingPriceMatch = normalizedCard.match(
    /\bog[łl]oszenie\s+(\d{1,3}(?:[ .]\d{3})+(?:\s*[.,]\s*\d{1,2})?|\d{1,7}(?:\s*[.,]\s*\d{1,2})?)\s*(zł|PLN)(?=\s|$|[.,;:!?()[\]{}"'\/+\-])/iu
  );

  if (listingPriceMatch) {
    const price = parseNumber(listingPriceMatch[1]);
    const currency = normalizeCurrency(listingPriceMatch[2]);

    if (price !== null && currency) {
      console.log(
        "[AIShopping] V34.CORE120 Allegro Lokalnie listing price:",
        productNameRaw,
        price,
        currency
      );
      return { price, currency };
    }
  }

  return { price: null, currency: null };
}

function extractAllegroLokalnieBoundPrice(
  textRaw: string,
  productNameRaw: string
): PriceInfo {
  const explicit = extractAllegroLokalnieExplicitBoundPrice(
    textRaw,
    productNameRaw
  );
  if (explicit.price !== null && explicit.currency) return explicit;

  // Search-result cards from older layouts do not always expose an explicit
  // card-type label. Discovery keeps the historical bounded fallback, while
  // concrete-page verification uses the strict helper above.
  const card = extractMarketplaceCardContext(textRaw, productNameRaw, 1700);
  if (!card) return extractPriceNearProductName(textRaw, productNameRaw);
  return extractPriceNearProductName(card, productNameRaw);
}

function isAuctionOnlyAllegroLokalnieResult(result: SearchResult): boolean {
  if (getResultHostname(result.url) !== "allegrolokalnie.pl") return false;

  const card = extractMarketplaceCardContext(
    `${result.name} ${result.snippet}`,
    result.name,
    1700
  );

  const scope = normalizeMatchText(card || `${result.name} ${result.snippet}`);

  return /\blicytacj[a-z]*\b/i.test(scope) && !/\bkup\s+teraz\b/i.test(scope);
}

function decodeJsonLikeString(value: string): string {
  try {
    return JSON.parse(`"${value.replace(/"/g, '\\"')}"`);
  } catch {
    return value
      .replace(/\\n|\\r|\\t/g, " ")
      .replace(/\\u002F/gi, "/")
      .replace(/\\u0026/gi, "&")
      .replace(/\\\//g, "/")
      .replace(/\\"/g, '"');
  }
}

function trimUniversalEvidenceAtRecommendationBoundary(textRaw: string): string {
  const text = String(textRaw ?? "");
  if (!text) return "";
  const lower = text.toLowerCase();
  const markers = [
    "podobne produkty", "podobne oferty", "produkty podobne", "polecane produkty", "polecane dla ciebie",
    "zobacz także", "zobacz tez", "zobacz również", "zobacz rowniez", "sprawdź również", "sprawdz rowniez",
    "inni kupili", "klienci kupili również", "klienci kupili rowniez", "akcesoria", "dobierz akcesoria",
    "produkty powiązane", "produkty powiazane", "related products", "similar products", "you may also like",
    "recommended products", "customers also bought", "compare similar", "porównaj podobne", "porownaj podobne",
  ];
  let cut = text.length;
  for (const marker of markers) {
    const index = lower.indexOf(marker);
    if (index >= 500 && index < cut) cut = index;
  }
  return text.slice(0, cut);
}

function universalJsonFeatureDescriptionMatchesProduct(
  descriptionRaw: string,
  productNameRaw: string
): boolean {
  const description = normalizeMatchText(descriptionRaw);
  const productName = normalizeMatchText(productNameRaw);
  if (!description || !productName) return false;

  // JSON blobs on large retailer pages frequently contain descriptions of
  // recommendations or sibling products. They are useful only when the blob
  // can be tied back to the current product identity. Require either a concrete
  // model/code token or at least two distinctive lexical tokens from the
  // current product name. Generic commerce/category words intentionally do not
  // count.
  const genericTokens = new Set([
    "produkt", "product", "oferta", "model", "wersja", "seria",
    "czarny", "bialy", "szary", "nowy", "nowa", "nowe",
  ]);

  // Reuse the engine's category vocabulary instead of maintaining a second
  // product-name dictionary here. Category nouns are weak identity by design;
  // a neighbouring product that shares only the class word must never bind a
  // free-floating description to the current item.
  for (const profile of Object.values(UNIVERSAL_CATEGORY_PROFILES)) {
    for (const alias of [
      ...(profile.positiveAliases ?? []),
      ...(profile.discoveryAliases ?? []),
    ]) {
      for (const token of normalizeMatchText(alias).split(/\s+/)) {
        if (token.length >= 2) genericTokens.add(token);
      }
    }
  }

  const tokens = Array.from(new Set(
    productName
      .split(/\s+/)
      .map((token) => token.replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, ""))
      .filter((token) => token.length >= 3 && !genericTokens.has(token))
  ));

  const modelTokens = tokens.filter((token) =>
    isUniversalModelCodeToken(token) ||
    (/\d/.test(token) && /[a-z]/.test(token) && token.length >= 3) ||
    (/^\d{3,}$/.test(token))
  );

  if (modelTokens.some((token) => universalEvidenceHasBoundedIdentityTerm(token, description))) {
    return true;
  }

  const lexicalTokens = tokens.filter((token) => !/^\d+$/.test(token));
  if (lexicalTokens.length < 3) return false;
  const matched = lexicalTokens.filter((token) =>
    universalEvidenceHasBoundedIdentityTerm(token, description)
  ).length;

  return matched >= 3;
}

function extractUniversalFeatureEvidenceFromHtml(
  html: string,
  productNameRaw: string
): string {
  if (!html) return "";

  const chunks: string[] = [];
  const metaDescription = extractDescriptionFromHtml(html);
  if (metaDescription) chunks.push(metaDescription);

  const decodedMarkup = String(html)
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
    .replace(/\\u002F/gi, "/")
    .replace(/\\u0026/gi, "&")
    .replace(/\\\//g, "/");

  const decoded = decodeHtml(html);

  const descriptionRegex = /"(?:description|offerDescription|descriptionText)"\s*:\s*"((?:\\.|[^"\\]){20,7000})"/giu;
  let match: RegExpExecArray | null;
  let count = 0;

  const productName = normalizeText(productNameRaw);

  while ((match = descriptionRegex.exec(decodedMarkup)) !== null && count < 8) {
    const value = normalizeText(decodeJsonLikeString(match[1]));
    if (
      value &&
      universalJsonFeatureDescriptionMatchesProduct(value, productName)
    ) {
      chunks.push(value.slice(0, 5000));
    }
    count += 1;
  }

  if (productName) {
    const lower = decoded.toLowerCase();
    const titleNeedle = productName.toLowerCase().slice(0, 80);
    const index = titleNeedle.length >= 8 ? lower.indexOf(titleNeedle) : -1;

    if (index >= 0) {
      const around = decoded.slice(
        Math.max(0, index - 1200),
        Math.min(decoded.length, index + 10000)
      );

      chunks.push(
        normalizeText(
          extractTagText(trimUniversalEvidenceAtRecommendationBoundary(around))
            .replace(/[{}[\]"']/g, " ")
        ).slice(0, 7000)
      );

      // V34.CORE120: some first-party product pages place dosage/serving
      // instructions well below the title/description block (after long FAQ,
      // lab-result or accordion markup). CORE49 correctly requires serving
      // weight to be listing-bound, but the old 10k title window could hide a
      // real field such as "Jedną porcję – 5 g" from the verifier.
      //
      // Do NOT append the whole distant page. Start at the current product,
      // stop at recommendation boundaries, and keep only small windows where
      // serving/dosage grammar is locally tied to a mass measurement. The
      // exact requested amount is still enforced later by
      // requirementHasExactNumericEvidence(), so this adds recall without
      // allowing a free-floating gram token or neighbouring product to prove
      // the hard requirement.
      const visibleFromProduct = trimUniversalEvidenceAtRecommendationBoundary(
        normalizeText(
          extractTagText(
            decoded.slice(index, Math.min(decoded.length, index + 140000))
          )
        )
      );

      const servingSignalRe = /\b(?:wielkosc\s+porcji|wielkość\s+porcji|masa\s+porcji|porcj\w*|dawk\w*|serving(?:\s+size)?|dose|miark\w*|zalecan\w*\s+(?:porcj\w*|dawk\w*)|recommended\s+(?:serving|dose))\b/giu;
      let servingSignal: RegExpExecArray | null;
      let servingWindows = 0;

      while (
        (servingSignal = servingSignalRe.exec(visibleFromProduct)) !== null &&
        servingWindows < 12
      ) {
        if (typeof servingSignal.index !== "number") continue;

        const scope = visibleFromProduct.slice(
          Math.max(0, servingSignal.index - 120),
          Math.min(visibleFromProduct.length, servingSignal.index + 260)
        );

        if (!/\b\d+(?:[.,]\d+)?\s*(?:kg|g)\b/iu.test(scope)) continue;

        chunks.push(scope);
        servingWindows += 1;
      }
    }
  }

  return normalizeText(chunks.join(" ")).slice(0, 16000);
}

function extractCanonicalHardRequirementEvidenceFromConcreteHtml(
  html: string,
  productNameRaw: string,
  productUrlRaw: string,
  parsed: ParsedQuery
): string {
  const hardRequirements = parsed.intent.required.filter(
    (requirement) => requirement.hard
  );
  if (!html || hardRequirements.length === 0) return "";

  const visible = normalizeText(extractTagText(html));
  if (!visible) return "";

  const productName = normalizeText(productNameRaw);
  const lowerVisible = visible.toLowerCase();
  const scopes: string[] = [];

  // The concrete page itself is already URL-bound by verifySearchResult(). Keep
  // the current product block only and canonicalize REQUIREMENTS from it instead
  // of carrying arbitrary page text into the verifier.
  const fullCurrentProductScope = trimUniversalEvidenceAtRecommendationBoundary(
    visible.slice(0, 140_000)
  );
  if (fullCurrentProductScope) scopes.push(fullCurrentProductScope);

  const titleNeedles = Array.from(new Set([
    productName,
    productName.replace(/\s+-\s+(?:opinie|najlepsze ceny).*$/iu, "").trim(),
  ].filter((value) => value.length >= 8)));

  for (const needle of titleNeedles) {
    const index = lowerVisible.indexOf(needle.toLowerCase().slice(0, 120));
    if (index < 0) continue;
    const around = trimUniversalEvidenceAtRecommendationBoundary(
      visible.slice(Math.max(0, index - 500), Math.min(visible.length, index + 120_000))
    );
    if (around) scopes.push(around);
    break;
  }

  const sharedModelCode = extractUniversalSharedConcreteModelCode(
    productNameRaw,
    productUrlRaw,
    parsed
  );
  if (sharedModelCode) {
    const titleModelToken = normalizeMatchText(productNameRaw)
      .split(/\s+/)
      .find((token) => compactUniversalModelCode(token) === sharedModelCode);
    if (titleModelToken) {
      const modelIndex = lowerVisible.indexOf(titleModelToken.toLowerCase());
      if (modelIndex >= 0) {
        const aroundModel = trimUniversalEvidenceAtRecommendationBoundary(
          visible.slice(
            Math.max(0, modelIndex - 1_000),
            Math.min(visible.length, modelIndex + 80_000)
          )
        );
        if (aroundModel) scopes.push(aroundModel);
      }
    }
  }

  const canonicalEvidence: string[] = [];
  for (const requirement of hardRequirements) {
    const proven = scopes.some((scope) =>
      requirementHasEvidenceInContext(
        requirement,
        scope,
        parsed.intent.required
      )
    );
    if (!proven) continue;
    canonicalEvidence.push(
      normalizeText(
        `${requirement.label} ${requirement.aliases[0] || requirement.value}`
      )
    );
  }

  return normalizeText(canonicalEvidence.join(" ")).slice(0, 8_000);
}

function extractVacuumFeatureEvidenceFromJina(
  text: string,
  productNameRaw: string
): string {
  if (!text) return "";

  const chunks: string[] = [];
  const offerContext = extractJinaOfferContext(text);
  if (offerContext) chunks.push(offerContext);

  const normalizedName = normalizeText(productNameRaw).toLowerCase();
  const lower = text.toLowerCase();
  const index = normalizedName.length >= 8
    ? lower.indexOf(normalizedName.slice(0, 100))
    : -1;

  if (index >= 0) {
    chunks.push(
      normalizeText(
        text.slice(index, Math.min(text.length, index + 30000))
          .replace(/!\[[^\]]*\]\([^)]+\)/g, " ")
          .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
          .replace(/[#*_`]/g, " ")
      ).slice(0, 14000)
    );
  }

  return normalizeText(chunks.join(" ")).slice(0, 16000);
}

function extractBoundedOlxListingEvidenceFromJina(
  textRaw: string,
  productNameRaw: string
): string {
  if (!textRaw || !/\bolx\.pl\/d\/oferta\//i.test(textRaw)) return "";

  const markdownMarker = /Markdown Content:\s*/i.exec(textRaw);
  if (!markdownMarker) return "";

  const bodyStart = (markdownMarker.index ?? 0) + markdownMarker[0].length;
  let body = textRaw.slice(bodyStart);

  // On a concrete OLX offer the first "ID: <number>" closes the seller's
  // actual listing description/attributes. Everything after it can contain
  // seller widgets, recommendations and neighbouring offers, so it must never
  // prove a hard user requirement.
  const idMatch = /\bID:\s*\d{5,}\b/i.exec(body);
  if (idMatch?.index !== undefined) {
    body = body.slice(0, idMatch.index + idMatch[0].length);
  } else {
    // If OLX changes markup and the listing boundary cannot be identified,
    // fail closed to a short prefix rather than trusting tens of thousands of
    // characters containing recommendations.
    body = body.slice(0, 9_000);
  }

  const cleaned = normalizeText(
    body
      .replace(/!\[[^\]]*\]\([^)]+\)/g, " ")
      .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
      .replace(/[#*_`]/g, " ")
  ).slice(0, 12_000);

  return normalizeText(`${productNameRaw} ${cleaned}`).slice(0, 13_000);
}

function extractUniversalFeatureEvidenceFromJina(
  textRaw: string,
  productNameRaw: string
): string {
  if (!textRaw) return "";

  // Concrete OLX listing pages are high-value sources, but their tail contains
  // "similar offers". Hard requirements must be proven only by the current
  // listing's bounded core. This prevents 1TB SSDs from inheriting "2TB" from
  // a neighbour and Wi-Fi 5 extenders from inheriting "Wi-Fi 6".
  const boundedOlxEvidence =
    extractBoundedOlxListingEvidenceFromJina(textRaw, productNameRaw);

  if (boundedOlxEvidence) {
    // Do not append extractJinaOfferContext(): on OLX that helper can reach the
    // recommendation tail and reintroduce attributes from neighbouring ads.
    return boundedOlxEvidence;
  }

  const productName = normalizeText(productNameRaw)
    .replace(/\s+-\s+Opinie.*$/i, "")
    .replace(/\s+•\s+.*$/i, "")
    .trim();

  const lower = textRaw.toLowerCase();
  const needle = productName.toLowerCase().slice(0, 120);
  const index = needle.length >= 6 ? lower.indexOf(needle) : -1;

  const chunks: string[] = [];

  if (index >= 0) {
    let slice = textRaw.slice(index, Math.min(textRaw.length, index + 16_000));

    const descriptionMarkers = [
      "Opis i dane produktu",
      "Opis produktu",
      "Specyfikacja",
      "Dane techniczne",
      "Najważniejsze cechy",
      "Najwazniejsze cechy",
    ];

    for (const marker of descriptionMarkers) {
      const markerIndex = slice.toLowerCase().indexOf(marker.toLowerCase());
      if (markerIndex >= 0) {
        slice = `${slice.slice(0, 5_000)} ${slice.slice(markerIndex, markerIndex + 9_000)}`;
        break;
      }
    }

    chunks.push(trimUniversalEvidenceAtRecommendationBoundary(slice));
  }

  const jinaContext = trimUniversalEvidenceAtRecommendationBoundary(
    extractJinaOfferContext(textRaw)
  );
  if (jinaContext) chunks.push(jinaContext);

  return normalizeText(
    chunks
      .join(" ")
      .replace(/!\[[^\]]*\]\([^)]+\)/g, " ")
      .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
      .replace(/[#*_`]/g, " ")
  ).slice(0, 14_000);
}


// V34.CORE185: Jina often preserves the concrete retailer's full specification
// section even when the ordinary feature-evidence helper intentionally stops at
// an early navigation/recommendation marker. HARD facts may be canonicalized
// from that specification only when the reader page itself is bound to the same
// product identity. Recommendation/related-product sections are cut away before
// any requirement matcher runs, so strict listing-bound gates stay fail-closed.
function extractCanonicalHardRequirementEvidenceFromConcreteJina(
  textRaw: string,
  productNameRaw: string,
  productUrlRaw: string,
  parsed: ParsedQuery
): string {
  const hardRequirements = parsed.intent.required.filter(
    (requirement) => requirement.hard
  );
  if (
    !textRaw ||
    hardRequirements.length === 0 ||
    isBlockedOrChallengePage(textRaw)
  ) {
    return "";
  }

  const productName = normalizeText(productNameRaw);
  const pageTitle = normalizeText(extractJinaPageTitle(textRaw));
  if (!productName || !pageTitle) return "";

  const sameProductIdentity =
    universalProofMatchesProductIdentity(productName, pageTitle) ||
    universalProofMatchesProductIdentity(pageTitle, productName) ||
    Boolean(
      extractUniversalSharedConcreteModelCode(
        `${productName} ${pageTitle}`,
        productUrlRaw,
        parsed
      )
    );
  if (!sameProductIdentity) return "";

  const markdownMarker = /Markdown Content:\s*/iu.exec(textRaw);
  const markdown = markdownMarker
    ? textRaw.slice((markdownMarker.index ?? 0) + markdownMarker[0].length)
    : textRaw;

  // Require an actual markdown heading, not a navigation tab named
  // "Specyfikacja". This keeps the scope tied to the page's product detail
  // block and avoids generic menus near the top of retailer pages.
  const specificationHeading =
    /^\s*#{1,4}\s*(?:specyfikacja|dane\s+techniczne|parametry(?:\s+techniczne)?|szczeg[oó][łl]y(?:\s+produktu)?|specification|technical\s+specifications?|product\s+details)\s*$/gimu;

  const sectionScopes: string[] = [];
  let headingMatch: RegExpExecArray | null;
  let sectionCount = 0;

  while (
    (headingMatch = specificationHeading.exec(markdown)) !== null &&
    sectionCount < 4
  ) {
    if (typeof headingMatch.index !== "number") continue;

    const sectionStart = headingMatch.index;
    const afterHeading = markdown.slice(sectionStart + headingMatch[0].length);
    const boundaryMatch = /\n\s*#{1,4}\s*(?:rekomendowane(?:\s+akcesoria|\s+produkty)?|polecane(?:\s+produkty)?|akcesoria|produkty\s+podobne|podobne\s+produkty|podobne\s+oferty|produkty\s+powi[aą]zane|opinie|recenzje|pytania(?:\s+i\s+odpowiedzi)?|related\s+products?|similar\s+products?|recommended\s+products?|reviews?|questions?)\b/iu.exec(
      afterHeading
    );

    const rawSection = boundaryMatch
      ? markdown.slice(
          sectionStart,
          sectionStart + headingMatch[0].length + boundaryMatch.index
        )
      : markdown.slice(sectionStart, Math.min(markdown.length, sectionStart + 28_000));

    const cleaned = normalizeText(
      rawSection
        .replace(/!\[[^\]]*\]\([^)]+\)/g, " ")
        .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
        .replace(/[#*_`|]/g, " ")
    ).slice(0, 20_000);

    if (cleaned) sectionScopes.push(cleaned);
    sectionCount += 1;
  }

  if (sectionScopes.length === 0) return "";

  const canonicalEvidence: string[] = [];
  for (const requirement of hardRequirements) {
    const proven = sectionScopes.some((scope) =>
      requirementHasEvidenceInContext(
        requirement,
        scope,
        parsed.intent.required
      )
    );
    if (!proven) continue;

    canonicalEvidence.push(
      normalizeText(
        `${requirement.label} ${requirement.aliases[0] || requirement.value}`
      )
    );
  }

  return normalizeText(canonicalEvidence.join(" ")).slice(0, 8_000);
}

function isReferenceDocumentOfferResult(result: SearchResult): boolean {
  const title = normalizeMatchText(result.name);
  const snippet = normalizeMatchText(result.snippet);
  let pathname = "";

  try {
    pathname = decodeURIComponent(new URL(result.url).pathname).toLowerCase();
  } catch {
    pathname = String(result.url || "").toLowerCase();
  }

  // Downloadable documents are supporting/reference material, not a concrete
  // purchasable offer. Retailer crawls frequently surface product sheets,
  // manuals and energy/info cards because they sit close to the product page.
  // Such files can contain campaign copy or neighbouring prices (e.g. "1 zł")
  // and must never be promoted to a product price.
  if (/\.(?:pdf|docx?|xlsx?|pptx?|odt|ods|odp|rtf|csv|xml)(?:$|[?#])/i.test(pathname)) {
    return true;
  }

  const referenceTitle = /\b(?:karta\s+(?:informacyjna|towarowa|produktu|produktu\s+informacyjna)|product\s+(?:information\s+sheet|information\s+card|fiche|datasheet|data\s+sheet)|karta\s+energetyczna|etykieta\s+energetyczna|energy\s+label|energy\s+fiche|instrukcja\s+(?:obslugi|uzytkownika)|user\s+manual|instruction\s+manual|specyfikacja\s+(?:pdf|techniczna)|technical\s+(?:specification|datasheet))\b/i;

  if (result.source === "RetailerRescue" && referenceTitle.test(`${title} ${snippet}`)) {
    return true;
  }

  // A retailer-owned download/file repository should not be treated as a
  // product URL merely because the filename contains the exact model code.
  if (
    result.source === "RetailerRescue" &&
    /\/(?:products?|produkty?)\/files?\//i.test(pathname)
  ) {
    return true;
  }

  return false;
}

function getDiscoveryValidationPriority(
  result: SearchResult,
  parsed: ParsedQuery
): number {
  const host = getResultHostname(result.url);
  let score = 0;

  if (result.retailerOwnedCardEvidence) score += 220;
  if (result.source === "RetailerRescue") score += 180;
  if (/Direct$/i.test(result.source)) score += 150;
  if (result.ceneoMerchantOffer) score += 145;

  // V34.CORE127: a concrete Ceneo product page is unusually valuable because
  // the verifier can expand one exact product card into multiple real merchant
  // offers. Keep those concrete /<productId> pages ahead of noisy marketplace
  // cards during the bounded discovery-validation pass so the existing Ceneo
  // merchant expansion gets a chance to run before the accepted-target or
  // validation budget is exhausted. This is scheduling only: the local Ceneo
  // card filter, merchant standalone identity, HARD, condition, price,
  // availability, originality and final relevance gates remain unchanged.
  if (
    result.source === "CeneoDirect" &&
    /^https?:\/\/(?:www\.)?ceneo\.pl\/\d+(?:\/|$)/iu.test(result.url)
  ) {
    score += 280;
  }
  if (host && isConfiguredCommerceDomain(result.url)) score += 120;
  if (host && V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((item) => String(item) === host)) {
    score += 105;
  }
  if (host.endsWith(".pl")) score += 25;
  if (looksLikeOpenWebProductUrl(result.url) || looksLikeProductUrl(result.url)) score += 35;
  score -= Math.min(25, Math.max(0, result.searchRank));
  return score;
}

function hasCheapDiscoveryIdentitySignal(
  result: SearchResult,
  parsed: ParsedQuery
): boolean {
  // Trusted commerce sources still pass through the full matcher; this gate is
  // only for obvious open-web noise. It never proves identity or a HARD fact.
  const host = getResultHostname(result.url);
  if (
    result.retailerOwnedCardEvidence ||
    result.source === "RetailerRescue" ||
    /Direct$/i.test(result.source) ||
    (host && isConfiguredCommerceDomain(result.url)) ||
    (host && V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((item) => String(item) === host))
  ) {
    return true;
  }

  const evidence = normalizeMatchText(`${result.name} ${result.url}`);
  const terms = Array.from(new Set([
    parsed.brand ?? "",
    parsed.intent.productPhrase,
    ...parsed.intent.strongIdentityTerms,
    ...parsed.intent.identityTerms,
  ]))
    .map((term) => normalizeMatchText(term))
    .flatMap((term) => term.split(/\s+/g))
    .filter((term) => term.length >= 3);

  return terms.length === 0 || terms.some((term) => evidence.includes(term));
}

function hasCompatibilityOnlyRequestedBrandClaim(
  result: SearchResult,
  parsed: ParsedQuery
): boolean {
  const brand = normalizeMatchText(parsed.brand ?? "");
  if (!brand) return false;

  const title = normalizeMatchText(result.name);
  if (!title.includes(brand)) return false;

  const escapedBrand = brand.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const compatibilityPattern = new RegExp(
    `(?:jak|ala|a la|kompatybiln\\w* z|compatible with|zamiennik dla|pasuje do)\\s+${escapedBrand}\\b`,
    "giu"
  );
  if (!compatibilityPattern.test(title)) return false;

  const withoutCompatibility = title.replace(compatibilityPattern, " ");
  return !new RegExp(`\\b${escapedBrand}\\b`, "iu").test(withoutCompatibility);
}

function looksLikeRequestedProduct(
  result: SearchResult,
  parsed: ParsedQuery
): boolean {
  const title = normalizeMatchText(result.name);
  const text = normalizeMatchText(
    `${result.name} ${result.snippet} ${result.url}`
  );

  if (hasCompatibilityOnlyRequestedBrandClaim(result, parsed)) {
    console.log(
      "[AIShopping] V34.CORE120 reject compatibility/lookalike brand claim:",
      result.url,
      result.name
    );
    return false;
  }

  // Reject explicit broken/for-parts listings before they consume a scarce
  // verification slot. This is listing-state logic shared by every category.
  if (isExplicitlyDamagedProduct(result.name, "", parsed)) {
    console.log(
      "[AIShopping] V34.CORE120 reject damaged before verification:",
      result.url,
      result.name
    );
    return false;
  }

  if (isReferenceDocumentOfferResult(result)) {
    console.log(
      "[AIShopping] V34.CORE120 reject reference document as offer:",
      result.url,
      result.name
    );
    return false;
  }

  if (isLikelyOpenWorldCategoryOrCollectionResult(result, parsed)) {
    console.log(
      "[AIShopping] V34.CORE120 reject category/collection as offer:",
      result.url,
      result.name
    );
    return false;
  }

  if (isUnrequestedMultiItemSameProductSet(result.name, parsed)) {
    console.log(
      "[AIShopping] V34.CORE120 reject unrequested multi-item same-product set:",
      result.url,
      result.name
    );
    return false;
  }

  if (hasTrustedVintedCatalogSizeConflict(result, parsed)) {
    console.log(
      "[AIShopping] V34.CORE120 reject trusted Vinted catalog size mismatch:",
      result.url,
      "requested=",
      getRequestedHardWearSize(parsed),
      "card=",
      getTrustedVintedCatalogSize(result)
    );
    return false;
  }

  const universalDiscoveryMatch = evaluateUniversalProductMatch(
    result.name,
    result.snippet,
    result.url,
    parsed,
    "discovery",
    result.source
  );

  if (!universalDiscoveryMatch.pass) {
    // V32.12: a retailer-owned multi-variant package card may legitimately
    // advertise the family using its default package (for example 4 kg) even
    // when the user requested another selectable package (for example 15 kg).
    // Keep ONLY trusted multi-variant cards whose product family/qualifiers
    // still match after removing package_weight. The exact requested package,
    // price and availability must then be resolved on the concrete product
    // page during verification; otherwise the offer is rejected there.
    const trustedMultiVariantPackageCandidate =
      result.source === "RetailerRescue" &&
      isTrustedMultiVariantPackageCatalogCandidate(
        result,
        parsed,
        getResultHostname(result.url)
      );

    // V32.12: official retailer product pages can legitimately list sibling
    // bottle sizes in the title/card (for example 30 ml, 60 ml, 100 ml) while
    // one canonical URL owns every selectable variant. The helper below removes
    // ONLY volume from the discovery matcher; brand, family, product class and
    // fragrance concentration still have to match. It is safe for Bing-sourced
    // duplicates too because the URL itself must belong to a configured
    // commerce host.
    const trustedPerfumeVolumeCandidate =
      isTrustedPerfumeVolumeDeferredRetailerCandidate(
        result,
        parsed,
        getResultHostname(result.url)
      );

    if (trustedMultiVariantPackageCandidate) {
      result.catalogVariantAvailabilityEvidence = true;
      console.log(
        "[AIShopping] V34.CORE120 keep trusted multi-variant package card for exact variant verification:",
        result.url,
        result.name,
        universalDiscoveryMatch.reasons
      );
    } else if (trustedPerfumeVolumeCandidate) {
      result.perfumeVolumeVariantEvidence = true;
      console.log(
        "[AIShopping] V34.CORE120 keep trusted multi-variant perfume card for exact volume verification:",
        result.url,
        result.name,
        universalDiscoveryMatch.reasons
      );
    } else if (
      result.source === "RetailerRescue" &&
      result.deferredModelIdentityBridgeCode &&
      universalDiscoveryMatch.reasons.includes("model-identity-mismatch")
    ) {
      console.log(
        "[AIShopping] V34.CORE120 keep deferred MPN model bridge through discovery:",
        result.url,
        result.deferredModelIdentityBridgeCode
      );
    } else {
      console.log(
        "[AIShopping] V34.CORE120 universal discovery reject:",
        result.url,
        result.name,
        universalDiscoveryMatch.reasons
      );
      return false;
    }
  }

  // V32.12: no category-specific feature gate is allowed to decide discovery.
  // Required attributes are evaluated by evaluateUniversalProductMatch() and,
  // after verification, by the universal requirement evidence engine.
  if (isAuctionOnlyAllegroLokalnieResult(result)) {
    console.log(
      "[AIShopping] V34.CORE120 reject auction-only marketplace result:",
      result.url,
      result.name
    );
    return false;
  }

  if (isGpuWrongProduct(result, parsed)) {
    console.log(
      "[AIShopping] reject GPU wrong product/model:",
      result.url,
      result.name
    );
    return false;
  }

  if (
    isPhoneAccessoryOrWrongVariant(
      result.name,
      result.snippet,
      result.url,
      parsed
    )
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject phone accessory/wrong variant:",
      result.url,
      result.name
    );
    return false;
  }

  if (parsed.condition === "new") {
    const titleExplicitlyNew = hasExplicitRequestedConditionInTitle(
      result.name,
      "new"
    );
    const titleHasUsedConflict = hasClearUsedProductSignals(result.name, "");
    const snippetHasUsedSignal = hasClearUsedProductSignals("", result.snippet);

    // Search-page snippets can contain neighbouring-card condition text.
    // A title that explicitly says "nowy" wins over snippet-only noise, but a
    // contradiction inside the title itself ("po zwrocie", "odnowiony", etc.)
    // remains a hard rejection.
    if (
      titleHasUsedConflict ||
      (!titleExplicitlyNew && snippetHasUsedSignal)
    ) {
      console.log(
        "[AIShopping] V34.CORE120 reject clearly used result for new query:",
        result.url,
        result.name,
        {
          titleExplicitlyNew,
          titleHasUsedConflict,
          snippetHasUsedSignal,
        }
      );
      return false;
    }

    if (titleExplicitlyNew && snippetHasUsedSignal) {
      console.log(
        "[AIShopping] V34.CORE120 ignored unanchored discovery used signal; title proves new:",
        result.url,
        result.name
      );
    }
  }

  if (parsed.category === "controller" && !parsed.intent.accessoryIntent) {
    if (
      isControllerAccessoryOrWrongProduct(
        result.name,
        result.url
      )
    ) {
      console.log(
        "[AIShopping] reject accessory/wrong product:",
        result.url,
        result.name
      );
      return false;
    }

    const controllerTitleSignals = [
      "dualshock 4",
      "dualsense",
      "kontroler",
      "controller",
      "gamepad",
      "pad sony",
      "sony pad",
      "pad ps4",
      "pad ps5",
    ];

    if (!controllerTitleSignals.some((signal) => title.includes(signal))) {
      return false;
    }
  }

  if (parsed.platform === "PS4") {
    if (
      title.includes("dualsense") ||
      title.includes("ps5") ||
      title.includes("playstation 5")
    ) {
      return false;
    }

    if (
      !text.includes("ps4") &&
      !text.includes("playstation 4") &&
      !text.includes("dualshock 4")
    ) {
      return false;
    }
  }

  if (parsed.platform === "PS5") {
    if (
      title.includes("dualshock 4") ||
      title.includes("ps4") ||
      title.includes("playstation 4")
    ) {
      return false;
    }

    if (
      !text.includes("ps5") &&
      !text.includes("playstation 5") &&
      !text.includes("dualsense")
    ) {
      return false;
    }
  }

  // This legacy literal-originality gate is controller-specific. First-party
  // retailer trust and category-aware authenticity are evaluated later during
  // verification; requiring words such as "original" in every discovery title
  // would incorrectly discard genuine perfume/electronics pages from official
  // retailers that simply use the product's normal catalogue name.
  if (parsed.original && parsed.category === "controller") {
    const originalSignals = [
      "dualshock 4",
      "dualsense",
      "oryginal",
      "orginal",
      "original",
      "sony",
      "genuine",
    ];

    if (!originalSignals.some((signal) => text.includes(signal))) {
      return false;
    }
  }

  return true;
}



function extractTirePerPiecePrice(valueRaw: string): { price: number | null; currency: string | null } {
  const value = normalizeText(valueRaw);
  if (!value) return { price: null, currency: null };

  // Tire retailers commonly expose the actual payable price as \"329 zł/szt\".
  // That is different from cosmetic/food unit prices such as \"12,99 zł/100 ml\":
  // one tire is a purchasable unit, so the per-piece price is the offer price.
  const patterns = [
    /(?:^|[^\d])(\d{1,5}(?:[.,]\d{1,2})?)\s*(?:zł|pln)\s*\/\s*(?:szt|szt\.|sztuke|sztukę)(?![\p{L}\p{N}_])/giu,
    /(?:^|[^\d])(\d{1,5}(?:[.,]\d{1,2})?)\s*(?:zł|pln)\s*(?:szt\.?)\s*\(\s*(?:zł|pln)\s+za\s+sztuk(?:e|ę|a)\s*\)/giu,
    /(?:^|[^\d])(\d{1,5}(?:[.,]\d{1,2})?)\s*(?:zł|pln)\s+(?:za\s+)?sztuk(?:e|ę|a)(?![\p{L}\p{N}_])/giu,
  ];

  const candidates: number[] = [];
  for (const pattern of patterns) {
    for (const match of value.matchAll(pattern)) {
      const price = Number((match[1] ?? "").replace(",", "."));
      if (!Number.isFinite(price) || price <= 0 || price > 100_000) continue;
      candidates.push(price);
    }
  }

  if (candidates.length === 0) return { price: null, currency: null };

  // The current payable tire price is usually the last per-piece amount after
  // an optional catalogue/old price.
  return { price: candidates[candidates.length - 1], currency: "PLN" };
}

function extractOfferPieceCountForBudget(valueRaw: string): number {
  const value = normalizeMatchText(valueRaw);
  if (!value) return 1;

  const explicit = value.match(/\b(\d{1,3})\s*(?:x\s*)?(?:szt|sztuki|sztuk|sztuka)\b/iu);
  if (explicit) {
    const count = Number(explicit[1]);
    if (Number.isFinite(count) && count >= 1 && count <= 100) return count;
  }

  const leadingBundle = value.match(/\b(?:komplet|zestaw|pakiet)\s+(?:of|po\s+)?(\d{1,3})\b/iu);
  if (leadingBundle) {
    const count = Number(leadingBundle[1]);
    if (Number.isFinite(count) && count >= 1 && count <= 100) return count;
  }

  // Tire marketplaces frequently encode bundle size as "4x opony" or
  // "4 opony" without a separate "szt." token. Keep this inside the
  // generic budget helper so per-piece comparison works consistently for
  // search cards, verified pages and future tire retailers.
  const tireBundle = value.match(
    /\b(\d{1,3})\s*(?:[x×]\s*)?(?:opon\w*|tire\w*|tyre\w*)\b/iu
  );
  if (tireBundle) {
    const count = Number(tireBundle[1]);
    if (Number.isFinite(count) && count >= 1 && count <= 100) return count;
  }

  return 1;
}


function extractRequestedPackageVariantPriceFromText(
  textRaw: string,
  parsed: ParsedQuery,
  requestedCondition: Condition = null
): PriceInfo {
  if (parsed.category !== "pet_food") return { price: null, currency: null };

  const requirement = parsed.intent.required.find(
    (item) => item.hard && item.key === "package_weight"
  );
  if (!requirement) return { price: null, currency: null };

  const measurement = normalizeMatchText(requirement.value).match(
    /^(\d+(?:[.,]\d+)?)\s*(kg|g)$/i
  );
  if (!measurement) return { price: null, currency: null };

  const requestedNumber = measurement[1].replace(",", ".");
  const unit = measurement[2].toLowerCase();
  const normalized = normalizeText(
    decodeHtml(textRaw).replace(/\u00a0|\u202f/g, " ")
  );

  const numberPattern = escapeRegExp(requestedNumber).replace("\\.", "[.,]");
  const requestedPattern = new RegExp(
    `(?:^|[^0-9])${numberPattern}\\s*${unit}(?=$|[^a-z0-9])`,
    "giu"
  );
  const anyPackagePattern =
    /(?:^|[^0-9])\d+(?:[.,]\d+)?\s*(?:kg|g)(?=$|[^a-z0-9])/giu;

  const candidates: Array<{
    price: number;
    currency: string;
    distance: number;
  }> = [];

  let match: RegExpExecArray | null;
  while ((match = requestedPattern.exec(normalized)) !== null) {
    const prefix = normalizeMatchText(
      normalized.slice(Math.max(0, match.index - 18), match.index)
    );

    // "2 x 15 kg" / "2x15 kg" is a bundle, not the requested single pack.
    if (/\b\d{1,2}\s*[x×]\s*$/iu.test(prefix)) continue;

    const valueStart = match.index + match[0].length;

    // Bind the price to this exact package option. Stop before the next
    // package-size token so a neighbouring 4 kg / 15 kg / 2x15 kg variant
    // cannot lend its price to the requested one.
    const tail = normalized.slice(valueStart, Math.min(normalized.length, valueStart + 220));
    const nextPackage = tail.search(anyPackagePattern);
    const boundedAfter = tail.slice(
      0,
      nextPackage >= 0 ? Math.max(0, nextPackage) : tail.length
    );

    const afterPrice = extractPriceFromText(
      boundedAfter.slice(0, 150),
      requestedCondition,
      false
    );

    if (afterPrice.price !== null && afterPrice.currency) {
      const priceIndex = boundedAfter.search(
        /\d{1,7}(?:[.,]\d{1,2})?\s*(?:zł|pln)/iu
      );
      candidates.push({
        price: afterPrice.price,
        currency: afterPrice.currency,
        distance: priceIndex >= 0 ? priceIndex : 999,
      });
      continue;
    }

    // Some shops render "227,89 zł — 15 kg". Allow a short backwards window
    // only when it does not contain another package-size token.
    const before = normalized.slice(Math.max(0, match.index - 95), match.index);
    const packageTokensBefore = Array.from(before.matchAll(anyPackagePattern));
    const lastOtherPackageEnd =
      packageTokensBefore.length > 0
        ? (packageTokensBefore[packageTokensBefore.length - 1].index ?? 0) +
          packageTokensBefore[packageTokensBefore.length - 1][0].length
        : 0;
    const boundedBefore = before.slice(lastOtherPackageEnd);
    const beforePrice = extractPriceFromText(
      boundedBefore,
      requestedCondition,
      false
    );

    if (beforePrice.price !== null && beforePrice.currency) {
      candidates.push({
        price: beforePrice.price,
        currency: beforePrice.currency,
        distance: 150,
      });
    }
  }

  if (candidates.length === 0) return { price: null, currency: null };

  candidates.sort((a, b) => a.distance - b.distance || a.price - b.price);
  return { price: candidates[0].price, currency: candidates[0].currency };
}

function extractRequestedVolumeVariantPriceFromText(
  textRaw: string,
  parsed: ParsedQuery,
  requestedCondition: Condition = null
): PriceInfo {
  if (parsed.category !== "perfume") return { price: null, currency: null };

  const requirement = parsed.intent.required.find(
    (item) => item.hard && item.key === "volume"
  );
  if (!requirement) return { price: null, currency: null };

  const requestedMeasurement = normalizeMatchText(requirement.value).match(
    /^(\d+(?:[.,]\d+)?)\s*(ml|l)$/i
  );
  if (!requestedMeasurement) return { price: null, currency: null };

  const requestedNumeric = Number(requestedMeasurement[1].replace(",", "."));
  const requestedUnit = requestedMeasurement[2].toLowerCase();
  if (!Number.isFinite(requestedNumeric) || requestedNumeric <= 0) {
    return { price: null, currency: null };
  }
  const requestedMl = requestedUnit === "l" ? requestedNumeric * 1000 : requestedNumeric;

  const normalized = normalizeText(
    decodeHtml(textRaw).replace(/\u00a0|\u202f/g, " ")
  );
  if (!normalized) return { price: null, currency: null };

  const volumePattern = /(?:^|[^0-9])(\d+(?:[.,]\d+)?)\s*(ml|l)(?=$|[^a-z0-9])/giu;
  const occurrences = Array.from(normalized.matchAll(volumePattern));
  if (occurrences.length === 0) return { price: null, currency: null };

  type Candidate = { price: number; currency: string; score: number };
  const candidates: Candidate[] = [];

  const toMl = (numberRaw: string, unitRaw: string): number => {
    const value = Number(numberRaw.replace(",", "."));
    return unitRaw.toLowerCase() === "l" ? value * 1000 : value;
  };

  for (let i = 0; i < occurrences.length; i += 1) {
    const occurrence = occurrences[i];
    const numberRaw = occurrence[1] ?? "";
    const unitRaw = occurrence[2] ?? "";
    const valueMl = toMl(numberRaw, unitRaw);
    if (!Number.isFinite(valueMl) || Math.abs(valueMl - requestedMl) > 0.001) {
      continue;
    }

    const start = occurrence.index ?? 0;
    const end = start + occurrence[0].length;

    // Ignore unit-price denominators such as "549 zł / 100 ml". They describe
    // price normalization, not the selectable bottle variant itself.
    const shortPrefix = normalizeMatchText(
      normalized.slice(Math.max(0, start - 28), start)
    );
    if (/(?:zł|pln)\s*\/\s*$/iu.test(shortPrefix) || /\/\s*$/u.test(shortPrefix)) {
      continue;
    }

    const previousEnd = i > 0
      ? ((occurrences[i - 1].index ?? 0) + occurrences[i - 1][0].length)
      : Math.max(0, start - 260);
    const nextStart = i + 1 < occurrences.length
      ? (occurrences[i + 1].index ?? normalized.length)
      : Math.min(normalized.length, end + 260);

    // Retailers commonly render "current price ... 100 ml". Bind only the
    // price block after the previous size token and before this exact size.
    const boundedBefore = normalized.slice(
      Math.max(previousEnd, start - 260),
      start
    );
    const beforePrice = extractPriceFromText(
      boundedBefore,
      requestedCondition,
      false
    );
    if (beforePrice.price !== null && beforePrice.currency) {
      candidates.push({
        price: beforePrice.price,
        currency: beforePrice.currency,
        score: 8,
      });
    }

    // Some stores render "100 ml 549 zł". Inspect only until the next volume
    // token and reject a price that is immediately followed by "/ 100 ml".
    const boundedAfter = normalized.slice(
      end,
      Math.min(nextStart, end + 220)
    );
    const afterPriceMatches = Array.from(
      boundedAfter.matchAll(
        /(\d{1,3}(?:[ .]\d{3})+|\d{1,7})(?:\s*[.,]\s*(\d{1,2}))?\s*(zł|pln)/giu
      )
    );

    for (const priceMatch of afterPriceMatches) {
      const matchEnd = (priceMatch.index ?? 0) + priceMatch[0].length;
      const suffix = normalizeMatchText(
        boundedAfter.slice(matchEnd, Math.min(boundedAfter.length, matchEnd + 28))
      );
      if (/^\/\s*\d+(?:[.,]\d+)?\s*(?:ml|l)\b/iu.test(suffix)) {
        continue;
      }

      const whole = String(priceMatch[1] ?? "").replace(/\s+/g, "");
      const cents = priceMatch[2] ? String(priceMatch[2]).padEnd(2, "0").slice(0, 2) : "";
      const numeric = Number(`${whole.replace(",", ".")}${cents ? `.${cents}` : ""}`);
      const currency = normalizeCurrency(priceMatch[3]);
      if (!Number.isFinite(numeric) || numeric <= 0 || !currency) continue;

      candidates.push({
        price: numeric,
        currency,
        score: 6 - Math.min(4, (priceMatch.index ?? 0) / 45),
      });
      break;
    }
  }

  // V32.12: some official perfume pages render a compact size selector first
  // (for example 30 / 60 / 100 / 200 ml), then ONE current payable price,
  // and repeat the selected size later as metadata such as "Capacity: 100 mL".
  // The strict neighbour binder above intentionally cannot bind across sibling
  // sizes, so recover only when the requested size is independently marked as
  // selected/current and belongs to that compact selector cluster.
  const requestedOccurrenceIndexes = occurrences
    .map((occurrence, index) => ({ occurrence, index }))
    .filter(({ occurrence }) => {
      const valueMl = toMl(occurrence[1] ?? "", occurrence[2] ?? "");
      return Number.isFinite(valueMl) && Math.abs(valueMl - requestedMl) <= 0.001;
    });

  const selectedRequestedOccurrence = requestedOccurrenceIndexes.some(
    ({ occurrence }) => {
      const start = occurrence.index ?? 0;
      const prefix = normalizeMatchText(
        normalized.slice(Math.max(0, start - 56), start)
      );
      return /(?:capacity|pojemnosc|selected|wybrany|wybrana|wariant|size|rozmiar)\s*:?\s*$/iu.test(prefix);
    }
  );

  if (selectedRequestedOccurrence) {
    for (const { index: requestedIndex } of requestedOccurrenceIndexes) {
      let left = requestedIndex;
      let right = requestedIndex;

      while (left > 0) {
        const previous = occurrences[left - 1];
        const current = occurrences[left];
        const previousEnd = (previous.index ?? 0) + previous[0].length;
        const currentStart = current.index ?? 0;
        if (currentStart - previousEnd > 90) break;
        left -= 1;
      }

      while (right + 1 < occurrences.length) {
        const current = occurrences[right];
        const next = occurrences[right + 1];
        const currentEnd = (current.index ?? 0) + current[0].length;
        const nextStart = next.index ?? 0;
        if (nextStart - currentEnd > 90) break;
        right += 1;
      }

      const distinctClusterVolumes = new Set<number>();
      for (let index = left; index <= right; index += 1) {
        const occurrence = occurrences[index];
        const volumeMl = toMl(occurrence[1] ?? "", occurrence[2] ?? "");
        if (Number.isFinite(volumeMl)) distinctClusterVolumes.add(volumeMl);
      }
      if (distinctClusterVolumes.size < 2) continue;

      const clusterEndOccurrence = occurrences[right];
      const clusterEnd = (clusterEndOccurrence.index ?? 0) + clusterEndOccurrence[0].length;
      const mainPriceWindow = normalized.slice(
        clusterEnd,
        Math.min(normalized.length, clusterEnd + 900)
      );

      const mainPriceMatches = Array.from(
        mainPriceWindow.matchAll(
          /(\d{1,3}(?:[ .]\d{3})+|\d{1,7})(?:\s*[.,]\s*(\d{1,2}))?\s*(zł|pln)/giu
        )
      );

      for (const priceMatch of mainPriceMatches.slice(0, 6)) {
        const matchStart = priceMatch.index ?? 0;
        const prefix = normalizeMatchText(
          mainPriceWindow.slice(Math.max(0, matchStart - 22), matchStart)
        );
        if (/(?:^|\s)(?:od|from|starting|juz od|już od)\s*$/iu.test(prefix)) continue;

        const whole = String(priceMatch[1] ?? "").replace(/\s+/g, "");
        const cents = priceMatch[2]
          ? String(priceMatch[2]).padEnd(2, "0").slice(0, 2)
          : "";
        const numeric = Number(`${whole.replace(",", ".")}${cents ? `.${cents}` : ""}`);
        const currency = normalizeCurrency(priceMatch[3]);
        if (!Number.isFinite(numeric) || numeric <= 0 || !currency) continue;

        candidates.push({
          price: numeric,
          currency,
          score: 10 - Math.min(3, matchStart / 220),
        });
        break;
      }

      if (candidates.length > 0) break;
    }
  }

  if (candidates.length === 0) return { price: null, currency: null };
  candidates.sort((a, b) => b.score - a.score || a.price - b.price);
  return { price: candidates[0].price, currency: candidates[0].currency };
}

function verifiedNameBindsRequestedPerfumeVolume(
  nameRaw: string,
  parsed: ParsedQuery
): boolean {
  if (parsed.category !== "perfume") return false;

  const requirement = parsed.intent.required.find(
    (item) => item.hard && item.key === "volume"
  );
  if (!requirement) return false;

  const requestedMeasurement = normalizeMatchText(requirement.value).match(
    /^(\d+(?:[.,]\d+)?)\s*(ml|l)$/i
  );
  if (!requestedMeasurement) return false;

  const requestedNumeric = Number(requestedMeasurement[1].replace(",", "."));
  const requestedMl = requestedMeasurement[2].toLowerCase() === "l"
    ? requestedNumeric * 1000
    : requestedNumeric;
  if (!Number.isFinite(requestedMl) || requestedMl <= 0) return false;

  const text = normalizeText(nameRaw);
  const volumes = Array.from(
    text.matchAll(/(?:^|[^0-9])(\d+(?:[.,]\d+)?)\s*(ml|l)(?=$|[^a-z0-9])/giu)
  )
    .map((match) => {
      const value = Number(String(match[1] ?? "").replace(",", "."));
      return String(match[2] ?? "").toLowerCase() === "l" ? value * 1000 : value;
    })
    .filter((value) => Number.isFinite(value) && value > 0);

  if (volumes.length === 0) return false;
  const hasRequested = volumes.some((value) => Math.abs(value - requestedMl) <= 0.001);
  const hasConflicting = volumes.some((value) => Math.abs(value - requestedMl) > 0.001);
  return hasRequested && !hasConflicting;
}

function extractRequestedPackageVariantUrlFromMarkup(
  markupRaw: string,
  baseUrl: string,
  parsed: ParsedQuery
): string | null {
  if (parsed.category !== "pet_food") return null;

  const requirement = parsed.intent.required.find(
    (item) => item.hard && item.key === "package_weight"
  );
  if (!requirement) return null;

  const measurement = normalizeMatchText(requirement.value).match(
    /^(\d+(?:[.,]\d+)?)\s*(kg|g)$/i
  );
  if (!measurement) return null;

  const requestedNumber = measurement[1].replace(",", ".");
  const unit = measurement[2].toLowerCase();
  const numberPattern = escapeRegExp(requestedNumber).replace("\\.", "[.,]");
  const exactVariantPattern = new RegExp(
    `(?:^|[^0-9])${numberPattern}\\s*${unit}(?!\\s*\\+)(?=$|[^a-z0-9])`,
    "iu"
  );

  const labelMatches = (labelRaw: string): boolean => {
    const label = normalizeText(
      decodeHtml(labelRaw)
        .replace(/<[^>]+>/g, " ")
        .replace(/\u00a0|\u202f/g, " ")
    );
    if (!label) return false;

    const match = exactVariantPattern.exec(label);
    if (!match) return false;

    const prefix = normalizeMatchText(
      label.slice(Math.max(0, match.index - 18), match.index)
    );

    // 2x15 kg / 2 x 15 kg is a bundle and must not masquerade as 15 kg.
    if (/\b\d{1,2}\s*[x×]\s*$/iu.test(prefix)) return false;

    return true;
  };

  const resolveCandidate = (hrefRaw: string, labelRaw: string): string | null => {
    if (!labelMatches(labelRaw)) return null;

    try {
      const absolute = new URL(decodeHtml(hrefRaw).trim(), baseUrl).toString();
      const normalized = normalizeUrl(absolute);
      if (!normalized) return null;
      if (getResultHostname(normalized) !== getResultHostname(baseUrl)) return null;
      if (!isProbablyRealOfferUrl(normalized)) return null;
      return normalized;
    } catch {
      return null;
    }
  };

  const htmlAnchorRe = /<a\b[^>]*?href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/giu;
  let htmlMatch: RegExpExecArray | null;
  while ((htmlMatch = htmlAnchorRe.exec(markupRaw)) !== null) {
    const resolved = resolveCandidate(htmlMatch[1], htmlMatch[2]);
    if (resolved) return resolved;
  }

  const markdownLinkRe = /\[([^\]]{1,500})\]\(([^)\s]+)\)/giu;
  let markdownMatch: RegExpExecArray | null;
  while ((markdownMatch = markdownLinkRe.exec(markupRaw)) !== null) {
    const resolved = resolveCandidate(markdownMatch[2], markdownMatch[1]);
    if (resolved) return resolved;
  }

  return null;
}

function isBarePackageVariantLabel(nameRaw: string): boolean {
  const name = normalizeText(nameRaw).trim();
  if (!name) return false;

  // Retailer JSON-LD/product selectors sometimes expose only the selected
  // package label ("4 kg", "15 kg", "2 x 15 kg", "15+3 kg") as Product.name.
  // Such a label is a variant value, not a usable product identity.
  return /^\s*(?:\d+\s*[x×]\s*)?\d+(?:[.,]\d+)?(?:\s*\+\s*\d+(?:[.,]\d+)?)?\s*(?:kg|g|ml|l)\s*$/i.test(
    name
  );
}

function rewriteVerifiedNameToRequestedPackageVariant(
  currentNameRaw: string,
  discoveryNameRaw: string,
  parsed: ParsedQuery
): string {
  const currentName = cleanTitle(currentNameRaw);
  const discoveryName = cleanTitle(discoveryNameRaw);

  // Prefer the verified/page identity when it is a real product name. If the
  // page exposes only a bare variant label, preserve the URL-bound discovery
  // identity and rewrite only its package amount. This keeps brand/family/model
  // semantics intact while still presenting the exact requested variant.
  const identityBase =
    currentName && !isBarePackageVariantLabel(currentName)
      ? currentName
      : discoveryName || currentName;

  return rewriteNameToRequestedPackageVariant(identityBase, parsed);
}

function rewriteNameToRequestedPackageVariant(
  nameRaw: string,
  parsed: ParsedQuery
): string {
  const requirement = parsed.intent.required.find(
    (item) => item.hard && item.key === "package_weight"
  );
  if (!requirement) return nameRaw;

  const requested = normalizeText(requirement.aliases[0] || requirement.value);
  if (!requested) return nameRaw;

  const name = cleanTitle(nameRaw);
  const replaced = name.replace(
    /\b\d+(?:[.,]\d+)?\s*(?:kg|g)\b/i,
    requested
  );

  return replaced === name ? cleanTitle(`${name} ${requested}`) : cleanTitle(replaced);
}

function rewriteVerifiedNameToRequestedVolumeVariant(
  currentNameRaw: string,
  discoveryNameRaw: string,
  parsed: ParsedQuery
): string {
  if (parsed.category !== "perfume") return cleanTitle(currentNameRaw || discoveryNameRaw);

  const requirement = parsed.intent.required.find(
    (item) => item.hard && item.key === "volume"
  );
  if (!requirement) return cleanTitle(currentNameRaw || discoveryNameRaw);

  const requested = normalizeText(requirement.aliases[0] || requirement.value);
  const identityBase = cleanTitle(currentNameRaw) || cleanTitle(discoveryNameRaw);
  if (!requested || !identityBase) return identityBase;

  // Multi-variant retailer titles often enumerate the default/selectable sizes
  // ("30ml, 60ml ..."). Once the exact requested size has been price-bound,
  // remove those catalogue-size tokens and append only the proven size. This
  // prevents the generic hard-conflict checker from mistaking sibling variants
  // for the selected bottle while preserving brand/family/concentration.
  const withoutCatalogVolumes = normalizeText(
    identityBase.replace(
      /(?:^|[^\p{L}\p{N}])\d+(?:[.,]\d+)?\s*(?:ml|l)(?=$|[^\p{L}\p{N}])/giu,
      " "
    )
  );

  return cleanTitle(`${withoutCatalogVolumes || identityBase} ${requested}`);
}

function getRequestedHardPieceCount(parsed: ParsedQuery): number {
  const requirement = parsed.intent.required.find(
    (item) => item.hard && item.key === "piece_count" && universalRequirementComparison(item) === "eq"
  );
  if (!requirement) return 1;
  const count = Number(String(requirement.value).match(/\d{1,3}/)?.[0] ?? NaN);
  return Number.isFinite(count) && count >= 1 && count <= 100 ? count : 1;
}

function isRetailerTireUnitPurchaseMode(titleRaw: string, urlRaw: string, sourceRaw: string, parsed: ParsedQuery): boolean {
  if (parsed.category !== "tire" || getRequestedHardPieceCount(parsed) <= 1 || sourceRaw !== "RetailerRescue") return false;
  if (!isConfiguredCommerceDomain(urlRaw) || !isProbablyRealOfferUrl(urlRaw)) return false;
  const title = normalizeMatchText(titleRaw);
  if (extractCanonicalTireSizesFromText(title).length === 0) return false;
  if (/\b(?:komplet|zestaw|pakiet|set)\b/iu.test(title)) return false;
  if (/\b\d{1,2}\s*(?:x\s*)?(?:szt\.?|sztuk|sztuki|sztuka|pcs?|pieces?)\b/iu.test(title)) return false;
  if (/\b(?:para|pair)\b/iu.test(title)) return false;
  return true;
}

function normalizeRequestedTirePurchasePrice(
  unitPricePln: number,
  deliveryCostPln: number | null,
  parsed: ParsedQuery
): { itemPrice: number; totalPrice: number; pieceCount: number } {
  const pieceCount = parsed.category === "tire" ? getRequestedHardPieceCount(parsed) : 1;
  const itemPrice = unitPricePln * Math.max(1, pieceCount);
  return {
    itemPrice,
    totalPrice: itemPrice + (deliveryCostPln ?? 0),
    pieceCount: Math.max(1, pieceCount),
  };
}

function budgetComparablePrice(
  totalPricePln: number,
  evidenceRaw: string,
  parsed: ParsedQuery
): { comparable: number; pieceCount: number } {
  if (!parsed.intent.budgetPerPiece) {
    return { comparable: totalPricePln, pieceCount: 1 };
  }

  const pieceCount = extractOfferPieceCountForBudget(evidenceRaw);
  return {
    comparable: totalPricePln / Math.max(1, pieceCount),
    pieceCount: Math.max(1, pieceCount),
  };
}


async function verifyTrustedCeneoMerchantResult(
  result: SearchResult,
  parsed: ParsedQuery,
  verificationSignal?: AbortSignal
): Promise<Offer | null> {
  const merchant = result.ceneoMerchantOffer;
  if (!merchant) return null;

  const evidence = normalizeText(
    `${merchant.productName} ${result.name} ${merchant.productEvidence} ${result.snippet}`
  ).slice(0, 24_000);

  if (
    parsed.condition &&
    merchant.condition &&
    merchant.condition !== parsed.condition
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject Ceneo merchant condition mismatch:",
      merchant.shopName,
      result.url,
      "requested=",
      parsed.condition,
      "verified=",
      merchant.condition
    );
    return null;
  }

  if (parsed.original && hasExplicitNonOriginalProductSignal(`${result.name} ${evidence}`)) {
    console.log(
      "[AIShopping] V34.CORE120 reject explicit non-original Ceneo merchant:",
      merchant.shopName,
      result.url
    );
    return null;
  }

  const standaloneIdentity = evaluateCeneoMerchantStandaloneIdentity(
    result.name,
    parsed,
    merchant.productName
  );
  if (!standaloneIdentity.pass) {
    console.log(
      "[AIShopping] V34.CORE120 reject Ceneo merchant standalone identity:",
      merchant.shopName,
      result.url,
      standaloneIdentity.reasons
    );
    return null;
  }

  let universalEvidence = evidence;
  let universalMatch = evaluateUniversalProductMatch(
    `${result.name} ${merchant.productName}`,
    universalEvidence,
    merchant.productPageUrl,
    parsed,
    "verified",
    "CeneoMerchant"
  );

  // CORE80: a Ceneo merchant row is intentionally narrow: it proves seller,
  // current price, condition and its own product identity, but it may omit a
  // stable chassis/model fact such as refresh rate. Before rejecting ONLY for
  // missing hard attributes, reuse the same exact-model proof mechanism as the
  // normal verifier. The proof is scoped to this merchant's concrete parent
  // product/model and may never supply listing-specific attributes.
  if (
    !universalMatch.pass &&
    universalMatch.reasons.includes("missing-required-attribute") &&
    !verificationSignal?.aborted
  ) {
    const unresolvedHardRequirements = parsed.intent.required
      .filter((requirement) => requirement.hard)
      .filter((requirement) => !requirementHasEvidence(requirement, universalEvidence));
    const listingBoundMissing = unresolvedHardRequirements.filter(
      (requirement) => !canUseExternalProofForRequirement(requirement)
    );
    const externallyProvableMissing = unresolvedHardRequirements.filter(
      canUseExternalProofForRequirement
    );

    if (listingBoundMissing.length === 0 && externallyProvableMissing.length > 0) {
      const exactModelProof = await findUniversalRequirementProofViaSearch(
        `${merchant.productName} ${result.name}`,
        externallyProvableMissing,
        parsed,
        merchant.productPageUrl,
        verificationSignal
      );

      if (exactModelProof) {
        universalEvidence = normalizeText(
          `${universalEvidence} ${exactModelProof}`
        ).slice(0, 36_000);
        universalMatch = evaluateUniversalProductMatch(
          `${result.name} ${merchant.productName}`,
          universalEvidence,
          merchant.productPageUrl,
          parsed,
          "verified",
          "CeneoMerchant"
        );

        console.log(
          "[AIShopping] V34.CORE120 Ceneo merchant exact-model requirement resolution:",
          merchant.productName,
          "pass=",
          universalMatch.pass,
          "missing=",
          universalMatch.missingRequirements
        );
      }
    }
  }

  if (!universalMatch.pass) {
    console.log(
      "[AIShopping] V34.CORE120 reject Ceneo merchant universal mismatch:",
      merchant.shopName,
      result.url,
      universalMatch.reasons
    );
    return null;
  }

  const brandAssessment = evaluateVerifiedBrandConflict(
    parsed,
    `${result.name} ${merchant.productName}`,
    evidence
  );
  if (brandAssessment.conflict) {
    console.log(
      "[AIShopping] V34.CORE120 reject Ceneo merchant brand conflict:",
      merchant.shopName,
      result.url,
      brandAssessment.claims
    );
    return null;
  }

  const pricePln = await convertToPln(merchant.price, merchant.currency);
  if (pricePln === null) return null;

  let deliveryCostPln: number | null = null;
  if (
    merchant.shippingCost !== null &&
    merchant.shippingCurrency
  ) {
    deliveryCostPln = await convertToPln(
      merchant.shippingCost,
      merchant.shippingCurrency
    );
  }

  const requestedTirePurchase = parsed.category === "tire" && getRequestedHardPieceCount(parsed) > 1
    ? normalizeRequestedTirePurchasePrice(pricePln, deliveryCostPln, parsed)
    : null;
  const outputItemPricePln = requestedTirePurchase?.itemPrice ?? pricePln;
  const totalPricePln = requestedTirePurchase?.totalPrice ?? (pricePln + (deliveryCostPln ?? 0));
  const budget = budgetComparablePrice(
    totalPricePln,
    `${result.name} ${evidence}`,
    parsed
  );

  if (parsed.maxPrice !== null && budget.comparable > parsed.maxPrice) {
    console.log(
      "[AIShopping] V34.CORE120 reject Ceneo merchant over total budget:",
      merchant.shopName,
      result.url,
      "item=",
      pricePln,
      "delivery=",
      deliveryCostPln,
      "total=",
      totalPricePln,
      "max=",
      parsed.maxPrice
    );
    return null;
  }

  if (
    !isRelevantProduct(
      `${result.name} ${merchant.productName}`,
      evidence,
      parsed,
      merchant.productPageUrl,
      pricePln
    )
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject irrelevant Ceneo merchant:",
      merchant.shopName,
      result.url
    );
    return null;
  }

  const relevance =
    calculateRelevance(
      `${result.name} ${merchant.productName}`,
      evidence,
      parsed,
      pricePln,
      merchant.productPageUrl
    ) - result.searchRank * 0.35;

  console.log(
    "[AIShopping] V34.CORE120 verified Ceneo merchant offer:",
    merchant.shopName,
    result.name,
    "item=",
    pricePln,
    "delivery=",
    deliveryCostPln,
    "total=",
    totalPricePln
  );

  return {
    id: 0,
    name: cleanTitle(result.name || merchant.productName),
    store: merchant.shopName,
    price: Math.round(outputItemPricePln * 100) / 100,
    currency: "PLN",
    rating: null,
    condition:
      merchant.condition === "used"
        ? "Używany"
        : merchant.condition === "new"
          ? "Nowy"
          : parsed.condition === "new"
            ? "Nowy"
            : parsed.condition === "used"
              ? "Używany"
              : null,
    original: parsed.original,
    delivery:
      deliveryCostPln !== null
        ? formatDeliveryLabel(deliveryCostPln, "PLN")
        : merchant.shippingLabel,
    category: parsed.category,
    platform: parsed.platform,
    brand: parsed.brand,
    url: result.url,
    description: normalizeText(
      `Oferta ${merchant.shopName} zweryfikowana na konkretnej karcie produktu Ceneo. ` +
      `${merchant.reviewsCount !== null ? `${merchant.reviewsCount} opinii sklepu. ` : ""}` +
      evidence
    ).slice(0, 700),
    priceVerified: true,
    availability: "available",
    verification: "verified",
    totalPrice: Math.round(totalPricePln * 100) / 100,
    comparisonPrice: Math.round(budget.comparable * 100) / 100,
    comparisonUnit: parsed.intent.budgetPerPiece ? "per-piece" : "total",
    pieceCount: requestedTirePurchase?.pieceCount ?? budget.pieceCount,
    relevance,
  };
}

async function expandCeneoMerchantVerificationCandidates(
  results: SearchResult[],
  parsed: ParsedQuery,
  hardDeadlineAt: number
): Promise<SearchResult[]> {
  const preciseTechIntent = isV34Core164PreciseTechIntent(parsed);
  const highConstraintRetailIntent = isV34Core164HighConstraintRetailIntent(parsed);
  const requestedBrandAliases = getUniversalRequestedBrandAliases(parsed);

  // V34.CORE173: a bounded first-party catalog card that already names the
  // requested brand, passes universal identity, proves every HARD requirement
  // and carries a listing-bound discovery price is the best verifier-budget
  // anchor we can have before concrete-page verification. Do not let several
  // speculative comparison-page readers consume the whole remaining window
  // before that retailer page gets a worker.
  const protectedHighConstraintRetailerCandidates = results.filter((result) => {
    if (!highConstraintRetailIntent) return false;
    if (result.source === "CeneoDirect" || result.source === "CeneoMerchant") return false;
    if (result.retailerOwnedCardEvidence !== true) return false;

    const host = getResultHostname(result.url);
    if (!host || host === "ceneo.pl") return false;
    if (
      V28_UNIVERSAL_MARKETPLACE_DOMAINS.some(
        (marketplaceHost) => String(marketplaceHost) === host
      )
    ) {
      return false;
    }

    const title = normalizeMatchText(result.name);
    const brandExplicit =
      requestedBrandAliases.length === 0 ||
      requestedBrandAliases.some((alias) =>
        phraseMorphologicallyMatches(alias, title) ||
        automotiveLexicalTermMatches(alias, title)
      );
    if (!brandExplicit) return false;

    const match = evaluateUniversalProductMatch(
      result.name,
      result.snippet,
      result.url,
      parsed,
      "discovery",
      result.source
    );
    if (!match.pass) return false;
    if (getTrustedPortfolioHardCoverageScore(result, parsed) < 10_000) return false;

    const discoveryPrice = getSilentDiscoveryPrice(result, parsed);
    return discoveryPrice.price !== null && Boolean(discoveryPrice.currency);
  });

  const protectHighConstraintRetailerVerifierBudget =
    highConstraintRetailIntent && protectedHighConstraintRetailerCandidates.length > 0;
  const core173VerifierReserveMs = protectHighConstraintRetailerVerifierBudget ? 4_200 : 0;

  const rawCeneoCandidatePool = dedupeSearchResultsByUrl(
    results.filter(
      (result) =>
        result.source === "CeneoDirect" &&
        /^https?:\/\/(?:www\.)?ceneo\.pl\/\d+(?:\/|$)/iu.test(result.url)
    )
  ).sort(
    (a, b) =>
      getSearchResultPriority(b, parsed) - getSearchResultPriority(a, parsed) ||
      a.searchRank - b.searchRank
  );

  // When an exact first-party anchor already proves the full requested bundle,
  // an anonymous Ceneo title that omits the requested brand is not worth a
  // globally throttled reader slot. This is scheduling-only and does not make
  // any Ceneo result easier to accept.
  const ceneoCandidatePool = protectHighConstraintRetailerVerifierBudget
    ? rawCeneoCandidatePool.filter((candidate) => {
        const title = normalizeMatchText(candidate.name);
        return requestedBrandAliases.some((alias) =>
          phraseMorphologicallyMatches(alias, title) ||
          automotiveLexicalTermMatches(alias, title)
        );
      })
    : rawCeneoCandidatePool;

  if (protectHighConstraintRetailerVerifierBudget) {
    console.log(
      "[AIShopping] V34.CORE173 high-constraint retailer verifier reserve:",
      {
        protectedRetailerHosts: Array.from(
          new Set(
            protectedHighConstraintRetailerCandidates
              .map((result) => getResultHostname(result.url))
              .filter(Boolean)
          )
        ),
        rawCeneoCards: rawCeneoCandidatePool.length,
        brandExplicitCeneoCards: ceneoCandidatePool.length,
        reserveMs: core173VerifierReserveMs,
      }
    );
  }

  const ceneoExpansionLimit = preciseTechIntent
    ? 1
    : protectHighConstraintRetailerVerifierBudget
      ? 1
      : 3;
  const ceneoCandidates = ceneoCandidatePool.slice(0, ceneoExpansionLimit);

  if (ceneoCandidates.length === 0) return results;

  // CORE165: Ceneo merchant recovery must not monopolise the first verification
  // wave when precise-tech discovery has already produced a broad first-party
  // portfolio. Keep the normal reader attempt, but suppress the additional
  // fresh/no-cache retry for a tiny document once 3+ independent non-Ceneo
  // retailer hosts are already queued. This is coverage-derived, not tied to
  // any benchmark model/store, and all merchant/HARD/price gates stay intact.
  const preciseTechRetailerHosts = new Set(
    results
      .filter((result) => {
        if (result.source === "CeneoDirect" || result.source === "CeneoMerchant") {
          return false;
        }
        const host = getResultHostname(result.url);
        if (!host) return false;
        return (
          host !== "ceneo.pl" &&
          !V28_UNIVERSAL_MARKETPLACE_DOMAINS.some(
            (marketplaceHost) => String(marketplaceHost) === host
          )
        );
      })
      .map((result) => getResultHostname(result.url))
      .filter((host): host is string => Boolean(host))
  );
  const protectPreciseTechVerifierBudget =
    preciseTechIntent && preciseTechRetailerHosts.size >= 3;

  const remaining = hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
  if (
    remaining < 2_200 ||
    (protectHighConstraintRetailerVerifierBudget &&
      remaining < core173VerifierReserveMs + 1_550)
  ) {
    if (protectHighConstraintRetailerVerifierBudget) {
      console.log(
        "[AIShopping] V34.CORE173 Ceneo expansion skipped to preserve retailer verifier:",
        { remainingMs: remaining, reserveMs: core173VerifierReserveMs }
      );
    }
    return results;
  }

  const expansionByUrl = new Map<string, CeneoMerchantExpansion>();

  const expandCeneoCandidate = async (
    candidate: SearchResult,
    options: {
      allowReader?: boolean;
      directTimeoutCapMs?: number;
      directOnlyLabel?: string;
    } = {}
  ): Promise<void> => {
      const allowReader = options.allowReader !== false;
      const candidateRemaining =
        hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
      if (
        candidateRemaining < 1_600 ||
        (protectHighConstraintRetailerVerifierBudget &&
          candidateRemaining < core173VerifierReserveMs + 1_550)
      ) {
        return;
      }

      const candidateExpansionHeadroom = Math.max(
        0,
        candidateRemaining - core173VerifierReserveMs
      );
      const timeoutMs = Math.max(
        options.directTimeoutCapMs ? Math.min(700, options.directTimeoutCapMs) : 1_200,
        Math.min(
          options.directTimeoutCapMs ?? 2_800,
          candidateExpansionHeadroom - 450
        )
      );
      const page = await fetchHtml(candidate.url, timeoutMs);
      if (!page || page.status >= 400 || !page.html || isBlockedOrChallengePage(page.html)) {
        console.log(
          "[AIShopping] V34.CORE120 Ceneo merchant expansion unavailable:",
          candidate.url,
          page?.status ?? "network"
        );
        return;
      }

      let expansion = parseCeneoMerchantOffersFromHtml(
        page.html,
        candidate.name,
        page.finalUrl || candidate.url,
        parsed,
        candidate.searchRank * 10
      );

      // V34.CORE151: Ceneo's direct HTML can be a shell with no merchant
      // anchors even though the same concrete product page is fully readable
      // through Jina. Recover merchant rows here, BEFORE aggregate Ceneo is
      // treated as a final shop. The converted reader document still passes
      // the exact same row-local identity/HARD/price parser; no broad page
      // evidence bypass is introduced.
      if (!expansion.foundMerchantCards && allowReader) {
        const readerRemaining =
          hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
        const readerExpansionHeadroom = Math.max(
          0,
          readerRemaining - core173VerifierReserveMs
        );
        if (readerExpansionHeadroom >= 1_700) {
          const readerTimeoutCapMs =
            protectHighConstraintRetailerVerifierBudget
              ? 2_200
              : protectPreciseTechVerifierBudget
                ? 2_200
                : 3_200;
          const readerTimeoutMs = Math.max(
            1_300,
            Math.min(
              readerTimeoutCapMs,
              readerExpansionHeadroom - 400
            )
          );
          let readerText = await fetchViaJina(
            page.finalUrl || candidate.url,
            readerTimeoutMs,
            false
          );

          let readerExpansion =
            readerText && !isBlockedOrChallengePage(readerText)
              ? parseCeneoMerchantOffersFromHtml(
                  convertCeneoReaderMarkdownToMerchantHtml(readerText),
                  candidate.name,
                  page.finalUrl || candidate.url,
                  parsed,
                  candidate.searchRank * 10
                )
              : null;

          // CORE164: Jina can occasionally return a tiny cached summary with
          // HTTP 200 instead of the concrete product merchant section. That
          // response is never merchant proof. With enough deadline headroom,
          // make one fresh no-cache read of the same concrete numeric Ceneo URL.
          const freshReaderRemaining =
            hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
          if (
            readerText &&
            readerText.length < 1_200 &&
            !readerExpansion?.foundMerchantCards &&
            freshReaderRemaining >= 2_600 &&
            !protectPreciseTechVerifierBudget &&
            !protectHighConstraintRetailerVerifierBudget
          ) {
            const freshTimeoutMs = Math.max(
              1_500,
              Math.min(2_300, freshReaderRemaining - 650)
            );
            const freshReaderText = await fetchViaJinaFresh(
              page.finalUrl || candidate.url,
              freshTimeoutMs
            );

            if (
              freshReaderText &&
              !isBlockedOrChallengePage(freshReaderText) &&
              freshReaderText.length > readerText.length
            ) {
              const freshExpansion = parseCeneoMerchantOffersFromHtml(
                convertCeneoReaderMarkdownToMerchantHtml(freshReaderText),
                candidate.name,
                page.finalUrl || candidate.url,
                parsed,
                candidate.searchRank * 10
              );

              console.log(
                "[AIShopping] V34.CORE164 Ceneo tiny-reader fresh retry:",
                candidate.name,
                "initialLength=",
                readerText.length,
                "freshLength=",
                freshReaderText.length,
                "cards=",
                freshExpansion.foundMerchantCards,
                "eligible=",
                freshExpansion.results.length
              );

              if (
                freshExpansion.foundMerchantCards ||
                freshExpansion.results.length >
                  (readerExpansion?.results.length ?? 0)
              ) {
                readerText = freshReaderText;
                readerExpansion = freshExpansion;
              }
            } else {
              console.log(
                "[AIShopping] V34.CORE164 Ceneo tiny-reader fresh retry unavailable:",
                candidate.url,
                "initialLength=",
                readerText.length,
                "freshLength=",
                freshReaderText.length
              );
            }
          } else if (
            readerText &&
            readerText.length < 1_200 &&
            !readerExpansion?.foundMerchantCards &&
            protectPreciseTechVerifierBudget
          ) {
            console.log(
              "[AIShopping] V34.CORE165 Ceneo tiny-reader fresh retry skipped to protect verifier budget:",
              candidate.name,
              "readerLength=",
              readerText.length,
              "retailerHosts=",
              preciseTechRetailerHosts.size,
              "remainingMs=",
              freshReaderRemaining
            );
          }

          if (
            readerText &&
            !isBlockedOrChallengePage(readerText) &&
            readerExpansion
          ) {
            if (
              readerExpansion.foundMerchantCards ||
              readerExpansion.results.length > expansion.results.length
            ) {
              expansion = readerExpansion;
            }

            console.log(
              "[AIShopping] V34.CORE153 Ceneo merchant reader expansion:",
              candidate.name,
              "readerLength=",
              readerText.length,
              "cards=",
              readerExpansion.foundMerchantCards,
              "eligible=",
              readerExpansion.results.length
            );
          } else {
            console.log(
              "[AIShopping] V34.CORE153 Ceneo merchant reader unavailable:",
              candidate.url,
              "received=",
              Boolean(readerText)
            );
          }
        }
      }

      if (!allowReader) {
        console.log(
          "[AIShopping] V34.CORE187 parallel secondary Ceneo direct-only result:",
          options.directOnlyLabel ?? candidate.name,
          "cards=",
          expansion.foundMerchantCards,
          "eligible=",
          expansion.results.length
        );
      }

      expansionByUrl.set(normalizeUrl(candidate.url), expansion);

      console.log(
        "[AIShopping] V34.CORE120 Ceneo merchant expansion:",
        candidate.name,
        "cards=",
        expansion.foundMerchantCards,
        "eligible=",
        expansion.results.length
      );
  };

  let core172ReservedSecondaryCeneoUrl: string | null = null;

  // V34.CORE187 PARALLEL DIRECT-ONLY SECOND CENEO CARD.
  // CORE186 scheduled the second direct card only after the primary Ceneo
  // reader had completed. Live tests showed that a slow/timeout reader could
  // consume nearly the entire verifier window before that code was reached.
  // Start the secondary direct-only page at the same time as the primary
  // expansion. It gets no reader retry and therefore cannot create another
  // slow recovery chain.
  const core187ParallelSecondaryCandidate =
    preciseTechIntent &&
    preciseTechRetailerHosts.size >= 3 &&
    ceneoCandidatePool.length > 1
      ? ceneoCandidatePool.find((candidate) =>
          !ceneoCandidates.some(
            (primary) => normalizeUrl(primary.url) === normalizeUrl(candidate.url)
          )
        ) ?? null
      : null;

  if (core187ParallelSecondaryCandidate) {
    core172ReservedSecondaryCeneoUrl = normalizeUrl(
      core187ParallelSecondaryCandidate.url
    );
    console.log(
      "[AIShopping] V34.CORE187 parallel secondary Ceneo direct-only attempt:",
      {
        retailerHosts: preciseTechRetailerHosts.size,
        secondary: core187ParallelSecondaryCandidate.name,
        timeoutMs: 1_000,
      }
    );
  }

  await Promise.all([
    ...ceneoCandidates.map((candidate) => expandCeneoCandidate(candidate)),
    ...(core187ParallelSecondaryCandidate
      ? [
          expandCeneoCandidate(core187ParallelSecondaryCandidate, {
            allowReader: false,
            directTimeoutCapMs: 1_000,
            directOnlyLabel: core187ParallelSecondaryCandidate.name,
          }),
        ]
      : []),
  ]);

  // V34.CORE172 ADAPTIVE SECOND CENEO PRODUCT CARD.
  // Precise-tech normally keeps the proven single-card behavior. When live
  // transport leaves fewer than three independent first-party retailer hosts
  // and the strongest Ceneo product card itself exposes fewer than three
  // concrete merchant stores, spend one bounded attempt on the next concrete
  // Ceneo product card. This is variant-agnostic and still uses the unchanged
  // row-local identity/HARD/price verifier for every merchant.
  if (
    preciseTechIntent &&
    preciseTechRetailerHosts.size < 3 &&
    ceneoCandidatePool.length > 1
  ) {
    const primaryCandidate = ceneoCandidates[0];
    const primaryExpansion = primaryCandidate
      ? expansionByUrl.get(normalizeUrl(primaryCandidate.url))
      : undefined;
    const primaryMerchantStores = new Set(
      (primaryExpansion?.results ?? [])
        .map((result) =>
          normalizeText(result.ceneoMerchantOffer?.shopName ?? getResultHostname(result.url))
            .toLowerCase()
        )
        .filter(Boolean)
    );
    const secondaryCandidate = ceneoCandidatePool.find((candidate) =>
      !ceneoCandidates.some(
        (primary) => normalizeUrl(primary.url) === normalizeUrl(candidate.url)
      )
    );
    const secondaryRemaining =
      hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
    core172ReservedSecondaryCeneoUrl = secondaryCandidate
      ? normalizeUrl(secondaryCandidate.url)
      : null;

    if (
      secondaryCandidate &&
      primaryMerchantStores.size < 3 &&
      secondaryRemaining >= 1_800
    ) {
      console.log(
        "[AIShopping] V34.CORE172 adaptive secondary Ceneo card:",
        {
          retailerHosts: preciseTechRetailerHosts.size,
          primaryMerchantStores: primaryMerchantStores.size,
          secondary: secondaryCandidate.name,
          remainingMs: secondaryRemaining,
        }
      );
      await expandCeneoCandidate(secondaryCandidate);
    } else {
      console.log(
        "[AIShopping] V34.CORE172 secondary Ceneo card skipped:",
        {
          retailerHosts: preciseTechRetailerHosts.size,
          primaryMerchantStores: primaryMerchantStores.size,
          hasSecondary: Boolean(secondaryCandidate),
          remainingMs: secondaryRemaining,
        }
      );
    }
  }

  const out: SearchResult[] = [];
  for (const result of results) {
    const normalizedResultUrl = normalizeUrl(result.url);
    const expansion = expansionByUrl.get(normalizedResultUrl);

    // The second precise-tech Ceneo card is a recovery reserve, not another
    // aggregate shopping result. If it was unnecessary or failed to expose
    // concrete merchant rows, drop only this extra reserved card and preserve
    // the historical primary Ceneo fallback behavior unchanged.
    if (
      core172ReservedSecondaryCeneoUrl &&
      normalizedResultUrl === core172ReservedSecondaryCeneoUrl &&
      (!expansion || !expansion.foundMerchantCards)
    ) {
      continue;
    }

    if (!expansion) {
      out.push(result);
      continue;
    }

    if (expansion.foundMerchantCards) {
      // Once the concrete product page exposes merchant rows, do not also show
      // the aggregate Ceneo product page as if it were a shop. Zero eligible
      // rows means all concrete merchants failed requirements/budget.
      out.push(...expansion.results);
      continue;
    }

    out.push(result);
  }

  return compactV34Core186CeneoMerchantDiversity(out);
}


function doesIndependentMpnProofBindRequestedModel(
  proofScopeRaw: string,
  codeRaw: string,
  parsed: ParsedQuery,
  modelCoreRaw: string
): boolean {
  const proofScope = normalizeMatchText(proofScopeRaw);
  const proofCompact = proofScope.replace(/[^a-z0-9]+/g, "");
  const normalizedCodeText = normalizeMatchText(codeRaw);
  const normalizedCode = normalizedCodeText.replace(/[^a-z0-9]+/g, "");
  if (!proofScope || !normalizedCode || !proofCompact.includes(normalizedCode)) {
    return false;
  }

  const normalizedBrand = normalizeMatchText(parsed.brand ?? "");
  const normalizedCategory = normalizeMatchText(parsed.category ?? "");
  const modelTokens = normalizeMatchText(modelCoreRaw)
    .split(/\s+/)
    .filter(Boolean)
    .filter((token) => token !== normalizedBrand)
    .filter((token) => token !== normalizedCategory)
    .filter(
      (token) =>
        ![
          "laptop",
          "notebook",
          "telefon",
          "smartfon",
          "sluchawki",
          "pad",
          "kontroler",
        ].includes(token)
    );
  const numericModelTokens = modelTokens.filter((token) => /\d/.test(token));
  const lexicalModelTokens = modelTokens.filter(
    (token) => !/\d/.test(token) && token.length >= 3
  );

  const scopeBinds = (scope: string): boolean => {
    const compact = scope.replace(/[^a-z0-9]+/g, "");
    if (!compact.includes(normalizedCode)) return false;

    const brandProven =
      !normalizedBrand ||
      scope.includes(normalizedBrand) ||
      compact.includes(normalizedBrand.replace(/[^a-z0-9]+/g, ""));
    if (!brandProven) return false;

    const numericModelProven =
      numericModelTokens.length === 0 ||
      numericModelTokens.some((token) => scope.includes(token));
    const lexicalModelProven =
      lexicalModelTokens.length === 0 ||
      lexicalModelTokens.some((token) => scope.includes(token));

    return numericModelProven && lexicalModelProven;
  };

  // Short search-result snippets are already one compact evidence unit. For
  // hydrated pages, require the model identity to appear locally around the
  // manufacturer code so a recommendation/footer cannot prove another card.
  if (proofScope.length <= 3_500) {
    return scopeBinds(proofScope);
  }

  const windows: string[] = [];
  let cursor = 0;
  while (cursor < proofScope.length) {
    const index = proofScope.indexOf(normalizedCodeText, cursor);
    if (index < 0) break;
    windows.push(
      proofScope.slice(
        Math.max(0, index - 2_200),
        Math.min(proofScope.length, index + normalizedCodeText.length + 2_200)
      )
    );
    cursor = index + Math.max(1, normalizedCodeText.length);
    if (windows.length >= 8) break;
  }

  if (windows.length === 0) {
    // Rare formatting can split a code with punctuation. In that case keep the
    // full compact-presence guard above but do not trust a long unrelated page.
    return false;
  }

  return windows.some(scopeBinds);
}



function getIndependentMpnProofHydrationScore(
  proof: SearchResult,
  codeRaw: string,
  parsed: ParsedQuery,
  modelCoreRaw: string
): number {
  const scope = normalizeMatchText(`${proof.name} ${proof.snippet} ${proof.url}`);
  if (!scope) return -1;

  const compact = scope.replace(/[^a-z0-9]+/g, "");
  const code = normalizeMatchText(codeRaw).replace(/[^a-z0-9]+/g, "");
  const brand = normalizeMatchText(parsed.brand ?? "");
  const category = normalizeMatchText(parsed.category ?? "");
  const modelTokens = normalizeMatchText(modelCoreRaw)
    .split(/\s+/)
    .filter(Boolean)
    .filter((token) => token !== brand)
    .filter((token) => token !== category)
    .filter(
      (token) =>
        ![
          "laptop",
          "notebook",
          "telefon",
          "smartfon",
          "sluchawki",
          "pad",
          "kontroler",
        ].includes(token)
    );
  const numericTokens = modelTokens.filter((token) => /\d/.test(token));
  const lexicalTokens = modelTokens.filter(
    (token) => !/\d/.test(token) && token.length >= 3
  );

  const codePresent = Boolean(code) && compact.includes(code);
  const brandPresent =
    !brand ||
    scope.includes(brand) ||
    compact.includes(brand.replace(/[^a-z0-9]+/g, ""));
  const numericPresent =
    numericTokens.length === 0 || numericTokens.some((token) => scope.includes(token));
  const lexicalPresent =
    lexicalTokens.length === 0 || lexicalTokens.some((token) => scope.includes(token));

  if (!codePresent && !(brandPresent && numericPresent && lexicalPresent)) {
    return -1;
  }

  let score = 0;
  if (codePresent) score += 12;
  if (brandPresent) score += 4;
  if (numericPresent) score += 6;
  if (lexicalPresent) score += 5;
  if (/\/p\/|\/product\/|produkt|product|laptop|notebook/i.test(proof.url)) {
    score += 2;
  }
  return score;
}

function htmlToIndependentMpnEvidenceText(htmlRaw: string): string {
  if (!htmlRaw) return "";
  return decodeHtml(
    htmlRaw
      .replace(/<!--[\s\S]*?-->/g, " ")
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, " ")
      .replace(/<[^>]+>/g, " ")
  );
}

function isConcreteIndependentProductReferenceUrl(
  urlRaw: string,
  parsed: ParsedQuery
): boolean {
  try {
    const url = new URL(urlRaw);
    const host = url.hostname.replace(/^www\./i, "").toLowerCase();
    const path = url.pathname.toLowerCase();
    const parts = path.split("/").filter(Boolean);
    const last = parts[parts.length - 1] ?? "";

    if (host === "ceneo.pl") return /^\/\d{4,}(?:\/|$)/i.test(path);
    if (host === "allegro.pl") return /\/(?:oferta|produkt)\/[a-z0-9][a-z0-9-]{4,}/i.test(path);
    if (host === "allegrolokalnie.pl") return /^\/oferta\/[a-z0-9][a-z0-9-]{4,}/i.test(path);
    if (host === "x-kom.pl") return /^\/p\/\d{4,}[-/]/i.test(path);

    const bannedGeneric = /\/(?:search|szukaj|category|kategoria|categories|kategorie|oferty|offers|listing|listings|kleinanzeigen|shop|sklep)\/?$/i;
    if (bannedGeneric.test(path)) return false;
    if (parts.length < 2 || last.length < 8) return false;

    const marker = /\/(?:product|produkt|products|produkty|item|oferta|offer|p)\//i.test(path);
    if (marker) return true;

    const slugEvidence = normalizeMatchText(decodeURIComponent(last));
    const requestedTokens = [
      ...parsed.intent.strongIdentityTerms,
      normalizeMatchText(parsed.brand ?? ""),
    ].filter((term) => term.length >= 3);
    const requestedHit = requestedTokens.some((term) =>
      universalEvidenceHasBoundedIdentityTerm(term, slugEvidence) ||
      titleContainsUniversalModelCode(slugEvidence, term)
    );

    return requestedHit && (/\d/.test(last) || (last.match(/-/g)?.length ?? 0) >= 3);
  } catch {
    return false;
  }
}

function getIndependentMpnHydrationSafetyScore(
  proof: SearchResult,
  originalHost: string,
  code: string,
  parsed: ParsedQuery,
  modelCore: string
): number {
  const host = getResultHostname(proof.url);
  if (!host || host === originalHost || isBlockedOpenWebHost(host)) return -1;

  // Never spend the identity-proof budget on category/editorial/homepage noise.
  // This gate is intentionally independent of the product itself: a search
  // engine returning a newspaper or generic landing for an exact MPN query is
  // not a reason to hydrate that page.
  if (isLikelyOpenWorldCategoryOrCollectionResult(proof, parsed)) return -1;

  let url: URL;
  try {
    url = new URL(proof.url);
  } catch {
    return -1;
  }

  const configuredCommerce = isConfiguredCommerceDomain(proof.url);
  const productLike = isConcreteIndependentProductReferenceUrl(proof.url, parsed);
  const staticReferenceLike = isProbablyExactModelStaticReferenceUrl(proof.url);

  const scope = normalizeMatchText(`${proof.name} ${proof.snippet} ${proof.url}`);
  const compact = scope.replace(/[^a-z0-9]+/g, '');
  const normalizedCode = normalizeMatchText(code).replace(/[^a-z0-9]+/g, '');
  const brand = normalizeMatchText(parsed.brand ?? '');
  const category = normalizeMatchText(parsed.category ?? '');
  const modelTokens = normalizeMatchText(modelCore)
    .split(/\s+/)
    .filter(Boolean)
    .filter((token) => token !== brand)
    .filter((token) => token !== category)
    .filter((token) => !['laptop','notebook','telefon','smartfon','sluchawki','pad','kontroler'].includes(token));
  const numericTokens = modelTokens.filter((token) => /\d/.test(token));
  const lexicalTokens = modelTokens.filter((token) => !/\d/.test(token) && token.length >= 3);

  const codePresent = Boolean(normalizedCode) && compact.includes(normalizedCode);
  const brandPresent = !brand || scope.includes(brand);
  const brandCompact = compactUniversalModelCode(brand);
  const hostCompact = compactUniversalModelCode(host);
  const officialBrandHost =
    Boolean(brandCompact) &&
    brandCompact.length >= 3 &&
    hostCompact.includes(brandCompact);
  const numericPresent = numericTokens.length === 0 || numericTokens.some((token) => scope.includes(token));
  const lexicalPresent = lexicalTokens.length === 0 || lexicalTokens.some((token) => scope.includes(token));

  const strictSnippetScore = getIndependentMpnProofHydrationScore(
    proof,
    code,
    parsed,
    modelCore
  );
  if (strictSnippetScore >= 0) return 100 + strictSnippetScore;

  // Sparse-snippet fallback is allowed only for a concrete commerce/product
  // reference. Unknown editorial/news pages need at least real MPN/model text
  // before hydration; configured commerce product pages may be read because
  // the exact query itself can have had its useful snippet truncated.
  if (configuredCommerce && productLike) {
    let score = 50;
    if (codePresent) score += 12;
    if (brandPresent) score += 4;
    if (numericPresent) score += 7;
    if (lexicalPresent) score += 6;
    return score;
  }

  if (productLike && codePresent && (numericPresent || lexicalPresent)) {
    return 35 + (brandPresent ? 4 : 0) + (numericPresent ? 5 : 0) + (lexicalPresent ? 4 : 0);
  }

  // V34.CORE120: exact-MPN searches can return the right independent product
  // page while omitting the queried MPN from the visible search snippet. We may
  // spend hydration budget on that sparse result ONLY when it is already a
  // concrete product URL and independently matches the requested brand + both
  // lexical and numeric model identity. The hydrated page is still required to
  // bind the exact MPN itself through doesIndependentMpnProofBindRequestedModel().
  // This broadens proof retrieval, never proof acceptance.
  if (
    productLike &&
    brandPresent &&
    numericPresent &&
    lexicalPresent
  ) {
    return 30 + (configuredCommerce ? 6 : 0) + (officialBrandHost ? 4 : 0);
  }

  // Static model proof may legitimately come from an official manufacturer
  // support/manual/specification document rather than a checkout URL. This
  // branch is proof-only: exact code + requested brand must already be bound
  // in the search result, and the hydrated page is still checked again before
  // any requirement is accepted.
  if (
    staticReferenceLike &&
    officialBrandHost &&
    codePresent &&
    brandPresent
  ) {
    return 62 + (numericPresent ? 6 : 0) + (lexicalPresent ? 5 : 0);
  }

  return -1;
}

function selectIndependentMpnHydrationCandidates(
  proofResults: SearchResult[],
  originalHost: string,
  code: string,
  parsed: ParsedQuery,
  modelCore: string,
  limit = 2
): {
  candidates: Array<{ proof: SearchResult; host: string; score: number; rank: number }>;
  preferredCount: number;
  fallbackCount: number;
} {
  const scoredIndependent = proofResults
    .map((proof, rank) => ({
      proof,
      host: getResultHostname(proof.url),
      strictScore: getIndependentMpnProofHydrationScore(proof, code, parsed, modelCore),
      score: getIndependentMpnHydrationSafetyScore(
        proof,
        originalHost,
        code,
        parsed,
        modelCore
      ),
      rank,
    }))
    .filter(
      (row): row is { proof: SearchResult; host: string; strictScore: number; score: number; rank: number } =>
        Boolean(row.host) && row.host !== originalHost && row.score >= 0
    );

  const pickHostDiverse = (
    rows: Array<{ proof: SearchResult; host: string; strictScore: number; score: number; rank: number }>,
    maxItems: number
  ) => {
    const seenHosts = new Set<string>();
    const out: Array<{ proof: SearchResult; host: string; score: number; rank: number }> = [];
    for (const row of rows) {
      if (seenHosts.has(row.host)) continue;
      seenHosts.add(row.host);
      out.push({ proof: row.proof, host: row.host, score: row.score, rank: row.rank });
      if (out.length >= maxItems) break;
    }
    return out;
  };

  const preferredRows = [...scoredIndependent]
    .filter(({ strictScore }) => strictScore >= 0)
    .sort((a, b) => b.score - a.score || a.rank - b.rank);
  const fallbackRows = [...scoredIndependent]
    .filter(({ strictScore }) => strictScore < 0)
    .sort((a, b) => b.score - a.score || a.rank - b.rank);

  const preferred = pickHostDiverse(preferredRows, limit);
  const fallback = preferred.length > 0 ? [] : pickHostDiverse(fallbackRows, limit);

  return {
    candidates: preferred.length > 0 ? preferred : fallback,
    preferredCount: preferred.length,
    fallbackCount: fallback.length,
  };
}


async function hydrateIndependentMpnProofCandidates(
  proofResults: SearchResult[],
  originalHost: string,
  code: string,
  parsed: ParsedQuery,
  modelCore: string,
  externalSignal?: AbortSignal
): Promise<{ proof: SearchResult; scope: string; transport: "direct" | "reader" }[]> {
  const selection = selectIndependentMpnHydrationCandidates(
    proofResults,
    originalHost,
    code,
    parsed,
    modelCore,
    2
  );
  const { candidates, preferredCount, fallbackCount } = selection;

  console.log(
    "[AIShopping] V34.CORE120 retailer MPN proof hydration shortlist:",
    code,
    "preferred=",
    preferredCount,
    "fallback=",
    fallbackCount,
    "candidates=",
    candidates.map(({ host, score, proof }) => ({ host, score, url: proof.url }))
  );

  if (candidates.length === 0) return [];

  const directHydrated = await withAbortableDeadline(
    async (deadlineSignal) => {
      const signal = externalSignal
        ? AbortSignal.any([externalSignal, deadlineSignal])
        : deadlineSignal;
      return await Promise.all(
        candidates.map(async ({ proof }) => {
          const page = await fetchHtml(proof.url, 1_050, signal);
          if (!page || page.status < 200 || page.status >= 400 || !page.html) {
            return null;
          }
          return {
            proof,
            scope: `${extractTitleFromHtml(page.html)} ${htmlToIndependentMpnEvidenceText(page.html)}`,
            transport: "direct" as const,
          };
        })
      );
    },
    1_300,
    [] as Array<{
      proof: SearchResult;
      scope: string;
      transport: "direct";
    } | null>,
    `retailer MPN proof direct hydration ${code}`
  );

  const directMatches = directHydrated.filter(
    (item): item is { proof: SearchResult; scope: string; transport: "direct" } =>
      Boolean(item?.scope)
  );
  if (
    directMatches.some((item) =>
      doesIndependentMpnProofBindRequestedModel(
        item.scope,
        code,
        parsed,
        modelCore
      )
    )
  ) {
    return directMatches;
  }

  const readerCandidates = candidates.slice(0, 2);
  const readerHydrated = await withAbortableDeadline(
    async (deadlineSignal) => {
      const signal = externalSignal
        ? AbortSignal.any([externalSignal, deadlineSignal])
        : deadlineSignal;
      return await Promise.all(
        readerCandidates.map(async ({ proof }) => {
          const text = await fetchViaJina(proof.url, 1_650, false, signal);
          if (!text) return null;
          return {
            proof,
            scope: text,
            transport: "reader" as const,
          };
        })
      );
    },
    1_950,
    [] as Array<{
      proof: SearchResult;
      scope: string;
      transport: "reader";
    } | null>,
    `retailer MPN proof reader hydration ${code}`
  );

  return [
    ...directMatches,
    ...readerHydrated.filter(
      (item): item is { proof: SearchResult; scope: string; transport: "reader" } =>
        Boolean(item?.scope)
    ),
  ];
}


async function findDirectCeneoMpnIdentityReference(
  originalHost: string,
  code: string,
  parsed: ParsedQuery,
  modelCore: string,
  externalSignal?: AbortSignal
): Promise<{ scope: string; url: string } | null> {
  if (!code || originalHost === "ceneo.pl") return null;

  const searchUrls = Array.from(new Set([
    `https://www.ceneo.pl/;szukaj-${encodeURIComponent(code)}`,
    `https://www.ceneo.pl/oferty/${encodeURIComponent(code)}`,
  ]));

  return await withAbortableDeadline(
    async (deadlineSignal) => {
      const signal = externalSignal
        ? AbortSignal.any([externalSignal, deadlineSignal])
        : deadlineSignal;

      const [pages, readerText] = await Promise.all([
        Promise.all(
          searchUrls.map((searchUrl) =>
            fetchHtml(searchUrl, 1_150, signal).catch(() => null)
          )
        ),
        fetchViaJina(searchUrls[0], 1_750, false, signal).catch(() => ""),
      ]);

      for (let index = 0; index < pages.length; index += 1) {
        const page = pages[index];
        const searchUrl = searchUrls[index];
        if (!page || page.status < 200 || page.status >= 400 || !page.html) continue;

        const cards = parseDirectMarketplaceHtml(
          page.html,
          page.finalUrl || searchUrl,
          "CeneoDirect"
        );

        for (const card of cards) {
          const scope = `${card.name} ${card.snippet} ${card.url}`;
          if (doesIndependentMpnProofBindRequestedModel(scope, code, parsed, modelCore)) {
            return { scope, url: card.url };
          }
        }

        const pageScope = htmlToIndependentMpnEvidenceText(page.html);
        if (doesIndependentMpnProofBindRequestedModel(pageScope, code, parsed, modelCore)) {
          return { scope: pageScope, url: page.finalUrl || searchUrl };
        }
      }

      if (
        readerText &&
        doesIndependentMpnProofBindRequestedModel(
          readerText,
          code,
          parsed,
          modelCore
        )
      ) {
        console.log(
          "[AIShopping] V34.CORE120 direct comparison MPN reader proof:",
          code,
          "=>",
          modelCore
        );
        return { scope: readerText, url: searchUrls[0] };
      }

      return null;
    },
    2_150,
    null as { scope: string; url: string } | null,
    `direct Ceneo MPN identity reference ${code}`
  );
}

async function resolveDeferredRetailerModelIdentityBridge(
  result: SearchResult,
  parsed: ParsedQuery,
  externalSignal?: AbortSignal
): Promise<string> {
  const code = result.deferredModelIdentityBridgeCode ?? "";
  if (!code) return "";

  const modelCore = normalizeText(
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed)
  );
  if (!modelCore) return "";

  const normalizedCode = normalizeMatchText(code).replace(/[^a-z0-9]+/g, "");
  const normalizedBrand = normalizeMatchText(parsed.brand ?? "");
  const normalizedCategory = normalizeMatchText(parsed.category ?? "");
  const modelTokens = normalizeMatchText(modelCore)
    .split(/\s+/)
    .filter(Boolean)
    .filter((token) => token !== normalizedBrand)
    .filter((token) => token !== normalizedCategory)
    .filter((token) => !["laptop", "notebook", "telefon", "smartfon", "sluchawki", "pad", "kontroler"].includes(token));
  const numericModelTokens = modelTokens.filter((token) => /\d/.test(token));
  const lexicalModelTokens = modelTokens.filter((token) => !/\d/.test(token) && token.length >= 3);
  const strongestNumericModelToken = [...numericModelTokens].sort((a, b) => b.length - a.length)[0] ?? "";
  const strongestLexicalModelToken = [...lexicalModelTokens].sort((a, b) => b.length - a.length)[0] ?? "";

  const comparisonBridgeQuery = strongestNumericModelToken
    ? `site:${V32_DISCOVERY_ONLY_COMPARISON_DOMAINS[0]} "${code}" "${strongestNumericModelToken}" ${strongestLexicalModelToken ? `"${strongestLexicalModelToken}"` : ""}`.trim()
    : `site:${V32_DISCOVERY_ONLY_COMPARISON_DOMAINS[0]} "${code}" "${modelCore}"`;

  const queryVariants = Array.from(new Set([
    `"${code}" "${modelCore}"`,
    strongestNumericModelToken
      ? `"${code}" "${strongestNumericModelToken}" ${normalizeText(parsed.brand ?? "")}`.trim()
      : "",
    strongestLexicalModelToken && strongestNumericModelToken
      ? `"${code}" "${strongestLexicalModelToken}" "${strongestNumericModelToken}"`
      : "",
    comparisonBridgeQuery,
  ].filter(Boolean))).slice(0, 4);

  const originalHost = getResultHostname(result.url);
  const startedAt = Date.now();

  const [indexedProofResults, ceneoReference, googleProofResults] = await Promise.all([
    withAbortableDeadline(
      async (deadlineSignal) => {
        const signal = externalSignal
          ? AbortSignal.any([externalSignal, deadlineSignal])
          : deadlineSignal;
        const chunks = await Promise.all(
          queryVariants.flatMap((query, queryIndex) => {
            const isComparisonSiteQuery = /^site:/i.test(query);
            return [
              isComparisonSiteQuery
                ? Promise.resolve([] as SearchResult[])
                : searchBing(query, signal).catch(() => []),
              searchBingRss(query, signal).catch(() => []),
              queryIndex === 0
                ? searchDuckDuckGo(query, signal).catch(() => [])
                : Promise.resolve([] as SearchResult[]),
            ];
          })
        );
        return dedupeSearchResultsByUrl(chunks.flat());
      },
      2_050,
      [],
      `retailer MPN model bridge ${code}`
    ),
    findDirectCeneoMpnIdentityReference(
      originalHost,
      code,
      parsed,
      modelCore,
      externalSignal
    ),
    withAbortableDeadline(
      async (deadlineSignal) => {
        const signal = externalSignal
          ? AbortSignal.any([externalSignal, deadlineSignal])
          : deadlineSignal;
        return await searchGoogleViaJina(queryVariants[0], signal).catch(() => []);
      },
      2_050,
      [],
      `retailer MPN Google bridge ${code}`
    ),
  ]);

  const proofResults = dedupeSearchResultsByUrl([
    ...indexedProofResults,
    ...googleProofResults,
  ]);

  if (ceneoReference) {
    console.log(
      "[AIShopping] V34.CORE120 retailer MPN model bridge:",
      code,
      "=>",
      modelCore,
      "proofHost=",
      "ceneo.pl",
      "proof=direct-reference-mesh",
      "elapsedMs=",
      Date.now() - startedAt
    );
    return normalizeText(`${modelCore} ${code}`);
  }

  for (const proof of proofResults) {
    const proofHost = getResultHostname(proof.url);
    if (!proofHost || proofHost === originalHost) continue;

    const proofScope = `${proof.name} ${proof.snippet} ${proof.url}`;
    if (
      !doesIndependentMpnProofBindRequestedModel(
        proofScope,
        code,
        parsed,
        modelCore
      )
    ) {
      continue;
    }

    console.log(
      "[AIShopping] V34.CORE120 retailer MPN model bridge:",
      code,
      "=>",
      modelCore,
      "proofHost=",
      proofHost,
      "proof=search-cooccurrence",
      "elapsedMs=",
      Date.now() - startedAt
    );
    return normalizeText(`${modelCore} ${code}`);
  }

  // V34.CORE120: search indexes often know the correct independent product page but
  // expose a truncated snippet that drops either the exact model token or MPN.
  // Hydrate only a tiny, host-diverse shortlist and require the FULL independent
  // page to pass the exact same strict code/brand/family/model predicate.
  const hydratedProofs = await hydrateIndependentMpnProofCandidates(
    proofResults,
    originalHost,
    code,
    parsed,
    modelCore,
    externalSignal
  );

  for (const hydrated of hydratedProofs) {
    if (
      !doesIndependentMpnProofBindRequestedModel(
        hydrated.scope,
        code,
        parsed,
        modelCore
      )
    ) {
      continue;
    }

    const proofHost = getResultHostname(hydrated.proof.url);
    console.log(
      "[AIShopping] V34.CORE120 retailer MPN model bridge:",
      code,
      "=>",
      modelCore,
      "proofHost=",
      proofHost,
      "proof=hydrated-independent-page",
      "transport=",
      hydrated.transport,
      "elapsedMs=",
      Date.now() - startedAt
    );
    return normalizeText(`${modelCore} ${code}`);
  }

  console.log(
    "[AIShopping] V34.CORE120 retailer MPN model bridge unresolved:",
    code,
    modelCore,
    "queries=",
    queryVariants,
    "results=",
    proofResults.length,
    "elapsedMs=",
    Date.now() - startedAt
  );
  return "";
}

async function verifySearchResult(
  result: SearchResult,
  parsed: ParsedQuery,
  verificationSignal?: AbortSignal,
  sharedExactModelStaticProofPromise?: Promise<string> | null
): Promise<Offer | null> {
  // Verification telemetry is request-local and must never survive a fresh
  // attempt (including the controlled CORE60 second chance).
  result.transientMarketplaceReaderTimeout = false;
  if (verificationSignal?.aborted) return null;

  if (result.ceneoMerchantOffer) {
    return verifyTrustedCeneoMerchantResult(result, parsed, verificationSignal);
  }

  const genericSearchPrice = extractSearchResultPrice(result, parsed.condition);
  const marketplaceIndexCard = result.source === "MarketplaceIndexRescue";
  const marketplaceIndexBoundPrice = marketplaceIndexCard
    ? extractPriceNearProductName(`${result.name} ${result.snippet}`, result.name, parsed.condition)
    : { price: null, currency: null };
  const marketplaceIndexCondition: Condition = marketplaceIndexCard
    ? hasExplicitRequestedConditionInTitle(result.name, "new")
      ? "new"
      : hasExplicitRequestedConditionInTitle(result.name, "used")
        ? "used"
        : extractTrustedConditionFromText(
            extractMarketplaceCardContext(`${result.name} ${result.snippet}`, result.name, 2200) ||
            `${result.name} ${result.snippet}`
          )
    : null;
  const initialHost = getResultHostname(result.url);
  const isCeneoResult = initialHost === "ceneo.pl";
  const isOlxResult = initialHost === "olx.pl";
  const isAllegroLokalnieResult =
    initialHost === "allegrolokalnie.pl";
  const isVintedResult =
    initialHost === "vinted.pl" || initialHost.endsWith(".vinted.pl");
  const vintedCatalogCondition: Condition = isVintedResult
    ? getTrustedVintedCatalogCondition(result)
    : null;
  const vintedCatalogSize = isVintedResult
    ? getTrustedVintedCatalogSize(result)
    : null;
  const requestedHardWearSize = getRequestedHardWearSize(parsed);
  if (
    requestedHardWearSize &&
    hasTrustedVintedCatalogSizeConflict(result, parsed)
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject trusted Vinted catalog size mismatch before page verification:",
      result.url,
      "requested=",
      requestedHardWearSize,
      "card=",
      vintedCatalogSize,
      "title=",
      getExplicitVintedTitleShoeSize(result)
    );
    return null;
  }

  const isAllegroResult =
    initialHost === "allegro.pl" ||
    isAllegroLokalnieResult;

  const trustedRetailerPerfumeCard =
    getTrustedRetailerPerfumeCardEvidence(result, parsed);

  const ceneoBoundPrice = isCeneoResult
    ? extractPriceNearProductName(
        `${result.name} ${result.snippet}`,
        result.name
      )
    : { price: null, currency: null };

  const allegroLokalnieBoundPrice =
    isAllegroLokalnieResult
      ? extractAllegroLokalnieBoundPrice(
          `${result.name} ${result.snippet}`,
          result.name
        )
      : { price: null, currency: null };

  const olxBoundPrice =
    isOlxResult && result.source === "OLXDirect"
      ? extractOlxDirectBoundPrice(
          `${result.name} ${result.snippet}`,
          result.name,
          result.url
        )
      : { price: null, currency: null };

  const olxBoundCondition =
    isOlxResult && result.source === "OLXDirect"
      ? extractOlxDirectBoundCondition(
          result.snippet,
          result.name
        )
      : null;

  const tirePerPieceSearchPrice =
    parsed.category === "tire"
      ? extractTirePerPiecePrice(`${result.name} ${result.snippet}`)
      : { price: null, currency: null };

  const allegroLokalnieTitleCondition: Condition =
    isAllegroLokalnieResult
      ? hasExplicitRequestedConditionInTitle(result.name, "new")
        ? "new"
        : hasExplicitRequestedConditionInTitle(result.name, "used")
          ? "used"
          : null
      : null;

  // V32.12: direct Allegro Lokalnie cards are already bounded to one concrete
  // /oferta/ URL before reaching verification. Preserve an explicit condition
  // label from that SAME card, but trust it only later when the card also has
  // a title-bound price. This avoids a reader round-trip without weakening the
  // marketplace condition gate.
  const allegroLokalnieCardCondition: Condition =
    isAllegroLokalnieResult
      ? extractTrustedConditionFromText(
          extractMarketplaceCardContext(
            `${result.name} ${result.snippet}`,
            result.name,
            1900
          ) || `${result.name} ${result.snippet}`
        )
      : null;

  // Ceneo category/search pages contain many neighbouring products. A price
  // appearing after a product name can belong to the next card, so discovery
  // price is diagnostic only. Ceneo price must be verified on the concrete
  // /<productId> page.
  const searchPrice =
    isCeneoResult
      ? { price: null, currency: null }
      : trustedRetailerPerfumeCard
        ? {
            price: trustedRetailerPerfumeCard.price,
            currency: trustedRetailerPerfumeCard.currency,
          }
      : (
          marketplaceIndexCard &&
          marketplaceIndexBoundPrice.price !== null &&
          marketplaceIndexBoundPrice.currency
        )
        ? marketplaceIndexBoundPrice
      : (
          isOlxResult && result.source === "OLXDirect"
        )
        ? olxBoundPrice
        : (
            isAllegroLokalnieResult &&
            allegroLokalnieBoundPrice.price !== null &&
            allegroLokalnieBoundPrice.currency
          )
          ? allegroLokalnieBoundPrice
          : (
              parsed.category === "tire" &&
              tirePerPieceSearchPrice.price !== null &&
              tirePerPieceSearchPrice.currency
            )
            ? tirePerPieceSearchPrice
            : genericSearchPrice;

  console.log(
    "[AIShopping] V34.CORE120 search price:",
    result.source,
    result.name,
    searchPrice,
    isCeneoResult
      ? `(Ceneo discovery price ignored; tentative=${ceneoBoundPrice.price ?? "null"})`
      : trustedRetailerPerfumeCard
        ? "(trusted retailer-owned exact perfume variant card)"
      : isOlxResult && result.source === "OLXDirect"
        ? "(OLX price restricted to current search card)"
        : isAllegroLokalnieResult
          ? "(Allegro Lokalnie price bound to result title)"
          : ""
  );

  if (
    result.source === "RetailerRescue" &&
    result.retailerOwnedCardEvidence === true &&
    result.retailerCatalogCardAvailability === "unavailable"
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject unavailable bounded retailer catalog card:",
      result.url,
      result.name
    );
    return null;
  }

  // V32.12 SOURCE-TRUST GATE: OLX search markdown can splice the state label
  // from a neighbouring result into an otherwise matching card. A condition
  // mismatch is strong enough for an early rejection only when the SAME
  // identity-bound card also contains a trustworthy product price. Without
  // that second anchor we verify the concrete listing instead. This rule is
  // category-agnostic and applies to every current and future product.
  const hasTrustedOlxCardAnchor =
    olxBoundPrice.price !== null &&
    Boolean(olxBoundPrice.currency);

  const hasOlxCardConditionMismatch = Boolean(
    parsed.condition &&
    olxBoundCondition &&
    olxBoundCondition !== parsed.condition
  );

  if (
    hasOlxCardConditionMismatch &&
    hasTrustedOlxCardAnchor
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject trusted OLX card condition mismatch:",
      result.url,
      "requested=",
      parsed.condition,
      "card=",
      olxBoundCondition
    );
    return null;
  }

  if (hasOlxCardConditionMismatch) {
    console.log(
      "[AIShopping] V34.CORE120 ignored unanchored OLX card condition; verifying listing:",
      result.url,
      "requested=",
      parsed.condition,
      "card=",
      olxBoundCondition
    );
  }

  let pricePln: number | null = null;
  let tirePriceIsPerPiece = false;
  let priceVerified = false;
  let availability: "available" | "unknown" = "unknown";
  let finalName =
    isAllegroLokalnieResult
      ? cleanDirectMarketplaceResultName(
          result.name,
          result.url
        )
      : result.name;
  let description = isCeneoResult ? "" : result.snippet;
  // Discovery snippets can contain neighbouring marketplace cards. Keep them
  // for presentation/ranking, but never let them prove a hard requirement.
  let trustedVerifiedDescription = "";
  // True only when a concrete product page was actually read through a reader.
  // Card/index snippets must never impersonate a page read in evidence scoring.
  let readerPageVerified = false;
  let finalUrl = result.url;
  let universalFeatureEvidence = "";
  // V34.CORE136: keep exact/bounded requirement channels separate from the
  // broad feature-evidence bucket. Listing-specific colour may only be proven
  // from these bound channels, never from incidental page-wide text.
  let trustedCanonicalConcreteRequirementEvidence = "";
  let trustedRetailerCardHardRequirementEvidence = "";
  // V34.CORE120: product-class proof can come from the focused CURRENT concrete
  // product page even when a retailer/comparison title is only brand + model.
  // The token is added only after the page itself exposes a category alias in
  // the product-focused scope; broad discovery/category snippets never qualify.
  let trustedConcreteProductClassEvidence = "";
  let trustedBoundProductDescription = "";
  let trustedCeneoExactRequirementEvidence = "";
  let verifiedCondition: Condition =
    marketplaceIndexCondition ?? allegroLokalnieTitleCondition ?? vintedCatalogCondition;
  let verifiedRating: number | null = null;
  let verifiedShipping: ShippingInfo = {
    cost: null,
    currency: null,
    label: null,
    verified: false,
  };
  let deliveryCostPln: number | null = null;

  // For multi-variant catalog cards (for example a 4 kg card that offers
  // 4/15/18/30 kg variants), a default Product price is not enough. The exact
  // requested package must be price-bound before the offer can be trusted.
  let requestedPackageVariantResolved = false;
  let requestedPackageVariantUrlResolved = false;
  let requestedPerfumeVolumeVariantResolved = false;

  if (trustedRetailerPerfumeCard) {
    const converted = await convertToPln(
      trustedRetailerPerfumeCard.price,
      trustedRetailerPerfumeCard.currency
    );

    if (converted !== null) {
      pricePln = converted;
      priceVerified = true;
      availability = "available";
      requestedPerfumeVolumeVariantResolved = true;
      trustedVerifiedDescription = normalizeText(result.snippet).slice(0, 12_000);

      const volumeRequirement = parsed.intent.required.find(
        (requirement) => requirement.hard && requirement.key === "volume"
      );
      if (volumeRequirement) {
        universalFeatureEvidence = normalizeText(
          `${universalFeatureEvidence} ${volumeRequirement.aliases[0] || volumeRequirement.value}`
        ).slice(0, 26_000);
        finalName = rewriteVerifiedNameToRequestedVolumeVariant(
          finalName,
          result.name,
          parsed
        );
      }

      console.log(
        "[AIShopping] V34.CORE120 trusted retailer perfume card variant:",
        finalUrl,
        trustedRetailerPerfumeCard.price,
        trustedRetailerPerfumeCard.currency,
        "=>",
        converted,
        "PLN"
      );
    }
  }

  // V34.CORE120 strong-index marketplace card: keep a concrete public-index
  // price/condition bound to one concrete offer URL when the marketplace page
  // itself is blocked. It is NEVER marked priceVerified and still passes the
  // full identity, originality, hard-attribute, condition and budget gates.
  if (
    marketplaceIndexCard &&
    marketplaceIndexBoundPrice.price !== null &&
    marketplaceIndexBoundPrice.currency
  ) {
    const converted = await convertToPln(
      marketplaceIndexBoundPrice.price,
      marketplaceIndexBoundPrice.currency
    );
    if (converted !== null) {
      pricePln = converted;
      availability = "unknown";
      trustedVerifiedDescription = normalizeText(`${result.name} ${result.snippet}`).slice(0, 12_000);
      if (marketplaceIndexCondition) verifiedCondition = marketplaceIndexCondition;
      console.log(
        "[AIShopping] V34.CORE120 trusted marketplace strong-index card:",
        result.url,
        converted,
        "PLN",
        "condition=",
        marketplaceIndexCondition
      );
    }
  }

  const trustedAllegroLokalnieSource =
    result.source === "AllegroLokalnieDirect" ||
    result.source === "JinaGoogle";

  const trustedAllegroLokalnieCard =
    trustedAllegroLokalnieSource &&
    isAllegroLokalnieResult &&
    allegroLokalnieBoundPrice.price !== null &&
    Boolean(allegroLokalnieBoundPrice.currency);

  const trustedRetailerCatalogCard =
    getTrustedRetailerCatalogCardEvidence(result, parsed);

  const trustedRetailerOwnedCardPrice: PriceInfo = trustedRetailerCatalogCard
    ? {
        price: trustedRetailerCatalogCard.price,
        currency: trustedRetailerCatalogCard.currency,
      }
    : (
        result.source === "RetailerRescue" &&
        result.retailerOwnedCardEvidence === true &&
        isConfiguredCommerceDomain(result.url) &&
        hasTrustedRetailerOwnedCardCheckoutEvidence(result)
      )
      ? extractPriceNearProductName(
          `${result.name} ${result.snippet}`,
          result.name,
          parsed.condition
        )
      : { price: null, currency: null };

  if (trustedAllegroLokalnieCard && allegroLokalnieCardCondition) {
    verifiedCondition = allegroLokalnieCardCondition;

    if (
      parsed.condition &&
      allegroLokalnieCardCondition !== parsed.condition
    ) {
      console.log(
        "[AIShopping] V34.CORE120 reject trusted Allegro Lokalnie card condition mismatch:",
        result.url,
        "requested=",
        parsed.condition,
        "card=",
        allegroLokalnieCardCondition
      );
      return null;
    }

    console.log(
      "[AIShopping] V34.CORE120 trusted Allegro Lokalnie card condition:",
      result.url,
      allegroLokalnieCardCondition
    );
  }

  if (vintedCatalogCondition) {
    if (parsed.condition && vintedCatalogCondition !== parsed.condition) {
      console.log(
        "[AIShopping] V34.CORE120 reject trusted Vinted catalog condition mismatch:",
        result.url,
        "requested=",
        parsed.condition,
        "card=",
        vintedCatalogCondition
      );
      return null;
    }

    console.log(
      "[AIShopping] V34.CORE120 trusted Vinted catalog condition:",
      result.url,
      vintedCatalogCondition
    );
  }

  const trustedOlxDirectCard =
    result.source === "OLXDirect" &&
    isOlxResult &&
    hasTrustedOlxCardAnchor;

  const trustedOlxConditionProven =
    parsed.condition === null ||
    olxBoundCondition === parsed.condition;

  if (trustedOlxDirectCard) {
    verifiedCondition = olxBoundCondition;
  }

  const trustedRetailerOwnedPriceMatchesSearch = Boolean(
    trustedRetailerOwnedCardPrice.price !== null &&
    trustedRetailerOwnedCardPrice.currency &&
    searchPrice.price !== null &&
    searchPrice.currency &&
    searchPrice.price === trustedRetailerOwnedCardPrice.price &&
    searchPrice.currency === trustedRetailerOwnedCardPrice.currency
  );

  if (
    !isCeneoResult &&
    searchPrice.price !== null &&
    searchPrice.currency &&
    (
      !isAllegroLokalnieResult ||
      allegroLokalnieBoundPrice.price !== null
    )
  ) {
    pricePln = await convertToPln(
      searchPrice.price,
      searchPrice.currency
    );
    if (
      parsed.category === "tire" &&
      tirePerPieceSearchPrice.price !== null &&
      tirePerPieceSearchPrice.currency &&
      searchPrice.price === tirePerPieceSearchPrice.price &&
      searchPrice.currency === tirePerPieceSearchPrice.currency
    ) {
      tirePriceIsPerPiece = true;
    }

    if (
      (
        trustedAllegroLokalnieCard ||
        trustedOlxDirectCard ||
        (
          trustedRetailerOwnedPriceMatchesSearch &&
          (
            trustedRetailerCatalogCard === null ||
            trustedRetailerCatalogCard.availability === "available"
          )
        )
      ) &&
      pricePln !== null
    ) {
      priceVerified = true;
      availability = "available";

      console.log(
        trustedOlxDirectCard
          ? "[AIShopping] V34.CORE120 trusted OLX current-card price:"
          : trustedAllegroLokalnieCard
            ? "[AIShopping] V34.CORE120 trusted Allegro Lokalnie discovery price:"
            : "[AIShopping] V34.CORE120 trusted retailer-owned card price:",
        result.source,
        finalUrl,
        pricePln,
        "PLN"
      );
    }
  }

  const discoveryBudgetComparable =
    pricePln !== null
      ? budgetComparablePrice(
          pricePln,
          `${result.name} ${result.snippet}`,
          parsed
        )
      : null;

  if (
    pricePln !== null &&
    parsed.maxPrice !== null &&
    discoveryBudgetComparable !== null &&
    discoveryBudgetComparable.comparable > parsed.maxPrice &&
    (
      isCeneoResult ||
      trustedAllegroLokalnieCard ||
      trustedOlxDirectCard ||
      trustedRetailerOwnedPriceMatchesSearch
    )
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject over budget before fetch:",
      finalUrl,
      "listing=",
      pricePln,
      "perPiece=",
      discoveryBudgetComparable.comparable,
      "pieces=",
      discoveryBudgetComparable.pieceCount,
      "max=",
      parsed.maxPrice
    );
    return null;
  }

  if (!isProbablyRealOfferUrl(result.url)) {
    console.log("[AIShopping] reject non-product URL:", result.url);
    return null;
  }

  // ------------------------------------------------------------
  // A. Bezpośredni fetch strony produktu
  // ------------------------------------------------------------
  const hardUniversalRequirements = parsed.intent.required.filter((item) => item.hard);
  const hasUniversalHardRequirements = hardUniversalRequirements.length > 0;
  // V32.12: unconfigured dynamic rescue hosts must prove a real checkout
  // surface on their concrete page before any incidental number can become a
  // verified offer price. Configured stores/marketplaces keep their adapters.
  let dynamicRetailerCommerceEvidence = false;

  // Do not search the web for facts already present in the concrete listing
  // title/URL. This removes redundant proof calls for titles such as
  // "RTX 4060 8GB" and "monitor 1440p 165Hz".
  const initialListingIdentityEvidence = normalizeMatchText(
    `${result.name} ${result.url} ${(trustedAllegroLokalnieCard || trustedOlxDirectCard || marketplaceIndexCard) ? result.snippet : ""}`
  );

  const unresolvedHardRequirements = hardUniversalRequirements
    .filter((requirement) =>
      !requirementHasEvidence(requirement, initialListingIdentityEvidence)
    );

  const externallyProvableRequirements = unresolvedHardRequirements
    .filter(canUseExternalProofForRequirement);

  // Listing-specific requirements (bundle contents, colour, size, etc.) cannot
  // be proven from another shop/model page. A trusted Allegro Lokalnie card
  // therefore still needs its concrete product page whenever ANY hard
  // requirement is unresolved in the card itself. This is universal and makes
  // queries such as "18V z 2 bateriami" behave correctly without a tool-specific
  // exception.
  const requestedBrandMissingFromTrustedCard = Boolean(
    parsed.brand &&
    isBrandExplicitlyRequested(parsed.brand, parsed.queryText) &&
    !getUniversalRequestedBrandAliases(parsed).some((alias) =>
      universalEvidenceHasBoundedIdentityTerm(alias, initialListingIdentityEvidence)
    )
  );

  const shouldFetchTrustedAllegroLokalnie =
    trustedAllegroLokalnieCard &&
    (
      unresolvedHardRequirements.length > 0 ||
      requestedBrandMissingFromTrustedCard ||
      (
        parsed.condition !== null &&
        verifiedCondition !== parsed.condition
      )
    );

  // A card-bound OLX price is enough for a simple product search. When the
  // user requested a fact that is not already in the current card title/URL,
  // or the card did not prove requested condition/originality, fetch the
  // concrete listing through Jina so the missing fact is actually proven.
  const shouldFetchTrustedOlx =
    trustedOlxDirectCard &&
    (
      unresolvedHardRequirements.length > 0 ||
      !trustedOlxConditionProven
    );

  // V32.12: generic originality intent is intentionally NOT a page-fetch
  // trigger by itself. Re-reading a peer-marketplace listing cannot turn a
  // seller's self-claim into independent authenticity proof, while it costs a
  // scarce Jina start slot. Originality is therefore represented by the
  // existing confidence/risk model. For explicit-original perfume, peer
  // listings remain caution-only unless independent originality evidence later
  // raises them into the recommendation-quality pool.

  const universalBrandProofPromise = parsed.brand && !getUniversalRequestedBrandAliases(parsed).some((alias) => universalEvidenceHasBoundedIdentityTerm(alias, result.name))
    ? findUniversalBrandProofViaSharedModelCode(result.name, result.url, parsed, verificationSignal)
    : null;

  // Start one exact-model proof mechanism only for unresolved model-level
  // requirements. It is never a price source.
  // V34.CORE120: verification may already have one exact-model retailer page
  // selected from discovery. Read that shared proof first. When it already
  // proves every unresolved STATIC requirement, do not launch a second web
  // proof mesh at all. If it is empty/partial, fall back to the existing
  // search-based proof (which usually reuses the request-start prefetch cache).
  const universalRequirementProofPromise =
    externallyProvableRequirements.length > 0
      ? (async () => {
          const sharedProof = await (
            sharedExactModelStaticProofPromise ?? Promise.resolve("")
          );

          const sharedComplete =
            Boolean(sharedProof) &&
            externallyProvableRequirements.every((requirement) =>
              requirementHasEvidence(requirement, sharedProof)
            );

          if (sharedComplete) {
            console.log(
              "[AIShopping] V34.CORE120 universal proof satisfied by shared exact-model profile:",
              result.name,
              externallyProvableRequirements.map((item) => item.key)
            );
            return sharedProof;
          }

          const searchedProof = await findUniversalRequirementProofViaSearch(
            result.name,
            externallyProvableRequirements,
            parsed,
            result.url,
            verificationSignal
          );

          return normalizeText(`${sharedProof} ${searchedProof}`).slice(0, 36_000);
        })()
      : null;

  // V34.CORE120: if discovery already bound an MPN/SKU to this retailer-owned card,
  // start the independent exact-model proof NOW, in parallel with the concrete
  // product-page fetch/reader. The previous serial order spent 6-8 seconds on
  // a blocked/heavy retailer page and only then started identity proof.
  const earlyDeferredModelBridgeCode = result.deferredModelIdentityBridgeCode ?? "";
  const earlyModelIdentityBridgePromise =
    earlyDeferredModelBridgeCode && result.source === "RetailerRescue"
      ? resolveDeferredRetailerModelIdentityBridge(
          {
            ...result,
            deferredModelIdentityBridgeCode: earlyDeferredModelBridgeCode,
          },
          parsed,
          verificationSignal
        )
      : null;

  let correctedDeferredModelBridgeCode = "";
  let correctedModelIdentityBridgePromise: Promise<string> | null = null;

  let universalIndependentRequirementProof = "";

  // V32.12 source-adapter fast path: concrete OLX offer pages are commonly
  // blocked for the direct fetcher (403) while Jina can still read them.
  // Skipping the known-dead direct attempt saves up to ~3.2 s per offer and
  // prevents the verification queue from missing the global deadline. This is
  // source-specific, not product-specific, so every category benefits.
  const preferJinaForConcreteOlxOffer =
    initialHost === "olx.pl" &&
    (
      result.source === "OLXDirect" ||
      result.source === "Bing" ||
      result.source === "BingRSS"
    );

  // CORE25 RETAILER VERIFICATION RACE:
  // A direct retailer adapter can already have timed out while still yielding
  // a concrete product card. Starting the reader only AFTER another direct
  // product fetch can consume the entire per-offer window. For first-party
  // commerce pages from a host that was slow/failed during discovery, start one
  // bounded reader in parallel with the direct fetch. It is only consumed when
  // normal verification still needs page evidence; all price/spec/availability
  // gates below stay unchanged.
  const discoveryRetailerHealth =
    getRetailerRequestHealthBucket(parsed)?.hosts.get(initialHost);
  const retailerVerificationReaderRaceReason =
    getRetailerVerificationReaderRaceReason(
      result,
      parsed,
      initialHost,
      searchPrice,
      discoveryRetailerHealth ?? undefined
    );
  const shouldRaceRetailerVerificationReader =
    retailerVerificationReaderRaceReason !== null;
  const racedRetailerReaderPromise: Promise<string> | null =
    shouldRaceRetailerVerificationReader
      ? fetchViaJina(
          result.url,
          retailerVerificationReaderRaceReason === "variant-proof"
            ? 4_150
            : 3_650,
          false,
          verificationSignal
        )
      : null;

  if (racedRetailerReaderPromise) {
    console.log(
      "[AIShopping] V34.CORE120 retailer verification reader raced:",
      initialHost,
      "reason=",
      retailerVerificationReaderRaceReason,
      result.url
    );
  }

  const page =
    trustedAllegroLokalnieCard && !shouldFetchTrustedAllegroLokalnie
      ? null
      : preferJinaForConcreteOlxOffer
        ? null
        : await fetchHtml(
            result.url,
            hasUniversalHardRequirements
              ? Math.min(FETCH_TIMEOUT_MS, 3_200)
              : FETCH_TIMEOUT_MS,
            verificationSignal
          );

  if (verificationSignal?.aborted) return null;

  if (preferJinaForConcreteOlxOffer) {
    console.log(
      "[AIShopping] V34.CORE120 OLX verification fast-path: skipped direct fetch:",
      result.url
    );
  } else if (!page && (!trustedAllegroLokalnieCard || shouldFetchTrustedAllegroLokalnie)) {
    console.log("[AIShopping] direct page fetch failed:", result.url);
  }

  if (trustedAllegroLokalnieCard && !shouldFetchTrustedAllegroLokalnie) {
    console.log(
      "[AIShopping] V34.CORE120 skipped Allegro Lokalnie product fetch:",
      finalUrl
    );
  }

  if (trustedAllegroLokalnieCard && shouldFetchTrustedAllegroLokalnie) {
    console.log(
      "[AIShopping] V34.CORE120 fetching Allegro Lokalnie page for universal requirements:",
      finalUrl
    );
  }

  const directPageBlocked = Boolean(
    page &&
    page.status >= 200 &&
    page.status < 400 &&
    isBlockedOrChallengePage(page.html)
  );

  if (directPageBlocked) {
    console.log(
      "[AIShopping] V34.CORE120 direct page is bot/challenge page; preserving bound discovery identity:",
      finalUrl
    );
  }

  if (page && page.status >= 200 && page.status < 400 && !directPageBlocked) {
    const fetchedUrl = normalizeUrl(page.finalUrl);

    if (fetchedUrl && isProbablyRealOfferUrl(fetchedUrl)) {
      finalUrl = fetchedUrl;
    } else if (fetchedUrl) {
      console.log(
        "[AIShopping] reject redirect to non-product URL:",
        result.url,
        "=>",
        fetchedUrl
      );
      return null;
    }

    if (isBlockedOrChallengePage(page.html)) {
      console.log(
        "[AIShopping] direct page is bot/challenge page:",
        finalUrl
      );
    }

    const pageTitle = extractTitleFromHtml(page.html);
    const pageDescription = extractDescriptionFromHtml(page.html);
    const structuredProduct = extractStructuredProductOfferEvidence(
      page.html,
      result.name,
      finalUrl
    );

    if (structuredProduct.matched && structuredProduct.name) {
      const structuredNameIsBarePackageVariant =
        result.catalogVariantAvailabilityEvidence === true &&
        parsed.intent.required.some(
          (requirement) =>
            requirement.hard && requirement.key === "package_weight"
        ) &&
        isBarePackageVariantLabel(structuredProduct.name);

      if (structuredNameIsBarePackageVariant) {
        // Keep the URL-bound catalog identity. A schema node named only
        // "4 kg" is a selector/variant label, not the product family name.
        finalName = result.name;
        console.log(
          "[AIShopping] V34.CORE120 preserve product identity over bare package label:",
          structuredProduct.name,
          "=>",
          finalName
        );
      } else {
        finalName = structuredProduct.name;
      }
    } else if (
      pageTitle &&
      !(isCeneoResult && isGenericCeneoTitle(pageTitle)) &&
      !isAllegroLokalnieResult &&
      !isWeakVerificationPageTitle(pageTitle, finalUrl)
    ) {
      finalName = pageTitle;
    }

    const boundPageDescription =
      structuredProduct.matched && structuredProduct.description
        ? structuredProduct.description
        : pageDescription;

    if (boundPageDescription && !isCeneoResult) {
      description = boundPageDescription;
      trustedVerifiedDescription = boundPageDescription;
    }

    if (structuredProduct.matched) {
      if (structuredProduct.description) {
        trustedBoundProductDescription = normalizeText(
          structuredProduct.description
        ).slice(0, 12_000);
      }
      verifiedCondition = structuredProduct.condition ?? verifiedCondition;
      verifiedRating = structuredProduct.rating;
      if (structuredProduct.shipping.verified) {
        verifiedShipping = structuredProduct.shipping;
      }

      console.log(
        "[AIShopping] V34.CORE120 bound Product/Offer:",
        getResultHostname(finalUrl),
        {
          name: structuredProduct.name,
          identityScore: structuredProduct.identityScore,
          price: structuredProduct.price,
          currency: structuredProduct.currency,
          availability: structuredProduct.availability,
          condition: structuredProduct.condition,
          shipping: structuredProduct.shipping.label,
          rating: structuredProduct.rating,
        }
      );

      if (
        parsed.condition &&
        structuredProduct.condition &&
        structuredProduct.condition !== parsed.condition
      ) {
        console.log(
          "[AIShopping] V34.CORE120 reject structured condition mismatch:",
          finalUrl,
          "requested=",
          parsed.condition,
          "product=",
          structuredProduct.condition
        );
        return null;
      }
    }

    if (parsed.intent.required.length > 0) {
      if (isCeneoResult) {
        trustedCeneoExactRequirementEvidence =
          extractTrustedCeneoExactProductRequirementEvidence(
            page.html,
            finalName || result.name,
            hardUniversalRequirements
          );

        universalFeatureEvidence = normalizeText(
          `${universalFeatureEvidence} ${trustedCeneoExactRequirementEvidence}`
        ).slice(0, 26_000);
      } else {
        const htmlRequirementEvidence =
          extractUniversalFeatureEvidenceFromHtml(
            page.html,
            finalName || result.name
          );
        trustedCanonicalConcreteRequirementEvidence =
          extractCanonicalHardRequirementEvidenceFromConcreteHtml(
            page.html,
            finalName || result.name,
            finalUrl,
            parsed
          );

        universalFeatureEvidence = normalizeText(
          `${universalFeatureEvidence} ${boundPageDescription ?? ""} ${htmlRequirementEvidence} ${trustedCanonicalConcreteRequirementEvidence}`
        ).slice(0, 30_000);

        if (trustedCanonicalConcreteRequirementEvidence) {
          console.log(
            "[AIShopping] V34.CORE120 concrete-page HARD propagation:",
            getResultHostname(finalUrl),
            finalName,
            trustedCanonicalConcreteRequirementEvidence
          );
        }
      }
    }

    const visibleRetailerPageText = extractTagText(page.html);

    if (
      result.source === "RetailerRescue" &&
      !isConfiguredCommerceDomain(finalUrl)
    ) {
      dynamicRetailerCommerceEvidence = hasStrongDynamicRetailerCommerceEvidence(
        page.html,
        visibleRetailerPageText,
        structuredProduct
      );

      if (!dynamicRetailerCommerceEvidence) {
        console.log(
          "[AIShopping] V34.CORE120 reject rescued non-commerce product page:",
          finalUrl
        );
      }
    }

    const requestedPackageVariantUrl =
      result.catalogVariantAvailabilityEvidence === true
        ? extractRequestedPackageVariantUrlFromMarkup(
            page.html,
            finalUrl,
            parsed
          )
        : null;

    if (
      requestedPackageVariantUrl &&
      normalizeUrl(requestedPackageVariantUrl) !== normalizeUrl(finalUrl)
    ) {
      finalUrl = requestedPackageVariantUrl;
      requestedPackageVariantUrlResolved = true;
      console.log(
        "[AIShopping] V34.CORE120 resolved exact package variant URL from retailer page:",
        finalUrl
      );
    }

    const requestedPackageVariantPrice =
      result.catalogVariantAvailabilityEvidence === true
        ? extractRequestedPackageVariantPriceFromText(
            visibleRetailerPageText,
            parsed,
            parsed.condition
          )
        : { price: null, currency: null };

    if (
      requestedPackageVariantPrice.price !== null &&
      requestedPackageVariantPrice.currency
    ) {
      requestedPackageVariantResolved = true;
      finalName = rewriteVerifiedNameToRequestedPackageVariant(
        finalName,
        result.name,
        parsed
      );
      const packageRequirement = parsed.intent.required.find(
        (requirement) => requirement.hard && requirement.key === "package_weight"
      );
      if (packageRequirement) {
        universalFeatureEvidence = normalizeText(
          `${universalFeatureEvidence} ${packageRequirement.aliases[0] || packageRequirement.value}`
        ).slice(0, 26_000);
      }
      console.log(
        "[AIShopping] V34.CORE120 requested catalog package variant price:",
        finalUrl,
        requestedPackageVariantPrice.price,
        requestedPackageVariantPrice.currency,
        "variant=",
        packageRequirement?.value ?? ""
      );
    }

    const requestedVolumeVariantPrice =
      parsed.category === "perfume"
        ? extractRequestedVolumeVariantPriceFromText(
            visibleRetailerPageText,
            parsed,
            parsed.condition
          )
        : { price: null, currency: null };

    if (
      requestedVolumeVariantPrice.price !== null &&
      requestedVolumeVariantPrice.currency
    ) {
      requestedPerfumeVolumeVariantResolved = true;
      const volumeRequirement = parsed.intent.required.find(
        (requirement) => requirement.hard && requirement.key === "volume"
      );
      if (volumeRequirement) {
        universalFeatureEvidence = normalizeText(
          `${universalFeatureEvidence} ${volumeRequirement.aliases[0] || volumeRequirement.value}`
        ).slice(0, 26_000);
        finalName = rewriteVerifiedNameToRequestedVolumeVariant(
          finalName,
          result.name,
          parsed
        );
      }
      console.log(
        "[AIShopping] V34.CORE120 requested perfume volume variant price:",
        finalUrl,
        requestedVolumeVariantPrice.price,
        requestedVolumeVariantPrice.currency,
        "variant=",
        volumeRequirement?.value ?? ""
      );
    }

    const tirePerPiecePagePrice =
      parsed.category === "tire"
        ? extractTirePerPiecePrice(visibleRetailerPageText)
        : { price: null, currency: null };

    const pagePrice =
      requestedPackageVariantPrice.price !== null &&
      requestedPackageVariantPrice.currency
        ? requestedPackageVariantPrice
        : requestedVolumeVariantPrice.price !== null &&
          requestedVolumeVariantPrice.currency
          ? requestedVolumeVariantPrice
        : isAllegroLokalnieResult
          ? extractAllegroLokalnieExplicitBoundPrice(
              visibleRetailerPageText,
              finalName || result.name
            )
        : structuredProduct.matched &&
      structuredProduct.price !== null &&
      structuredProduct.currency
        ? {
            price: structuredProduct.price,
            currency: structuredProduct.currency,
          }
        : (
            parsed.category === "tire" &&
            tirePerPiecePagePrice.price !== null &&
            tirePerPiecePagePrice.currency
          )
          ? tirePerPiecePagePrice
          : extractCurrencyPriceFromHtml(
              page.html,
              parsed.condition,
              [finalName, result.name, pageTitle].filter(Boolean),
              finalUrl
            );
    const ceneoDirectPagePrice = isCeneoResult
      ? extractCeneoDirectProductPriceFromHtml(page.html, result.name)
      : { price: null, currency: null };

    const unconfiguredDynamicRetailerNeedsCommerceProof =
      result.source === "RetailerRescue" &&
      !isConfiguredCommerceDomain(finalUrl);

    const trustedPagePrice = isCeneoResult
      ? ceneoDirectPagePrice
      : unconfiguredDynamicRetailerNeedsCommerceProof && !dynamicRetailerCommerceEvidence
        ? { price: null, currency: null }
        : pagePrice;

    if (
      !trustedAllegroLokalnieCard &&
      trustedPagePrice.price !== null &&
      trustedPagePrice.currency
    ) {
      const converted = await convertToPln(
        trustedPagePrice.price,
        trustedPagePrice.currency
      );

      if (converted !== null) {
        pricePln = converted;
        if (
          parsed.category === "tire" &&
          tirePerPiecePagePrice.price !== null &&
          tirePerPiecePagePrice.currency &&
          trustedPagePrice.price === tirePerPiecePagePrice.price &&
          trustedPagePrice.currency === tirePerPiecePagePrice.currency &&
          !(structuredProduct.matched && structuredProduct.price !== null && structuredProduct.currency)
        ) {
          tirePriceIsPerPiece = true;
        }
        priceVerified = true;

        console.log(
          isCeneoResult
            ? "[AIShopping] V34.CORE120 verified Ceneo direct-page price:"
            : "[AIShopping] verified price from product page:",
          finalUrl,
          trustedPagePrice.price,
          trustedPagePrice.currency,
          "=>",
          converted,
          "PLN"
        );
      }
    }

    const visiblePageText = normalizeText(
      extractTagText(page.html)
    ).slice(0, 120_000);
    const focusedVisiblePageText = getUniversalEvidenceScope(
      finalName,
      visiblePageText,
      finalUrl
    );

    if (
      parsed.category &&
      hasUniversalCategoryEvidence(focusedVisiblePageText, parsed)
    ) {
      const categoryProfile = UNIVERSAL_CATEGORY_PROFILES[parsed.category];
      trustedConcreteProductClassEvidence = normalizeText(
        categoryProfile?.positiveAliases?.[0] ?? parsed.category
      );
    }

    if (!verifiedCondition) {
      verifiedCondition = extractTrustedConditionFromText(
        focusedVisiblePageText
      );
    }

    if (!verifiedShipping.verified) {
      const visibleShipping = extractShippingFromText(
        focusedVisiblePageText,
        pricePln
      );
      if (visibleShipping.verified) verifiedShipping = visibleShipping;
    }

    if (
      verifiedShipping.verified &&
      verifiedShipping.cost !== null &&
      verifiedShipping.currency
    ) {
      deliveryCostPln = await convertToPln(
        verifiedShipping.cost,
        verifiedShipping.currency
      );
    }

    const jsonAvailability =
      structuredProduct.matched &&
      structuredProduct.availability !== "unknown"
        ? structuredProduct.availability
        : extractJsonLdAvailability(page.html);

    const textAvailability = getAvailabilityFromHtml(focusedVisiblePageText);
    const hasTrustedFilteredVariantAvailability =
      result.source === "RetailerRescue" &&
      result.catalogVariantAvailabilityEvidence === true &&
      (
        (result.catalogRequirementProofKeys ?? []).some((key) =>
          parsed.intent.required.some(
            (requirement) =>
              requirement.hard &&
              requirement.key === key &&
              ["shoe_size", "clothing_size"].includes(key)
          )
        ) ||
        (
          requestedPackageVariantPrice.price !== null &&
          requestedPackageVariantPrice.currency !== null
        )
      );
    const directRequestedVariantSelectorCheckout =
      hasRequestedVariantSelectorCheckoutEvidence(
        focusedVisiblePageText,
        result,
        parsed
      );

    // CORE37: direct retailer HTML can expose structured price/availability
    // while rendering the actual variant selector only in the reader-visible
    // storefront. The reader was already started in parallel above, so this
    // does not add a new request or extend the route budget. Consume it only
    // for the narrow stale-unavailable case and still require the concrete
    // product page to expose BOTH the requested size and an active checkout
    // action before overriding product-level JSON-LD.
    const hasConcreteRequestedVariantCheckout =
      await resolveRequestedVariantSelectorCheckoutEvidence(
        focusedVisiblePageText,
        result,
        parsed,
        jsonAvailability,
        hasTrustedFilteredVariantAvailability,
        racedRetailerReaderPromise
      );

    if (verificationSignal?.aborted) return null;

    if (
      !directRequestedVariantSelectorCheckout &&
      hasConcreteRequestedVariantCheckout
    ) {
      console.log(
        "[AIShopping] V34.CORE120 reader variant selector + checkout evidence:",
        finalUrl,
        result.catalogRequirementProofKeys
      );
    }

    if (jsonAvailability === "unavailable") {
      // Some retailers publish product-level JSON-LD for the default variant,
      // while their own filtered catalog proves that the requested size is a
      // selectable/current variant. Never let that generic Product offer erase
      // variant-specific evidence. A focused unavailable signal still wins
      // unless the concrete page itself simultaneously exposes the requested
      // size in its selector and an active checkout action.
      if (
        hasTrustedFilteredVariantAvailability &&
        (
          textAvailability !== "unavailable" ||
          hasConcreteRequestedVariantCheckout
        )
      ) {
        console.log(
          "[AIShopping] V34.CORE120 variant-filtered catalog overrides product-level unavailable JSON-LD:",
          finalUrl,
          result.catalogRequirementProofKeys,
          "focusedText=",
          textAvailability,
          "selectorCheckout=",
          hasConcreteRequestedVariantCheckout
        );
        availability =
          textAvailability === "available" ||
          hasConcreteRequestedVariantCheckout
            ? "available"
            : "unknown";
      } else {
        console.log("[AIShopping] reject unavailable JSON-LD:", finalUrl);
        return null;
      }
    } else if (jsonAvailability === "available") {
      availability = "available";
    } else {
      if (textAvailability === "unavailable") {
        console.log("[AIShopping] reject unavailable focused text:", finalUrl);
        return null;
      }

      availability =
        textAvailability === "available"
          ? "available"
          : "unknown";
    }
  }

  // ------------------------------------------------------------
  // B. Jina Reader — fallback NIEZALEŻNY od direct fetch
  // ------------------------------------------------------------
  // Jeżeli sklep blokuje naszego fetchera albo zwraca HTML bez ceny,
  // próbujemy czytelnego tekstu strony przez darmowy reader.
  // To musi być poza blokiem `if (page)`, bo właśnie wtedy jest
  // najbardziej potrzebny.
  // V32.12: feature/spec verification is handled by the universal proof
  // engine below. Jina is used for price/page extraction, not as a
  // category-specific feature fallback.

  const needsExactPackageVariantReader =
    parsed.category === "pet_food" &&
    result.catalogVariantAvailabilityEvidence === true &&
    parsed.intent.required.some(
      (requirement) =>
        requirement.hard && requirement.key === "package_weight"
    ) &&
    (
      !requestedPackageVariantResolved ||
      !requestedPackageVariantUrlResolved
    );

  const needsExactPerfumeVolumeReader =
    parsed.category === "perfume" &&
    parsed.intent.required.some(
      (requirement) => requirement.hard && requirement.key === "volume"
    ) &&
    !requestedPerfumeVolumeVariantResolved &&
    !verifiedNameBindsRequestedPerfumeVolume(finalName, parsed);

  const needsMarketplaceConditionReader =
    parsed.condition !== null &&
    verifiedCondition === null &&
    (isOlxResult || isAllegroLokalnieResult || initialHost === "allegro.pl");

  if (needsMarketplaceConditionReader) {
    console.log(
      "[AIShopping] V34.CORE120 marketplace condition reader:",
      finalUrl,
      "requested=",
      parsed.condition
    );
  }

  if (
    pricePln === null ||
    shouldFetchTrustedOlx ||
    needsExactPackageVariantReader ||
    needsExactPerfumeVolumeReader ||
    needsMarketplaceConditionReader ||
    (
      isAllegroResult &&
      !priceVerified &&
      !trustedAllegroLokalnieCard
    )
  ) {
    const finalHostForJina = getResultHostname(finalUrl);
    const jinaTimeoutMs =
      finalHostForJina === "olx.pl"
        ? getOlxReaderBudgetProfile(parsed).primaryTimeoutMs
        : finalHostForJina === "allegrolokalnie.pl" && needsMarketplaceConditionReader
          ? 4_800
          : externallyProvableRequirements.length > 0
            ? 6_000
            : 7_200;

    // Verification is already a diversified batch. A transient retry for one
    // candidate can consume another full reader timeout and starve the rest,
    // so retries stay enabled for discovery but are disabled here.
    const marketplaceReaderStartedAt = Date.now();
    let jinaText = racedRetailerReaderPromise
      ? await racedRetailerReaderPromise
      : await fetchViaJina(
          finalUrl,
          jinaTimeoutMs,
          false,
          verificationSignal
        );

    // Jedna kontrolowana ponowna próba tylko dla oferty, której WŁASNY tytuł
    // potwierdza żądany stan. Nie retry'ujemy całej kolejki i nie wydłużamy
    // odpowiedzi dla przypadkowych kandydatów. To pomaga przy chwilowych
    // timeoutach OLX, zachowując twardy limit czasu całego wyszukiwania.
    if (
      !jinaText &&
      finalHostForJina === "olx.pl" &&
      parsed.condition &&
      hasExplicitRequestedConditionInTitle(result.name, parsed.condition)
    ) {
      console.log(
        "[AIShopping] V34.CORE120 retry strongest OLX condition match:",
        finalUrl,
        parsed.condition
      );

      await sleep(250);
      if (verificationSignal?.aborted) return null;

      // V34.CORE120: the primary OLX read now receives almost the whole
      // per-offer window (6.9 s). A second long 4.2 s retry could never finish
      // inside the same hard route deadline after a true timeout. Keep only a
      // short retry for fast transient failures; two separately-ranked OLX
      // listings already provide the main source redundancy.
      jinaText = await fetchViaJina(
        finalUrl,
        getOlxReaderBudgetProfile(parsed).retryTimeoutMs,
        false,
        verificationSignal
      );
    }

    const marketplaceReaderElapsedMs = Date.now() - marketplaceReaderStartedAt;
    if (
      isLikelyTransientMarketplaceReaderTimeout(
        finalHostForJina,
        marketplaceReaderElapsedMs,
        jinaTimeoutMs,
        Boolean(jinaText)
      )
    ) {
      result.transientMarketplaceReaderTimeout = true;
      console.log(
        "[AIShopping] V34.CORE120 transient marketplace reader timeout candidate:",
        finalUrl,
        "elapsedMs=",
        marketplaceReaderElapsedMs
      );
    }

    if (verificationSignal?.aborted) return null;

    console.log(
      "[AIShopping] Jina result:",
      finalUrl,
      "received=",
      Boolean(jinaText),
      "length=",
      jinaText?.length ?? 0
    );

    if (jinaText) {
      const preview = jinaText
        .slice(0, 3500)
        .replace(/\s+/g, " ");

      console.log(
        "[AIShopping] Jina preview:",
        preview
      );

      if (isBlockedOrChallengePage(jinaText)) {
        console.log(
          "[AIShopping] Jina returned bot/challenge page; price is NOT trusted:",
          finalUrl
        );
      } else {
        readerPageVerified = true;
        const jinaTitle = extractJinaPageTitle(jinaText);
        const jinaContext = extractJinaOfferContext(jinaText);

        if (
          !trustedConcreteProductClassEvidence &&
          parsed.category &&
          hasUniversalCategoryEvidence(jinaContext, parsed)
        ) {
          const categoryProfile = UNIVERSAL_CATEGORY_PROFILES[parsed.category];
          trustedConcreteProductClassEvidence = normalizeText(
            categoryProfile?.positiveAliases?.[0] ?? parsed.category
          );
        }

        if (jinaTitle && !(isCeneoResult && isGenericCeneoTitle(jinaTitle))) {
          const jinaTitleIsBarePackageVariant =
            result.catalogVariantAvailabilityEvidence === true &&
            parsed.intent.required.some(
              (requirement) =>
                requirement.hard && requirement.key === "package_weight"
            ) &&
            isBarePackageVariantLabel(jinaTitle);

          if (!jinaTitleIsBarePackageVariant) {
            finalName = jinaTitle;
          }
        }

        if (jinaContext && !isCeneoResult) {
          description = jinaContext;
          trustedVerifiedDescription = jinaContext;

          const jinaCondition = extractTrustedConditionFromText(jinaContext);
          if (jinaCondition) verifiedCondition = jinaCondition;

          if (
            parsed.condition &&
            jinaCondition &&
            jinaCondition !== parsed.condition
          ) {
            console.log(
              "[AIShopping] V34.CORE120 reject verified text condition mismatch:",
              finalUrl,
              "requested=",
              parsed.condition,
              "product=",
              jinaCondition
            );
            return null;
          }

          if (!verifiedShipping.verified) {
            const jinaShipping = extractShippingFromText(jinaContext);
            if (jinaShipping.verified) {
              verifiedShipping = jinaShipping;
              if (
                jinaShipping.cost !== null &&
                jinaShipping.currency
              ) {
                deliveryCostPln = await convertToPln(
                  jinaShipping.cost,
                  jinaShipping.currency
                );
              }
            }
          }
        }

        if (parsed.intent.required.length > 0) {
          universalFeatureEvidence = normalizeText(
            `${universalFeatureEvidence} ${extractUniversalFeatureEvidenceFromJina(
              jinaText,
              finalName
            )}`
          ).slice(0, 26_000);

          const jinaCanonicalConcreteRequirementEvidence =
            !isCeneoResult &&
            !["olx.pl", "allegro.pl", "allegrolokalnie.pl"].includes(
              getResultHostname(finalUrl)
            )
              ? extractCanonicalHardRequirementEvidenceFromConcreteJina(
                  jinaText.slice(0, 180_000),
                  finalName || result.name,
                  finalUrl,
                  parsed
                )
              : "";

          if (jinaCanonicalConcreteRequirementEvidence) {
            trustedCanonicalConcreteRequirementEvidence = normalizeText(
              `${trustedCanonicalConcreteRequirementEvidence} ${jinaCanonicalConcreteRequirementEvidence}`
            ).slice(0, 8_000);
            universalFeatureEvidence = normalizeText(
              `${universalFeatureEvidence} ${jinaCanonicalConcreteRequirementEvidence}`
            ).slice(0, 26_000);

            console.log(
              "[AIShopping] V34.CORE185 Jina concrete-spec HARD propagation:",
              getResultHostname(finalUrl),
              finalName,
              jinaCanonicalConcreteRequirementEvidence
            );
          }
        }

        const requestedJinaPackageVariantUrl =
          result.catalogVariantAvailabilityEvidence === true
            ? extractRequestedPackageVariantUrlFromMarkup(
                jinaText.slice(0, 160_000),
                finalUrl,
                parsed
              )
            : null;

        if (
          requestedJinaPackageVariantUrl &&
          normalizeUrl(requestedJinaPackageVariantUrl) !== normalizeUrl(finalUrl)
        ) {
          finalUrl = requestedJinaPackageVariantUrl;
          requestedPackageVariantUrlResolved = true;
          console.log(
            "[AIShopping] V34.CORE120 resolved exact package variant URL from Jina:",
            finalUrl
          );
        }

        const finalHost = getResultHostname(finalUrl);

        const requestedJinaPackageVariantPrice =
          result.catalogVariantAvailabilityEvidence === true
            ? extractRequestedPackageVariantPriceFromText(
                jinaText.slice(0, 120_000),
                parsed,
                parsed.condition
              )
            : { price: null, currency: null };

        if (
          requestedJinaPackageVariantPrice.price !== null &&
          requestedJinaPackageVariantPrice.currency
        ) {
          requestedPackageVariantResolved = true;
          finalName = rewriteVerifiedNameToRequestedPackageVariant(
            finalName,
            result.name,
            parsed
          );
          const packageRequirement = parsed.intent.required.find(
            (requirement) =>
              requirement.hard && requirement.key === "package_weight"
          );
          if (packageRequirement) {
            universalFeatureEvidence = normalizeText(
              `${universalFeatureEvidence} ${packageRequirement.aliases[0] || packageRequirement.value}`
            ).slice(0, 26_000);
          }

          console.log(
            "[AIShopping] V34.CORE120 requested Jina package variant price:",
            finalUrl,
            requestedJinaPackageVariantPrice.price,
            requestedJinaPackageVariantPrice.currency,
            "variant=",
            packageRequirement?.value ?? ""
          );
        }

        const requestedJinaVolumeVariantPrice =
          parsed.category === "perfume"
            ? extractRequestedVolumeVariantPriceFromText(
                jinaText.slice(0, 120_000),
                parsed,
                parsed.condition
              )
            : { price: null, currency: null };

        if (
          requestedJinaVolumeVariantPrice.price !== null &&
          requestedJinaVolumeVariantPrice.currency
        ) {
          requestedPerfumeVolumeVariantResolved = true;
          const volumeRequirement = parsed.intent.required.find(
            (requirement) =>
              requirement.hard && requirement.key === "volume"
          );
          if (volumeRequirement) {
            universalFeatureEvidence = normalizeText(
              `${universalFeatureEvidence} ${volumeRequirement.aliases[0] || volumeRequirement.value}`
            ).slice(0, 26_000);
            finalName = rewriteVerifiedNameToRequestedVolumeVariant(
              finalName,
              result.name,
              parsed
            );
          }

          console.log(
            "[AIShopping] V34.CORE120 requested Jina perfume volume variant price:",
            finalUrl,
            requestedJinaVolumeVariantPrice.price,
            requestedJinaVolumeVariantPrice.currency,
            "variant=",
            volumeRequirement?.value ?? ""
          );
        }

        const checkoutBoundRetailerEvidence =
          !["ceneo.pl", "olx.pl", "allegro.pl", "allegrolokalnie.pl"].includes(finalHost)
            ? extractRetailerCheckoutBoundEvidenceFromJina(
                jinaText.slice(0, 160_000),
                [finalName, result.name],
                parsed,
                finalUrl
              )
            : {
                price: null,
                currency: null,
                availability: "unknown" as const,
                anchor: "",
              };

        if (checkoutBoundRetailerEvidence.availability === "unavailable") {
          console.log(
            "[AIShopping] V34.CORE120 reject checkout-bound unavailable retailer product:",
            finalUrl
          );
          return null;
        }
        if (checkoutBoundRetailerEvidence.availability === "available") {
          availability = "available";
        }

        // V32.17: discovery catalog snippets can be noisy even when the product
        // URL itself is correct. Re-bind MPN/SKU only from the verified concrete
        // product page around the same product title. The code still does not
        // prove the requested model by itself; it is fed into the unchanged
        // independent MPN -> exact-model bridge below.
        if (result.source === "RetailerRescue") {
          const productBoundMpn = extractProductBoundRetailerManufacturerCodeFromJina(
            jinaText.slice(0, 180_000),
            [finalName, result.name, checkoutBoundRetailerEvidence.anchor],
            finalUrl
          );

          if (productBoundMpn) {
            const previousMpn = result.deferredModelIdentityBridgeCode ?? "";
            if (previousMpn && previousMpn !== productBoundMpn) {
              console.log(
                "[AIShopping] V34.CORE120 corrected noisy retailer MPN:",
                getResultHostname(finalUrl),
                previousMpn,
                "=>",
                productBoundMpn
              );
            }
            result.deferredModelIdentityBridgeCode = productBoundMpn;

            // V34.CORE120: a catalog card can carry a noisy SKU while the verified
            // first-party page exposes the real manufacturer code. Start proof
            // for the corrected code immediately instead of waiting until the
            // final universal gate, so proof search overlaps the remaining page
            // parsing / price binding work.
            if (
              productBoundMpn !== earlyDeferredModelBridgeCode &&
              productBoundMpn !== correctedDeferredModelBridgeCode
            ) {
              correctedDeferredModelBridgeCode = productBoundMpn;
              correctedModelIdentityBridgePromise =
                resolveDeferredRetailerModelIdentityBridge(
                  {
                    ...result,
                    deferredModelIdentityBridgeCode: productBoundMpn,
                  },
                  parsed,
                  verificationSignal
                );
              console.log(
                "[AIShopping] V34.CORE120 corrected MPN bridge prefetch:",
                getResultHostname(finalUrl),
                productBoundMpn
              );
            }
          }
        }

        const jinaPrice =
          requestedJinaPackageVariantPrice.price !== null &&
          requestedJinaPackageVariantPrice.currency
            ? requestedJinaPackageVariantPrice
            : requestedJinaVolumeVariantPrice.price !== null &&
              requestedJinaVolumeVariantPrice.currency
              ? requestedJinaVolumeVariantPrice
              : finalHost === "ceneo.pl"
                ? extractCeneoProductPriceFromText(
                    jinaText.slice(0, 120_000)
                  )
                : finalHost === "olx.pl"
                  ? extractOlxListingPriceFromJina(
                      jinaText.slice(0, 120_000),
                      result.name
                    )
                  : finalHost === "allegrolokalnie.pl"
                    ? extractAllegroLokalnieExplicitBoundPrice(
                        jinaText.slice(0, 160_000),
                        result.name
                      )
                  : checkoutBoundRetailerEvidence.price !== null &&
                    checkoutBoundRetailerEvidence.currency
                    ? {
                        price: checkoutBoundRetailerEvidence.price,
                        currency: checkoutBoundRetailerEvidence.currency,
                      }
                    : extractRetailerProductPriceFromJina(
                        jinaText.slice(0, 120_000),
                        [finalName, result.name],
                        parsed,
                        finalUrl
                      );

        console.log(
          "[AIShopping] Jina parsed price:",
          jinaPrice
        );

        if (
          jinaPrice.price !== null &&
          jinaPrice.currency
        ) {
          const converted = await convertToPln(
            jinaPrice.price,
            jinaPrice.currency
          );

          if (converted !== null) {
            if (
              trustedAllegroLokalnieCard &&
              priceVerified &&
              pricePln !== null
            ) {
              console.log(
                "[AIShopping] V34.CORE120 kept trusted Allegro Lokalnie buy-now price:",
                finalUrl,
                pricePln,
                "PLN; Jina candidate=",
                converted,
                "PLN"
              );
            } else {
              pricePln = converted;
              tirePriceIsPerPiece = false;
              priceVerified = true;

              console.log(
                "[AIShopping] verified price via Jina:",
                finalUrl,
                jinaPrice.price,
                jinaPrice.currency,
                "=>",
                converted,
                "PLN"
              );
            }
          }
        }

        if (
          jinaContext &&
          result.catalogVariantAvailabilityEvidence === true &&
          requestedPackageVariantUrlResolved
        ) {
          const exactVariantAvailability = getAvailabilityFromHtml(jinaContext);
          if (exactVariantAvailability === "unavailable") {
            console.log(
              "[AIShopping] V34.CORE120 reject unavailable exact package variant via Jina:",
              finalUrl
            );
            return null;
          }
          if (exactVariantAvailability === "available") {
            availability = "available";
          }
        }

        if (jinaContext && !verifiedShipping.verified) {
          const pricedJinaShipping = extractShippingFromText(
            jinaContext,
            pricePln
          );
          if (pricedJinaShipping.verified) {
            verifiedShipping = pricedJinaShipping;
            if (
              pricedJinaShipping.cost !== null &&
              pricedJinaShipping.currency
            ) {
              deliveryCostPln = await convertToPln(
                pricedJinaShipping.cost,
                pricedJinaShipping.currency
              );
            }
          }
        }
      }
    }
  }

  if (
    parsed.category === "pet_food" &&
    result.catalogVariantAvailabilityEvidence === true &&
    parsed.intent.required.some(
      (requirement) =>
        requirement.hard && requirement.key === "package_weight"
    ) &&
    !requestedPackageVariantResolved
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject unresolved requested package variant:",
      finalUrl,
      parsed.intent.required
        .filter(
          (requirement) =>
            requirement.hard && requirement.key === "package_weight"
        )
        .map((requirement) => requirement.value)
    );
    return null;
  }

  const hardRequestedPerfumeVolume =
    parsed.category === "perfume" &&
    parsed.intent.required.some(
      (requirement) => requirement.hard && requirement.key === "volume"
    );

  // V32.12: every hard perfume volume must be tied to the exact bottle price.
  // A page-wide lowPrice / "from" price cannot satisfy 100 ml just because
  // 100 ml is mentioned somewhere else on the same multi-variant page.
  if (
    hardRequestedPerfumeVolume &&
    !requestedPerfumeVolumeVariantResolved &&
    !verifiedNameBindsRequestedPerfumeVolume(finalName, parsed)
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject unresolved requested perfume volume variant:",
      finalUrl,
      parsed.intent.required
        .filter(
          (requirement) => requirement.hard && requirement.key === "volume"
        )
        .map((requirement) => requirement.value),
      "verifiedName=",
      finalName
    );
    return null;
  }

  const verifiedBrandAssessment = evaluateVerifiedBrandConflict(
    parsed,
    finalName,
    trustedVerifiedDescription
  );

  if (verifiedBrandAssessment.conflict) {
    console.log(
      "[AIShopping] V34.CORE120 reject verified brand identity conflict:",
      finalUrl,
      "requested=",
      parsed.brand,
      "claims=",
      verifiedBrandAssessment.claims,
      "reason=",
      verifiedBrandAssessment.reason
    );
    return null;
  }

  if (
    result.source === "RetailerRescue" &&
    !isConfiguredCommerceDomain(finalUrl) &&
    !dynamicRetailerCommerceEvidence
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject unconfigured rescue without commerce proof:",
      finalUrl
    );
    return null;
  }

  // ------------------------------------------------------------
  // V32.12 UNIVERSAL REQUIREMENT PROOF RESOLUTION
  // ------------------------------------------------------------
  // First evaluate only the concrete offer evidence. If hard model/spec
  // attributes are missing, enrich with exact-model evidence gathered in
  // parallel. One mechanism serves every category.
  // V32.12: a structured Product name can intentionally omit the brand while
  // the retailer search card still contains it (Rossmann is a common example).
  // For trusted, URL-bound discovery sources keep BOTH names as identity proof.
  // This is source-level logic: no brand/product is hard-coded. Bing-like open
  // web titles are not allowed to rescue a mismatched redirect.
  const trustedBoundDiscoveryIdentityName = [
    "RetailerRescue",
    "OLXDirect",
    "AllegroDirect",
    "AllegroLokalnieDirect",
    "MarketplaceIndexRescue",
    "CeneoDirect",
    "CeneoMerchant",
  ].includes(result.source)
    ? result.name
    : "";

  const rawUniversalVerifiedIdentityTitle = normalizeText(
    `${finalName} ${trustedBoundDiscoveryIdentityName}`
  ).slice(0, 1_600);

  const requestedVerifiedVolumeRequirement =
    parsed.category === "perfume" && requestedPerfumeVolumeVariantResolved
      ? parsed.intent.required.find(
          (requirement) => requirement.hard && requirement.key === "volume"
        )
      : undefined;

  let resolvedModelIdentityBridgeProof = "";

  let universalVerifiedIdentityTitle = requestedVerifiedVolumeRequirement
    ? normalizeText(
        `${rawUniversalVerifiedIdentityTitle.replace(
          /(?:^|[^\p{L}\p{N}])\d+(?:[.,]\d+)?\s*(?:ml|l)(?=$|[^\p{L}\p{N}])/giu,
          " "
        )} ${requestedVerifiedVolumeRequirement.aliases[0] || requestedVerifiedVolumeRequirement.value}`
      ).slice(0, 1_600)
    : rawUniversalVerifiedIdentityTitle;

  // V32.12: preserve exact filters proven by a retailer-owned filtered catalog.
  // A card returned from /rozmiar_43/kolor_bialy is stronger evidence for
  // listing-specific size/color than an unrelated external page, and the proof
  // remains bound to this exact discovered card.
  const retailerTireUnitPurchaseMode = priceVerified && isRetailerTireUnitPurchaseMode(`${finalName} ${trustedBoundDiscoveryIdentityName}`, finalUrl, result.source, parsed);
  if (retailerTireUnitPurchaseMode) {
    const requestedCount = getRequestedHardPieceCount(parsed);
    tirePriceIsPerPiece = true;
    universalFeatureEvidence = normalizeText(`${universalFeatureEvidence} ${requestedCount} szt`).slice(0, 30_000);
    console.log("[AIShopping] V34.CORE120 retailer tire unit-purchase normalization:", { url: finalUrl, requestedCount, unitPrice: pricePln });
  }

  const trustedCatalogRequirementEvidence = parsed.intent.required
    .filter((requirement) =>
      result.catalogRequirementProofKeys?.includes(requirement.key)
    )
    .map((requirement) => requirement.aliases[0] || requirement.value)
    .filter(Boolean)
    .join(" ");

  if (trustedCatalogRequirementEvidence) {
    universalFeatureEvidence = normalizeText(
      `${universalFeatureEvidence} ${trustedCatalogRequirementEvidence}`
    ).slice(0, 30_000);
  }

  // V34.CORE120: scheduling already knows which HARD facts are explicitly
  // present on one retailer-owned bounded product card. CORE109 used those
  // facts to choose a candidate, then discarded them before final verification.
  // Preserve ONLY those previously proven keys. Generic Bing/DDG snippets and
  // comparison/category text remain ineligible, so this cannot borrow specs
  // from a neighbouring product.
  const trustedRetailerCardHardProofKeys = result.retailerOwnedCardEvidence === true
    ? getTrustedPortfolioHardProofKeys(result, parsed)
    : [];
  if (trustedRetailerCardHardProofKeys.length > 0) {
    trustedRetailerCardHardRequirementEvidence = parsed.intent.required
      .filter((requirement) =>
        requirement.hard && trustedRetailerCardHardProofKeys.includes(requirement.key)
      )
      .map((requirement) => requirement.aliases[0] || requirement.value)
      .filter(Boolean)
      .join(" ");

    if (trustedRetailerCardHardRequirementEvidence) {
      universalFeatureEvidence = normalizeText(
        `${universalFeatureEvidence} ${trustedRetailerCardHardRequirementEvidence}`
      ).slice(0, 30_000);
      console.log(
        "[AIShopping] V34.CORE120 trusted retailer-card HARD propagation:",
        getResultHostname(finalUrl),
        finalName,
        trustedRetailerCardHardProofKeys
      );
    }
  }

  if (trustedConcreteProductClassEvidence) {
    universalFeatureEvidence = normalizeText(
      `${universalFeatureEvidence} ${trustedConcreteProductClassEvidence}`
    ).slice(0, 30_000);
    console.log(
      "[AIShopping] V34.CORE120 concrete-page product-class propagation:",
      getResultHostname(finalUrl),
      trustedConcreteProductClassEvidence
    );
  }

  // CORE99: a marketplace title may omit the manufacturer while the CURRENT
  // product page exposes an explicit labelled field such as "Marka: ...".
  // That product-bound label is stronger and cheaper than an external search,
  // but free-floating brand mentions remain insufficient.
  const boundRequestedBrandProof = extractExplicitRequestedBrandFromBoundEvidence(
    `${trustedBoundProductDescription} ${trustedVerifiedDescription} ${universalFeatureEvidence}`,
    parsed
  );
  if (boundRequestedBrandProof) {
    universalVerifiedIdentityTitle = normalizeText(
      `${universalVerifiedIdentityTitle} ${boundRequestedBrandProof}`
    ).slice(0, 1_950);
  }

  // V34.CORE120: preserve facts stated directly in the VERIFIED product title
  // as explicit requirement evidence before any page-scope reduction. This does
  // not invent or borrow a spec: every appended token was already proven by the
  // concrete final title itself. It prevents a later HTML/product-scope cleanup
  // from accidentally dropping a title fact such as panel technology or Hz.
  const verifiedTitleHardRequirements = parsed.intent.required
    .filter((requirement) => requirement.hard)
    .filter((requirement) =>
      requirementHasEvidenceInContext(
        requirement,
        finalName,
        parsed.intent.required
      )
    );
  if (verifiedTitleHardRequirements.length > 0) {
    const verifiedTitleHardEvidence = verifiedTitleHardRequirements
      .map((requirement) => requirement.aliases[0] || requirement.value)
      .filter(Boolean)
      .join(" ");
    universalFeatureEvidence = normalizeText(
      `${universalFeatureEvidence} ${verifiedTitleHardEvidence}`
    ).slice(0, 30_000);
    console.log(
      "[AIShopping] V34.CORE120 verified-title HARD preservation:",
      finalName,
      verifiedTitleHardRequirements.map((requirement) => requirement.key)
    );
  }

  let preProofUniversalMatch = evaluateUniversalProductMatch(
    universalVerifiedIdentityTitle,
    `${trustedVerifiedDescription} ${universalFeatureEvidence}`,
    finalUrl,
    parsed,
    "verified"
  );

  if (!preProofUniversalMatch.pass && preProofUniversalMatch.reasons.includes("brand-mismatch") && universalBrandProofPromise) {
    const brandProof = await universalBrandProofPromise;
    if (brandProof) {
      universalVerifiedIdentityTitle = normalizeText(`${universalVerifiedIdentityTitle} ${brandProof}`).slice(0, 1_950);
      preProofUniversalMatch = evaluateUniversalProductMatch(universalVerifiedIdentityTitle, `${trustedVerifiedDescription} ${universalFeatureEvidence}`, finalUrl, parsed, "verified");
    }
    console.log("[AIShopping] V34.CORE120 universal brand resolution:", finalName, "pass=", preProofUniversalMatch.pass, "reasons=", preProofUniversalMatch.reasons);
  }

  if (
    !preProofUniversalMatch.pass &&
    result.deferredModelIdentityBridgeCode &&
    preProofUniversalMatch.reasons.includes("model-identity-mismatch")
  ) {
    const currentDeferredModelBridgeCode =
      result.deferredModelIdentityBridgeCode ?? "";
    const modelBridgeProof =
      earlyModelIdentityBridgePromise &&
      currentDeferredModelBridgeCode === earlyDeferredModelBridgeCode
        ? await earlyModelIdentityBridgePromise
        : correctedModelIdentityBridgePromise &&
            currentDeferredModelBridgeCode === correctedDeferredModelBridgeCode
          ? await correctedModelIdentityBridgePromise
          : await resolveDeferredRetailerModelIdentityBridge(
              result,
              parsed,
              verificationSignal
            );

    if (modelBridgeProof) {
      resolvedModelIdentityBridgeProof = modelBridgeProof;
      universalVerifiedIdentityTitle = normalizeText(
        `${universalVerifiedIdentityTitle} ${modelBridgeProof}`
      ).slice(0, 1_900);
      preProofUniversalMatch = evaluateUniversalProductMatch(
        universalVerifiedIdentityTitle,
        `${trustedVerifiedDescription} ${universalFeatureEvidence}`,
        finalUrl,
        parsed,
        "verified"
      );
    }
  }

  if (
    !preProofUniversalMatch.pass &&
    preProofUniversalMatch.reasons.includes("missing-required-attribute") &&
    universalRequirementProofPromise
  ) {
    universalIndependentRequirementProof = await universalRequirementProofPromise;

    if (universalIndependentRequirementProof) {
      universalFeatureEvidence = normalizeText(
        `${universalFeatureEvidence} ${universalIndependentRequirementProof}`
      ).slice(0, 30_000);

      preProofUniversalMatch = evaluateUniversalProductMatch(
        universalVerifiedIdentityTitle,
        `${description} ${universalFeatureEvidence}`,
        finalUrl,
        parsed,
        "verified"
      );
    }

    console.log(
      "[AIShopping] V34.CORE120 universal requirement resolution:",
      finalName,
      "pass=",
      preProofUniversalMatch.pass,
      "missing=",
      preProofUniversalMatch.missingRequirements
    );
  }

  const beforeVerifiedTitleReconciliation = preProofUniversalMatch;
  preProofUniversalMatch = reconcileVerifiedTitleHardRequirements(
    preProofUniversalMatch,
    verifiedTitleHardRequirements
  );
  if (
    !beforeVerifiedTitleReconciliation.pass &&
    preProofUniversalMatch.pass
  ) {
    console.log(
      "[AIShopping] V34.CORE120 verified-title HARD reconciliation:",
      finalName,
      verifiedTitleHardRequirements.map((requirement) => requirement.key)
    );
  }

  // V34.CORE120 LISTING-BOUND SAFETY GATE
  // The old engine had category-specific hard gates (most visibly power tools).
  // That architecture forced us to fix products one by one. The rule is now
  // universal: any hard requirement that can vary per listing/configuration
  // must be visible on THIS offer/card/page. Static exact-model proof is allowed
  // only for requirements classified by canUseExternalProofForRequirement().
  const listingBoundHardRequirements = getListingBoundHardRequirements(parsed);

  // V34.CORE136 STRICT BOUND COLOR PROOF
  // Colour is a per-offer/configuration fact. Do not let broad HTML feature
  // text prove it because recommendation widgets, sibling variants and hidden
  // page payloads can contain another colour. Only the exact verified title,
  // bound Product/Offer description, trusted filtered catalog/card evidence,
  // or canonical concrete-product HARD extraction may satisfy it.
  const strictBoundColorRequirements = listingBoundHardRequirements.filter(
    (requirement) => requirement.kind === "color" || requirement.key === "color"
  );
  const strictBoundColorEvidence = normalizeText(
    `${universalVerifiedIdentityTitle} ${trustedBoundProductDescription} ${trustedCatalogRequirementEvidence} ${trustedRetailerCardHardRequirementEvidence} ${trustedCanonicalConcreteRequirementEvidence}`
  );
  const missingStrictBoundColorRequirements = strictBoundColorRequirements.filter(
    (requirement) => !requirementHasEvidence(requirement, strictBoundColorEvidence)
  );
  if (missingStrictBoundColorRequirements.length > 0) {
    console.log(
      "[AIShopping] V34.CORE136 reject strict bound color not proven:",
      finalUrl,
      missingStrictBoundColorRequirements.map((item) => item.label)
    );
    return null;
  }

  const listingBoundEvidence = normalizeText(
    `${universalVerifiedIdentityTitle} ${trustedBoundProductDescription} ${trustedCatalogRequirementEvidence} ${trustedVerifiedDescription} ${universalFeatureEvidence}`
  );
  const missingListingBoundRequirements = listingBoundHardRequirements.filter(
    (requirement) => !requirementHasEvidence(requirement, listingBoundEvidence)
  );
  if (missingListingBoundRequirements.length > 0) {
    console.log(
      "[AIShopping] V34.CORE120 reject listing-bound requirement not proven:",
      finalUrl,
      missingListingBoundRequirements.map((item) => item.label)
    );
    return null;
  }

  // HARD SAFETY GATE: every hard user requirement must be proven by the
  // concrete listing or by allowed exact-model independent evidence before the
  // offer can continue. Never rely on the later relevance score to enforce a
  // hard attribute. This prevents false positives such as a generic robot
  // listing satisfying "mapowanie" because an unrelated page token happened
  // to contain the substring "map".
  if (!preProofUniversalMatch.pass) {
    console.log(
      "[AIShopping] V34.CORE120 reject hard universal requirements not proven:",
      finalUrl,
      preProofUniversalMatch.reasons,
      "missing=",
      preProofUniversalMatch.missingRequirements
    );
    return null;
  }

  // Aggregators can contain neighbouring-product snippets. For externally
  // provable model/spec attributes, do not trust unrelated text from the same
  // page unless the exact title itself proves the attribute or independent
  // exact-model evidence proves it.
  if (sourceRequiresIndependentRequirementProof(finalUrl)) {
    const titleEvidence = normalizeMatchText(`${result.name} ${finalName} ${finalUrl}`);
    const unprovenOnAggregator = externallyProvableRequirements.filter(
      (requirement) =>
        !requirementHasEvidence(requirement, titleEvidence) &&
        !requirementHasEvidence(requirement, trustedCeneoExactRequirementEvidence) &&
        !requirementHasEvidence(requirement, universalIndependentRequirementProof)
    );

    if (unprovenOnAggregator.length > 0) {
      console.log(
        "[AIShopping] V34.CORE120 reject aggregator attributes not independently proven:",
        finalUrl,
        unprovenOnAggregator.map((item) => item.label)
      );
      return null;
    }
  }

  // A concrete Ceneo product must retain a concrete product name. A generic
  // "Ceneo - porównanie cen..." title means the product page did not load
  // reliably enough to present as a verified offer.
  if (isCeneoResult && isGenericCeneoTitle(finalName)) {
    console.log(
      "[AIShopping] V34.CORE120 reject generic Ceneo product page:",
      finalUrl,
      finalName
    );
    return null;
  }

  const finalHost = getResultHostname(finalUrl);

  // V34.CORE120: a peer seller cannot independently prove authenticity, but an
  // exact, new, price-verified listing may still be useful as a caution result.
  // The originality/risk layer below the verifier keeps low-confidence offers
  // out of best/cheapest/safest recommendation pools when original=true.
  if (
    parsed.original === true &&
    parsed.category === "perfume" &&
    ["olx.pl", "allegrolokalnie.pl", "vinted.pl", "ebay.pl"].includes(finalHost)
  ) {
    console.log(
      "[AIShopping] V34.CORE120 hard-original perfume peer offer kept for caution-only originality scoring:",
      finalUrl
    );
  }

  const marketplaceRequiresExplicitCondition = [
    "olx.pl",
    "allegrolokalnie.pl",
    "allegro.pl",
    "vinted.pl",
  ].includes(finalHost);

  // Peer-to-peer/marketplace offers must prove the requested state. Never
  // label a private, condition-unknown listing as new merely because the user
  // asked for a new item. Normal retailer product pages remain eligible after
  // condition-aware price binding has excluded outlet/refurbished amounts.
  if (
    parsed.condition &&
    marketplaceRequiresExplicitCondition &&
    verifiedCondition !== parsed.condition
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject marketplace condition not proven:",
      finalUrl,
      "requested=",
      parsed.condition,
      "verified=",
      verifiedCondition
    );
    return null;
  }

  // ------------------------------------------------------------
  // C. Nadal nie mamy ceny -> oferta nie jest wiarygodna
  // ------------------------------------------------------------
  if (pricePln === null) {
    console.log(
      "[AIShopping] reject no price:",
      finalUrl,
      finalName
    );

    console.log(
      "[AIShopping] price debug:",
      JSON.stringify({
        name: finalName,
        snippet: result.snippet,
        url: finalUrl,
        searchPrice,
        pageFetched: Boolean(page),
        pageStatus: page?.status ?? null,
      })
    );

    return null;
  }



  const requestedTirePurchase = tirePriceIsPerPiece
    ? normalizeRequestedTirePurchasePrice(pricePln, deliveryCostPln, parsed)
    : null;
  const outputItemPricePln = requestedTirePurchase?.itemPrice ?? pricePln;
  const totalPricePln = requestedTirePurchase?.totalPrice ?? (
    deliveryCostPln !== null
      ? pricePln + deliveryCostPln
      : pricePln
  );

  // ------------------------------------------------------------
  // D. Budżet — jeśli znamy dostawę, limit użytkownika dotyczy pełnego kosztu.
  // ------------------------------------------------------------
  const finalBudgetComparable = budgetComparablePrice(
    totalPricePln,
    `${finalName} ${description} ${result.snippet}`,
    parsed
  );

  if (
    parsed.maxPrice !== null &&
    finalBudgetComparable.comparable > parsed.maxPrice
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject over total budget:",
      finalUrl,
      "item=",
      pricePln,
      "delivery=",
      deliveryCostPln,
      "total=",
      totalPricePln,
      "perPiece=",
      finalBudgetComparable.comparable,
      "pieces=",
      finalBudgetComparable.pieceCount,
      "max=",
      parsed.maxPrice
    );

    return null;
  }

  // ------------------------------------------------------------
  // E. Trafność produktu + V32.12 safety guard after full verification
  // ------------------------------------------------------------
  const verifiedConditionEvidence =
    verifiedCondition === "new"
      ? "Stan: Nowe"
      : verifiedCondition === "used"
        ? "Stan: Używane"
        : "";

  if (isGpuWholeSystemAfterVerification(finalName, description, finalUrl, parsed)) {
    console.log(
      "[AIShopping] V34.CORE120 reject verified GPU whole system:",
      finalUrl,
      "title=",
      finalName
    );
    return null;
  }

  if (isExplicitlyDamagedProduct(finalName, description, parsed)) {
    console.log(
      "[AIShopping] V34.CORE120 reject damaged/for-parts offer:",
      finalUrl,
      "title=",
      finalName
    );
    return null;
  }

  if (
    isPhoneAccessoryOrWrongVariant(
      finalName,
      description,
      finalUrl,
      parsed
    )
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject verified phone accessory/wrong variant:",
      finalUrl,
      "title=",
      finalName
    );
    return null;
  }

  if (
    await hasGenericPhoneManufacturerCodeSiblingConflict(
      finalName,
      `${description} ${universalFeatureEvidence}`,
      parsed,
      verificationSignal
    )
  ) {
    console.log(
      "[AIShopping] V34.CORE120 reject verified phone manufacturer-code sibling:",
      finalUrl,
      "title=",
      finalName
    );
    return null;
  }

  if (
    !isRelevantProduct(
      finalName,
      `${description} ${universalFeatureEvidence} ${verifiedConditionEvidence}`,
      parsed,
      finalUrl,
      pricePln,
      verifiedCondition,
      resolvedModelIdentityBridgeProof,
      verifiedTitleHardRequirements
    )
  ) {
    console.log(
      "[AIShopping] reject irrelevant:",
      finalUrl,
      "title=",
      finalName,
      "price=",
      pricePln
    );

    return null;
  }

  const relevance =
    calculateRelevance(
      finalName,
      `${description} ${universalFeatureEvidence} ${verifiedConditionEvidence}`,
      parsed,
      pricePln,
      finalUrl
    ) -
    getCountryPenalty(finalUrl, parsed.country) -
    result.searchRank * 0.8;



  const evidenceAssessment = buildOfferEvidenceSummary(
    Boolean(page && page.status >= 200 && page.status < 400 && !directPageBlocked) || readerPageVerified,
    priceVerified,
    universalIndependentRequirementProof,
    result,
    parsed,
    marketplaceIndexCard && marketplaceIndexBoundPrice.price !== null
  );

  return {
    id: 0,
    name: cleanTitle(finalName),
    store: detectStore(finalUrl),
    price: Math.round(outputItemPricePln * 100) / 100,
    currency: "PLN",
    rating: verifiedRating,
    condition:
      verifiedCondition === "new"
        ? "Nowy"
        : verifiedCondition === "used"
          ? "Używany"
          : parsed.condition === "new"
            ? "Nowy"
            : parsed.condition === "used"
              ? "Używany"
              : null,
    original: parsed.original,
    delivery:
      deliveryCostPln !== null
        ? formatDeliveryLabel(deliveryCostPln, "PLN")
        : verifiedShipping.label,
    category: parsed.category,
    platform: parsed.platform,
    brand: parsed.brand,
    url: finalUrl,
    description: normalizeText(description).slice(0, 700),
    priceVerified,
    availability,
    verification: priceVerified
      ? "verified"
      : "search-result",
    verificationTier: evidenceAssessment.tier,
    evidenceConfidence: evidenceAssessment.confidence,
    evidenceSummary: evidenceAssessment.summary,
    totalPrice: Math.round(totalPricePln * 100) / 100,
    comparisonPrice: Math.round(finalBudgetComparable.comparable * 100) / 100,
    comparisonUnit: parsed.intent.budgetPerPiece ? "per-piece" : "total",
    pieceCount: requestedTirePurchase?.pieceCount ?? finalBudgetComparable.pieceCount,
    relevance,
  };
}


type ExactModelStaticReferenceCandidate = {
  result: SearchResult;
  score: number;
};

function getExactModelStaticReferenceCandidateScore(
  result: SearchResult,
  parsed: ParsedQuery,
  exactModelAnchorRaw: string
): number {
  const exactModelAnchor = normalizeMatchText(exactModelAnchorRaw);
  if (!exactModelAnchor) return -1;

  const host = getResultHostname(result.url);
  if (!host) return -1;

  // A peer-marketplace listing is offer evidence, not a model-spec authority.
  // Prefer a concrete retailer/manufacturer product page for shared static
  // specs so one seller cannot make every other seller pass a hard spec.
  if (["olx.pl", "allegro.pl", "allegrolokalnie.pl", "vinted.pl", "ebay.pl", "amazon.pl", "erli.pl", "arena.pl"].includes(host)) {
    return -1;
  }

  const brandCompactForHostEarly = compactUniversalModelCode(parsed.brand ?? "");
  const hostCompactForBrandEarly = compactUniversalModelCode(host);
  const officialBrandHostEarly =
    Boolean(brandCompactForHostEarly) &&
    brandCompactForHostEarly.length >= 3 &&
    hostCompactForBrandEarly.includes(brandCompactForHostEarly);
  const staticReferenceLike =
    isProbablyExactModelStaticReferenceUrl(result.url) ||
    officialBrandHostEarly ||
    isConfiguredCommerceDomain(result.url);
  if (!staticReferenceLike) return -1;
  if (
    !officialBrandHostEarly &&
    isProbablyRealOfferUrl(result.url) &&
    isLikelyOpenWorldCategoryOrCollectionResult(result, parsed)
  ) {
    return -1;
  }

  const scope = normalizeText(`${result.name} ${result.snippet} ${result.url}`);
  if (!titleContainsUniversalModelCode(scope, exactModelAnchor)) return -1;

  const brand = normalizeMatchText(parsed.brand ?? "");
  const normalizedScope = normalizeMatchText(scope);
  if (
    brand &&
    !universalEvidenceHasBoundedIdentityTerm(brand, normalizedScope) &&
    !normalizedScope.replace(/[^a-z0-9]+/g, "").includes(
      brand.replace(/[^a-z0-9]+/g, "")
    )
  ) {
    return -1;
  }

  if (hasUniversalVariantMismatch(result.name, parsed)) return -1;
  if (getUniversalQualifierFamilyConflict(result.name, parsed)) return -1;

  let score = 0;
  const brandCompactForHost = compactUniversalModelCode(parsed.brand ?? "");
  const hostCompactForBrand = compactUniversalModelCode(host);
  const officialBrandHost =
    Boolean(brandCompactForHost) &&
    brandCompactForHost.length >= 3 &&
    hostCompactForBrand.includes(brandCompactForHost);

  if (officialBrandHost) score += 50;
  if (isConfiguredCommerceDomain(result.url)) score += 40;
  if (isConcreteIndependentProductReferenceUrl(result.url, parsed)) score += 30;
  if (result.source === "RetailerRescue") score += 12;
  if (host === "ceneo.pl") score -= 15; // aggregator: usable, but not first choice
  if (titleContainsUniversalModelCode(result.name, exactModelAnchor)) score += 18;
  if (normalizeMatchText(result.name).includes(brand) && brand) score += 8;
  score -= Math.min(10, Math.max(0, result.searchRank));
  return score;
}

function selectExactModelStaticReferenceCandidate(
  results: SearchResult[],
  parsed: ParsedQuery
): ExactModelStaticReferenceCandidate | null {
  const phrase = buildUniversalProofPhrase(
    parsed.intent.productPhrase || parsed.intent.searchBase,
    parsed
  );
  const exactModelAnchor = getUniversalExactModelAnchor(parsed, phrase);
  if (!exactModelAnchor) return null;

  const ranked = results
    .map((result) => ({
      result,
      score: getExactModelStaticReferenceCandidateScore(
        result,
        parsed,
        exactModelAnchor
      ),
    }))
    .filter((item) => item.score >= 0)
    .sort((a, b) => b.score - a.score || a.result.searchRank - b.result.searchRank);

  return ranked[0] ?? null;
}

async function buildSharedExactModelStaticProofFromVerificationCandidates(
  results: SearchResult[],
  parsed: ParsedQuery,
  hardDeadlineAt: number
): Promise<string> {
  const requirements = parsed.intent.required
    .filter((requirement) => requirement.hard)
    .filter(canUseExternalProofForRequirement);
  if (requirements.length === 0) return "";

  const phrase = buildUniversalProofPhrase(
    parsed.intent.productPhrase || parsed.intent.searchBase,
    parsed
  );
  const exactModelAnchor = getUniversalExactModelAnchor(parsed, phrase);
  if (!exactModelAnchor) return "";

  const indexedConsensus = collectUniversalRequirementProofFromSearchResults(
    results,
    requirements,
    parsed,
    phrase,
    exactModelAnchor
  );
  const indexedProof = normalizeText(indexedConsensus.chunks.join(" ")).slice(0, 20_000);
  const indexedComplete = requirements.every((requirement) =>
    indexedConsensus.provenKeys.has(requirement.key) ||
    requirementHasEvidence(requirement, indexedProof)
  );
  if (indexedComplete) {
    console.log("[AIShopping] V34.CORE120 verification-model profile ready from evidence graph:", {
      anchor: exactModelAnchor,
      provedKeys: Array.from(indexedConsensus.provenKeys),
      sources: indexedConsensus.sources,
    });
    return indexedProof;
  }

  const selected = selectExactModelStaticReferenceCandidate(results, parsed);
  if (!selected) {
    console.log("[AIShopping] V34.CORE120 verification-model profile: no concrete exact-model reference candidate", {
      indexedKeys: Array.from(indexedConsensus.provenKeys),
    });
    return indexedProof;
  }

  const remaining = Math.max(
    0,
    hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
  );
  if (remaining < 1_600) return "";

  const referenceBudgetMs = Math.min(4_900, Math.max(1_600, remaining - 700));
  console.log("[AIShopping] V34.CORE120 verification-model profile start:", {
    host: getResultHostname(selected.result.url),
    url: selected.result.url,
    score: selected.score,
    anchor: exactModelAnchor,
    keys: requirements.map((item) => item.key),
    budgetMs: referenceBudgetMs,
  });

  // Start the reader immediately. This promise is created before verification
  // workers, so it gets an early Jina slot instead of waiting behind 3-4 OLX
  // readers. It is a spec-only reference; price/condition are never borrowed.
  const text = await withAbortableDeadline(
    (signal) => fetchViaJina(
      selected.result.url,
      Math.min(4_400, referenceBudgetMs),
      false,
      signal
    ),
    referenceBudgetMs,
    "",
    `verification exact-model static reference ${selected.result.url}`
  );

  if (!text || isBlockedOrChallengePage(text)) return "";

  const pageTitle = extractJinaPageTitle(text) || selected.result.name;
  const titleScope = normalizeText(`${pageTitle} ${selected.result.name} ${selected.result.url}`);
  if (!titleContainsUniversalModelCode(titleScope, exactModelAnchor)) return "";
  if (hasUniversalVariantMismatch(pageTitle, parsed)) return "";
  if (getUniversalQualifierFamilyConflict(pageTitle, parsed)) return "";

  const brand = normalizeMatchText(parsed.brand ?? "");
  const titleScopeNormalized = normalizeMatchText(titleScope);
  if (
    brand &&
    !universalEvidenceHasBoundedIdentityTerm(brand, titleScopeNormalized) &&
    !titleScopeNormalized.replace(/[^a-z0-9]+/g, "").includes(
      brand.replace(/[^a-z0-9]+/g, "")
    )
  ) {
    return "";
  }

  const boundedScope = getBoundedUniversalModelReferenceScope(
    text,
    phrase,
    exactModelAnchor
  );
  if (!boundedScope) return "";

  const hydratedRequirements = requirements.filter((requirement) =>
    requirementHasEvidence(requirement, boundedScope)
  );
  const mergedKeys = new Set<string>([
    ...indexedConsensus.provenKeys,
    ...hydratedRequirements.map((item) => item.key),
  ]);
  if (mergedKeys.size === 0) return indexedProof;

  const canonicalTail = requirements
    .filter((requirement) => mergedKeys.has(requirement.key))
    .map(buildCanonicalRequirementProofToken)
    .join(" ");
  const proof = normalizeText(`${indexedProof} ${boundedScope} ${canonicalTail}`).slice(0, 30_000);
  console.log("[AIShopping] V34.CORE120 verification-model profile ready:", {
    host: getResultHostname(selected.result.url),
    anchor: exactModelAnchor,
    provedKeys: Array.from(mergedKeys),
  });
  return proof;
}

function hasHighValueNoPriceMarketplaceVerification(
  results: SearchResult[],
  parsed: ParsedQuery
): boolean {
  const requestedBrandAliases = getUniversalRequestedBrandAliases(parsed);

  return results.some((result) => {
    const host = getResultHostname(result.url);
    if (!["olx.pl", "allegro.pl", "allegrolokalnie.pl", "vinted.pl"].includes(host)) {
      return false;
    }
    if (!isProbablyRealOfferUrl(result.url)) return false;

    const discoveryPrice = getSilentDiscoveryPrice(result, parsed);
    if (discoveryPrice.price !== null && discoveryPrice.currency) return false;

    const title = normalizeMatchText(result.name);
    if (!title) return false;

    // CORE56: an unknown marketplace condition is a reason to VERIFY the
    // concrete listing, not a reason to deny it enough verification time.
    // Only an explicit opposite condition removes scheduling pressure. Final
    // acceptance below still requires the requested condition to be proven by
    // listing-bound evidence, so this changes latency allocation only.
    if (parsed.condition !== null) {
      const conflictingCondition: Condition =
        parsed.condition === "new" ? "used" : "new";
      if (
        hasExplicitRequestedConditionInTitle(
          result.name,
          conflictingCondition
        )
      ) {
        return false;
      }
    }

    // Do not spend the longer slow-reader window on a merely generic
    // marketplace card. Require a strong URL-bound product identity: either
    // an exact-model anchor or the generic named-product anchor used by the
    // universal discovery gate. This keeps the scheduling change cross-
    // category while preventing broad no-price marketplace results from
    // starving normal recovery.
    const phrase = normalizeText(
      parsed.intent.productPhrase || parsed.intent.searchBase || parsed.queryText
    );
    const exactModelAnchor = getUniversalExactModelAnchor(parsed, phrase);
    const exactModelBound = Boolean(
      exactModelAnchor &&
      titleContainsUniversalModelCode(
        `${result.name} ${result.url}`,
        exactModelAnchor
      )
    );
    const namedProductBound = hasSafeUniversalNamedProductAnchor(
      result.name,
      result.url,
      parsed,
      result.source
    );

    const hardRequirements = parsed.intent.required.filter((item) => item.hard);
    const ownHardComplete =
      hardRequirements.length > 0 &&
      hardRequirements.every((requirement) =>
        requirementHasEvidenceInContext(
          requirement,
          normalizeText(`${result.name} ${result.url}`),
          parsed.intent.required
        )
      );
    const strongIdentityHits = parsed.intent.strongIdentityTerms.filter((term) =>
      phraseMorphologicallyMatches(term, title) ||
      automotiveLexicalTermMatches(term, title)
    ).length;
    const strongIdentityBound = parsed.intent.strongIdentityTerms.length === 0 ||
      strongIdentityHits >= Math.min(
        parsed.intent.strongIdentityTerms.length,
        Math.max(2, Math.ceil(parsed.intent.strongIdentityTerms.length * 0.6))
      );

    if (!exactModelBound && !namedProductBound && !(ownHardComplete && strongIdentityBound)) {
      return false;
    }

    if (
      requestedBrandAliases.length > 0 &&
      !requestedBrandAliases.some((alias) =>
        phraseMorphologicallyMatches(alias, title) ||
        automotiveLexicalTermMatches(alias, title)
      )
    ) {
      return false;
    }

    if (
      parsed.original === true &&
      !/\b(?:oryginal\w*|orginal\w*|original|genuine)\b/iu.test(result.name)
    ) {
      return false;
    }

    return true;
  });
}


function isLikelyTransientMarketplaceReaderTimeout(
  host: string,
  elapsedMs: number,
  configuredTimeoutMs: number,
  receivedText: boolean
): boolean {
  if (receivedText) return false;
  if (host !== "olx.pl" && host !== "allegrolokalnie.pl") return false;

  // Immediate HTTP rejects/404s are not worth retrying. A retry marker is set
  // only when the attempt consumed a substantial share of the configured
  // reader window (or was aborted near the first-wave deadline).
  const thresholdMs = Math.min(
    3_500,
    Math.max(1_800, configuredTimeoutMs - 1_200)
  );
  return elapsedMs >= thresholdMs;
}

function getLateTransientMarketplaceRetryWindowMs(remainingMs: number): number {
  if (remainingMs < LATE_TRANSIENT_MARKETPLACE_RETRY_MIN_REMAINING_MS) return 0;
  return Math.min(
    LATE_TRANSIENT_MARKETPLACE_RETRY_MAX_WINDOW_MS,
    Math.max(
      0,
      remainingMs - LATE_TRANSIENT_MARKETPLACE_RETRY_ROUTE_RESERVE_MS
    )
  );
}

function selectLateTransientMarketplaceRetryCandidates(
  results: SearchResult[],
  parsed: ParsedQuery
): SearchResult[] {
  const requestedBrandAliases = getUniversalRequestedBrandAliases(parsed);
  const hardRequirements = parsed.intent.required.filter((item) => item.hard);
  const phrase = normalizeText(
    parsed.intent.productPhrase || parsed.intent.searchBase || parsed.queryText
  );
  const exactModelAnchor = getUniversalExactModelAnchor(parsed, phrase);

  return results
    .filter((result) => {
      if (result.transientMarketplaceReaderTimeout !== true) return false;

      const host = getResultHostname(result.url);
      if (host !== "olx.pl" && host !== "allegrolokalnie.pl") return false;
      if (!isProbablyRealOfferUrl(result.url)) return false;

      // A late retry is intentionally narrower than the first-wave pressure
      // heuristic. Every listing-bound HARD attribute that can be present in
      // the title must already be explicitly proven there. This is what keeps
      // a size-only candidate from stealing a second read from a candidate
      // whose own title says both the requested size and requested color.
      const titleEvidence = normalizeMatchText(result.name);
      if (
        hardRequirements.some(
          (requirement) => !requirementHasEvidence(requirement, titleEvidence)
        )
      ) {
        return false;
      }

      if (parsed.condition !== null) {
        const conflictingCondition: Condition =
          parsed.condition === "new" ? "used" : "new";
        if (
          hasExplicitRequestedConditionInTitle(
            result.name,
            conflictingCondition
          )
        ) {
          return false;
        }
      }

      const exactModelBound = Boolean(
        exactModelAnchor &&
        titleContainsUniversalModelCode(result.name, exactModelAnchor)
      );
      const namedProductBound = hasSafeUniversalNamedProductAnchor(
        result.name,
        result.url,
        parsed,
        result.source
      );
      const genericCategoryTitleBound = Boolean(
        !exactModelAnchor &&
        hardRequirements.length > 0 &&
        parsed.category &&
        hasUniversalCategoryEvidence(result.name, parsed)
      );
      // The late lane is intentionally TITLE-bound. An exact-model query may
      // not borrow its model anchor from the URL while the visible title names
      // a sibling exact model. For a brandless generic category query there may
      // be no named-product/model anchor at all; in that case category evidence
      // is safe only because EVERY hard listing attribute was already proven
      // from this same title above. Ordinary discovery can be more exploratory;
      // a second network attempt cannot.
      if (
        exactModelAnchor
          ? !exactModelBound
          : !(namedProductBound || genericCategoryTitleBound)
      ) return false;

      if (
        requestedBrandAliases.length > 0 &&
        !requestedBrandAliases.some((alias) =>
          phraseMorphologicallyMatches(alias, titleEvidence) ||
          automotiveLexicalTermMatches(alias, titleEvidence)
        )
      ) {
        return false;
      }

      if (
        parsed.original === true &&
        !/\b(?:oryginal\w*|orginal\w*|original|genuine)\b/iu.test(result.name)
      ) {
        return false;
      }

      return evaluateUniversalProductMatch(
        result.name,
        result.snippet,
        result.url,
        parsed,
        "discovery",
        result.source
      ).pass;
    })
    .sort((a, b) => {
      const priorityDiff =
        getSearchResultPriority(b, parsed) - getSearchResultPriority(a, parsed);
      if (priorityDiff !== 0) return priorityDiff;
      return a.searchRank - b.searchRank;
    })
    .slice(0, 1);
}


const MAX_SLOW_OLX_READER_CANDIDATES = 2;
const MAX_SLOW_ALLEGRO_LOKALNIE_READER_CANDIDATES = 2;

// V34.CORE120: expensive peer-marketplace readers remain tightly bounded, but
// the cap now preserves two different objectives instead of blindly keeping
// the first N queue entries. One slot keeps the strongest already-sorted
// candidate; one slot explores the cheapest other trusted card-bound price
// that is still inside the user's budget and has no known condition conflict.
// This improves cheapest-offer recall without adding reader calls, changing
// the hard route budget, or weakening final condition/requirement verification.
function capSlowMarketplaceReaderCandidates(
  queue: SearchResult[],
  parsed: ParsedQuery
): SearchResult[] {
  type SlowHostState = {
    indexes: number[];
    limit: number;
    host: "olx.pl" | "allegrolokalnie.pl";
  };

  const slowHosts: Record<"olx.pl" | "allegrolokalnie.pl", SlowHostState> = {
    "olx.pl": {
      indexes: [],
      limit: MAX_SLOW_OLX_READER_CANDIDATES,
      host: "olx.pl",
    },
    "allegrolokalnie.pl": {
      indexes: [],
      limit: MAX_SLOW_ALLEGRO_LOKALNIE_READER_CANDIDATES,
      host: "allegrolokalnie.pl",
    },
  };

  const alwaysKeep = new Set<number>();

  const getKnownMarketplaceCondition = (
    result: SearchResult,
    host: "olx.pl" | "allegrolokalnie.pl"
  ): Condition => {
    if (host === "olx.pl") {
      return extractOlxDirectBoundCondition(
        `${result.name} ${result.snippet}`,
        result.name
      );
    }

    const card =
      extractMarketplaceCardContext(
        `${result.name} ${result.snippet}`,
        result.name,
        1900
      ) || `${result.name} ${result.snippet}`;
    const cardCondition = extractTrustedConditionFromText(card);
    if (cardCondition) return cardCondition;

    if (hasExplicitRequestedConditionInTitle(result.name, "new")) return "new";
    if (hasExplicitRequestedConditionInTitle(result.name, "used")) return "used";
    return null;
  };

  const candidateNeedsSlowReader = (
    result: SearchResult,
    host: "olx.pl" | "allegrolokalnie.pl"
  ): boolean => {
    const price = getSilentDiscoveryPrice(result, parsed);
    const hardRequirements = parsed.intent.required.filter((item) => item.hard);
    const cardEvidence = normalizeMatchText(
      `${result.name} ${result.url} ${result.snippet}`
    );
    const missingHardRequirement = hardRequirements.some(
      (requirement) => !requirementHasEvidence(requirement, cardEvidence)
    );
    const knownCondition = getKnownMarketplaceCondition(result, host);
    const conditionNeedsReader = Boolean(parsed.condition && !knownCondition);

    return (
      price.price === null ||
      missingHardRequirement ||
      conditionNeedsReader
    );
  };

  for (let index = 0; index < queue.length; index += 1) {
    const result = queue[index];
    const host = getResultHostname(result.url);

    if (host !== "olx.pl" && host !== "allegrolokalnie.pl") {
      alwaysKeep.add(index);
      continue;
    }

    if (!candidateNeedsSlowReader(result, host)) {
      alwaysKeep.add(index);
      continue;
    }

    slowHosts[host].indexes.push(index);
  }

  const selectedSlow = new Set<number>();
  const priceExploration: Array<{
    host: string;
    price: number;
    name: string;
  }> = [];

  for (const state of Object.values(slowHosts)) {
    const { indexes, limit, host } = state;
    if (indexes.length === 0) continue;

    if (indexes.length <= limit) {
      indexes.forEach((index) => selectedSlow.add(index));
      continue;
    }

    // Quality slot: preserve the candidate that already carries the strongest
    // trusted HARD footprint. Queue order remains the deterministic tie-breaker.
    // This prevents a generic same-brand card from crowding out a listing whose
    // own title already proves a requested quantity/spec threshold.
    const qualityIndex = [...indexes].sort((a, b) =>
      getTrustedPortfolioHardCoverageScore(queue[b], parsed) -
        getTrustedPortfolioHardCoverageScore(queue[a], parsed) ||
      a - b
    )[0];
    selectedSlow.add(qualityIndex);

    if (limit > 1) {
      let cheapestIndex: number | null = null;
      let cheapestComparable = Number.POSITIVE_INFINITY;

      for (const index of indexes) {
        if (index === qualityIndex) continue;

        const result = queue[index];
        const knownCondition = getKnownMarketplaceCondition(result, host);
        if (
          parsed.condition &&
          knownCondition &&
          knownCondition !== parsed.condition
        ) {
          continue;
        }

        const price = getSilentDiscoveryPrice(result, parsed);
        if (
          price.price === null ||
          normalizeMatchText(price.currency ?? "") !== "pln"
        ) {
          continue;
        }

        const comparable = budgetComparablePrice(
          price.price,
          `${result.name} ${result.snippet}`,
          parsed
        ).comparable;

        if (parsed.maxPrice !== null && comparable > parsed.maxPrice) {
          continue;
        }

        if (
          comparable < cheapestComparable ||
          (comparable === cheapestComparable &&
            (cheapestIndex === null || index < cheapestIndex))
        ) {
          cheapestComparable = comparable;
          cheapestIndex = index;
        }
      }

      if (cheapestIndex !== null) {
        selectedSlow.add(cheapestIndex);
        const price = getSilentDiscoveryPrice(queue[cheapestIndex], parsed);
        priceExploration.push({
          host,
          price: price.price ?? cheapestComparable,
          name: queue[cheapestIndex].name,
        });
      }
    }

    // If the quality + price objectives did not fill the host cap (for example
    // all remaining cards have no safe bound price), keep the next strongest
    // queue entries exactly as CORE47 did.
    let selectedForHost = indexes.filter((candidateIndex) =>
      selectedSlow.has(candidateIndex)
    ).length;
    for (const index of indexes) {
      if (selectedForHost >= limit) break;
      if (selectedSlow.has(index)) continue;
      selectedSlow.add(index);
      selectedForHost += 1;
    }
  }

  const limited = queue.filter(
    (_result, index) => alwaysKeep.has(index) || selectedSlow.has(index)
  );

  const droppedOlx =
    slowHosts["olx.pl"].indexes.length -
    slowHosts["olx.pl"].indexes.filter((index) => selectedSlow.has(index)).length;
  const droppedAllegroLokalnie =
    slowHosts["allegrolokalnie.pl"].indexes.length -
    slowHosts["allegrolokalnie.pl"].indexes.filter((index) =>
      selectedSlow.has(index)
    ).length;

  if (droppedOlx > 0 || droppedAllegroLokalnie > 0) {
    console.log(
      "[AIShopping] V34.CORE120 bounded slow marketplace readers:",
      {
        before: queue.length,
        after: limited.length,
        droppedOlx,
        droppedAllegroLokalnie,
        priceExploration,
      }
    );
  }

  return limited;
}

async function verifyOffers(
  results: SearchResult[],
  parsed: ParsedQuery,
  hardDeadlineAt: number,
  staticReferenceCandidates: SearchResult[] = [],
  prefetchedExactModelStaticProofPromise: Promise<string> | null = null
): Promise<Offer[]> {
  const verified: Offer[] = [];
  let cursor = 0;

  // V32.12: Ceneo product pages are aggregators, not stores. Expand selected
  // concrete Ceneo products into their merchant rows before verification so
  // the final UI shows actual sellers, item price and delivery. The expansion
  // reuses one already-selected product page and stays inside the hard route
  // deadline; if Ceneo exposes no merchant cards we keep the old fallback.
  const merchantExpandedResults = await expandCeneoMerchantVerificationCandidates(
    results,
    parsed,
    hardDeadlineAt
  );

  // V32.12 executes the already-selected diverse batch in cost-aware order.
  // Retailer pages and marketplace cards with their own visible price go first;
  // no-price OLX listings stay as fallbacks instead of monopolising the first
  // seconds of verification. Priority and discovery-price evidence are computed
  // once per candidate; Array.sort() must never rerun expensive parsers.
  const preparationStartedAt = Date.now();
  const priorityCache = new WeakMap<SearchResult, number>();
  const priorityOf = (result: SearchResult): number => {
    const cached = priorityCache.get(result);
    if (cached !== undefined) return cached;
    const score = getSearchResultPriority(result, parsed);
    priorityCache.set(result, score);
    return score;
  };
  const costTier = (result: SearchResult): number => {
    const host = getResultHostname(result.url);

    // V34.CORE184 DETERMINISTIC SIBLING FIRST-WAVE: once a concrete sibling
    // route has already earned the single CORE183 portfolio reserve, do not
    // let duplicate same-host retailer pages consume all initial workers ahead
    // of it. This changes scheduling only: no donor price/HARD/availability is
    // inherited and verifySearchResult() remains fully fail-closed.
    const isDeterministicSiblingRoute =
      isV34Core164PreciseTechIntent(parsed) &&
      Boolean(host) &&
      V34_CORE183_DETERMINISTIC_SIBLING_ROUTE_HOSTS.includes(host) &&
      normalizeMatchText(result.snippet).includes(
        "deterministic sibling catalog route"
      );

    if (isDeterministicSiblingRoute) return -1;

    if (host === "allegrolokalnie.pl") {
      const discoveryPrice = getSilentDiscoveryPrice(result, parsed);
      const boundedCard =
        extractMarketplaceCardContext(
          `${result.name} ${result.snippet}`,
          result.name,
          1900
        ) || `${result.name} ${result.snippet}`;
      const cardCondition = extractTrustedConditionFromText(boundedCard);
      const titleCondition: Condition =
        hasExplicitRequestedConditionInTitle(result.name, "new")
          ? "new"
          : hasExplicitRequestedConditionInTitle(result.name, "used")
            ? "used"
            : null;
      const conditionProven =
        parsed.condition === null ||
        cardCondition === parsed.condition ||
        titleCondition === parsed.condition;

      // A bound price + proven condition is nearly free. An otherwise good
      // Allegro Lokalnie card needs the same scarce Jina reader used by OLX,
      // so do not let it take the first reader slot ahead of stronger OLX
      // listings when another already-proven Allegro Lokalnie offer exists.
      return discoveryPrice.price !== null && conditionProven ? 0 : 3;
    }

    if (host !== "olx.pl") {
      const requestedBrandAliases = getUniversalRequestedBrandAliases(parsed);
      if (requestedBrandAliases.length === 0) return 0;
      const title = normalizeMatchText(result.name);
      const requestedBrandInTitle = requestedBrandAliases.some((alias) =>
        phraseMorphologicallyMatches(alias, title) || automotiveLexicalTermMatches(alias, title)
      );
      // Scheduling only: brand-ambiguous retailer cards remain eligible, but
      // they cannot take the first worker wave ahead of a candidate whose own
      // title already names the requested manufacturer.
      return requestedBrandInTitle ? 0 : 1;
    }

    const olxDiscoveryPrice = getSilentDiscoveryPrice(result, parsed);
    const olxBoundCondition = extractOlxDirectBoundCondition(
      `${result.name} ${result.snippet}`,
      result.name
    );
    const olxCardEvidence = normalizeMatchText(
      `${result.name} ${result.url} ${result.snippet}`
    );
    const olxHardRequirementsProven = parsed.intent.required
      .filter((item) => item.hard)
      .every((requirement) => requirementHasEvidence(requirement, olxCardEvidence));
    const olxConditionProven =
      parsed.condition === null || olxBoundCondition === parsed.condition;

    // V34.CORE120 structured OLX JSON cards are cheaper than a retailer page:
    // when one atomic listing object already proves price + requested state +
    // every listing-specific hard requirement, verification does not need Jina.
    if (
      olxDiscoveryPrice.price !== null &&
      olxDiscoveryPrice.currency &&
      olxConditionProven &&
      olxHardRequirementsProven
    ) return 0;
    if (olxDiscoveryPrice.price !== null && olxDiscoveryPrice.currency) return 1;

    if (isLikelyMultiProductExactModelResult(result, parsed)) return 4;

    const requestedConditionInTitle =
      parsed.condition === null ||
      hasExplicitRequestedConditionInTitle(result.name, parsed.condition);
    const requestedBrandAliases = getUniversalRequestedBrandAliases(parsed);
    const title = normalizeMatchText(result.name);
    const requestedBrandInTitle =
      requestedBrandAliases.length === 0 ||
      requestedBrandAliases.some((alias) =>
        phraseMorphologicallyMatches(alias, title) || automotiveLexicalTermMatches(alias, title)
      );

    // Scheduling only: if the listing's OWN evidence already proves every HARD
    // requirement and the requested brand identity is present, it gets the first
    // slow-reader slot. A generic same-brand title without the HARD footprint is
    // deliberately one tier lower. Final acceptance is unchanged/fail-closed.
    if (olxHardRequirementsProven && requestedBrandInTitle) return 0;
    if (olxHardRequirementsProven) return 1;
    const requestedOriginalityInTitle =
      parsed.original !== true ||
      /\b(?:oryginal\w*|orginal\w*|original|genuine)\b/iu.test(result.name);

    // A peer-marketplace card that states every high-value identity signal in
    // its own title deserves the first reader wave. This fixes the previous
    // cost-only ordering where six fast wrong-brand retailer cards could starve
    // one exact Sony/new/original OLX offer until the global deadline.
    if (requestedConditionInTitle && requestedBrandInTitle && requestedOriginalityInTitle) return 1;
    if (requestedConditionInTitle && requestedBrandInTitle) return 2;
    return isSlowNoPriceOlxDiscoveryResult(result, parsed) ? 3 : 2;
  };

  const verificationQueueUnbounded = [...merchantExpandedResults].sort((a, b) => {
    const tierDiff = costTier(a) - costTier(b);
    if (tierDiff !== 0) return tierDiff;

    const priorityDiff = priorityOf(b) - priorityOf(a);
    if (priorityDiff !== 0) return priorityDiff;

    // V34.CORE120 secondary tie-breaker. Only already card-bound discovery
    // prices participate; unknown prices retain their old search-rank order.
    // This does not bypass product-page verification or reject any candidate.
    const aPrice = getSilentDiscoveryPrice(a, parsed);
    const bPrice = getSilentDiscoveryPrice(b, parsed);
    const aComparable =
      aPrice.price !== null && normalizeMatchText(aPrice.currency ?? "") === "pln"
        ? budgetComparablePrice(aPrice.price, `${a.name} ${a.snippet}`, parsed).comparable
        : null;
    const bComparable =
      bPrice.price !== null && normalizeMatchText(bPrice.currency ?? "") === "pln"
        ? budgetComparablePrice(bPrice.price, `${b.name} ${b.snippet}`, parsed).comparable
        : null;

    if (parsed.maxPrice !== null) {
      const aFit = aComparable !== null ? Number(aComparable <= parsed.maxPrice) : -1;
      const bFit = bComparable !== null ? Number(bComparable <= parsed.maxPrice) : -1;
      if (aFit !== bFit) return bFit - aFit;
    }
    if (aComparable !== null && bComparable !== null && aComparable !== bComparable) {
      return aComparable - bComparable;
    }
    if ((aComparable !== null) !== (bComparable !== null)) {
      return aComparable !== null ? -1 : 1;
    }

    return a.searchRank - b.searchRank;
  });

  const verificationQueue = capSlowMarketplaceReaderCandidates(
    verificationQueueUnbounded,
    parsed
  );

  // V34.CORE120: discovery itself may already have found a concrete retailer
  // page for the exact requested model. Read that one page once and let every
  // verification worker reuse its STATIC model facts. This closes the gap where
  // search-based proof returned an empty snippet mesh even though a perfect
  // exact-model retailer page was sitting in the verification queue.
  const sharedReferencePool = dedupeSearchResultsByUrl([
    ...staticReferenceCandidates,
    ...merchantExpandedResults,
    ...verificationQueue,
  ]);

  let verificationReferenceProofPromise: Promise<string> | null = null;
  const getVerificationReferenceProof = (): Promise<string> => {
    if (!verificationReferenceProofPromise) {
      verificationReferenceProofPromise =
        buildSharedExactModelStaticProofFromVerificationCandidates(
          sharedReferencePool,
          parsed,
          hardDeadlineAt
        );
    }
    return verificationReferenceProofPromise;
  };

  // V34.CORE120: preserve the request-start proof Promise itself. A worker must
  // never rebuild a weaker model phrase from seller grammar after a correct
  // exact-model prefetch has already started. Only start the concrete
  // retailer/manufacturer reader if the request-start proof is incomplete.
  const sharedExactModelStaticProofPromise = (async () => {
    const prefetchedProof = await (
      prefetchedExactModelStaticProofPromise ?? Promise.resolve("")
    );

    const sharedStaticRequirements = parsed.intent.required
      .filter((requirement) => requirement.hard)
      .filter(canUseExternalProofForRequirement);

    const prefetchComplete =
      Boolean(prefetchedProof) &&
      sharedStaticRequirements.every((requirement) =>
        requirementHasEvidence(requirement, prefetchedProof)
      );

    if (prefetchComplete) {
      console.log(
        "[AIShopping] V34.CORE120 verification-model profile: request-start prefetch complete",
        sharedStaticRequirements.map((item) => item.key)
      );
      return prefetchedProof;
    }

    const referenceProof = await getVerificationReferenceProof();
    return normalizeText(`${prefetchedProof} ${referenceProof}`).slice(0, 36_000);
  })();

  const verificationHosts = new Set(
    verificationQueue
      .map((result) => getResultHostname(result.url))
      .filter(Boolean)
  );

  const allCandidatesAreOlx =
    verificationQueue.length > 0 &&
    verificationHosts.size === 1 &&
    verificationHosts.has("olx.pl");

  // OLX is internally rate-limited by waitForJinaStartSlot(), so more workers
  // do not create a request burst. They only avoid a second worker wave that
  // used to start too late to finish before the 20 s route deadline.
  const allCandidatesAreConditionSensitiveAllegroLokalnie =
    parsed.condition !== null &&
    verificationHosts.size === 1 &&
    verificationHosts.has("allegrolokalnie.pl");

  const workerCount =
    allCandidatesAreOlx
      // V34.CORE120: the slow-reader cap already keeps at most two expensive
      // OLX fallbacks. Two workers preserve fallback concurrency while the
      // stronger own-card HARD candidate is ordered first.
      ? Math.min(2, Math.max(verificationQueue.length, 1))
      : allCandidatesAreConditionSensitiveAllegroLokalnie
        // Condition-sensitive AL offers may require a concrete reader pass.
        // Keep a small same-host pool to avoid a burst that gets throttled.
        ? Math.min(3, Math.max(verificationQueue.length, 1))
        : Math.min(
            VERIFY_CONCURRENCY,
            Math.max(verificationQueue.length, 1)
          );

  console.log(
    "[AIShopping] V34.CORE120 verification scheduling:",
    {
      workers: workerCount,
      allCandidatesAreOlx,
      preparationMs: Date.now() - preparationStartedAt,
      remainingMs: Math.max(0, hardDeadlineAt - Date.now() - VERIFICATION_RESPONSE_SAFETY_MARGIN_MS),
      hosts: Array.from(verificationHosts),
      queue: verificationQueue.map((result) => ({
        host: getResultHostname(result.url),
        source: result.source,
        hasDiscoveryPrice:
          getSilentDiscoveryPrice(result, parsed).price !== null,
        name: result.name,
      })),
    }
  );

  // V32.12: withAbortableDeadline used to start before an OLX worker had
  // acquired the globally rate-limited Jina start slot. With several OLX
  // candidates, later workers could therefore spend most of their 4.8 s
  // budget merely waiting in the local reader queue and get aborted before
  // the HTTP response had a fair chance to arrive. Keep one hard route
  // deadline, but grant each OLX candidate a bounded queue-wait allowance.
  const olxReaderOrdinalByIndex = new Map<number, number>();
  let olxReaderOrdinal = 0;

  verificationQueue.forEach((result, index) => {
    if (getResultHostname(result.url) === "olx.pl") {
      olxReaderOrdinalByIndex.set(index, olxReaderOrdinal);
      olxReaderOrdinal += 1;
    }
  });

  const worker = async () => {
    while (true) {
      const remaining =
        hardDeadlineAt - Date.now() - VERIFICATION_RESPONSE_SAFETY_MARGIN_MS;

      if (remaining <= 0) return;

      const index = cursor++;
      if (index >= verificationQueue.length) return;

      try {
        const candidateHost =
          getResultHostname(verificationQueue[index]?.url ?? "");

        const olxOrdinal =
          candidateHost === "olx.pl"
            ? (olxReaderOrdinalByIndex.get(index) ?? 0)
            : 0;
        const readerQueueAllowanceMs =
          candidateHost === "olx.pl"
            ? Math.min(3_500, olxOrdinal * JINA_MIN_INTERVAL_MS)
            : 0;

        const perOfferBudget =
          candidateHost === "olx.pl"
            ? getOlxReaderBudgetProfile(parsed).perOfferBudgetMs +
              readerQueueAllowanceMs
            : parsed.intent.required.length > 0
              ? 8_500
              : 6_500;

        const effectivePerOfferBudgetMs = Math.min(
          remaining,
          perOfferBudget
        );

        console.log(
          "[AIShopping] V34.CORE120 verification candidate budget:",
          {
            host: candidateHost,
            url: verificationQueue[index]?.url,
            olxReaderOrdinal: candidateHost === "olx.pl" ? olxOrdinal : null,
            readerQueueAllowanceMs,
            perOfferBudgetMs: effectivePerOfferBudgetMs,
            globalRemainingMs: remaining,
          }
        );

        const offer = await withAbortableDeadline(
          (signal) => verifySearchResult(
            verificationQueue[index],
            parsed,
            signal,
            sharedExactModelStaticProofPromise
          ),
          effectivePerOfferBudgetMs,
          null,
          `verify ${verificationQueue[index]?.url ?? index}`
        );

        if (offer) verified.push(offer);
      } catch (error) {
        console.error(
          "[AIShopping] verify error:",
          verificationQueue[index]?.url,
          error
        );
      }
    }
  };

  await Promise.all(
    Array.from(
      {
        length: workerCount,
      },
      () => worker()
    )
  );

  return verified;
}


// V34.CORE120: discovery may keep a retailer-owned card only because a concrete
// manufacturer code can independently bridge an abbreviated retailer title to
// the exact requested model. That proof is verification work and can need a
// corrected page-bound MPN plus one independent hydration read. The presence
// of deferredModelIdentityBridgeCode is already protected by the discovery
// gates (brand/family + every hard configuration attribute); this helper only
// changes scheduling and never relaxes acceptance.
function hasDeferredRetailerModelBridgeVerificationPressure(
  results: SearchResult[]
): boolean {
  return results.some((result) =>
    result.source === "RetailerRescue" &&
    Boolean(result.deferredModelIdentityBridgeCode) &&
    Boolean(getResultHostname(result.url))
  );
}

function getV34Core164ExplicitCompetingTitleBrand(
  result: SearchResult,
  parsed: ParsedQuery
): string {
  if (!parsed.brand || !isBrandExplicitlyRequested(parsed.brand, parsed.queryText)) {
    return "";
  }

  const title = normalizeText(result.name);
  if (!title) return "";

  const requestedAliases = getUniversalRequestedBrandAliases(parsed)
    .map(normalizeMatchText)
    .filter(Boolean);
  if (requestedAliases.some((alias) => universalEvidenceHasBoundedIdentityTerm(alias, title))) {
    return "";
  }

  const inferred = normalizeMatchText(
    inferOpenWorldBrandFromCapitalization(title) ?? detectBrand(title, parsed.category) ?? ""
  );
  if (!inferred) return "";
  if (requestedAliases.some((alias) => universalEvidenceHasBoundedIdentityTerm(alias, inferred))) {
    return "";
  }

  const identityTerms = new Set([
    ...parsed.intent.identityTerms,
    ...parsed.intent.qualifierTerms,
  ].map(normalizeMatchText));
  if (identityTerms.has(inferred) || OPEN_WORLD_NON_BRAND_CAPITALIZED_TOKENS.has(inferred)) {
    return "";
  }

  // Fail closed only when the card itself already proves the HARD footprint.
  // If page hydration is still needed for any HARD value, brand proof stays
  // deferred to the normal verified-page logic.
  if (!resultProvesHardCoverageRequirements(result, parsed)) return "";
  return inferred;
}

function pruneV34Core164ExplicitCompetingBrandsBeforeVerification(
  results: SearchResult[],
  parsed: ParsedQuery
): SearchResult[] {
  const kept: SearchResult[] = [];
  let rejected = 0;
  for (const result of results) {
    const competingBrand = getV34Core164ExplicitCompetingTitleBrand(result, parsed);
    if (!competingBrand) {
      kept.push(result);
      continue;
    }
    rejected += 1;
    console.log(
      "[AIShopping] V34.CORE164 pre-verification explicit brand conflict:",
      competingBrand,
      result.url,
      result.name
    );
  }
  if (rejected > 0) {
    console.log(
      "[AIShopping] V34.CORE164 pre-verification brand prune:",
      { rejected, kept: kept.length }
    );
  }
  return kept;
}

function capV34Core164VerificationCandidatesBySourceHealth(
  results: SearchResult[],
  parsed: ParsedQuery,
  limit: number
): SearchResult[] {
  const highConstraint = isV34Core164HighConstraintRetailIntent(parsed);
  const perHost = new Map<string, number>();
  const kept: SearchResult[] = [];
  const health = getRetailerRequestHealthBucket(parsed)?.hosts;

  for (const result of results) {
    if (kept.length >= limit) break;
    const host = getResultHostname(result.url) || "unknown";
    const state = health?.get(host);
    const unhealthyEmptyRetailer = Boolean(
      result.source === "RetailerRescue" &&
      state &&
      state.products === 0 &&
      (state.directBlockFailures >= 1 || state.directHardFailures >= 2 || state.adapterTimedOut)
    );
    const hostCap =
      result.source === "CeneoMerchant"
        ? limit
        : unhealthyEmptyRetailer
          ? 1
          : highConstraint
            ? 3
            : limit;
    const used = perHost.get(host) ?? 0;
    if (used >= hostCap) continue;
    perHost.set(host, used + 1);
    kept.push(result);
  }

  if (kept.length !== results.length) {
    console.log(
      "[AIShopping] V34.CORE164 source-health verification cap:",
      { before: results.length, after: kept.length, hosts: Object.fromEntries(perHost) }
    );
  }
  return kept;
}

type StagedVerificationBudgetProfile = {
  slowMarketplaceVerificationPressure: boolean;
  deferredModelBridgeVerificationPressure: boolean;
  firstVerificationWindowMs: number;
  recoveryReserveMs: number;
  shouldReserveZeroResultRecovery: boolean;
};

function getStagedVerificationBudgetProfile(
  results: SearchResult[],
  parsed: ParsedQuery,
  firstWaveRemaining: number
): StagedVerificationBudgetProfile {
  const slowMarketplaceVerificationPressure =
    hasHighValueNoPriceMarketplaceVerification(results, parsed);
  const deferredModelBridgeVerificationPressure =
    hasDeferredRetailerModelBridgeVerificationPressure(results);

  const firstVerificationWindowMs = deferredModelBridgeVerificationPressure
    ? DEFERRED_MODEL_BRIDGE_FIRST_VERIFICATION_MS
    : slowMarketplaceVerificationPressure
      ? SLOW_MARKETPLACE_FIRST_VERIFICATION_MS
      : GUARANTEED_FIRST_VERIFICATION_MS;
  const recoveryReserveMs = deferredModelBridgeVerificationPressure
    ? DEFERRED_MODEL_BRIDGE_RECOVERY_RESERVE_MS
    : slowMarketplaceVerificationPressure
      ? SLOW_MARKETPLACE_RECOVERY_RESERVE_MS
      : ZERO_RESULT_RECOVERY_RESERVE_MS;

  return {
    slowMarketplaceVerificationPressure,
    deferredModelBridgeVerificationPressure,
    firstVerificationWindowMs,
    recoveryReserveMs,
    shouldReserveZeroResultRecovery:
      firstWaveRemaining >= firstVerificationWindowMs + recoveryReserveMs,
  };
}

type V34Core181CanonicalStoreIdentity = {
  key: string;
  display: string;
};

function getV34Core181CanonicalStoreIdentity(
  rawStore: string
): V34Core181CanonicalStoreIdentity | null {
  const normalized = normalizeMatchText(rawStore)
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\b(?:www|sklep|store)\b/g, " ")
    .replace(/\bpl\b$/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  const aliases: Record<string, V34Core181CanonicalStoreIdentity> = {
    "mediamarkt": { key: "mediamarkt", display: "MediaMarkt" },
    "media markt": { key: "mediamarkt", display: "MediaMarkt" },
    "mediaexpert": { key: "media expert", display: "Media Expert" },
    "media expert": { key: "media expert", display: "Media Expert" },
    "euro com": { key: "rtv euro agd", display: "RTV EURO AGD" },
    "rtv euro agd": { key: "rtv euro agd", display: "RTV EURO AGD" },
    "oleole": { key: "oleole", display: "OleOle!" },
    "neonet": { key: "neonet", display: "Neonet" },
    "morele": { key: "morele", display: "Morele" },
    "morele net": { key: "morele", display: "Morele" },
    "delkom": { key: "delkom", display: "Delkom" },
    "senetic": { key: "senetic", display: "Senetic" },
    "al to": { key: "al to", display: "al.to" },
    "x kom": { key: "x kom", display: "x-kom" },
    "kr system": { key: "kr system", display: "KR System" },
    "krsystem": { key: "kr system", display: "KR System" },
  };

  return aliases[normalized] ?? null;
}

function normalizeOfferStoreKey(offer: Offer): string {
  const canonical = getV34Core181CanonicalStoreIdentity(offer.store);
  if (canonical) return canonical.key;

  const normalizedStore = normalizeMatchText(offer.store)
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\b(?:www|sklep|store)\b/g, " ")
    .replace(/\bpl\b$/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (normalizedStore) return normalizedStore;
  return getResultHostname(offer.url) || "unknown";
}

function canonicalizeOfferStoreDisplayV34Core181(offer: Offer): Offer {
  const canonical = getV34Core181CanonicalStoreIdentity(offer.store);
  if (!canonical || canonical.display === offer.store) return offer;
  return {
    ...offer,
    store: canonical.display,
  };
}

function isPeerMarketplaceOffer(offer: Offer): boolean {
  const storeKey = normalizeOfferStoreKey(offer);
  const host = getResultHostname(offer.url);
  const peerTokens = [
    "olx",
    "vinted",
    "allegro",
    "allegro lokalnie",
    "ceneo",
    "erli",
    "amazon",
    "ebay",
    "arena",
  ];

  if (peerTokens.some((token) => storeKey === token || storeKey.startsWith(`${token} `))) {
    return true;
  }

  if (host === "vinted.pl" || host.endsWith(".vinted.pl")) {
    return true;
  }

  // A Ceneo redirect may point to a real retailer whose store name is already
  // bound in merchant evidence. In that case the redirect host is transport,
  // not seller identity, so allow cross-path retailer deduplication.
  if (storeKey && storeKey !== "unknown") {
    return false;
  }

  return V28_UNIVERSAL_MARKETPLACE_DOMAINS.some(
    (marketplaceHost) => host === String(marketplaceHost)
  );
}

function choosePreferredDuplicateOffer(existing: Offer, candidate: Offer): Offer {
  const existingComparable = getOfferComparablePrice(existing);
  const candidateComparable = getOfferComparablePrice(candidate);

  if (
    candidateComparable !== null &&
    (existingComparable === null || candidateComparable < existingComparable)
  ) {
    return candidate;
  }

  if (
    existingComparable !== null &&
    candidateComparable !== null &&
    candidateComparable > existingComparable
  ) {
    return existing;
  }

  if (candidate.priceVerified !== existing.priceVerified) {
    return candidate.priceVerified ? candidate : existing;
  }

  return (candidate.relevance ?? 0) > (existing.relevance ?? 0)
    ? candidate
    : existing;
}

function getRetailerExactModelDedupeKey(
  offer: Offer,
  parsed: ParsedQuery
): string | null {
  if (isPeerMarketplaceOffer(offer)) return null;

  const modelCore = normalizeMatchText(
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed) ||
    ""
  );
  if (!modelCore) return null;

  const hardRequirementKey = parsed.intent.required
    .filter((requirement) => requirement.hard)
    .map((requirement) =>
      `${requirement.key}:${normalizeMatchText(requirementPrimarySearchTerm(requirement))}`
    )
    .sort()
    .join("|");

  return `${normalizeOfferStoreKey(offer)}|${modelCore}|${hardRequirementKey}`;
}

function deduplicateOffers(offers: Offer[], parsed: ParsedQuery): Offer[] {
  const byUrl = new Map<string, Offer>();

  for (const offer of offers) {
    const normalized = normalizeUrl(offer.url);
    if (!normalized) continue;

    const normalizedOffer = {
      ...offer,
      url: normalized,
    };
    const existing = byUrl.get(normalized);
    byUrl.set(
      normalized,
      existing
        ? choosePreferredDuplicateOffer(existing, normalizedOffer)
        : normalizedOffer
    );
  }

  // Second level: exact same normalized title from the same store, but another
  // tracking/redirect URL. This preserves the old behavior for every category.
  const byProduct = new Map<string, Offer>();

  for (const offer of byUrl.values()) {
    const productKey = isPeerMarketplaceOffer(offer)
      ? `marketplace|${normalizeUrl(offer.url)}`
      : `${normalizeOfferStoreKey(offer)}|${offer.name}`
          .toLowerCase()
          .replace(/[^\p{L}\p{N}]+/gu, " ")
          .trim();

    const existing = byProduct.get(productKey);
    byProduct.set(
      productKey,
      existing
        ? choosePreferredDuplicateOffer(existing, offer)
        : offer
    );
  }

  // V32.12 third level: for a concrete exact-model request, the same retailer
  // may be discovered through Ceneo, a direct catalog, Bing and a rescued
  // product URL with slightly different marketing titles. Collapse those
  // duplicate paths for real retailers, but NEVER collapse separate OLX /
  // Allegro / other peer-marketplace seller listings.
  const exactRetailerGroups = new Map<string, Offer>();
  const passthrough: Offer[] = [];

  for (const offer of byProduct.values()) {
    const exactKey = getRetailerExactModelDedupeKey(offer, parsed);
    if (!exactKey) {
      passthrough.push(offer);
      continue;
    }

    const existing = exactRetailerGroups.get(exactKey);
    exactRetailerGroups.set(
      exactKey,
      existing
        ? choosePreferredDuplicateOffer(existing, offer)
        : offer
    );
  }

  return [...passthrough, ...exactRetailerGroups.values()];
}


function clampScore(value: number): number {
  return Math.max(0, Math.min(100, Math.round(value)));
}

function median(values: number[]): number | null {
  if (values.length === 0) return null;

  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);

  if (sorted.length % 2 === 0) {
    return (sorted[middle - 1] + sorted[middle]) / 2;
  }

  return sorted[middle];
}

function getOfferComparablePrice(offer: Offer): number | null {
  const candidate = offer.comparisonPrice ?? offer.totalPrice ?? offer.price;
  return typeof candidate === "number" && Number.isFinite(candidate)
    ? candidate
    : null;
}

function getOfferAssessmentText(offer: Offer): string {
  return normalizeText(
    `${offer.name} ${offer.description} ${offer.store} ${offer.url}`
  )
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function assessCondition(
  offer: Offer
): {
  condition: AssessedCondition;
  confidence: number;
} {
  const text = getOfferAssessmentText(offer);

  const newSignals = [
    "stan nowe",
    "stan nowy",
    "nowy",
    "nowa",
    "nieuzywany",
    "nieuzywana",
    "fabrycznie now",
    "fabryczna plomba",
    "fabryczna plomba",
    "sealed",
    "nieotwierany",
  ];

  const usedSignals = [
    "stan uzywane",
    "uzywany",
    "uzywana",
    "slady uzytkowania",
    "bardzo dobry stan",
    "stan dobry",
    "stan techn",
    "odnowiony",
    "regenerowany",
  ];

  const newHits = newSignals.filter((signal) =>
    text.includes(signal)
  ).length;

  const usedHits = usedSignals.filter((signal) =>
    text.includes(signal)
  ).length;

  if (newHits > usedHits && newHits > 0) {
    return {
      condition: "new",
      confidence: clampScore(58 + newHits * 12),
    };
  }

  if (usedHits > 0) {
    return {
      condition: "used",
      confidence: clampScore(58 + usedHits * 12),
    };
  }

  return {
    condition: "unknown",
    confidence: 35,
  };
}

function isRequestedBrandFirstPartyHost(
  urlRaw: string,
  brandRaw: string | null
): boolean {
  const brandCompact = normalizeMatchText(brandRaw ?? "").replace(/[^a-z0-9]+/g, "");
  if (brandCompact.length < 2) return false;

  const host = getResultHostname(urlRaw);
  if (!host) return false;
  const firstLabel = host.split(".")[0] ?? "";
  const hostCompact = normalizeMatchText(firstLabel).replace(/[^a-z0-9]+/g, "");
  return hostCompact === brandCompact;
}

function assessOriginality(
  offer: Offer,
  parsed: ParsedQuery
): {
  score: number;
  confidence: OriginalityConfidence;
} {
  const text = getOfferAssessmentText(offer);

  const negative = [
    "zamiennik",
    "kompatybilny",
    "compatible",
    "replacement",
    "replika",
    "podrob",
    "fake",
    "inspired",
    "do sony",
    "for sony",
  ];

  if (negative.some((signal) => text.includes(signal))) {
    return {
      score: 18,
      confidence: "unknown",
    };
  }

  const explicitOriginal =
    text.includes("oryginal") ||
    text.includes("orginal") ||
    text.includes("original") ||
    text.includes("genuine");

  const sonySignal =
    text.includes("sony");

  const modelSignal =
    text.includes("dualshock 4") ||
    text.includes("dualshock v2") ||
    text.includes("dualshock v1") ||
    text.includes("dualsense");

  const modelCodeSignal =
    text.includes("cuh-zct1") ||
    text.includes("cuh-zct2");

  const normalizedBrand = normalizeMatchText(parsed.brand ?? "");
  const genericBrandSignal =
    normalizedBrand.length >= 2 &&
    universalEvidenceHasBoundedIdentityTerm(normalizedBrand, text);
  const requestedBrandFirstPartyHost = isRequestedBrandFirstPartyHost(
    offer.url,
    parsed.brand
  );

  let score = 30;

  if (genericBrandSignal) score += 12;
  if (requestedBrandFirstPartyHost) score += 55;
  if (sonySignal) score += 15;
  if (modelSignal) score += 18;
  if (modelCodeSignal) score += 20;
  if (explicitOriginal) score += 28;

  if (
    text.includes("100% oryginal") ||
    text.includes("w 100% oryginal") ||
    text.includes("oryginalny produkt sony") ||
    text.includes("genuine sony")
  ) {
    score += 12;
  }

  if (offer.store === "Media Expert") score += 8;
  if (offer.store === "Allegro") score += 5;

  const originalitySourceConfidence = getSourceConfidence(offer);
  const peerOriginalityMarketplace =
    /\b(?:allegro\s+lokalnie|olx|ebay)\b/iu.test(normalizeMatchText(offer.store));

  // A trusted retailer carrying the requested brand is stronger authenticity
  // evidence than a self-written marketplace adjective. Conversely, on P2P
  // marketplaces "oryginalny" alone stays low-confidence unless a stronger
  // model-code signal exists.
  if (
    parsed.original &&
    !peerOriginalityMarketplace &&
    originalitySourceConfidence >= 88 &&
    genericBrandSignal
  ) {
    score += 40;
  }

  if (
    parsed.original &&
    peerOriginalityMarketplace &&
    explicitOriginal &&
    !modelCodeSignal
  ) {
    score = Math.min(score, 58);
  }

  // For a query explicitly requiring an original product, brand/model alone
  // is evidence of compatibility/model identity, not proof of originality.
  const trustedFirstPartyOriginalityEvidence =
    parsed.original &&
    !peerOriginalityMarketplace &&
    (
      requestedBrandFirstPartyHost ||
      (originalitySourceConfidence >= 88 && genericBrandSignal)
    );

  if (
    parsed.original &&
    !explicitOriginal &&
    !modelCodeSignal &&
    !trustedFirstPartyOriginalityEvidence
  ) {
    score = Math.min(score, 58);
  }

  score = clampScore(score);

  const confidence: OriginalityConfidence =
    score >= 82
      ? "high"
      : score >= 62
        ? "medium"
        : score >= 42
          ? "low"
          : "unknown";

  return {
    score,
    confidence,
  };
}

function getSourceConfidence(offer: Offer): number {
  const store = offer.store.toLowerCase();

  let score = 58;

  if (store.includes("douglas")) score = 96;
  else if (store.includes("sephora")) score = 96;
  else if (store.includes("notino")) score = 94;
  else if (store.includes("rossmann")) score = 93;
  else if (store.includes("hebe")) score = 92;
  else if (store.includes("media expert")) score = 94;
  else if (store.includes("media markt")) score = 93;
  else if (store.includes("x-kom")) score = 93;
  else if (store.includes("rtv euro agd")) score = 93;
  else if (store.includes("oleole")) score = 91;
  else if (store.includes("komputronik")) score = 92;
  else if (store.includes("morele")) score = 90;
  else if (store.includes("neonet")) score = 90;
  else if (store.includes("amazon")) score = 90;
  else if (store.includes("empik")) score = 88;
  else if (store.includes("allegro lokalnie")) score = 74;
  else if (store.includes("allegro")) score = 88;
  else if (store.includes("ceneo")) score = 78;
  else if (store.includes("erli")) score = 80;
  else if (store.includes("olx")) score = 70;
  else if (store.includes("ebay")) score = 66;

  if (offer.priceVerified) score += 5;
  if (offer.verification === "verified") score += 4;
  if (offer.availability === "available") score += 3;
  if (!looksLikeProductUrl(offer.url)) score -= 12;

  return clampScore(score);
}

function getSellerConfidence(offer: Offer): number {
  const text = getOfferAssessmentText(offer);
  let score = 52;

  const ratingMatch = text.match(
    /([1-5](?:[.,]\d)?)\s*\/\s*5/
  );

  if (ratingMatch) {
    const rating = Number(
      ratingMatch[1].replace(",", ".")
    );

    if (Number.isFinite(rating)) {
      score = 35 + rating * 12;
    }
  }

  const reviewsMatch =
    text.match(/\((\d{1,6})\s*ocen/) ??
    text.match(/(\d{1,6})\s*opini/);

  if (reviewsMatch) {
    const reviews = Number(reviewsMatch[1]);

    if (reviews >= 100) score += 10;
    else if (reviews >= 20) score += 7;
    else if (reviews >= 5) score += 4;
  }

  if (text.includes("firmowe")) score += 8;
  if (text.includes("gwarancj")) score += 6;
  if (text.includes("30 dni")) score += 3;

  if (offer.store === "OLX" && !ratingMatch) {
    score -= 5;
  }

  if (/\b(?:osoba\s+prywatna|private\s+seller)\b/iu.test(text)) {
    score -= 14;
  }

  return clampScore(score);
}

function getPriceAssessment(
  offer: Offer,
  priceMedian: number | null,
  parsed: ParsedQuery
): {
  score: number;
  attractiveness: PriceAttractiveness;
} {
  const comparablePrice = getOfferComparablePrice(offer);

  if (comparablePrice === null) {
    return {
      score: 0,
      attractiveness: "poor",
    };
  }

  let score = 60;

  if (priceMedian !== null && priceMedian > 0) {
    const ratio = comparablePrice / priceMedian;

    if (ratio <= 0.65) score = 100;
    else if (ratio <= 0.8) score = 92;
    else if (ratio <= 0.95) score = 82;
    else if (ratio <= 1.05) score = 72;
    else if (ratio <= 1.2) score = 58;
    else if (ratio <= 1.4) score = 42;
    else score = 25;
  }

  if (
    parsed.maxPrice !== null &&
    parsed.maxPrice > 0
  ) {
    const budgetRatio = comparablePrice / parsed.maxPrice;

    if (budgetRatio <= 0.65) score += 8;
    else if (budgetRatio <= 0.85) score += 4;
    else if (budgetRatio >= 0.98) score -= 5;
  }

  score = clampScore(score);

  const attractiveness: PriceAttractiveness =
    score >= 90
      ? "excellent"
      : score >= 76
        ? "good"
        : score >= 56
          ? "fair"
          : "poor";

  return {
    score,
    attractiveness,
  };
}

function getMatchScore(
  offer: Offer,
  parsed: ParsedQuery
): number {
  const text = getOfferAssessmentText(offer);
  let score = 55;

  const universalMatch = evaluateUniversalProductMatch(
    offer.name,
    offer.description,
    offer.url,
    parsed,
    "verified"
  );

  if (universalMatch.pass) {
    score += Math.min(25, universalMatch.score * 0.25);
  }

  const relevance = offer.relevance ?? 0;
  score += Math.min(30, relevance * 0.12);

  if (
    parsed.platform === "PS4" &&
    (
      text.includes("dualshock 4") ||
      text.includes("playstation 4") ||
      text.includes("ps4")
    )
  ) {
    score += 10;
  }

  if (
    parsed.platform === "PS5" &&
    (
      text.includes("dualsense") ||
      text.includes("playstation 5") ||
      text.includes("ps5")
    )
  ) {
    score += 10;
  }

  if (parsed.category === "controller") {
    if (
      text.includes("pad") ||
      text.includes("kontroler") ||
      text.includes("controller") ||
      text.includes("gamepad")
    ) {
      score += 5;
    }
  }

  if (
    parsed.original &&
    (
      text.includes("oryginal") ||
      text.includes("orginal") ||
      text.includes("original")
    )
  ) {
    score += 5;
  }

  return clampScore(score);
}

function getRiskAssessment(
  offer: Offer,
  originalityScore: number,
  sourceConfidence: number,
  sellerConfidence: number,
  priceMedian: number | null,
  assessedCondition: AssessedCondition,
  parsed: ParsedQuery
): {
  score: number;
  level: RiskLevel;
} {
  const text = getOfferAssessmentText(offer);
  const comparablePrice = getOfferComparablePrice(offer);
  let risk = 38;

  risk -= (sourceConfidence - 50) * 0.22;
  risk -= (sellerConfidence - 50) * 0.12;
  risk -= (originalityScore - 50) * 0.18;

  if (offer.priceVerified) risk -= 7;
  else risk += 8;

  if (offer.verification === "verified") risk -= 4;
  if (offer.availability === "available") risk -= 3;

  const riskySignals = [
    "bez zwrotu",
    "brak gwarancji",
    "nie sprawdzony",
    "niesprawny",
    "uszkodzony",
    "na czesci",
    "do naprawy",
    "brak mozliwosci sprawdzenia",
    "tylko pobranie",
    "kontakt tylko sms",
  ];

  for (const signal of riskySignals) {
    if (text.includes(signal)) risk += 12;
  }

  if (
    comparablePrice !== null &&
    priceMedian !== null &&
    priceMedian > 0
  ) {
    const ratio = comparablePrice / priceMedian;

    // Bardzo niska cena może być okazją, ale przy "oryginalnym"
    // produkcie jest też sygnałem do dodatkowej ostrożności.
    if (ratio < 0.42) risk += 28;
    else if (ratio < 0.58) risk += 16;
    else if (ratio < 0.7) risk += 7;
  }

  if (
    assessedCondition === "new" &&
    comparablePrice !== null &&
    priceMedian !== null &&
    comparablePrice < priceMedian * 0.6
  ) {
    risk += 10;
  }

  const peerMarketplace = /\b(?:allegro\s+lokalnie|olx|ebay)\b/iu.test(text);
  const privateSeller = /\b(?:osoba\s+prywatna|private\s+seller)\b/iu.test(text);

  // Unknown authenticity on a peer-to-peer marketplace cannot be labelled
  // "low risk" merely because the listing page and price were reachable.
  if (peerMarketplace && originalityScore < 62) risk = Math.max(risk, 38);
  if (privateSeller && originalityScore < 62) risk = Math.max(risk, 46);

  // V34.CORE120: explicit originality is a user constraint, not a decorative
  // ranking hint. A page that merely says the requested brand/model but lacks
  // trustworthy authenticity evidence may still be shown for recall, but it
  // can never be labelled low-risk. This avoids the dangerous combination
  // seen in real runtime: originalityConfidence=low + riskLevel=low.
  if (parsed.original === true) {
    if (originalityScore < 42) risk = Math.max(risk, 72);
    else if (originalityScore < 62) risk = Math.max(risk, 54);
    else if (originalityScore < 82) risk = Math.max(risk, 34);
  }

  risk = clampScore(risk);

  const level: RiskLevel =
    risk <= 30
      ? "low"
      : risk <= 58
        ? "medium"
        : "high";

  return {
    score: risk,
    level,
  };
}

function buildAiReason(
  offer: Offer,
  originalityConfidence: OriginalityConfidence,
  riskLevel: RiskLevel,
  priceAttractiveness: PriceAttractiveness,
  assessedCondition: AssessedCondition
): string {
  const parts: string[] = [];

  if (priceAttractiveness === "excellent") {
    parts.push("bardzo dobra cena");
  } else if (priceAttractiveness === "good") {
    parts.push("dobra cena");
  } else if (priceAttractiveness === "poor") {
    parts.push("cena słabsza od innych ofert");
  }

  if (originalityConfidence === "high") {
    parts.push("mocne sygnały oryginalności");
  } else if (originalityConfidence === "medium") {
    parts.push("oryginalność wygląda wiarygodnie");
  } else if (originalityConfidence === "low") {
    parts.push("oryginalność wymaga ostrożności");
  }

  if (riskLevel === "low") {
    parts.push("niskie ryzyko");
  } else if (riskLevel === "high") {
    parts.push("podwyższone ryzyko");
  }

  if (assessedCondition === "new") {
    parts.push("stan oceniony jako nowy");
  } else if (assessedCondition === "used") {
    parts.push("stan oceniony jako używany");
  }

  if (offer.priceVerified) {
    parts.push("cena zweryfikowana");
  }

  if (
    offer.delivery &&
    offer.totalPrice !== null &&
    offer.totalPrice !== undefined
  ) {
    parts.push("dostawa uwzględniona");
  }

  return parts.slice(0, 4).join(" • ");
}

function scoreAndRankOffers(
  offers: Offer[],
  parsed: ParsedQuery
): Offer[] {
  if (offers.length === 0) return [];

  const prices = offers
    .map(getOfferComparablePrice)
    .filter(
      (price): price is number =>
        typeof price === "number" &&
        Number.isFinite(price) &&
        price > 0
    );

  const priceMedian = median(prices);

  const scored = offers.map((offer) => {
    const conditionAssessment = assessCondition(offer);
    const originality = assessOriginality(offer, parsed);
    const sourceConfidence = getSourceConfidence(offer);
    const sellerConfidence = getSellerConfidence(offer);

    const priceAssessment = getPriceAssessment(
      offer,
      priceMedian,
      parsed
    );

    const matchScore = getMatchScore(offer, parsed);

    const risk = getRiskAssessment(
      offer,
      originality.score,
      sourceConfidence,
      sellerConfidence,
      priceMedian,
      conditionAssessment.condition,
      parsed
    );

    const safetyScore = 100 - risk.score;

    let dealScore =
      matchScore * 0.30 +
      priceAssessment.score * 0.22 +
      originality.score * 0.18 +
      safetyScore * 0.18 +
      sourceConfidence * 0.07 +
      sellerConfidence * 0.05;

    if (risk.level === "high") dealScore -= 8;
    if (offer.priceVerified) dealScore += 3;

    dealScore = clampScore(dealScore);

    return {
      ...offer,
      matchScore,
      originalityScore: originality.score,
      originalityConfidence: originality.confidence,
      riskScore: risk.score,
      riskLevel: risk.level,
      assessedCondition: conditionAssessment.condition,
      conditionConfidence: conditionAssessment.confidence,
      priceScore: priceAssessment.score,
      priceAttractiveness: priceAssessment.attractiveness,
      sourceConfidence,
      sellerConfidence,
      totalPrice: offer.totalPrice ?? offer.price,
      comparisonPrice: getOfferComparablePrice(offer),
      dealScore,
      aiReason: buildAiReason(
        offer,
        originality.confidence,
        risk.level,
        priceAssessment.attractiveness,
        conditionAssessment.condition
      ),
      bestOffer: false,
      cheapestOffer: false,
      safestOffer: false,
    };
  });

  const primaryRecommendationEligible = (offer: Offer): boolean =>
    parsed.original !== true ||
    offer.originalityConfidence === "high" ||
    offer.originalityConfidence === "medium";

  const recommendationPool = scored.filter(primaryRecommendationEligible);
  const rankingPool = recommendationPool.length > 0 ? recommendationPool : scored;

  const cheapestPool =
    parsed.original === true
      ? recommendationPool
      : scored;

  const cheapest = cheapestPool
    .filter((offer) => getOfferComparablePrice(offer) !== null)
    .sort(
      (a, b) =>
        (getOfferComparablePrice(a) ?? Number.POSITIVE_INFINITY) -
        (getOfferComparablePrice(b) ?? Number.POSITIVE_INFINITY)
    )[0];

  const safest = [...rankingPool].sort((a, b) => {
    if ((a.riskScore ?? 100) !== (b.riskScore ?? 100)) {
      return (a.riskScore ?? 100) - (b.riskScore ?? 100);
    }

    if ((b.originalityScore ?? 0) !== (a.originalityScore ?? 0)) {
      return (b.originalityScore ?? 0) - (a.originalityScore ?? 0);
    }

    if ((b.sellerConfidence ?? 0) !== (a.sellerConfidence ?? 0)) {
      return (b.sellerConfidence ?? 0) - (a.sellerConfidence ?? 0);
    }

    if ((b.sourceConfidence ?? 0) !== (a.sourceConfidence ?? 0)) {
      return (b.sourceConfidence ?? 0) - (a.sourceConfidence ?? 0);
    }

    if (priceMedian !== null) {
      const aPrice = getOfferComparablePrice(a);
      const bPrice = getOfferComparablePrice(b);
      if (aPrice !== null && bPrice !== null) {
        return Math.abs(aPrice - priceMedian) - Math.abs(bPrice - priceMedian);
      }
    }

    return 0;
  })[0];

  const ranked = [...rankingPool].sort((a, b) => {
    if ((b.dealScore ?? 0) !== (a.dealScore ?? 0)) {
      return (b.dealScore ?? 0) - (a.dealScore ?? 0);
    }

    if ((a.riskScore ?? 100) !== (b.riskScore ?? 100)) {
      return (a.riskScore ?? 100) - (b.riskScore ?? 100);
    }

    const aComparablePrice = getOfferComparablePrice(a);
    const bComparablePrice = getOfferComparablePrice(b);
    if (aComparablePrice !== null && bComparablePrice !== null) {
      return aComparablePrice - bComparablePrice;
    }

    return (b.relevance ?? 0) - (a.relevance ?? 0);
  });

  // A verified offer that is BOTH the cheapest and the safest Pareto-dominates
  // the alternatives. A one-point scoring difference must not label a more
  // expensive and riskier offer as "best". This rule is product-agnostic and
  // runs only after every candidate has already passed identity/spec checks.
  const cheapestAndSafest =
    cheapest &&
    safest &&
    primaryRecommendationEligible(cheapest) &&
    cheapest.url === safest.url
      ? cheapest
      : null;

  const best = parsed.original === true && recommendationPool.length === 0
    ? null
    : cheapestAndSafest ?? ranked[0];

  const rankedUrls = new Set(ranked.map((offer) => offer.url));
  const cautiousFallbacks = scored
    .filter((offer) => !rankedUrls.has(offer.url))
    .sort((a, b) => {
      if ((a.riskScore ?? 100) !== (b.riskScore ?? 100)) {
        return (a.riskScore ?? 100) - (b.riskScore ?? 100);
      }
      return (b.dealScore ?? 0) - (a.dealScore ?? 0);
    });

  const ordered = best
    ? [
        best,
        ...ranked.filter((offer) => offer.url !== best.url),
        ...cautiousFallbacks,
      ]
    : [...ranked, ...cautiousFallbacks];

  const safestIsRecommendable = safest && primaryRecommendationEligible(safest);

  return ordered.map((offer) => ({
    ...offer,
    bestOffer: best ? offer.url === best.url : false,
    cheapestOffer: cheapest
      ? offer.url === cheapest.url
      : false,
    safestOffer: safestIsRecommendable
      ? offer.url === safest.url
      : false,
  }));
}

function sortOffers(offers: Offer[]): Offer[] {
  return offers.sort((a, b) => {
    if ((b.relevance ?? 0) !== (a.relevance ?? 0)) {
      return (b.relevance ?? 0) - (a.relevance ?? 0);
    }

    if (a.price !== null && b.price === null) return -1;
    if (a.price === null && b.price !== null) return 1;

    if (a.price !== null && b.price !== null) {
      return a.price - b.price;
    }

    return 0;
  });
}

function splitAlternativeShoppingQuery(queryRaw: string): string[] {
  const query = normalizeText(queryRaw);
  if (!query) return [];

  // Split only explicit alternative conjunctions. Do not split ordinary
  // question grammar ("czy") or slash-separated model names. Each branch is
  // then parsed and verified independently, so brand/category/model evidence
  // from product A can never contaminate product B.
  const parts = query
    .split(/\s+(?:albo|lub|or)\s+/iu)
    .map((part) => normalizeText(part.replace(/^[,;:\-]+|[,;:\-]+$/g, " ")))
    .filter(Boolean);

  if (parts.length < 2 || parts.length > 3) return [];

  const viable = parts.every((part) => {
    const tokens = normalizeMatchText(part)
      .split(/\s+/)
      .filter((token) => /[a-z0-9]/i.test(token));
    return tokens.length >= 2 || tokens.some((token) => /[a-z]+\d|\d+[a-z]+/i.test(token));
  });

  if (!viable) return [];
  return Array.from(new Set(parts));
}

type AlternativeChildSearchResponse = {
  success?: boolean;
  query?: string;
  interpreted?: unknown;
  offers?: Array<Omit<Offer, "relevance">>;
  found?: number;
  resultStatus?: "offers_found" | "no_matching_verified_offer" | "coverage_incomplete" | string;
  coverage?: {
    discoveredCandidates?: number;
    verificationCandidates?: number;
  };
  message?: string;
};

function mergeAlternativeOffers(
  payloads: AlternativeChildSearchResponse[]
): Array<Omit<Offer, "relevance">> {
  const byUrl = new Map<string, Omit<Offer, "relevance">>();

  for (const payload of payloads) {
    for (const offer of payload.offers ?? []) {
      if (!offer || typeof offer.url !== "string" || !offer.url) continue;
      const key = normalizeUrl(offer.url) || offer.url;
      const existing = byUrl.get(key);

      if (!existing) {
        byUrl.set(key, offer);
        continue;
      }

      const existingVerified = existing.verification === "verified" ? 1 : 0;
      const candidateVerified = offer.verification === "verified" ? 1 : 0;
      const existingScore = (existing.dealScore ?? 0) + existingVerified * 1000;
      const candidateScore = (offer.dealScore ?? 0) + candidateVerified * 1000;
      if (candidateScore > existingScore) byUrl.set(key, offer);
    }
  }

  return [...byUrl.values()]
    .sort((a, b) => {
      const verifiedDiff =
        (b.verification === "verified" ? 1 : 0) -
        (a.verification === "verified" ? 1 : 0);
      if (verifiedDiff !== 0) return verifiedDiff;

      const scoreDiff = (b.dealScore ?? 0) - (a.dealScore ?? 0);
      if (scoreDiff !== 0) return scoreDiff;

      if (a.price !== null && b.price !== null) return a.price - b.price;
      if (a.price !== null) return -1;
      if (b.price !== null) return 1;
      return 0;
    })
    .slice(0, MAX_FINAL_OFFERS)
    .map((offer, index) => ({ ...offer, id: index + 1 }));
}

function parseQuery(query: string, bodyCountry: unknown): ParsedQuery {
  const normalizedShoppingQuery = normalizeOpenWorldShoppingQuery(query);
  const category = detectCategory(normalizedShoppingQuery);
  const platform = detectPlatform(normalizedShoppingQuery);
  const brand = detectBrand(normalizedShoppingQuery, category);
  const condition = detectCondition(normalizedShoppingQuery);
  const original = detectOriginal(normalizedShoppingQuery);
  const maxPrice = extractMaxPrice(normalizedShoppingQuery);
  const country = detectCountry(bodyCountry, normalizedShoppingQuery);
  const model = detectModel(normalizedShoppingQuery, platform);
  const provisionalProduct = detectProduct(normalizedShoppingQuery, category);

  const intent = buildUniversalProductIntent(
    normalizedShoppingQuery,
    category,
    brand,
    model,
    platform,
    provisionalProduct
  );

  return {
    queryText: normalizeText(query),
    query: normalizeText(query),
    product: intent.productPhrase || provisionalProduct,
    category,
    brand,
    model,
    platform,
    condition,
    original,
    maxPrice,
    country,
    intent,
  };
}


// V34.CORE120 ZERO-RESULT RECOVERY. Verification gets first claim on time.
// Only a failed or authenticity-weak first wave pays for this compact pulse.
//
// CORE5 started Google/Jina only after the first verification wave had already
// failed. Real runtime showed both late reader requests being cut at 2.45 s.
// CORE7 therefore starts ONE generic commerce-oriented open-web lookup near the
// beginning of the request and lets it run in parallel with ordinary discovery.
// Normal searches never wait for it. Only zero/authenticity-weak results consume
// its already-settled snapshot, and all recovered URLs still pass the unchanged
// universal product/offer verification gates.
type ZeroResultOpenWebPrefetch = {
  query: string | null;
  kind: "first-party" | "open-web" | "none";
  promise: Promise<SearchResult[]> | null;
  state: {
    settled: boolean;
    results: SearchResult[];
  };
};

function buildZeroResultOpenWebPrefetchQuery(parsed: ParsedQuery): string | null {
  const identity = normalizeText(
    getUniversalCoverageDiscoveryCore(parsed) ||
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed) ||
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    parsed.queryText
  );
  if (!identity) return null;

  const hardTerms = parsed.intent.required
    .filter(isRequirementDiscoverySearchEligible)
    .slice(0, 4)
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .join(" ");
  const stateHint = parsed.condition === "new"
    ? "nowy"
    : parsed.condition === "used"
      ? "uzywany"
      : "";
  const originalityHint = parsed.original === true ? "oryginalny" : "";

  // No site/domain/product special-casing here. The independent index is asked
  // for concrete commercial pages around the parsed identity; host diversity
  // and all hard requirements are enforced later by the normal engine.
  return normalizeText(
    `${quoteSearchTerm(identity)} ${hardTerms} ${stateHint} ${originalityHint} cena sklep kup`
  );
}

function getZeroResultFirstPartyReaderPrefetchSeed(
  parsed: ParsedQuery
): SearchResult | null {
  const hasHardRequirement = parsed.intent.required.some(
    (requirement) => requirement.hard
  );
  const hasExactIdentity = Boolean(
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed) ||
    getUniversalExactModelAnchor(parsed, parsed.intent.productPhrase)
  );

  // Request-start reader capacity is scarce. Spend it on first-party only when
  // the query is constrained enough that the adapter-derived landing is more
  // valuable than a generic web search. The seed itself is still discovery-only.
  if (!hasHardRequirement && !hasExactIdentity) return null;

  return buildZeroResultAdapterDerivedLandingExpansionSeeds(parsed, 1)[0] ?? null;
}

async function searchZeroResultFirstPartyReaderPrefetch(
  parsed: ParsedQuery,
  seed: SearchResult,
  externalSignal?: AbortSignal
): Promise<SearchResult[]> {
  const host = getResultHostname(seed.url);
  if (!host || externalSignal?.aborted) return [];

  const adapter = V28_DIRECT_RETAILER_CATALOG_ADAPTERS.find((candidate) =>
    retailerHostMatchesDomain(host, candidate.host)
  );
  const readerTimeoutMs = Math.max(
    7_200,
    Math.min(9_000, (adapter?.readerCatalogTimeoutMs ?? 5_000) + 2_400)
  );

  const markdown = await fetchViaJina(
    seed.url,
    readerTimeoutMs,
    true,
    externalSignal
  );
  if (
    !markdown ||
    externalSignal?.aborted ||
    isBlockedOrChallengePage(markdown)
  ) {
    return [];
  }

  mutateRetailerRequestHealth(parsed, host, (state) => {
    state.readerSuccesses += 1;
  });

  const products = parseRescuedRetailerLandingMarkdown(
    markdown,
    seed.url,
    parsed,
    host,
    Boolean(adapter?.allowDeferredModelIdentityBridge)
  );

  if (products.length > 0) {
    mutateRetailerRequestHealth(parsed, host, (state) => {
      state.products = Math.max(state.products, products.length);
    });
  }

  console.log(
    "[AIShopping] V34.CORE120 request-start first-party reader prefetch settled:",
    {
      host,
      url: seed.url,
      products: products.length,
      textLength: markdown.length,
    }
  );

  return products.slice(0, 12);
}

function startZeroResultOpenWebPrefetch(parsed: ParsedQuery): ZeroResultOpenWebPrefetch {
  const firstPartySeed = getZeroResultFirstPartyReaderPrefetchSeed(parsed);
  const state = { settled: false, results: [] as SearchResult[] };

  // CORE106: CORE105 launched a generic Google/Jina prefetch at request start
  // for every benchmark and all seven returned 0 results. Worse, that speculative
  // reader competed with concrete marketplace/retailer verification for the
  // globally rate-limited Jina start queue. Only a precise adapter-derived
  // first-party landing is allowed to prefetch now. Generic open-web rescue is
  // deferred until the first verification wave actually fails.
  if (!firstPartySeed) {
    state.settled = true;
    console.log("[AIShopping] V34.CORE120 request-start recovery prefetch skipped: no precise first-party seed");
    return { query: null, kind: "none", promise: null, state };
  }

  if (
    firstPartySeed &&
    shouldV34Core164DeferRequestStartFirstPartyReaderPrefetch(parsed, firstPartySeed)
  ) {
    state.settled = true;
    console.log(
      "[AIShopping] V34.CORE164 request-start first-party reader deferred to recovery:",
      firstPartySeed.url
    );
    return { query: null, kind: "none", promise: null, state };
  }

  const kind: ZeroResultOpenWebPrefetch["kind"] = "first-party";
  const query = firstPartySeed.url;
  const promise = withAbortableDeadline(
    (signal) => searchZeroResultFirstPartyReaderPrefetch(parsed, firstPartySeed, signal),
    4_600,
    [] as SearchResult[],
    "request-start first-party catalog recovery prefetch"
  ).then((results) => {
    state.results = results;
    state.settled = true;
    console.log("[AIShopping] V34.CORE120 request-start recovery prefetch settled:", {
      kind,
      query,
      results: results.length,
    });
    return results;
  }).catch(() => {
    state.results = [];
    state.settled = true;
    return [] as SearchResult[];
  });

  console.log("[AIShopping] V34.CORE120 request-start recovery prefetch:", {
    kind,
    query,
  });
  return { query, kind, promise, state };
}

async function getZeroResultPrefetchSnapshot(
  prefetch: ZeroResultOpenWebPrefetch | null,
  hardDeadlineAt: number
): Promise<SearchResult[]> {
  if (!prefetch?.promise) return [];
  if (prefetch.state.settled) return prefetch.state.results;

  const remaining = hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
  if (remaining <= 250) return [];

  // If the prefetch is just about to settle, spend only a tiny bounded grace
  // period. The main recovery/verification budget must never be held hostage by
  // a slow reader. The underlying prefetch owns its own 10.5 s abort deadline.
  const graceMs = prefetch.kind === "first-party"
    ? Math.min(900, Math.max(150, remaining - 3_500))
    : Math.min(350, Math.max(100, remaining - 2_500));
  if (graceMs <= 0) return [];

  return await withDeadline(
    prefetch.promise,
    graceMs,
    [] as SearchResult[],
    "request-start recovery prefetch snapshot"
  );
}
function filterZeroResultRecoveryCandidates(
  results: SearchResult[], parsed: ParsedQuery
): SearchResult[] {
  const seen = new Set<string>();
  const out: SearchResult[] = [];
  for (const result of dedupeSearchResultsByUrl(results)) {
    const url = normalizeUrl(result.url);
    if (!url || seen.has(url)) continue;
    seen.add(url);
    const candidate: SearchResult = { ...result, url };
    if (!isAllowedSearchDomainForQuery(url, parsed)) continue;
    if (!looksLikeRequestedProduct(candidate, parsed)) continue;
    if (!isConcreteVerificationCandidate(candidate, parsed)) continue;
    out.push(candidate);
  }
  return out.sort((a, b) =>
    getSearchResultPriority(b, parsed) - getSearchResultPriority(a, parsed) ||
    a.searchRank - b.searchRank
  );
}

function getZeroResultFirstPartySiblingDiscoveryCode(
  result: SearchResult,
  parsed: ParsedQuery,
  expectedHostRaw: string
): string {
  const expectedHost = expectedHostRaw.replace(/^www\./i, "").trim().toLowerCase();
  if (!expectedHost || !retailerHostMatchesDomain(getResultHostname(result.url), expectedHost)) return "";
  if (!result.retailerOwnedCardEvidence || parsed.intent.openWorld) return "";

  const alreadyBound = normalizeText(result.deferredModelIdentityBridgeCode ?? "");
  if (alreadyBound) return alreadyBound;

  // CORE30: a trusted first-party catalog card may already expose a manufacturer
  // code even when the later concrete product-page reader times out. Use that
  // code only as a sibling-discovery hint. It does NOT prove identity, specs,
  // price, condition or availability; every recovered URL still passes the
  // unchanged concrete-page verifier.
  const cardEvidence = normalizeText(`${result.name} ${result.snippet}`);
  const candidateCode = extractRetailerManufacturerCodeForModelBridge(cardEvidence);
  if (!candidateCode) return "";

  // Require the same product class / brand / lexical family after removing only
  // exact numeric model identity. This prevents a neighboring catalog card from
  // donating an unrelated MPN while still allowing sibling configurations of
  // the same product family to be explored.
  const relaxedParsed = getParsedQueryWithoutExactModelIdentity(parsed);
  const relaxedMatch = evaluateUniversalProductMatch(
    result.name,
    result.snippet,
    result.url,
    relaxedParsed,
    "discovery",
    "RetailerRescue"
  );
  if (!relaxedMatch.pass) return "";

  return candidateCode;
}

function getZeroResultFirstPartyRecoveryHosts(
  parsed: ParsedQuery,
  alreadySeenResults: SearchResult[],
  limit = 3
): string[] {
  if (limit <= 0) return [];

  const requests = buildDirectRetailerCatalogRequests(parsed);
  const directRankByHost = new Map<string, number>();
  for (const [index, request] of requests.entries()) {
    const host = request.adapter.host.replace(/^www\./i, "").trim().toLowerCase();
    if (host && !directRankByHost.has(host)) directRankByHost.set(host, index);
  }

  // CORE51: direct-catalog adapters intentionally cover only a small subset of
  // each commerce vertical. Zero-result first-party recovery used to derive its
  // whole bounded host portfolio from that subset, which stranded specialist
  // primary retailers that were already configured for the matched vertical but
  // had no bespoke direct adapter. Fill the SAME three-slot recovery portfolio
  // from the vertical's primary retailer directory after preserving all existing
  // direct-adapter/source-health priorities. This adds no reader slots and no
  // serial wave: the selected host-label index searches still execute in parallel,
  // and every recovered URL remains untrusted until normal concrete-page
  // verification proves identity, price, condition, availability and hard specs.
  const verticalRankByHost = new Map<string, number>();
  for (const [index, domain] of getIntentPrimaryRetailerDomains(parsed).entries()) {
    const host = domain.replace(/^www\./i, "").trim().toLowerCase();
    if (host && !verticalRankByHost.has(host)) verticalRankByHost.set(host, index);
  }

  const candidateHosts = Array.from(new Set([
    ...directRankByHost.keys(),
    ...verticalRankByHost.keys(),
  ])).filter((host) =>
    Boolean(host) &&
    !V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((domain) =>
      host === domain || host.endsWith(`.${domain}`)
    )
  );
  if (candidateHosts.length === 0) return [];

  const coveredHosts = getLikelyConcreteCoverageHostSet(
    alreadySeenResults,
    parsed
  );
  const health = getRetailerRequestHealthBucket(parsed)?.hosts;
  const [recoveryPivotRequirement] = getRarestPortfolioHardRequirements(
    alreadySeenResults, parsed, 1
  );

  const ranked = candidateHosts.map((host, index) => {
    const state = health?.get(host);
    const transportFragile = Boolean(
      state && (
        state.directHardFailures > 0 ||
        state.adapterTimedOut ||
        (state.directAttempts > 0 && state.directSuccesses === 0)
      )
    );

    const covered = coveredHosts.has(host);
    const hardTransportFailure = Boolean(
      state && (
        state.directHardFailures > 0 ||
        (state.directAttempts > 0 && state.directSuccesses === 0)
      )
    );
    const failedConcreteCoverage = covered && hardTransportFailure;
    const hasSiblingDiscoveryCode = alreadySeenResults.some((result) =>
      retailerHostMatchesDomain(getResultHostname(result.url), host) &&
      Boolean(getZeroResultFirstPartySiblingDiscoveryCode(result, parsed, host))
    );
    const provesRecoveryPivot = Boolean(
      recoveryPivotRequirement &&
      alreadySeenResults.some((result) =>
        retailerHostMatchesDomain(getResultHostname(result.url), host) &&
        getTrustedPortfolioHardProofKeys(result, parsed).includes(recoveryPivotRequirement.key)
      )
    );
    const coveredMissingRecoveryPivot = Boolean(
      recoveryPivotRequirement && covered && !provesRecoveryPivot
    );

    return {
      host,
      index,
      directRank: directRankByHost.get(host) ?? Number.MAX_SAFE_INTEGER,
      verticalRank: verticalRankByHost.get(host) ?? Number.MAX_SAFE_INTEGER,
      hasDirectAdapter: directRankByHost.has(host),
      transportFragile,
      hardTransportFailure,
      failedConcreteCoverage,
      hasSiblingDiscoveryCode,
      coveredMissingRecoveryPivot,
      provesRecoveryPivot,
      recoveryPivotKey: recoveryPivotRequirement?.key ?? null,
      covered,
      productCount: state?.products ?? 0,
    };
  });

  // CORE27: a retailer that already yielded a concrete matching candidate but
  // then suffered hard transport failures is the strongest zero-result recovery
  // target. CORE26 ranked uncovered blocked hosts ahead of that case, so the
  // bounded top-N wave could spend all slots on empty stores while skipping the
  // only store whose concrete offer actually failed at verification transport.
  // This is generic source-health scheduling: no product, SKU, price or host is
  // special-cased, and every recovered URL still passes the normal verifier.
  // CORE30: product evidence outranks raw HTTP failure. A host that already
  // exposed a trustworthy manufacturer-code anchor is a much stronger recovery
  // target than an empty blocked host, even if its catalog requests technically
  // returned 2xx. This fixes the class where transport health masks a missed
  // sibling variant. CORE51 preserves that ordering and uses direct-adapter rank
  // before vertical rank only as the deterministic tie-breaker/fill policy.
  ranked.sort((a, b) =>
    Number(b.hasSiblingDiscoveryCode) - Number(a.hasSiblingDiscoveryCode) ||
    Number(b.coveredMissingRecoveryPivot) - Number(a.coveredMissingRecoveryPivot) ||
    Number(b.failedConcreteCoverage) - Number(a.failedConcreteCoverage) ||
    Number(b.hardTransportFailure) - Number(a.hardTransportFailure) ||
    Number(b.transportFragile) - Number(a.transportFragile) ||
    Number(a.covered) - Number(b.covered) ||
    a.productCount - b.productCount ||
    Number(b.hasDirectAdapter) - Number(a.hasDirectAdapter) ||
    a.directRank - b.directRank ||
    a.verticalRank - b.verticalRank ||
    a.index - b.index
  );

  return ranked.map((item) => item.host).slice(0, limit);
}

function buildZeroResultFirstPartyIndexQueries(
  identityCoreRaw: string,
  hardTermsRaw: string,
  hostRaw: string,
  siblingCodeRaw: string,
  isPrimaryHost: boolean,
  relationalHintTermsRaw = "",
  categoryCoreRaw = "",
  anchorHardTermsRaw = "",
  quotedHardFingerprintRaw = ""
): {
  standardQueries: string[];
  siblingHostQuery: string;
  categoryRelationalSpecQuery: string;
  categoryAnchorRelationalSpecQuery: string;
  productScopedQuotedFingerprintQuery: string;
} {
  const identityCore = normalizeText(identityCoreRaw);
  const hardTerms = normalizeText(hardTermsRaw);
  const relationalHintTerms = normalizeText(relationalHintTermsRaw);
  const categoryCore = normalizeText(categoryCoreRaw);
  const anchorHardTerms = normalizeText(anchorHardTermsRaw);
  const quotedHardFingerprint = normalizeText(quotedHardFingerprintRaw);
  const host = hostRaw.replace(/^www\./i, "").trim().toLowerCase();
  const siblingCode = normalizeText(siblingCodeRaw);
  const productScope = V28_RETAILER_PRODUCT_SITE_SCOPES[host] || host;

  const labelQuery = normalizeText(
    identityCore && host
      ? `${quoteSearchTerm(identityCore)} ${host} ${hardTerms}`
      : ""
  );
  const siteScopedFallbackQuery = normalizeText(
    identityCore && productScope
      ? `site:${productScope} ${quoteSearchTerm(identityCore)} ${hardTerms}`
      : ""
  );
  // CORE67: preserve CORE66's wide root-domain relational query, then add ONE
  // even broader category-core fallback when a soft merchandising qualifier is
  // part of the identity phrase. Retailer indexes often omit words such as
  // "gamingowy" from the product title even when the concrete page clearly
  // proves that use case. Both queries are recovery-only and every recovered
  // URL remains untrusted until the unchanged category/qualifier/HARD/condition/
  // availability/price verifier accepts the concrete product page.
  const relationalSpecQuery = normalizeText(
    identityCore && host && relationalHintTerms
      ? `site:${host} ${identityCore} ${hardTerms} ${relationalHintTerms}`
      : ""
  );
  const categoryRelationalSpecQuery = normalizeText(
    categoryCore &&
    categoryCore !== identityCore &&
    host &&
    relationalHintTerms
      ? `site:${host} ${categoryCore} ${hardTerms} ${relationalHintTerms}`
      : ""
  );
  // CORE68: exact HARD search terms can themselves over-constrain a public
  // retailer index even though they remain mandatory at verification. In a
  // composite-device query, for example, a title can expose the GPU + RAM +
  // capacity + refresh rate while omitting a storage-medium word that exists
  // only in the specification table. Keep the full CORE67 query for backwards
  // compatibility, but add one bounded progressive-relaxation shape using only
  // the strongest exact HARD anchor plus every relational threshold hint. The
  // concrete page still has to prove ALL omitted exact HARD requirements.
  const categoryAnchorRelationalSpecQuery = normalizeText(
    categoryCore &&
    categoryCore !== identityCore &&
    host &&
    relationalHintTerms &&
    anchorHardTerms &&
    anchorHardTerms !== hardTerms
      ? `site:${host} ${categoryCore} ${anchorHardTerms} ${relationalHintTerms}`
      : ""
  );
  // CORE70: public retailer indexes often rank broad category pages above
  // concrete products when every threshold token is unquoted. Add ONE
  // product-scope-aware fingerprint query in sparse zero-result recovery.
  // The strongest exact HARD anchor and the relational threshold values are
  // quoted only to improve index co-occurrence; omitted exact requirements
  // (for example a storage-medium token) remain mandatory at verification.
  // When the retailer exposes a known concrete-product path scope, use it;
  // otherwise stay on the root domain. No product/model/SKU mapping is added.
  const productScopedQuotedFingerprintQuery = normalizeText(
    categoryCore &&
    host &&
    relationalHintTerms &&
    quotedHardFingerprint
      ? `site:${productScope} ${categoryCore} ${quotedHardFingerprint}`
      : ""
  );
  const siblingHostQuery = normalizeText(
    siblingCode && host
      ? `${quoteSearchTerm(siblingCode)} ${host} ${hardTerms}`
      : ""
  );
  const preciseRecoveryQuery =
    isPrimaryHost
      ? (siblingHostQuery || siteScopedFallbackQuery)
      : "";

  return {
    standardQueries: Array.from(new Set([
      labelQuery,
      relationalSpecQuery,
      categoryRelationalSpecQuery,
      categoryAnchorRelationalSpecQuery,
      productScopedQuotedFingerprintQuery,
      preciseRecoveryQuery,
    ].filter(Boolean))),
    siblingHostQuery,
    categoryRelationalSpecQuery,
    categoryAnchorRelationalSpecQuery,
    productScopedQuotedFingerprintQuery,
  };
}


function selectEarlyPrefetchedFirstPartyRecoveryCandidates(
  prefetchedResults: SearchResult[],
  parsed: ParsedQuery,
  alreadySeenResults: SearchResult[]
): SearchResult[] {
  if (prefetchedResults.length === 0) return [];

  const seenUrls = new Set(
    alreadySeenResults
      .map((item) => normalizeUrl(item.url))
      .filter(Boolean)
  );

  return filterZeroResultRecoveryCandidates(prefetchedResults, parsed)
    .filter((result) => !seenUrls.has(normalizeUrl(result.url)))
    .filter((result) =>
      result.source === "RetailerRescue" &&
      result.retailerOwnedCardEvidence === true &&
      resultProvesHardCoverageRequirements(result, parsed) &&
      getTrustedRetailerCatalogCardEvidence(result, parsed) !== null
    )
    .sort((a, b) =>
      getSearchResultPriority(b, parsed) - getSearchResultPriority(a, parsed) ||
      a.searchRank - b.searchRank
    )
    .slice(0, 6);
}

function getZeroResultRelationalSpecSupplementHosts(
  parsed: ParsedQuery,
  alreadySeenResults: SearchResult[],
  excludedHostsRaw: string[],
  limit = 2
): string[] {
  if (limit <= 0) return [];
  const hasRelationalHardRequirement = parsed.intent.required.some(
    (requirement) =>
      requirement.hard &&
      (requirement.comparison === "gte" || requirement.comparison === "lte") &&
      !isRequirementDiscoverySearchEligible(requirement)
  );
  if (!hasRelationalHardRequirement) return [];

  // CORE65: the normal zero-result host ranking intentionally favors stores
  // that suffered hard transport failures, because that is usually the best
  // retry target. Relational-spec searches expose a different failure mode:
  // a first-party adapter can return 2xx / partially settle yet produce zero
  // product cards, while the public search index still has exact product pages.
  // Add a tiny, parallel supplement lane for those readable-but-empty primary
  // retailers. This changes discovery coverage only; no requirement, condition,
  // price or availability gate is weakened.
  const excludedHosts = new Set(
    excludedHostsRaw
      .map((host) => host.replace(/^www\./i, "").trim().toLowerCase())
      .filter(Boolean)
  );
  const coveredHosts = getLikelyConcreteCoverageHostSet(
    alreadySeenResults,
    parsed
  );
  const health = getRetailerRequestHealthBucket(parsed)?.hosts;

  return getIntentPrimaryRetailerDomains(parsed)
    .map((domain, index) => ({
      host: domain.replace(/^www\./i, "").trim().toLowerCase(),
      index,
    }))
    .filter(({ host }) =>
      Boolean(host) &&
      !excludedHosts.has(host) &&
      !coveredHosts.has(host) &&
      !V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((domain) =>
        host === domain || host.endsWith(`.${domain}`)
      )
    )
    .map(({ host, index }) => {
      const state = health?.get(host);
      const successfulButEmpty = Boolean(
        state && state.directSuccesses > 0 && state.products === 0
      );
      const readableButEmpty = Boolean(
        state &&
        state.products === 0 &&
        (state.directSuccesses > 0 || state.readerSuccesses > 0)
      );
      const hardTransportFailure = Boolean(
        state && (
          state.directHardFailures > 0 ||
          (state.directAttempts > 0 && state.directSuccesses === 0)
        )
      );
      return {
        host,
        index,
        successfulButEmpty,
        readableButEmpty,
        hardTransportFailure,
      };
    })
    .sort((a, b) =>
      Number(b.successfulButEmpty) - Number(a.successfulButEmpty) ||
      Number(b.readableButEmpty) - Number(a.readableButEmpty) ||
      Number(a.hardTransportFailure) - Number(b.hardTransportFailure) ||
      a.index - b.index
    )
    .slice(0, limit)
    .map((item) => item.host);
}

function buildZeroResultAdapterDerivedLandingExpansionSeeds(
  parsed: ParsedQuery,
  limitHosts = 2
): SearchResult[] {
  if (limitHosts <= 0) return [];

  const primaryDomains = getIntentPrimaryRetailerDomains(parsed)
    .map((domain) => domain.replace(/^www\./i, "").trim().toLowerCase())
    .filter(Boolean);
  if (primaryDomains.length === 0) return [];

  const primaryRank = new Map(
    primaryDomains.map((domain, index) => [domain, index] as const)
  );
  const health = getRetailerRequestHealthBucket(parsed, false);
  const bestByHost = new Map<string, { result: SearchResult; score: number; rank: number }>();

  for (const { adapter, urls } of buildDirectRetailerCatalogRequests(parsed)) {
    const host = adapter.host.replace(/^www\./i, "").trim().toLowerCase();
    const primaryDomain = primaryDomains.find((domain) =>
      retailerHostMatchesDomain(host, domain)
    );
    if (!primaryDomain) continue;

    const state = health?.hosts.get(host);
    if (state && state.products > 0) continue;

    for (const [urlIndex, url] of urls.entries()) {
      if (!/^https?:\/\//i.test(url)) continue;

      const result: SearchResult = {
        url,
        name: normalizeText(parsed.intent.productPhrase || buildProductSearchBase(parsed)),
        snippet: normalizeText(`${parsed.intent.productPhrase || ""} ${parsed.intent.required
          .filter((requirement) => requirement.hard)
          .map((requirement) => requirement.value)
          .join(" ")}`),
        source: "RetailerRescue",
        searchRank: urlIndex,
      };

      // Only collection/search surfaces are useful here. Concrete product URLs
      // already have their normal verification path. The generated landing is
      // discovery-only and can never become a final offer by itself.
      if (!isLikelyOpenWorldCategoryOrCollectionResult(result, parsed)) continue;

      const landingScore = getRetailerLandingRescueScore(result, parsed);
      if (landingScore < 0) continue;

      const filterSpecificity = /(?:filter|filtr|dedykowana-karta-graficzna|search|szukaj|keyword|query)/i.test(url)
        ? 220
        : 0;
      const sourceHealthScore = state
        ? (state.directSuccesses > 0 && state.products === 0 ? 80 : 0) +
          (state.readerSuccesses > 0 && state.products === 0 ? 60 : 0) -
          (state.directHardFailures > 0 ? 20 : 0)
        : 0;
      const score = landingScore + filterSpecificity + sourceHealthScore - urlIndex * 8;
      const rank = primaryRank.get(primaryDomain) ?? Number.MAX_SAFE_INTEGER;
      const previous = bestByHost.get(primaryDomain);
      if (!previous || score > previous.score || (score === previous.score && rank < previous.rank)) {
        bestByHost.set(primaryDomain, { result, score, rank });
      }
    }
  }

  return [...bestByHost.values()]
    .sort((a, b) => b.score - a.score || a.rank - b.rank)
    .slice(0, limitHosts)
    .map(({ result }) => result);
}

function selectZeroResultFirstPartyLandingExpansionSeeds(
  indexedResults: SearchResult[],
  parsed: ParsedQuery,
  limitHosts = 2
): SearchResult[] {
  if (limitHosts <= 0) return [];

  const primaryDomains = getIntentPrimaryRetailerDomains(parsed)
    .map((domain) => domain.replace(/^www\./i, "").trim().toLowerCase())
    .filter(Boolean);
  if (primaryDomains.length === 0) return [];

  const primaryRank = new Map(
    primaryDomains.map((domain, index) => [domain, index] as const)
  );
  const bestByHost = new Map<string, { result: SearchResult; score: number; rank: number }>();

  for (const result of indexedResults) {
    if (result.source !== "RetailerRescue") continue;

    const host = getResultHostname(result.url);
    if (!host || !isConfiguredCommerceDomain(result.url)) continue;

    const primaryDomain = primaryDomains.find((domain) =>
      retailerHostMatchesDomain(host, domain)
    );
    if (!primaryDomain) continue;

    // Concrete product URLs already have a direct verification path. This lane
    // exists only for same-retailer category/filter/family pages surfaced by a
    // public index. An indexed result that carries its own model/code specificity
    // is kept on the direct path even if one generic matcher is conservative.
    const collectionSurface = isLikelyOpenWorldCategoryOrCollectionResult(
      result,
      parsed
    );
    if (
      !collectionSurface &&
      hasIndependentUniversalProductSpecificity(
        `${result.name} ${result.url}`,
        parsed
      )
    ) {
      continue;
    }

    const score = getRetailerLandingRescueScore(result, parsed);
    if (score < 0) continue;

    const candidate = {
      result,
      score,
      rank: primaryRank.get(primaryDomain) ?? Number.MAX_SAFE_INTEGER,
    };
    const previous = bestByHost.get(primaryDomain);
    if (
      !previous ||
      candidate.score > previous.score ||
      (
        candidate.score === previous.score &&
        (result.searchRank ?? Number.MAX_SAFE_INTEGER) <
          (previous.result.searchRank ?? Number.MAX_SAFE_INTEGER)
      )
    ) {
      bestByHost.set(primaryDomain, candidate);
    }
  }

  return [...bestByHost.values()]
    .sort((a, b) =>
      b.score - a.score ||
      a.rank - b.rank ||
      (a.result.searchRank ?? Number.MAX_SAFE_INTEGER) -
        (b.result.searchRank ?? Number.MAX_SAFE_INTEGER)
    )
    .slice(0, limitHosts)
    .map(({ result }) => result);
}

function rankZeroResultFirstPartyIndexedCandidates(
  results: SearchResult[],
  parsed: ParsedQuery,
  limit = 8
): SearchResult[] {
  if (limit <= 0) return [];
  return [...dedupeSearchResultsByUrl(results)]
    .sort((a, b) => {
      const aConcrete = isConcreteVerificationCandidate(a, parsed) ? 1 : 0;
      const bConcrete = isConcreteVerificationCandidate(b, parsed) ? 1 : 0;
      if (aConcrete !== bConcrete) return bConcrete - aConcrete;
      return getSearchResultPriority(b, parsed) - getSearchResultPriority(a, parsed) ||
        a.searchRank - b.searchRank;
    })
    .slice(0, limit);
}

async function searchZeroResultFirstPartyIndexedProducts(
  parsed: ParsedQuery,
  discoveryCore: string | null,
  existingResults: SearchResult[],
  budgetMs: number,
  externalSignal?: AbortSignal
): Promise<SearchResult[]> {
  if (budgetMs < 700 || externalSignal?.aborted) return [];

  const baseHosts = getZeroResultFirstPartyRecoveryHosts(
    parsed,
    existingResults,
    3
  );

  const identityCore = normalizeText(
    discoveryCore ||
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed) ||
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    parsed.queryText
  );
  const categoryCore = normalizeText(
    parsed.category ? detectProduct(parsed.queryText, parsed.category) : ""
  );
  const perHostBudgetMs = Math.max(700, Math.min(1_550, budgetMs));
  const [recoveryPivotRequirement] = getRarestPortfolioHardRequirements(
    existingResults, parsed, 1
  );
  const recoveryPivotTerm = recoveryPivotRequirement
    ? normalizeText(requirementDiscoveryHintTerm(recoveryPivotRequirement))
    : "";

  const hardTerms = parsed.intent.required
    .filter(isRequirementDiscoverySearchEligible)
    .slice(0, 4)
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .join(" ");

  // CORE68: zero-result recovery gets one exact-HARD anchor variant in
  // addition to the full exact-HARD footprint. Parser order already places the
  // most identity-discriminating component/variant requirements first (for
  // example a GPU model before storage medium), so one term is enough to widen
  // recall without turning the query into an unbounded category search. This
  // value is discovery-only and never changes final HARD verification.
  const relationalAnchorHardTerms = parsed.intent.required
    .filter(isRequirementDiscoverySearchEligible)
    .slice(0, 1)
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .join(" ");

  // CORE65: relational scalar requirements stay OUT of normal discovery so
  // `minimum`/`maximum` never become accidental exact-match requirements.
  // If a zero-result first-party recovery is already running, however, the
  // requested threshold values are useful as search-engine HINTS. They do not
  // alter acceptance semantics: a result recovered with `16GB`, `1TB` or
  // `144Hz` still has to pass the ordinary comparator-aware verifier, and a
  // better 32GB / 2TB / 165Hz variant remains valid even though the index query
  // used the user's threshold token. Keep this bounded to three hints so the
  // recovery query remains search-engine friendly for any future category.
  const relationalHintRequirements = parsed.intent.required
    .filter((requirement) =>
      requirement.hard &&
      Boolean(requirement.comparison) &&
      !isRequirementDiscoverySearchEligible(requirement)
    )
    .slice(0, 3);
  const relationalHintTerms = relationalHintRequirements
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .join(" ");

  // CORE70: keep the same progressive semantics as CORE68, but provide one
  // compact quoted fingerprint for the public index. Quoting is discovery-only
  // and never changes comparator semantics or the set of HARD requirements.
  const quotedHardFingerprint = [
    ...parsed.intent.required
      .filter(isRequirementDiscoverySearchEligible)
      .slice(0, 1),
    ...relationalHintRequirements,
  ]
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .map(quoteSearchTerm)
    .join(" ");

  const relationalSupplementHosts = relationalHintTerms
    ? getZeroResultRelationalSpecSupplementHosts(
        parsed,
        existingResults,
        baseHosts,
        2
      )
    : [];
  const hosts = Array.from(new Set([
    ...baseHosts,
    ...relationalSupplementHosts,
  ]));
  if (hosts.length === 0) return [];

  if (relationalSupplementHosts.length > 0) {
    console.log(
      "[AIShopping] V34.CORE120 zero-result relational-spec supplemental hosts:",
      { baseHosts, relationalSupplementHosts }
    );
  }

  const chunks = await Promise.all(
    hosts.map(async (host, hostIndex) => {
      // CORE32: a page-bound manufacturer code is valuable sibling-variant
      // discovery evidence, but exact base-MPN queries may return only external
      // reference pages while same-host fidelity remains 0. For the single
      // highest-priority first-party host, preserve those external hits only long
      // enough to mine a MORE PRECISE code in the same MPN family. A bridge code
      // is accepted only when that external result also proves every hard user
      // requirement and the same product family. The external page never becomes
      // an offer; the refined code is used only for a second first-party search,
      // whose concrete URL still goes through the unchanged verifier.
      const pageBoundCodes = Array.from(new Set(
        existingResults
          .filter((result) => retailerHostMatchesDomain(getResultHostname(result.url), host))
          .map((result) =>
            normalizeText(
              result.deferredModelIdentityBridgeCode ||
              getZeroResultFirstPartySiblingDiscoveryCode(result, parsed, host) ||
              ""
            )
          )
          .filter(Boolean)
      ));
      const siblingCode = pageBoundCodes[0] ?? "";

      // Keep the mature host-label builder for the normal lane. The pure helper
      // below only constructs the additional primary-host recovery shape and is
      // intentionally testable without any retailer/product fixtures.
      const matureLabelQuery = normalizeText(
        buildExactModelHostLabelQuery(parsed, identityCore, host) ||
        buildRelaxedFirstPartyHostLabelQuery(parsed, host)
      );
      const recoveryQueryPlan = buildZeroResultFirstPartyIndexQueries(
        identityCore,
        hardTerms,
        host,
        siblingCode,
        hostIndex === 0,
        relationalHintTerms,
        categoryCore,
        relationalAnchorHardTerms,
        quotedHardFingerprint
      );
      const siblingHostQuery = recoveryQueryPlan.siblingHostQuery;
      const plannedRecoveryQueries = recoveryQueryPlan.standardQueries
        .slice(1)
        .filter((query) =>
          !recoveryQueryPlan.categoryAnchorRelationalSpecQuery ||
          query !== recoveryQueryPlan.categoryRelationalSpecQuery
        );
      const recoveryProductScope = V28_RETAILER_PRODUCT_SITE_SCOPES[host] || host;
      // V34.CORE120: if primary discovery repeatedly found the right product
      // class but never the rarest HARD axis, ask the public index one bounded
      // single-pivot question for this SAME retailer. Omitting the other HARDs
      // is discovery-only: a recovered concrete page must still prove every
      // requirement, price, availability and identity in the normal verifier.
      const rarePivotIdentity = normalizeText(
        categoryCore || parsed.intent.productPhrase || identityCore
      );
      const rareHardPivotQuery = normalizeText(
        recoveryPivotTerm && rarePivotIdentity
          ? `site:${recoveryProductScope} ${quoteSearchTerm(rarePivotIdentity)} ${quoteSearchTerm(recoveryPivotTerm)}`
          : ""
      );
      const standardQueries = Array.from(new Set([
        rareHardPivotQuery,
        matureLabelQuery,
        ...plannedRecoveryQueries,
      ].filter(Boolean)));
      if (standardQueries.length === 0) return [] as SearchResult[];

      const standardPromise = Promise.all(
        standardQueries.map((query) =>
          searchHostLabelIndexCoverage(
            query,
            host,
            perHostBudgetMs,
            externalSignal
          )
        )
      );

      const referenceRawPromise =
        hostIndex === 0 && siblingHostQuery
          ? searchSiblingVariantReferenceIndexRaw(
              siblingHostQuery,
              Math.min(1_300, perHostBudgetMs),
              externalSignal
            )
          : Promise.resolve([] as SearchResult[]);

      // CORE99: standard search parsers frequently rank a retailer category
      // landing first even when a concrete product is indexed for the same
      // exact HARD fingerprint. Run the reference parsers in PARALLEL for one
      // strongest fingerprint query per host, then rank concrete URLs ahead of
      // collection landings before the global slice. Final verification is
      // unchanged, so index snippets never become spec/price proof.
      const preciseReferenceQuery = normalizeText(
        recoveryQueryPlan.productScopedQuotedFingerprintQuery ||
        recoveryQueryPlan.categoryRelationalSpecQuery ||
        standardQueries[0] ||
        ""
      );
      const preciseReferencePromise = preciseReferenceQuery
        ? searchHostLabelIndexCoverage(
            preciseReferenceQuery,
            host,
            Math.min(1_350, perHostBudgetMs),
            externalSignal,
            true
          )
        : Promise.resolve([] as SearchResult[]);

      const googlePromise =
        hostIndex === 0 && siblingHostQuery
          ? withAbortableDeadline(
              (signal) => searchGoogleViaJina(
                siblingHostQuery,
                externalSignal
                  ? AbortSignal.any([externalSignal, signal])
                  : signal
              ),
              Math.min(1_350, perHostBudgetMs),
              [] as SearchResult[],
              `zero-result first-party sibling Google/Jina: ${host}`
            )
          : Promise.resolve([] as SearchResult[]);

      const [standardChunks, referenceRaw, preciseReferenceIndexed, googleIndexed] = await Promise.all([
        standardPromise,
        referenceRawPromise,
        preciseReferencePromise,
        googlePromise,
      ]);

      const referenceIndexed = referenceRaw.filter((result) => {
        const resultHost = getResultHostname(result.url);
        return resultHost === host || resultHost.endsWith(`.${host}`);
      });
      const googleFaithful = googleIndexed.filter((result) => {
        const resultHost = getResultHostname(result.url);
        return resultHost === host || resultHost.endsWith(`.${host}`);
      });

      const bridgeCodes =
        hostIndex === 0 && siblingCode
          ? extractIndexedSiblingVariantCodes(
              siblingCode,
              [...existingResults, ...referenceRaw, ...googleIndexed],
              parsed,
              2
            )
          : [];

      let bridgeIndexed: SearchResult[] = [];
      if (bridgeCodes.length > 0 && !externalSignal?.aborted) {
        const bridgeQueries = buildSiblingVariantBridgeQueries(host, bridgeCodes);
        const bridgeBudgetMs = Math.max(600, Math.min(950, perHostBudgetMs));
        const bridgeChunks = await Promise.all(
          bridgeQueries.map((query) =>
            searchHostLabelIndexCoverage(
              query,
              host,
              bridgeBudgetMs,
              externalSignal
            )
          )
        );
        bridgeIndexed = dedupeSearchResultsByUrl(bridgeChunks.flat());

        console.log(
          "[AIShopping] V34.CORE120 zero-result sibling variant-code bridge:",
          {
            host,
            baseCode: siblingCode,
            bridgeCodes,
            queries: bridgeQueries,
            recovered: bridgeIndexed.length,
          }
        );
      }

      const indexed = dedupeSearchResultsByUrl([
        ...standardChunks.flat(),
        ...preciseReferenceIndexed,
        ...referenceIndexed,
        ...googleFaithful,
        ...bridgeIndexed,
      ]);

      if (hostIndex === 0 && standardQueries.length > 1) {
        console.log(
          "[AIShopping] V34.CORE120 zero-result first-party multi-index:",
          {
            host,
            siblingCode: siblingCode || null,
            queries: standardQueries,
            referenceRaw: referenceRaw.length,
            referenceRecovered: referenceIndexed.length,
            bridgeCodes,
            bridgeRecovered: bridgeIndexed.length,
            googleRecovered: googleFaithful.length,
            recovered: indexed.length,
          }
        );
      }

      // CORE70: preserve same-host index landings as discovery seeds in
      // addition to concrete product URLs. They are NOT verification candidates:
      // runZeroResultRecoverySearch either filters them out normally or, only
      // under sparse zero-result coverage, crawls a tiny bounded subset to
      // extract concrete child product cards through the mature retailer parser.
      return indexed.map((result) => ({
        ...result,
        source: "RetailerRescue",
        // Deliberately DO NOT set retailerOwnedCardEvidence. An index snippet
        // cannot self-prove listing-bound price/spec/availability.
      }));
    })
  );

  const allIndexedRecovery = dedupeSearchResultsByUrl(chunks.flat());
  const recovered = rankZeroResultFirstPartyIndexedCandidates(
    allIndexedRecovery,
    parsed,
    8
  );
  console.log(
    "[AIShopping] V34.CORE120 zero-result first-party indexed rescue:",
    {
      hosts,
      recovered: recovered.length,
      concrete: recovered.filter((item) => isConcreteVerificationCandidate(item, parsed)).length,
    }
  );
  return recovered;
}

const LATE_FIRST_PARTY_PRICE_MIN_REMAINING_MS = 7_500;
const LATE_FIRST_PARTY_PRICE_COVERAGE_TARGET = 2;

function countVerifiedIntentPrimaryRetailerHosts(
  offers: Offer[],
  parsed: ParsedQuery
): number {
  const primaryDomains = getIntentPrimaryRetailerDomains(parsed)
    .map((domain) => domain.replace(/^www\./i, "").trim().toLowerCase())
    .filter(Boolean);
  if (primaryDomains.length === 0) return 0;

  const matched = new Set<string>();
  for (const offer of offers) {
    const host = getResultHostname(offer.url);
    if (!host || !offer.priceVerified || offer.verification !== "verified") continue;

    const domain = primaryDomains.find((candidate) =>
      retailerHostMatchesDomain(host, candidate)
    );
    if (domain) matched.add(domain);
  }

  return matched.size;
}

function getLateFirstPartyPriceOptimizationHosts(
  parsed: ParsedQuery,
  existingResults: SearchResult[],
  verifiedOffers: Offer[],
  limit = 2
): string[] {
  if (limit <= 0) return [];

  const primaryDomains = getIntentPrimaryRetailerDomains(parsed)
    .map((domain) => domain.replace(/^www\./i, "").trim().toLowerCase())
    .filter(Boolean);
  if (primaryDomains.length === 0) return [];

  const coveredHosts = [...getLikelyConcreteCoverageHostSet(existingResults, parsed)];
  const verifiedHosts = verifiedOffers
    .filter((offer) => offer.priceVerified && offer.verification === "verified")
    .map((offer) => getResultHostname(offer.url))
    .filter(Boolean);

  return Array.from(new Set(primaryDomains))
    .filter((domain) =>
      !V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((marketplaceHost) =>
        retailerHostMatchesDomain(domain, String(marketplaceHost))
      )
    )
    .filter((domain) =>
      !verifiedHosts.some((host) => retailerHostMatchesDomain(host, domain))
    )
    // Do not spend the late price lane re-verifying a primary retailer that
    // already exposed a concrete candidate in the first wave. The purpose of
    // this lane is missing-store coverage, not duplicate transport retries.
    .filter((domain) =>
      !coveredHosts.some((host) => retailerHostMatchesDomain(host, domain))
    )
    .slice(0, limit);
}

function shouldRunLateFirstPartyPriceOptimization(
  verifiedOffers: Offer[],
  parsed: ParsedQuery,
  existingResults: SearchResult[],
  remainingMs: number
): boolean {
  if (verifiedOffers.length === 0) return false;
  if (remainingMs < LATE_FIRST_PARTY_PRICE_MIN_REMAINING_MS) return false;

  const primaryDomains = getIntentPrimaryRetailerDomains(parsed);
  if (primaryDomains.length === 0) return false;

  const target = Math.min(
    LATE_FIRST_PARTY_PRICE_COVERAGE_TARGET,
    new Set(primaryDomains).size
  );
  if (countVerifiedIntentPrimaryRetailerHosts(verifiedOffers, parsed) >= target) {
    return false;
  }

  return getLateFirstPartyPriceOptimizationHosts(
    parsed,
    existingResults,
    verifiedOffers,
    2
  ).length > 0;
}

function buildGenericFirstPartyRootSeeds(
  parsed: ParsedQuery,
  hostRaw: string
): SearchResult[] {
  const host = hostRaw.replace(/^www\./i, "").trim().toLowerCase();
  if (!host) return [];

  const identity = normalizeText(
    parsed.intent.productPhrase ||
    getUniversalCoverageDiscoveryCore(parsed) ||
    parsed.intent.searchBase ||
    parsed.queryText
  );
  if (!identity) return [];

  const labels = host.split(".").filter(Boolean);
  const canUseStoreSubdomain = labels.length === 2;
  const roots = parsed.country === "PL" && canUseStoreSubdomain
    ? [`https://sklep.${host}/`, `https://${host}/`]
    : canUseStoreSubdomain
      ? [`https://shop.${host}/`, `https://${host}/`]
      : [`https://${host}/`];

  return Array.from(new Set(roots)).map((url, searchRank) => ({
    url,
    name: identity,
    snippet: identity,
    source: "RetailerRescue",
    searchRank,
  }));
}

async function searchLateFirstPartyPriceOptimization(
  parsed: ParsedQuery,
  hardDeadlineAt: number,
  existingResults: SearchResult[],
  verifiedOffers: Offer[]
): Promise<SearchResult[]> {
  const remaining = Math.max(
    0,
    hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
  );
  if (remaining < LATE_FIRST_PARTY_PRICE_MIN_REMAINING_MS) return [];

  const hosts = getLateFirstPartyPriceOptimizationHosts(
    parsed,
    existingResults,
    verifiedOffers,
    2
  );
  if (hosts.length === 0) return [];

  // Spend only otherwise-unused tail budget. Keep >=2.8 s for concrete-page
  // verification and never increase the global reader cap. Host searches run
  // in parallel and each host gets at most one broad category/landing query.
  const budgetMs = Math.min(3_250, Math.max(1_900, remaining - 2_800));
  const identity = normalizeText(
    getUniversalCoverageDiscoveryCore(parsed) ||
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    parsed.queryText
  );
  if (!identity) return [];

  console.log("[AIShopping] V34.CORE120 late first-party price coverage start:", {
    remainingMs: remaining,
    budgetMs,
    hosts,
    identity,
  });

  const recovered = await withAbortableDeadline(
    async (signal) => {
      const chunks = await Promise.all(
        hosts.map(async (host) => {
          const hostStartedAt = Date.now();
          const productScope = getRetailerProductSiteScope(host);
          // Deliberately omit verification-only requirements and even package
          // qualifiers here. This lane wants a retailer category/family landing
          // when precise indexed product queries were too brittle. Concrete
          // product pages still have to prove ALL hard requirements afterward.
          const query = normalizeText(
            `site:${productScope} ${quoteSearchTerm(identity)}`
          );
          const indexBudget = Math.min(1_450, Math.max(850, budgetMs - 900));
          const indexed = await searchHostLabelIndexCoverage(
            query,
            host,
            indexBudget,
            signal
          );

          const directProducts: SearchResult[] = [];
          const landingSeeds: SearchResult[] = [];
          for (const item of indexed) {
            const itemHost = getResultHostname(item.url);
            if (!retailerHostMatchesDomain(itemHost, host)) continue;
            const candidate: SearchResult = {
              ...item,
              source: "RetailerRescue",
            };

            if (looksLikeRescuedRetailerProductCandidate(candidate, parsed, host)) {
              directProducts.push(candidate);
              continue;
            }

            if (getRetailerLandingRescueScore(candidate, parsed) >= 0) {
              landingSeeds.push(candidate);
            }
          }

          // If public indexes still expose no same-retailer landing, try two
          // generic storefront roots (Poland-first: sklep.<domain> + bare root).
          // This is domain/vertical-generic and contains no product/SKU/price
          // mapping. The crawl stays at two hops and normal match gates decide
          // whether any concrete product link is useful.
          const seeds = landingSeeds.length > 0
            ? landingSeeds
            : buildGenericFirstPartyRootSeeds(parsed, host);
          const crawlRemaining = Math.max(
            0,
            budgetMs - (Date.now() - hostStartedAt)
          );
          const crawled = seeds.length > 0 && crawlRemaining >= 850
            ? await crawlRescuedRetailerLandingPages(
                host,
                seeds,
                parsed,
                Math.min(2_450, crawlRemaining),
                signal
              )
            : [];

          console.log(
            "[AIShopping] V34.CORE120 late first-party price host:",
            host,
            "indexed=",
            indexed.length,
            "directProducts=",
            directProducts.length,
            "seeds=",
            seeds.length,
            "crawl=",
            crawled.length
          );

          return [...directProducts, ...crawled];
        })
      );

      return dedupeSearchResultsByUrl(chunks.flat()).slice(0, 8);
    },
    budgetMs,
    [] as SearchResult[],
    "late first-party price coverage"
  );

  console.log(
    "[AIShopping] V34.CORE120 late first-party price coverage results:",
    recovered.length
  );
  return recovered;
}

function buildZeroResultFocusedGoogleQuery(
  parsed: ParsedQuery,
  coverageCore: string | null,
  alreadySeenResults: SearchResult[]
): string | null {
  const identity = normalizeText(
    coverageCore ||
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed) ||
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    parsed.queryText
  );
  if (!identity) return null;

  const coveredHosts = getLikelyConcreteCoverageHostSet(
    alreadySeenResults,
    parsed
  );

  // V34.CORE120: when the first wave produced zero verified offers, search one
  // independent index across the still-missing commercial surface rather than
  // repeating the same broad query. Hosts come only from the generic marketplace
  // mesh + the matched retail vertical; there are no product/SKU/domain-price
  // exceptions here.
  const marketplaceHosts = parsed.country === "PL"
    ? [
        "allegro.pl", "ceneo.pl", "erli.pl", "allegrolokalnie.pl", "olx.pl",
        ...(getRetailVerticalMatches(parsed).some(({ profile }) => profile.id === "fashion")
          ? ["vinted.pl"]
          : []),
      ]
    : [];
  const firstPartyRecoveryHosts = getZeroResultFirstPartyRecoveryHosts(
    parsed,
    alreadySeenResults,
    4
  );
  const verticalHosts = getIntentPrimaryRetailerDomains(parsed);
  const relationalHintTerms = parsed.intent.required
    .filter((requirement) =>
      requirement.hard &&
      Boolean(requirement.comparison) &&
      !isRequirementDiscoverySearchEligible(requirement)
    )
    .slice(0, 3)
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .join(" ");
  const relationalSupplementHosts = relationalHintTerms
    ? getZeroResultRelationalSpecSupplementHosts(
        parsed,
        alreadySeenResults,
        firstPartyRecoveryHosts,
        2
      )
    : [];

  const missingMarketplaceHosts = marketplaceHosts
    .map((host) => host.replace(/^www\./i, "").toLowerCase())
    .filter((host) => host && !coveredHosts.has(host));
  const missingVerticalHosts = verticalHosts
    .map((host) => host.replace(/^www\./i, "").toLowerCase())
    .filter((host) => host && !coveredHosts.has(host));

  // CORE65: for relational-spec zero results, reserve half of the focused
  // cross-site query for first-party stores instead of letting five generic
  // marketplaces consume nearly the entire eight-host clause. The ordinary
  // non-relational path keeps the previous ordering byte-for-byte in behavior.
  const hosts = relationalHintTerms
    ? Array.from(new Set([
        ...relationalSupplementHosts,
        ...firstPartyRecoveryHosts,
        ...missingVerticalHosts,
      ])).filter(Boolean).slice(0, 4).concat(
        Array.from(new Set(missingMarketplaceHosts)).slice(0, 4)
      ).slice(0, 8)
    : Array.from(new Set([
        ...missingMarketplaceHosts,
        ...firstPartyRecoveryHosts,
        ...missingVerticalHosts,
      ])).filter(Boolean).slice(0, 8);

  if (hosts.length === 0) return null;

  const hardTerms = parsed.intent.required
    .filter(isRequirementDiscoverySearchEligible)
    .slice(0, 3)
    .map(requirementPrimarySearchTerm)
    .filter(Boolean)
    .join(" ");
  const stateHint = parsed.condition === "new"
    ? "nowy"
    : parsed.condition === "used"
      ? "uzywany"
      : "";
  const originalityHint = parsed.original === true ? "oryginalny" : "";
  const siteClause = hosts.map((host) => `site:${host}`).join(" OR ");

  return normalizeText(
    `${quoteSearchTerm(identity)} (${siteClause}) ${hardTerms} ${relationalHintTerms} ${stateHint} ${originalityHint}`
  );
}

function buildLateOlxRecoveryUrl(parsed: ParsedQuery): string | null {
  if (parsed.country !== "PL") return null;

  // V34.CORE120: late recovery must NOT repeat the same category/attribute URL
  // that already timed out during primary discovery. Use a broader generic
  // identity landing: exact/named model when available, otherwise the relaxed
  // marketplace product identity. Final variant/state/originality gates still
  // verify every recovered concrete offer.
  const exactIdentity = normalizeText(
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed)
  );
  const relaxed = buildMarketplaceDiscoveryQuery(parsed);
  const base = normalizeText(
    exactIdentity || relaxed || parsed.intent.productPhrase || parsed.intent.searchBase
  );
  if (!base) return null;

  const slug = base
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "");
  if (!slug) return null;

  return `https://www.olx.pl/oferty/q-${encodeURIComponent(slug)}/`;
}

async function searchLateOlxRecoveryViaJina(
  parsed: ParsedQuery,
  budgetMs: number,
  externalSignal?: AbortSignal
): Promise<SearchResult[]> {
  if (budgetMs < 2_400) return [];
  const url = buildLateOlxRecoveryUrl(parsed);
  if (!url) return [];

  return withAbortableDeadline(
    async (deadlineSignal) => {
      const signal = externalSignal
        ? AbortSignal.any([externalSignal, deadlineSignal])
        : deadlineSignal;
      const markdown = await fetchViaJina(
        url,
        Math.min(4_200, Math.max(2_500, budgetMs - 250)),
        true,
        signal
      );
      if (!markdown || isBlockedOrChallengePage(markdown)) return [];
      const parsedResults = parseDirectMarketplaceMarkdown(markdown, "OLXDirect");
      console.log(
        "[AIShopping] V34.CORE120 late OLX recovery reader:",
        url,
        "results=",
        parsedResults.length
      );
      return parsedResults;
    },
    budgetMs,
    [] as SearchResult[],
    "late OLX recovery reader"
  );
}

function getZeroResultExactFeatureRecoveryTerm(
  requirement: UniversalRequirement
): string {
  const primary = normalizeText(requirementPrimarySearchTerm(requirement));
  if (!primary) return "";

  // For equality requirements, the exact value is useful discovery identity.
  // For relational thresholds, keep the threshold as a search hint but add the
  // semantic axis in plain shopping language so engines can still surface a
  // better value (for example a product above a requested minimum).
  if (universalRequirementComparison(requirement) === "eq") return primary;

  const semanticByKey: Record<string, string> = {
    component_count: "elementow",
    load_capacity_kg: "maksymalne obciazenie",
    drum_capacity_kg: "wsad",
    spin_speed_rpm: "obr/min",
    read_speed_mbps: "odczyt mb/s",
    runtime_minutes: "czas pracy",
    refresh_rate: "hz",
    memory_speed: "mhz",
    cas_latency: "cl",
  };
  const semantic = semanticByKey[requirement.key] || normalizeText(requirement.label);
  const hinted = requirementDiscoveryHintTerm(requirement);
  return hinted || normalizeText(`${primary} ${semantic}`);
}

function getRareHardLexicalSearchAnchors(
  requirement: UniversalRequirement,
  limit = 3
): string[] {
  const primary = normalizeText(requirementDiscoveryHintTerm(requirement));
  const aliases = Array.from(new Set([
    ...requirement.aliases,
    requirement.label,
    requirement.value,
    primary,
  ].map((value) => normalizeText(String(value ?? ""))).filter(Boolean)));

  const anchors: string[] = [];
  const anchorKeys = new Set<string>();
  const add = (valueRaw: string) => {
    const value = normalizeText(valueRaw);
    const key = normalizeMatchText(value);
    if (!value || key.length < 2) return;
    if (["tak", "yes", "true", "nie", "no", "false"].includes(key)) return;
    if (anchorKeys.has(key)) return;
    anchorKeys.add(key);
    anchors.push(value);
  };

  // Numeric thresholds become much more indexable when kept together with a
  // nearby unit instead of a long natural-language clause.
  for (const alias of aliases) {
    const unitMatch = alias.match(/\b\d{1,7}(?:[.,]\d+)?\s*(?:mb\/s|mbps|hz|rpm|obr\/min|kg|tb|gb|pa|kpa|w|v|mah|ah|mm|cm|ml|l)\b/iu);
    if (unitMatch) add(unitMatch[0]);
  }

  // A compact mixed alpha-numeric token is often the strongest retailer-index
  // key (4D, DDR5, PCIe4, WiFi6, etc.). This is discovery vocabulary only and
  // never changes the final semantic requirement.
  for (const alias of aliases) {
    for (const match of alias.matchAll(/\b(?=[\p{L}\p{N}]*\d)(?=[\p{L}\p{N}]*\p{L})[\p{L}\p{N}]{2,12}\b/giu)) {
      add(match[0]);
    }
  }

  // Keep one short natural phrase as a stable fallback for non-numeric rare
  // requirements such as energy class, station type, waterproofing, etc.
  const shortAlias = aliases
    .filter((value) => value.split(/\s+/).length <= 4 && value.length <= 42)
    .sort((a, b) => a.length - b.length)[0];
  if (shortAlias) add(shortAlias);
  if (primary) add(primary);

  return anchors.slice(0, Math.max(1, limit));
}

function buildRareHardDirectSearchTexts(
  parsed: ParsedQuery,
  missingHard: UniversalRequirement,
  limit = 3
): string[] {
  const identity = normalizeText(
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    getUniversalCoverageDiscoveryCore(parsed) ||
    parsed.queryText
  );
  if (!identity) return [];

  const anchors = getRareHardLexicalSearchAnchors(missingHard, 3);
  const supportRequirement = parsed.intent.required
    .filter((requirement) => requirement.hard && requirement.key !== missingHard.key)
    .sort((a, b) =>
      getRetailerRequirementPivotScore(b) - getRetailerRequirementPivotScore(a)
    )[0];
  const support = supportRequirement
    ? (universalRequirementComparison(supportRequirement) === "gte" ||
        universalRequirementComparison(supportRequirement) === "lte")
      ? normalizeText(supportRequirement.label)
      : normalizeText(requirementDiscoveryHintTerm(supportRequirement))
    : "";
  const supportLiteral = supportRequirement
    ? normalizeText(
        getRareHardLexicalSearchAnchors(supportRequirement, 3)
          .find((anchor) => /\d/.test(anchor)) ||
        requirementPrimarySearchTerm(supportRequirement) ||
        requirementDiscoveryHintTerm(supportRequirement)
      )
    : "";

  const strongest = anchors[0] || normalizeText(getZeroResultExactFeatureRecoveryTerm(missingHard));
  const natural = normalizeText(getZeroResultExactFeatureRecoveryTerm(missingHard));

  // CORE120: a focused replay has two retailer URL slots. The first stays
  // recall-heavy (rare HARD only). The second now carries the strongest literal
  // supporting value with its unit (e.g. 130 kg, 7000 MB/s, 1400 obr/min).
  // This is a discovery hint only: relational thresholds remain final-verifier
  // math, and the first query still allows better-than-threshold products.
  return Array.from(new Set([
    strongest ? normalizeText(`${identity} ${strongest}`) : "",
    strongest && supportLiteral
      ? normalizeText(`${identity} ${strongest} ${supportLiteral}`)
      : "",
    natural ? normalizeText(`${identity} ${natural}`) : "",
    strongest && support ? normalizeText(`${identity} ${strongest} ${support}`) : "",
    anchors[1] ? normalizeText(`${identity} ${anchors[1]}`) : "",
  ].filter(Boolean))).slice(0, Math.max(1, limit));
}

function getRareHardRecoveryReservationScore(
  result: SearchResult,
  parsed: ParsedQuery
): number {
  const targetKey = result.rareHardRecoveryTargetKey;
  if (!targetKey) return Number.NEGATIVE_INFINITY;
  const target = parsed.intent.required.find(
    (requirement) => requirement.hard && requirement.key === targetKey
  );
  if (!target) return Number.NEGATIVE_INFINITY;

  const ownEvidence = normalizeText(`${result.name} ${result.url}`);
  const boundedEvidence = result.retailerOwnedCardEvidence === true
    ? normalizeText(`${ownEvidence} ${result.snippet}`)
    : ownEvidence;
  const ownProof = requirementHasEvidenceInContext(
    target,
    ownEvidence,
    parsed.intent.required
  );
  const boundedProof = result.retailerOwnedCardEvidence === true &&
    requirementHasEvidenceInContext(
      target,
      boundedEvidence,
      parsed.intent.required
    );
  const allProofKeys = getTrustedPortfolioHardProofKeys(result, parsed);
  const budgetFit = getTrustedPortfolioKnownBudgetFitRank(result, parsed);

  let score = 0;
  if (ownProof) score += 100_000;
  else if (boundedProof) score += 80_000;
  score += allProofKeys.length * 4_000;
  score += Math.max(-2, budgetFit) * 1_000;

  // Origin affects scheduling only. It is deliberately far weaker than bound
  // feature evidence and can never make the final verifier accept a product.
  if (result.rareHardRecoveryOrigin === "google-jina") score += 500;
  else if (result.rareHardRecoveryOrigin === "direct-retailer") score += 300;
  else if (result.rareHardRecoveryOrigin === "indexed") score += 100;

  score += Math.max(0, 500 - Math.min(500, result.searchRank));
  return score;
}

function buildZeroResultExactFeatureRecoveryQuery(
  parsed: ParsedQuery,
  coverageCore: string | null
): string | null {
  const identity = normalizeText(
    coverageCore ||
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    parsed.queryText
  );
  if (!identity) return null;

  const hardRequirements = parsed.intent.required.filter((item) => item.hard);
  if (hardRequirements.length === 0) return null;

  const highSignalKeys = new Set([
    "component_count", "load_capacity_kg", "armrests_4d",
    "drum_capacity_kg", "spin_speed_rpm", "energy_class",
    "pcie_generation", "read_speed_mbps", "runtime_minutes",
    "mopping", "self_empty_station", "refresh_rate", "resolution",
    "storage", "storage_medium", "ram", "ram_total_capacity",
  ]);
  const selected = hardRequirements
    .filter((item) => highSignalKeys.has(item.key) || item.aliases.length > 0)
    .slice(0, 5);
  if (selected.length === 0) return null;

  const terms = selected
    .map(getZeroResultExactFeatureRecoveryTerm)
    .filter(Boolean);
  if (terms.length === 0) return null;

  const stateHint = parsed.condition === "new"
    ? "nowy"
    : parsed.condition === "used"
      ? "uzywany"
      : "";

  return normalizeText(
    `${quoteSearchTerm(identity)} ${terms.join(" ")} ${stateHint} cena sklep`
  );
}


function getZeroFrequencyPortfolioHardRequirements(
  results: SearchResult[],
  parsed: ParsedQuery,
  limit = 2
): UniversalRequirement[] {
  const frequencies = getPortfolioHardRequirementFrequencies(results, parsed);
  return parsed.intent.required
    .filter((requirement) => requirement.hard)
    .filter((requirement) => (frequencies.get(requirement.key) ?? 0) === 0)
    .sort((a, b) =>
      getRetailerRequirementPivotScore(b) - getRetailerRequirementPivotScore(a)
    )
    .slice(0, Math.max(0, limit));
}

function getRareHardGapEvidenceBearingFirstPartyHosts(
  parsed: ParsedQuery,
  existingResults: SearchResult[],
  missingHard: UniversalRequirement,
  limit = 2
): string[] {
  if (limit <= 0) return [];

  const stats = new Map<string, { candidates: number; provesMissingHard: number }>();
  for (const result of existingResults) {
    const host = getResultHostname(result.url).replace(/^www\./i, "").toLowerCase();
    if (!host) continue;
    if (V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((domain) =>
      host === domain || host.endsWith(`.${domain}`)
    )) continue;

    // This lane is intentionally based on hosts that already yielded concrete
    // commerce candidates in the current request. It does not trust their
    // missing specs; it only decides where the next indexed lookup is most
    // likely to find a sibling product that exposes the rare HARD.
    const current = stats.get(host) ?? { candidates: 0, provesMissingHard: 0 };
    current.candidates += 1;
    if (getTrustedPortfolioHardProofKeys(result, parsed).includes(missingHard.key)) {
      current.provesMissingHard += 1;
    }
    stats.set(host, current);
  }

  return [...stats.entries()]
    .filter(([, stat]) => stat.candidates > 0 && stat.provesMissingHard === 0)
    .sort((a, b) =>
      b[1].candidates - a[1].candidates ||
      a[0].localeCompare(b[0])
    )
    .map(([host]) => host)
    .slice(0, limit);
}

function getRareHardGapDirectReplayHosts(
  parsed: ParsedQuery,
  existingResults: SearchResult[],
  missingHard: UniversalRequirement,
  limit = 6
): { hosts: string[]; usedFallbackMesh: boolean } {
  if (limit <= 0) return { hosts: [], usedFallbackMesh: false };

  const evidenceBearingHosts = getRareHardGapEvidenceBearingFirstPartyHosts(
    parsed,
    existingResults,
    missingHard,
    Math.min(2, limit)
  );

  // V34.CORE120 RARE-HARD SUPPLEMENTAL MESH: a current-run retailer can yield
  // perfectly valid product cards while still exposing ZERO evidence for the
  // one HARD attribute that blocked the whole portfolio. CORE117 treated the
  // mere presence of that retailer as sufficient and returned early, so a
  // five-card x-kom result could prevent Morele/other matched adapters from
  // receiving the focused 4D/7000MB/s/etc. replay at all. When the portfolio
  // frequency for `missingHard` is zero, every evidenceBearingHost is by
  // definition still missing that axis. Keep those hosts first, then fill the
  // same bounded six-host parallel replay mesh from matched direct adapters and
  // health-ranked recovery hosts. This changes discovery scheduling only; no
  // replay origin can prove a HARD requirement or bypass final verification.
  const adapterHosts = buildDirectRetailerCatalogRequests(parsed, {
    maxAdapters: Math.max(6, limit),
  })
    .map(({ adapter }) =>
      adapter.host.replace(/^www\./i, "").trim().toLowerCase()
    )
    .filter(Boolean);
  const healthRankedFallback = getZeroResultFirstPartyRecoveryHosts(
    parsed,
    existingResults,
    Math.max(6, limit)
  );

  const evidenceSet = new Set(evidenceBearingHosts);
  const hosts = Array.from(new Set([
    ...evidenceBearingHosts,
    ...adapterHosts,
    ...healthRankedFallback,
  ]))
    .filter((host) =>
      !V28_UNIVERSAL_MARKETPLACE_DOMAINS.some((domain) =>
        host === domain || host.endsWith(`.${domain}`)
      )
    )
    .slice(0, limit);

  const usedFallbackMesh = hosts.some((host) => !evidenceSet.has(host));
  return { hosts, usedFallbackMesh };
}

function buildPreVerificationRareHardGapQueries(
  parsed: ParsedQuery,
  existingResults: SearchResult[],
  limit = 5
): string[] {
  const [missingHard] = getZeroFrequencyPortfolioHardRequirements(
    existingResults,
    parsed,
    1
  );
  if (!missingHard) return [];

  const identity = normalizeText(
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    getUniversalCoverageDiscoveryCore(parsed) ||
    parsed.queryText
  );
  if (!identity) return [];

  const rareTerm = normalizeText(getZeroResultExactFeatureRecoveryTerm(missingHard));
  if (!rareTerm) return [];
  const rareAnchor = getRareHardLexicalSearchAnchors(missingHard, 1)[0] || rareTerm;

  const supportTerms = parsed.intent.required
    .filter((requirement) => requirement.hard && requirement.key !== missingHard.key)
    .sort((a, b) =>
      getRetailerRequirementPivotScore(b) - getRetailerRequirementPivotScore(a)
    )
    .slice(0, 2)
    .map((requirement) => {
      const comparison = universalRequirementComparison(requirement);
      return normalizeText(
        comparison === "gte" || comparison === "lte"
          ? requirement.label
          : getZeroResultExactFeatureRecoveryTerm(requirement)
      );
    })
    .filter(Boolean)
    .join(" ");

  const core = normalizeText(
    `${quoteSearchTerm(identity)} ${quoteSearchTerm(rareAnchor)} ${supportTerms} cena`
  );
  const evidenceBearingFirstPartyHosts =
    getRareHardGapEvidenceBearingFirstPartyHosts(
      parsed,
      existingResults,
      missingHard,
      2
    );
  const firstPartyHosts = Array.from(new Set([
    ...evidenceBearingFirstPartyHosts,
    ...getZeroResultFirstPartyRecoveryHosts(parsed, existingResults, 2),
  ])).slice(0, 2);

  const rangeRelaxedBudgetQuery =
    buildRangeRelaxedBudgetSearchQuery(parsed);

  // V34.CORE120: when discovery has ZERO evidence for a rare HARD, the
  // strongest next move is to revisit concrete first-party stores that already
  // yielded products but missed that one feature. CORE111/112 inserted the
  // range-relaxed query ahead of those host-scoped searches; with the bounded
  // five-query pulse this pushed every first-party query out of the wave and
  // caused a live chair/4D regression. Keep the broad relaxed query, but rank
  // up to two evidence-bearing first-party hosts before marketplace fallbacks.
  // This is source/evidence scheduling only: every recovered URL still passes
  // the unchanged concrete-page identity, HARD, price and availability gates.
  return Array.from(new Set([
    rangeRelaxedBudgetQuery
      ? normalizeText(`${quoteSearchTerm(rangeRelaxedBudgetQuery)} cena sklep`)
      : "",
    core,
    ...firstPartyHosts.map((host) =>
      `site:${host} ${core}`
    ),
    rangeRelaxedBudgetQuery
      ? `site:ceneo.pl ${rangeRelaxedBudgetQuery}`
      : `site:ceneo.pl ${core}`,
    `site:olx.pl/d/oferta ${core}`,
    `site:allegrolokalnie.pl/oferta ${core}`,
  ].map(normalizeText).filter(Boolean))).slice(0, Math.max(1, limit));
}

async function searchPreVerificationRareHardGap(
  parsed: ParsedQuery,
  existingResults: SearchResult[],
  hardDeadlineAt: number
): Promise<SearchResult[]> {
  const missingHard = getZeroFrequencyPortfolioHardRequirements(
    existingResults,
    parsed,
    1
  );
  if (missingHard.length === 0) return [];

  const remaining = hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
  // CORE119: rare-HARD recall is useful only if there is still time to verify
  // the recovered concrete offer. Preserve a hard verification reserve BEFORE
  // starting the retailer mesh rather than hoping the adapter-local deadlines
  // leave enough tail time. CORE118 recovered 10 useful cards but entered
  // verification with remainingMs=0.
  const verificationReserveMs = 4_650;
  if (remaining < verificationReserveMs + 1_350) return [];

  const lateCompactMode = remaining < 8_700;
  const phaseBudgetMs = Math.min(
    lateCompactMode ? 2_150 : 2_850,
    Math.max(1_250, remaining - verificationReserveMs)
  );
  const budgetMs = Math.min(
    lateCompactMode ? 650 : 1_050,
    Math.max(450, phaseBudgetMs - 1_300)
  );
  const queries = buildPreVerificationRareHardGapQueries(parsed, existingResults, 5);
  if (queries.length === 0) return [];

  console.log("[AIShopping] V34.CORE120 pre-verification rare-HARD gap search:", {
    missingKey: missingHard[0].key,
    remainingMs: remaining,
    phaseBudgetMs,
    verificationReserveMs,
    budgetMs,
    lateCompactMode,
    queries,
  });

  const { hosts: directHosts, usedFallbackMesh } =
    getRareHardGapDirectReplayHosts(
      parsed,
      existingResults,
      missingHard[0],
      6
    );
  const directIdentity = normalizeText(
    parsed.intent.productPhrase ||
    parsed.intent.searchBase ||
    getUniversalCoverageDiscoveryCore(parsed) ||
    parsed.queryText
  );
  const directRareSearchTexts = buildRareHardDirectSearchTexts(
    parsed,
    missingHard[0],
    3
  );
  const directAdapterBudgetMs = Math.min(
    lateCompactMode ? 1_850 : 2_250,
    Math.max(1_250, phaseBudgetMs - 450)
  );

  const compactRareAnchor = getRareHardLexicalSearchAnchors(missingHard[0], 1)[0] ||
    normalizeText(getZeroResultExactFeatureRecoveryTerm(missingHard[0]));
  const supportRequirement = parsed.intent.required
    .filter((requirement) => requirement.hard && requirement.key !== missingHard[0].key)
    .sort((a, b) =>
      getRetailerRequirementPivotScore(b) - getRetailerRequirementPivotScore(a)
    )[0];
  const supportSearchTerm = supportRequirement
    ? normalizeText(
        universalRequirementComparison(supportRequirement) === "gte" ||
        universalRequirementComparison(supportRequirement) === "lte"
          ? supportRequirement.label
          : requirementDiscoveryHintTerm(supportRequirement)
      )
    : "";
  const supportLiteralSearchTerm = supportRequirement
    ? normalizeText(
        getRareHardLexicalSearchAnchors(supportRequirement, 3)
          .find((anchor) => /\d/.test(anchor)) ||
        requirementPrimarySearchTerm(supportRequirement) ||
        requirementDiscoveryHintTerm(supportRequirement)
      )
    : "";
  const budgetHint = parsed.maxPrice !== null && parsed.maxPrice !== undefined
    ? normalizeText(`do ${parsed.maxPrice} zl`)
    : "";
  const targetedOpenWebQuery = normalizeText(
    `${quoteSearchTerm(directIdentity)} ${quoteSearchTerm(compactRareAnchor)} ${quoteSearchTerm(supportLiteralSearchTerm || supportSearchTerm)} ${budgetHint} cena sklep`
  );

  // CORE119: when the fallback retailer mesh is active, first-party direct
  // cards are the highest-value lane. Keep at most one tiny indexed pulse in
  // parallel; do not let broad search compete with the verification reserve.
  const indexedQueries = lateCompactMode
    ? []
    : usedFallbackMesh
      ? Array.from(new Set([targetedOpenWebQuery, ...queries].filter(Boolean))).slice(0, 1)
      : directHosts.length > 0
        ? Array.from(new Set([targetedOpenWebQuery, ...queries].filter(Boolean))).slice(0, 2)
        : Array.from(new Set([targetedOpenWebQuery, ...queries].filter(Boolean))).slice(0, 3);
  const shouldRunTargetedGoogle =
    !lateCompactMode && Boolean(targetedOpenWebQuery);

  const directPartialProducts: SearchResult[] = [];
  const directPartialSeen = new Set<string>();
  const collectDirectPartial = (results: SearchResult[]) => {
    for (const result of results) {
      const key = normalizeUrl(result.url);
      if (!key || directPartialSeen.has(key)) continue;
      directPartialSeen.add(key);
      directPartialProducts.push(result);
    }
  };

  type RareHardPhaseResult = {
    indexed: SearchResult[][];
    direct: SearchResult[];
    google: SearchResult[];
  };

  const phaseResult = await withAbortableDeadlineSnapshot<RareHardPhaseResult>(
    async (phaseSignal) => {
      const [indexed, direct, google] = await Promise.all([
        Promise.all(
          indexedQueries.map(async (query) => {
            const [bing, rss, duck] = await Promise.all([
              withAbortableDeadline(
                (innerSignal) => searchBing(
                  query,
                  AbortSignal.any([phaseSignal, innerSignal])
                ),
                budgetMs,
                [] as SearchResult[],
                "pre-verification rare-HARD Bing"
              ),
              withAbortableDeadline(
                (innerSignal) => searchBingRss(
                  query,
                  AbortSignal.any([phaseSignal, innerSignal])
                ),
                budgetMs,
                [] as SearchResult[],
                "pre-verification rare-HARD Bing RSS"
              ),
              withAbortableDeadline(
                (innerSignal) => searchDuckDuckGo(
                  query,
                  AbortSignal.any([phaseSignal, innerSignal])
                ),
                budgetMs,
                [] as SearchResult[],
                "pre-verification rare-HARD DuckDuckGo"
              ),
            ]);
            return [...bing, ...rss, ...duck].map((result) => ({
              ...result,
              rareHardRecoveryTargetKey: missingHard[0].key,
              rareHardRecoveryOrigin: "indexed" as const,
            }));
          })
        ),
        directHosts.length > 0 && directRareSearchTexts.length > 0
          ? searchDirectRetailerCatalogPages(
              parsed,
              phaseSignal,
              collectDirectPartial,
              {
                hosts: directHosts,
                overrideSearchTexts: directRareSearchTexts,
                adapterBudgetMs: directAdapterBudgetMs,
                maxAdapters: usedFallbackMesh ? Math.min(6, directHosts.length) : 2,
                maxUrlsPerAdapter: Math.min(2, directRareSearchTexts.length),
                // This is a short recovery pulse, not primary discovery. Reader
                // queues/retries can outlive the phase and starve verification;
                // direct retailer HTML is enough to nominate candidates here.
                disableReaderFallback: true,
                disableDirectRetries: true,
                directFetchTimeoutMs: Math.min(2_000, directAdapterBudgetMs - 100),
              }
            )
          : Promise.resolve([] as SearchResult[]),
        shouldRunTargetedGoogle
          ? withAbortableDeadline(
              (innerSignal) => searchGoogleViaJina(
                targetedOpenWebQuery,
                AbortSignal.any([phaseSignal, innerSignal])
              ),
              Math.min(1_450, Math.max(900, phaseBudgetMs - 1_200)),
              [] as SearchResult[],
              "pre-verification rare-HARD Google/Jina"
            )
          : Promise.resolve([] as SearchResult[]),
      ]);

      collectDirectPartial(direct);
      return { indexed, direct, google };
    },
    phaseBudgetMs,
    () => ({
      indexed: [] as SearchResult[][],
      direct: [...directPartialProducts],
      google: [] as SearchResult[],
    }),
    "pre-verification rare-HARD phase"
  );

  const directRetailerGapResults = phaseResult.direct.map((result) => ({
    ...result,
    rareHardRecoveryTargetKey: missingHard[0].key,
    rareHardRecoveryOrigin: "direct-retailer" as const,
  }));
  const googleGapResults = phaseResult.google.map((result) => ({
    ...result,
    rareHardRecoveryTargetKey: missingHard[0].key,
    rareHardRecoveryOrigin: "google-jina" as const,
  }));

  const remainingAfterPhase = Math.max(
    0,
    hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
  );
  console.log("[AIShopping] V34.CORE120 pre-verification rare-HARD direct retailer replay:", {
    missingKey: missingHard[0].key,
    hosts: directHosts,
    usedFallbackMesh,
    lateCompactMode,
    queries: directRareSearchTexts,
    phaseBudgetMs,
    verificationReserveMs,
    adapterBudgetMs: directAdapterBudgetMs,
    recovered: directRetailerGapResults.length,
    partialRecovered: directPartialProducts.length,
    targetedOpenWebQuery,
    googleRecovered: googleGapResults.length,
    remainingAfterPhaseMs: remainingAfterPhase,
  });

  const seen = new Set(existingResults.map((item) => normalizeUrl(item.url)).filter(Boolean));
  const recovered = filterZeroResultRecoveryCandidates(
    [...phaseResult.indexed.flat(), ...directRetailerGapResults, ...googleGapResults],
    parsed
  )
    .filter((item) => !seen.has(normalizeUrl(item.url)))
    .sort((a, b) =>
      getRareHardRecoveryReservationScore(b, parsed) -
        getRareHardRecoveryReservationScore(a, parsed) ||
      getSearchResultPriority(b, parsed) - getSearchResultPriority(a, parsed) ||
      a.searchRank - b.searchRank
    )
    .slice(0, 10);

  console.log("[AIShopping] V34.CORE120 pre-verification rare-HARD gap results:", {
    missingKey: missingHard[0].key,
    recovered: recovered.length,
    remainingAfterPhaseMs: Math.max(
      0,
      hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
    ),
    hosts: Object.fromEntries(
      recovered.reduce((map, item) => {
        const host = getResultHostname(item.url) || "unknown";
        map.set(host, (map.get(host) ?? 0) + 1);
        return map;
      }, new Map<string, number>())
    ),
  });

  return recovered;
}

async function runZeroResultRecoverySearch(
  parsed: ParsedQuery,
  hardDeadlineAt: number,
  alreadySeenResults: SearchResult[],
  openWebPrefetch: ZeroResultOpenWebPrefetch | null = null
): Promise<SearchResult[]> {
  const remaining = hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS;
  if (remaining < 2_200) return [];

  // V34.CORE120: recovery receives its own absolute phase deadline, already
  // separated from the final concrete-offer verification reserve. Use the
  // available phase instead of double-reserving several seconds inside it.
  const recoveryBudgetMs = Math.min(
    3_200,
    Math.max(1_300, remaining - 450)
  );
  const coverageCore = getUniversalCoverageDiscoveryCore(parsed);
  const automotive = parsed.category === "auto_part"
    ? buildAutomotiveDiscoveryQueries(parsed)
    : [];
  const stateHint = parsed.condition === "new" ? "nowy" : parsed.condition === "used" ? "uzywany" : "";
  const originalityHint = parsed.original === true ? "oryginalny" : "";
  const base = normalizeText(
    coverageCore || parsed.intent.searchBase || parsed.intent.productPhrase || parsed.queryText
  );
  const exactFeatureRecoveryQuery = buildZeroResultExactFeatureRecoveryQuery(
    parsed,
    coverageCore
  );
  const hardLexicalRecoveryQueries = buildHardCoverageLexicalRecoveryQueries(
    parsed,
    coverageCore,
    alreadySeenResults,
    3
  );
  const rangeRelaxedBudgetRecoveryQuery =
    buildRangeRelaxedBudgetSearchQuery(parsed);
  const recoveryQueries = Array.from(new Set([
    rangeRelaxedBudgetRecoveryQuery
      ? normalizeText(`${quoteSearchTerm(rangeRelaxedBudgetRecoveryQuery)} cena sklep kup`)
      : "",
    automotive[0] ?? "",
    exactFeatureRecoveryQuery ?? "",
    ...hardLexicalRecoveryQueries,
    normalizeText(`${quoteSearchTerm(base)} ${stateHint} ${originalityHint} cena kup`),
    normalizeText(`${parsed.intent.productPhrase || base} ${stateHint} ${originalityHint} sklep`),
  ].filter(Boolean))).slice(0, 4);

  const exactReferenceQuery = normalizeText(
    buildExactModelReferenceFootprintQuery(parsed) ||
    buildExactModelHardSpecFootprintQuery(parsed) ||
    recoveryQueries[0] ||
    base
  );
  const focusedGoogleQuery = buildZeroResultFocusedGoogleQuery(
    parsed,
    coverageCore,
    alreadySeenResults
  );

  console.log("[AIShopping] V34.CORE120 zero-result recovery start:", {
    remainingMs: remaining,
    budgetMs: recoveryBudgetMs,
    queries: recoveryQueries,
    prefetchedOpenWebQuery: openWebPrefetch?.query ?? null,
    lateReferenceQuery: exactReferenceQuery || null,
    lateFocusedQuery: focusedGoogleQuery,
    lateOlxEligible: !alreadySeenResults.some((item) => getResultHostname(item.url) === "olx.pl"),
  });

  // CORE75: consume request-start first-party cards BEFORE launching broad
  // marketplace/index recovery. A marketplace title without price/condition
  // must not suppress a retailer-owned card whose own bounded evidence already
  // proves every HARD requirement plus a trusted re-bound price/availability.
  const earlyPrefetchedResults = await getZeroResultPrefetchSnapshot(
    openWebPrefetch,
    hardDeadlineAt
  );
  const earlyFirstPartyCandidates = selectEarlyPrefetchedFirstPartyRecoveryCandidates(
    earlyPrefetchedResults,
    parsed,
    alreadySeenResults
  );
  if (earlyFirstPartyCandidates.length > 0) {
    console.log(
      "[AIShopping] V34.CORE120 zero-result early first-party prefetch hit:",
      earlyFirstPartyCandidates.map((result) => ({
        host: getResultHostname(result.url),
        name: result.name,
        url: result.url,
        price: extractSearchResultPrice(result, parsed.condition, false),
        availability: result.retailerCatalogCardAvailability ?? "unknown",
      }))
    );
    return earlyFirstPartyCandidates;
  }

  const hasSeenOlx = alreadySeenResults.some((item) => getResultHostname(item.url) === "olx.pl");
  const exactModelRecovery = Boolean(
    getCompactExactModelDiscoveryCore(parsed) ||
    getNamedVariantDiscoveryCore(parsed) ||
    getUniversalExactModelAnchor(parsed, parsed.intent.productPhrase)
  );
  const hardVariantRecovery =
    parsed.intent.required.some((requirement) => requirement.hard) &&
    parsed.intent.strongIdentityTerms.length >= 2;
  const preciseOlxRecovery = exactModelRecovery || hardVariantRecovery;

  // V34.CORE120: exact-model and hard-variant searches can both be precise
  // enough for one late OLX retry. Recovery already runs under an absolute
  // phase deadline preserves a compact final concrete-verification window, so
  // this lane may use most of the recovery phase without double-reserving it.
  const lateOlxBudgetMs = !hasSeenOlx && preciseOlxRecovery && remaining >= 3_000
    ? Math.min(
        recoveryBudgetMs,
        3_200,
        Math.max(0, remaining - 700)
      )
    : 0;
  const lateOlxPromise = lateOlxBudgetMs >= 2_400
    ? searchLateOlxRecoveryViaJina(parsed, lateOlxBudgetMs)
    : Promise.resolve([] as SearchResult[]);

  // V34.CORE120: retry the public JSON endpoint independently in recovery.
  // This is intentionally parallel to the legacy Jina landing: a temporary
  // CloudFront/API failure and a Jina timeout are independent failure modes.
  const lateOlxApiBudgetMs = !hasSeenOlx && preciseOlxRecovery && remaining >= 3_200
    ? Math.min(
        recoveryBudgetMs,
        3_000,
        Math.max(0, remaining - 700)
      )
    : 0;
  const lateOlxApiQuery = normalizeText(
    buildOlxPublicApiSearchQuery(parsed) || coverageCore || base
  );
  const lateOlxApiPromise = lateOlxApiBudgetMs >= 1_500
    ? withAbortableDeadline(
        (signal) => searchOlxPublicJsonApi(parsed, lateOlxApiQuery, signal),
        lateOlxApiBudgetMs,
        [] as SearchResult[],
        "zero-result OLX public JSON recovery"
      )
    : Promise.resolve([] as SearchResult[]);

  const marketplaceBudgetMs = Math.min(2_250, recoveryBudgetMs);
  const marketplacePromise = coverageCore
    ? withAbortableDeadline(
        (signal) => searchIndexedMarketplaceProductRescue(
          parsed,
          coverageCore,
          marketplaceBudgetMs,
          signal
        ),
        marketplaceBudgetMs,
        [] as SearchResult[],
        "zero-result marketplace recovery"
      )
    : Promise.resolve([] as SearchResult[]);

  const firstPartyIndexBudgetMs = Math.min(2_350, recoveryBudgetMs);
  const firstPartyIndexedPromise = withAbortableDeadline(
    (signal) => searchZeroResultFirstPartyIndexedProducts(
      parsed,
      coverageCore,
      alreadySeenResults,
      firstPartyIndexBudgetMs,
      signal
    ),
    firstPartyIndexBudgetMs,
    [] as SearchResult[],
    "zero-result first-party indexed recovery"
  );

  // CORE26: CORE25 constructed and logged this precise hard-spec query but did
  // not execute it. Keep it independent from the host-label first-party lane:
  // the focused query can still recover marketplaces/comparison pages, while
  // every URL must pass the unchanged candidate + concrete-page verifier.
  const focusedQueryBudgetMs = Math.min(2_100, recoveryBudgetMs);
  const relationalHardRecovery =
    parsed.intent.required.filter((requirement) => requirement.hard).length >= 2;
  const focusedOpenWebPromise =
    focusedGoogleQuery && (exactModelRecovery || relationalHardRecovery)
      ? withAbortableDeadline(
          (signal) => searchGoogleViaJina(focusedGoogleQuery, signal),
          focusedQueryBudgetMs,
          [] as SearchResult[],
          "zero-result focused open-web recovery"
        )
      : Promise.resolve([] as SearchResult[]);

  const queryEngineBudgetMs = Math.min(2_150, recoveryBudgetMs);
  const queryChunksPromise = Promise.all(recoveryQueries.slice(0, 3).map(async (query) => {
    // CORE106 recovery uses the two Bing surfaces first. Repeated DuckDuckGo
    // network failures consumed 1.8 s lanes in every CORE105 benchmark without
    // producing candidates; normal discovery still retains DDG when healthy.
    const [bing, rss] = await Promise.all([
      withAbortableDeadline(
        (signal) => searchBing(query, signal),
        queryEngineBudgetMs,
        [] as SearchResult[],
        "zero-result Bing recovery"
      ),
      withAbortableDeadline(
        (signal) => searchBingRss(query, signal),
        queryEngineBudgetMs,
        [] as SearchResult[],
        "zero-result Bing RSS recovery"
      ),
    ]);
    return [...bing, ...rss];
  }));

  // CORE7: the slow independent reader was started near request start, in
  // parallel with primary discovery. Consume its snapshot now instead of
  // launching two fresh Jina requests that real logs showed timing out at 2.45 s.
  const prefetchedOpenWebPromise = Promise.resolve(earlyPrefetchedResults);

  const [
    marketplace,
    firstPartyIndexed,
    focusedOpenWeb,
    queryChunks,
    prefetchedOpenWeb,
    lateOlx,
    lateOlxApi,
  ] = await Promise.all([
    marketplacePromise,
    firstPartyIndexedPromise,
    focusedOpenWebPromise,
    queryChunksPromise,
    prefetchedOpenWebPromise,
    lateOlxPromise,
    lateOlxApiPromise,
  ]);

  const seenUrls = new Set(
    alreadySeenResults
      .map((item) => normalizeUrl(item.url))
      .filter(Boolean)
  );
  let rawRecoveryResults = dedupeSearchResultsByUrl([
    ...marketplace,
    ...firstPartyIndexed,
    ...focusedOpenWeb,
    ...queryChunks.flat(),
    ...prefetchedOpenWeb,
    ...lateOlxApi,
    ...lateOlx,
  ]);
  let recovered = filterZeroResultRecoveryCandidates(
    rawRecoveryResults,
    parsed
  )
    .filter((item) => !seenUrls.has(normalizeUrl(item.url)))
    .slice(0, 10);

  // CORE70: public indexes often return a retailer-owned filtered category page
  // instead of the concrete product card that made the page relevant. CORE68
  // correctly refused to verify such a collection URL, but then discarded the
  // useful first-party discovery surface entirely. When recovery is still sparse,
  // keep at most one landing per two primary retailers and crawl those landings
  // with the existing mature product-card parser. This spends only tail budget
  // that would otherwise be unused and always preserves >=3.2 s for concrete
  // product verification. The landing itself never becomes an offer. CORE106's
  // phase deadline already preserves the final verifier window, so this crawl
  // can use the remaining recovery phase more fully.
  const remainingForIndexedLandingExpansion = Math.max(
    0,
    hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
  );
  const indexedLandingSeeds = recovered.length < 2
    ? dedupeSearchResultsByUrl([
        // CORE75: do not depend on a public index to rediscover a precise
        // first-party filter URL that our own source adapter already derived
        // from the user's generic HARD requirements. These adapter-derived
        // landings are tried first; indexed broad category pages remain a
        // fallback. The landing itself never becomes an offer.
        ...buildZeroResultAdapterDerivedLandingExpansionSeeds(parsed, 2),
        ...selectZeroResultFirstPartyLandingExpansionSeeds(
          firstPartyIndexed,
          parsed,
          2
        ),
      ]).slice(0, 2)
    : [];

  if (
    indexedLandingSeeds.length > 0 &&
    remainingForIndexedLandingExpansion >= 4_600
  ) {
    const landingExpansionBudgetMs = Math.min(
      3_800,
      Math.max(1_600, remainingForIndexedLandingExpansion - 700)
    );

    const crawledLandingProducts = await withAbortableDeadline(
      async (signal) => {
        const chunks = await Promise.all(
          indexedLandingSeeds.map((seed) => {
            const host = getResultHostname(seed.url);
            if (!host) return Promise.resolve([] as SearchResult[]);
            return crawlRescuedRetailerLandingPages(
              host,
              [seed],
              parsed,
              landingExpansionBudgetMs,
              signal
            );
          })
        );
        return dedupeSearchResultsByUrl(chunks.flat()).slice(0, 8);
      },
      landingExpansionBudgetMs,
      [] as SearchResult[],
      "zero-result first-party indexed landing expansion"
    );

    if (crawledLandingProducts.length > 0) {
      rawRecoveryResults = dedupeSearchResultsByUrl([
        ...rawRecoveryResults,
        ...crawledLandingProducts,
      ]);
      recovered = filterZeroResultRecoveryCandidates(
        rawRecoveryResults,
        parsed
      )
        .filter((item) => !seenUrls.has(normalizeUrl(item.url)))
        .slice(0, 10);
    }

    console.log(
      "[AIShopping] V34.CORE120 zero-result indexed landing expansion:",
      {
        budgetMs: landingExpansionBudgetMs,
        seeds: indexedLandingSeeds.map((seed) => ({
          host: getResultHostname(seed.url),
          name: seed.name,
          url: seed.url,
        })),
        crawledProducts: crawledLandingProducts.length,
        recoveredCandidates: recovered.length,
      }
    );
  }

  console.log("[AIShopping] V34.CORE120 zero-result recovery source mix:",
    rawRecoveryResults.reduce<Record<string, number>>((acc, item) => {
      acc[item.source] = (acc[item.source] ?? 0) + 1;
      return acc;
    }, {})
  );
  console.log("[AIShopping] V34.CORE120 zero-result recovery candidates:", recovered.map((item) => ({
    host: getResultHostname(item.url), name: item.name, source: item.source, url: item.url,
  })));
  return recovered;
}

type CachedSearchResponse = {
  expiresAt: number;
  promise: Promise<NextResponse>;
};

const SEARCH_REQUEST_CACHE = new Map<string, CachedSearchResponse>();
const SEARCH_REQUEST_DEDUPE_MS = 8_000;

function getSearchCacheKey(query: string, country: unknown): string {
  return JSON.stringify({
    query: normalizeText(query).toLowerCase(),
    country:
      typeof country === "string"
        ? country.trim().toUpperCase()
        : null,
  });
}

export async function POST(request: Request): Promise<NextResponse> {
  try {
    const body = await request.json();

    const query =
      typeof body?.query === "string"
        ? normalizeText(body.query)
        : "";

    if (!query) {
      return NextResponse.json(
        {
          success: false,
          error: "Brak zapytania.",
          offers: [],
        },
        { status: 400 }
      );
    }

    const isAlternativeChild = body?.__alternativeChild === true;
    const alternativeQueries = isAlternativeChild
      ? []
      : splitAlternativeShoppingQuery(query);

    if (alternativeQueries.length >= 2) {
      console.log("================================================");
      console.log("[AIShopping] NEW SEARCH V34.CORE187 alternatives:", alternativeQueries);

      // Alternatives run independently and in parallel. This preserves the
      // same wall-clock target as one search while preventing cross-product
      // identity contamination (category/brand/model/requirements).
      const childResponses: NextResponse[] = await Promise.all(
        alternativeQueries.map((alternativeQuery) =>
          POST(
            new Request(request.url, {
              method: "POST",
              headers: { "content-type": "application/json" },
              body: JSON.stringify({
                ...body,
                query: alternativeQuery,
                __alternativeChild: true,
              }),
            })
          )
        )
      );

      const payloads: AlternativeChildSearchResponse[] = await Promise.all(
        childResponses.map(async (response: NextResponse) =>
          (await response.json()) as AlternativeChildSearchResponse
        )
      );

      const cleanOffers = mergeAlternativeOffers(payloads);
      const discoveredCandidates = payloads.reduce(
        (sum, payload) => sum + (payload.coverage?.discoveredCandidates ?? 0),
        0
      );
      const verificationCandidates = payloads.reduce(
        (sum, payload) => sum + (payload.coverage?.verificationCandidates ?? 0),
        0
      );
      const anyVerifiedMismatch = payloads.some(
        (payload) => payload.resultStatus === "no_matching_verified_offer"
      );
      const resultStatus = cleanOffers.length > 0
        ? "offers_found"
        : anyVerifiedMismatch
          ? "no_matching_verified_offer"
          : "coverage_incomplete";

      return NextResponse.json({
        success: payloads.some((payload) => payload.success !== false),
        query,
        interpreted: {
          mode: "alternatives",
          alternatives: payloads.map((payload, index) => ({
            query: alternativeQueries[index],
            interpreted: payload.interpreted ?? null,
            resultStatus: payload.resultStatus ?? null,
            found: payload.found ?? 0,
          })),
        },
        offers: cleanOffers,
        found: cleanOffers.length,
        resultStatus,
        coverage: { discoveredCandidates, verificationCandidates },
        message: cleanOffers.length > 0
          ? "Znaleziono pasujące oferty dla podanych alternatyw."
          : anyVerifiedMismatch
            ? "Znaleziono produkty dla podanych alternatyw, ale żadna zweryfikowana oferta nie spełnia wszystkich warunków."
            : "Nie udało się zdobyć wystarczającej liczby konkretnych ofert dla podanych alternatyw.",
      });
    }

    const parsed = parseQuery(query, body?.country);
    V32_RETAILER_REQUEST_HEALTH.delete(getRetailerRequestHealthKey(parsed));
    getRetailerRequestHealthBucket(parsed, true);

    const requestStartedAt = Date.now();
    const hardDeadlineAt = requestStartedAt + HARD_SEARCH_BUDGET_MS;

    console.log("================================================");
    console.log("[AIShopping] NEW SEARCH V34.CORE187");
    console.log("[AIShopping] query:", query);
    console.log("[AIShopping] category:", parsed.category);
    console.log("[AIShopping] platform:", parsed.platform);
    console.log("[AIShopping] brand:", parsed.brand);
    console.log("[AIShopping] condition:", parsed.condition);
    console.log("[AIShopping] original:", parsed.original);
    console.log("[AIShopping] maxPrice:", parsed.maxPrice);
    console.log("[AIShopping] country:", parsed.country);
    console.log(
      "[AIShopping] V34.CORE120 configured commerce domains:",
      getConfiguredCommerceDomains().length
    );
    console.log(
      "[AIShopping] V34.CORE176 static commerce coverage audit:",
      getV34Core176StaticCoverageAudit()
    );
    console.log(
      "[AIShopping] V34.CORE176 query retail coverage audit:",
      getV34Core176QueryCoverageAudit(parsed)
    );
    console.log("[AIShopping] V34.CORE120 universal intent:", {
      productPhrase: parsed.intent.productPhrase,
      searchBase: parsed.intent.searchBase,
      identityTerms: parsed.intent.identityTerms,
      strongIdentityTerms: parsed.intent.strongIdentityTerms,
      qualifierTerms: parsed.intent.qualifierTerms,
      required: parsed.intent.required.map((item) => ({
        key: item.key,
        label: item.label,
        value: item.value,
        hard: item.hard,
        comparison: universalRequirementComparison(item),
      })),
      forbiddenTerms: parsed.intent.forbiddenTerms,
      accessoryIntent: parsed.intent.accessoryIntent,
      openWorld: parsed.intent.openWorld,
      normalizedQuery: parsed.intent.normalizedQuery,
      searchVariants: parsed.intent.searchVariants,
      confidence: parsed.intent.confidence,
    });
    console.log("================================================");

    const queries = buildSearchQueries(parsed);

    // V34.CORE164 PRIORITY CENEO PREFLIGHT
    // Precise model/technology searches previously launched the exact Ceneo
    // RSS lookup into the same 20+ branch network burst as generic/targeted
    // Bing and retailer discovery. Live runs proved the lookup itself works,
    // but it intermittently timed out before receiving a socket/response. Give
    // that single high-value comparison lane a bounded head start, then reuse
    // its request-scoped result later inside direct Ceneo discovery.
    if (shouldRunCeneoPriorityPreflight(parsed)) {
      const ceneoPreflightStartedAt = Date.now();
      console.log(
        "[AIShopping] V34.CORE164 Ceneo priority preflight start"
      );

      const ceneoPreflightResults = await withDeadline(
        searchCeneoIndexedEmptyPageFallback(parsed, 1_950),
        2_050,
        [] as SearchResult[],
        "Ceneo priority preflight"
      );

      V34_CENEO_PRIORITY_PREFLIGHT.set(parsed, {
        attempted: true,
        results: ceneoPreflightResults,
      });

      console.log(
        "[AIShopping] V34.CORE164 Ceneo priority preflight settled:",
        {
          results: ceneoPreflightResults.length,
          elapsedMs: Date.now() - ceneoPreflightStartedAt,
        }
      );
    }

    // V34.CORE120 REQUEST-START OPEN-WEB RECOVERY PREFETCH
    // It runs concurrently with normal discovery and is consumed only if the
    // first verification wave yields zero/no recommendable-original offers.
    const zeroResultOpenWebPrefetch = startZeroResultOpenWebPrefetch(parsed);

    // V34.CORE120 EXACT-MODEL STATIC PROFILE PREFETCH
    // Start stable model/spec proof immediately, in parallel with discovery.
    // Verification later reuses the same cache key, so it does not have to
    // spend the last seconds of the request discovering basic model facts.
    // Listing-specific/configurable values are excluded by
    // canUseExternalProofForRequirement and remain bound to each offer.
    const prefetchedStaticRequirements = parsed.intent.required
      .filter((requirement) => requirement.hard)
      .filter(canUseExternalProofForRequirement);
    const prefetchedExactModelAnchor = getUniversalExactModelAnchor(
      parsed,
      parsed.intent.productPhrase || parsed.intent.searchBase
    );

    let prefetchedExactModelStaticProofPromise: Promise<string> | null = null;

    if (
      prefetchedExactModelAnchor &&
      prefetchedStaticRequirements.length > 0
    ) {
      console.log("[AIShopping] V34.CORE120 exact-model static proof prefetch:", {
        anchor: prefetchedExactModelAnchor,
        keys: prefetchedStaticRequirements.map((item) => item.key),
      });

      // Keep the actual in-flight Promise. Verification receives this same
      // exact-model proof object instead of reconstructing model identity from
      // a seller title that may split/simplify the manufacturer code.
      prefetchedExactModelStaticProofPromise =
        findUniversalRequirementProofViaSearch(
          parsed.intent.productPhrase || parsed.intent.searchBase,
          prefetchedStaticRequirements,
          parsed,
          ""
        );
    }

    // V32.12 SOFT DISCOVERY DEADLINE: abort outstanding network requests at
    // the discovery budget, but DO NOT race runSearch against an [] fallback.
    // runSearch owns the already-completed results and returns them after the
    // aborted/individually-timed-out branches settle. This prevents the V28.7
    // failure where OLX + Rossmann had already found dozens of products, yet
    // the API returned 0 because the outer timeout won the race.
    const discoveryController = new AbortController();
    const effectiveDiscoveryBudgetMs = getEffectiveDiscoveryBudgetMs(parsed);
    const effectiveDiscoveryNetworkBudgetMs = getEffectiveDiscoveryNetworkBudgetMs(parsed);
    const discoveryTimer = setTimeout(() => {
      console.log(
        "[AIShopping] V34.CORE120 network discovery cancellation:",
        {
          networkBudgetMs: effectiveDiscoveryNetworkBudgetMs,
          totalDiscoveryBudgetMs: effectiveDiscoveryBudgetMs,
          validationReserveMs: DISCOVERY_VALIDATION_RESERVE_MS,
        }
      );
      discoveryController.abort();
    }, effectiveDiscoveryNetworkBudgetMs);

    const staticReferenceCandidates: SearchResult[] = [];
    let searchResults: SearchResult[] = [];
    try {
      searchResults = await runSearch(
        queries,
        parsed,
        discoveryController.signal,
        staticReferenceCandidates
      );
    } finally {
      clearTimeout(discoveryTimer);
      if (!discoveryController.signal.aborted) {
        discoveryController.abort();
      }
    }

    const postDiscoverySiblingBridge =
      buildV34Core183DeterministicSiblingCatalogBridgeCandidates(searchResults, parsed);
    if (postDiscoverySiblingBridge.length > 0) {
      searchResults = dedupeSearchResultsByUrl([
        ...searchResults,
        ...postDiscoverySiblingBridge,
      ]);
      console.log(
        "[AIShopping] V34.CORE183 search results after sibling bridge:",
        searchResults.length
      );
    }

    console.log(
      "[AIShopping] raw search results:",
      searchResults.length
    );

    // V34.CORE120: if ordinary discovery has ZERO trusted evidence for one HARD
    // requirement, verifying a whole batch that cannot possibly satisfy it wastes
    // the request. Spend one short parallel Bing pulse on that missing axis first.
    // This is generic, bounded and discovery-only; recovered URLs still pass the
    // unchanged concrete offer verifier below.
    const rareHardGapResults = await searchPreVerificationRareHardGap(
      parsed,
      searchResults,
      hardDeadlineAt
    );
    if (rareHardGapResults.length > 0) {
      searchResults = dedupeSearchResultsByUrl([
        ...searchResults,
        ...rareHardGapResults,
      ]);
      console.log(
        "[AIShopping] V34.CORE120 discovery after rare-HARD gap:",
        searchResults.length
      );
    }

    // V32.12: broad discovery first, expensive verification only for the strongest
    // candidates. Diversity prevents one marketplace from consuming the batch.
    // Requirement-heavy searches previously verified only eight candidates.
    // In practice several slots can be rejected instantly (wrong bundle,
    // over budget or used condition). CORE106's bounded 20-second scheduler
    // can safely retain sixteen ranked/diverse candidates and let the existing
    // hard deadline stop slow page fetches safely.
    const remainingBeforeCandidateSelection = Math.max(
      0,
      hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
    );

    // V32.12 keeps a real verification window. When discovery was slower than
    // usual, verifying fewer strong/diverse candidates is better than preparing
    // twelve and letting every worker discover that the hard deadline is gone.
    const baseVerificationLimit =
      remainingBeforeCandidateSelection < MIN_USEFUL_VERIFICATION_WINDOW_MS
        ? Math.min(4, VERIFICATION_CANDIDATE_LIMIT)
        : remainingBeforeCandidateSelection < 5_500
          ? Math.min(5, VERIFICATION_CANDIDATE_LIMIT)
          : remainingBeforeCandidateSelection < 8_000
            ? Math.min(7, VERIFICATION_CANDIDATE_LIMIT)
            : VERIFICATION_CANDIDATE_LIMIT;
    const hardRequirementCount = parsed.intent.required.filter(
      (requirement) => requirement.hard
    ).length;
    const verificationLimit =
      parsed.brand && hardRequirementCount >= 3
        ? Math.min(6, baseVerificationLimit)
        : parsed.brand && hardRequirementCount >= 2
          ? Math.min(8, baseVerificationLimit)
          : baseVerificationLimit;

    console.log("[AIShopping] V34.CORE120 verification budget before selection:", {
      remainingMs: remainingBeforeCandidateSelection,
      candidateLimit: verificationLimit,
    });

    const verificationPool = pruneV34Core164ExplicitCompetingBrandsBeforeVerification(
      pruneKnownOverBudgetBeforeVerification(searchResults, parsed),
      parsed
    );

    const rareHardGapExplicitProof = rareHardGapResults
      .filter((result) => getRareHardRecoveryReservationScore(result, parsed) >= 80_000)
      .sort((a, b) =>
        getRareHardRecoveryReservationScore(b, parsed) -
        getRareHardRecoveryReservationScore(a, parsed)
      );
    const rareHardGapFallback = rareHardGapResults
      .filter((result) => Boolean(result.rareHardRecoveryTargetKey))
      .sort((a, b) =>
        getRareHardRecoveryReservationScore(b, parsed) -
        getRareHardRecoveryReservationScore(a, parsed)
      );
    // V34.CORE120: if a recovered card already exposes the missing HARD in its
    // OWN/bounded evidence, reserve up to two such candidates. Otherwise keep
    // only the single strongest targeted recovery candidate. CORE115 reserved
    // two arbitrary replay hits even when neither showed the missing feature,
    // wasting scarce verifier slots on candidates known to be weak.
    const rareHardGapReserveCandidates = rareHardGapExplicitProof.length > 0
      ? rareHardGapExplicitProof.slice(0, 2)
      : rareHardGapFallback.slice(0, 1);
    const rareHardGapReserveUrls = new Set(
      rareHardGapReserveCandidates
        .map((result) => normalizeUrl(result.url))
        .filter(Boolean)
    );
    if (rareHardGapReserveCandidates.length > 0) {
      console.log("[AIShopping] V34.CORE120 rare-HARD reserve candidates:",
        rareHardGapReserveCandidates.map((result) => ({
          host: getResultHostname(result.url),
          name: result.name,
          targetKey: result.rareHardRecoveryTargetKey ?? null,
          origin: result.rareHardRecoveryOrigin ?? null,
          reservationScore: getRareHardRecoveryReservationScore(result, parsed),
          proofKeys: getTrustedPortfolioHardProofKeys(result, parsed),
        }))
      );
    }

    const limitedResults = capV34Core164VerificationCandidatesBySourceHealth(
      selectDiverseSearchResults(
        verificationPool,
        verificationLimit,
        parsed,
        rareHardGapReserveUrls
      ),
      parsed,
      verificationLimit
    );

    console.log(
      "[AIShopping] V34.CORE120 verification candidates:",
      limitedResults.length,
      Object.fromEntries(
        limitedResults.reduce((map, result) => {
          const host = getResultHostname(result.url) || "unknown";
          map.set(host, (map.get(host) ?? 0) + 1);
          return map;
        }, new Map<string, number>())
      )
    );

    // V34.CORE120 staged verification: verify first, recover only after failure.
    // CORE6 always reserved 3.6 s for recovery and therefore gave a strong
    // no-price marketplace listing only ~4.7 s. OLX/Jina starts are globally
    // rate-limited, so a correct concrete offer could time out even while the
    // route still had >10 s available. Adapt the split to the evidence already
    // discovered: when one high-value concrete marketplace listing needs only
    // its own page price/condition, verification gets the larger share.
    const firstWaveRemaining = Math.max(
      0, hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
    );
    const {
      slowMarketplaceVerificationPressure,
      deferredModelBridgeVerificationPressure,
      firstVerificationWindowMs,
      recoveryReserveMs,
      shouldReserveZeroResultRecovery,
    } = getStagedVerificationBudgetProfile(
      limitedResults,
      parsed,
      firstWaveRemaining
    );
    const firstVerificationDeadline = shouldReserveZeroResultRecovery
      ? Math.min(
          hardDeadlineAt,
          Date.now() + firstVerificationWindowMs + RESPONSE_SAFETY_MARGIN_MS
        )
      : hardDeadlineAt;

    console.log("[AIShopping] V34.CORE120 staged verification budget:", {
      firstWaveRemaining,
      slowMarketplaceVerificationPressure,
      deferredModelBridgeVerificationPressure,
      firstVerificationWindowMs,
      recoveryReserveMs,
      shouldReserveZeroResultRecovery,
    });

    let offers = await verifyOffers(
      limitedResults,
      parsed,
      firstVerificationDeadline,
      staticReferenceCandidates,
      prefetchedExactModelStaticProofPromise
    );

    let preRecoveryScored = scoreAndRankOffers(
      deduplicateOffers(offers, parsed),
      parsed
    );
    let remainingForRecovery = Math.max(
      0, hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
    );

    // V34.CORE120: if the first wave produced zero offers specifically because
    // a concrete reader-bound marketplace listing spent most of its reader
    // window and returned no page, prefer one controlled second chance over
    // immediately discarding that exact URL and launching broad discovery.
    // The retry candidate is much stricter than the ordinary verification
    // queue: its OWN title must already prove every HARD listing attribute.
    if (preRecoveryScored.length === 0) {
      const transientRetryCandidates =
        selectLateTransientMarketplaceRetryCandidates(limitedResults, parsed);
      const transientRetryWindowMs =
        getLateTransientMarketplaceRetryWindowMs(remainingForRecovery);

      if (
        transientRetryCandidates.length > 0 &&
        transientRetryWindowMs > 0
      ) {
        const transientRetryDeadline = Math.min(
          hardDeadlineAt,
          Date.now() + transientRetryWindowMs + RESPONSE_SAFETY_MARGIN_MS
        );

        console.log(
          "[AIShopping] V34.CORE120 late transient marketplace retry start:",
          {
            remainingMs: remainingForRecovery,
            budgetMs: transientRetryWindowMs,
            candidates: transientRetryCandidates.map((result) => ({
              host: getResultHostname(result.url),
              url: result.url,
              name: result.name,
            })),
          }
        );

        const transientRetryOffers = await verifyOffers(
          transientRetryCandidates,
          parsed,
          transientRetryDeadline,
          staticReferenceCandidates,
          prefetchedExactModelStaticProofPromise
        );
        offers = [...offers, ...transientRetryOffers];
        preRecoveryScored = scoreAndRankOffers(
          deduplicateOffers(offers, parsed),
          parsed
        );
        remainingForRecovery = Math.max(
          0, hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
        );

        console.log(
          "[AIShopping] V34.CORE120 late transient marketplace retry results:",
          {
            verifiedOffers: transientRetryOffers.length,
            remainingMs: remainingForRecovery,
          }
        );
      }
    }

    const firstWaveHasRecommendableOriginal =
      parsed.original !== true ||
      preRecoveryScored.some((offer) =>
        offer.originalityConfidence === "high" || offer.originalityConfidence === "medium"
      );
    const recoveryNeeded =
      preRecoveryScored.length === 0 || !firstWaveHasRecommendableOriginal;

    // V34.CORE120: broad recovery gets its OWN absolute deadline. CORE78's
    // individual lane timeouts were not enough under real load: late/ghost
    // parsing could delay JS timers and the recovery function returned with only
    // ~0.35 s left for three concrete candidates. Ending search recovery before
    // the global deadline guarantees one useful listing-verification window.
    // Final verification still owns the original hardDeadlineAt and all HARD /
    // price / condition / availability gates remain unchanged.
    const recoverySearchDeadlineAt =
      getZeroResultRecoverySearchDeadlineAt(hardDeadlineAt);
    const remainingForRecoverySearch = Math.max(
      0,
      recoverySearchDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
    );

    if (recoveryNeeded && remainingForRecoverySearch >= 2_200) {
      console.log("[AIShopping] V34.CORE120 zero-result recovery phase budget:", {
        globalRemainingMs: remainingForRecovery,
        searchRemainingMs: remainingForRecoverySearch,
        preservedVerificationMs: ZERO_RESULT_RECOVERED_VERIFICATION_RESERVE_MS,
      });

      const recoveredResults = await runZeroResultRecoverySearch(
        parsed,
        recoverySearchDeadlineAt,
        searchResults,
        zeroResultOpenWebPrefetch
      );
      if (recoveredResults.length > 0) {
        const remainingForRecoveredVerification = Math.max(
          0,
          hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
        );
        const recoveryLimit = remainingForRecoveredVerification < 4_500
          ? 3
          : remainingForRecoveredVerification < 6_500
            ? 4
            : 6;
        const recoveryCandidates = selectDiverseSearchResults(
          pruneKnownOverBudgetBeforeVerification(recoveredResults, parsed),
          recoveryLimit,
          parsed
        );
        if (recoveryCandidates.length > 0) {
          const recoveredOffers = await verifyOffers(
            recoveryCandidates, parsed, hardDeadlineAt, staticReferenceCandidates,
            prefetchedExactModelStaticProofPromise
          );
          offers = [...offers, ...recoveredOffers];
        }
      }
    } else if (recoveryNeeded) {
      console.log("[AIShopping] V34.CORE120 zero-result recovery skipped: preserving verifier reserve", {
        globalRemainingMs: remainingForRecovery,
        searchRemainingMs: remainingForRecoverySearch,
        preservedVerificationMs: ZERO_RESULT_RECOVERED_VERIFICATION_RESERVE_MS,
      });
    }

    // CORE52: a successful marketplace first wave used to suppress ALL late
    // first-party recovery. That satisfies "find something" but can miss a
    // materially cheaper specialist-store offer while 5-8 seconds remain.
    // Run one bounded first-party-only price-coverage lane only when ordinary
    // zero-result/originality recovery is not needed, primary retailer coverage
    // is still below target, and the hard deadline can preserve verification.
    const postRecoveryScored = scoreAndRankOffers(
      deduplicateOffers(offers, parsed),
      parsed
    );
    const remainingForPriceCoverage = Math.max(
      0,
      hardDeadlineAt - Date.now() - RESPONSE_SAFETY_MARGIN_MS
    );

    if (
      !recoveryNeeded &&
      shouldRunLateFirstPartyPriceOptimization(
        postRecoveryScored,
        parsed,
        searchResults,
        remainingForPriceCoverage
      )
    ) {
      const priceCoverageResults = await searchLateFirstPartyPriceOptimization(
        parsed,
        hardDeadlineAt,
        searchResults,
        postRecoveryScored
      );

      if (priceCoverageResults.length > 0) {
        const priceCoverageCandidates = selectDiverseSearchResults(
          pruneKnownOverBudgetBeforeVerification(priceCoverageResults, parsed),
          remainingForPriceCoverage < 6_500 ? 4 : 6,
          parsed
        );

        if (priceCoverageCandidates.length > 0) {
          const priceCoverageOffers = await verifyOffers(
            priceCoverageCandidates,
            parsed,
            hardDeadlineAt,
            staticReferenceCandidates,
            prefetchedExactModelStaticProofPromise
          );
          offers = [...offers, ...priceCoverageOffers];
        }
      }
    }

    offers = deduplicateOffers(offers, parsed);
    offers = scoreAndRankOffers(offers, parsed);
    // CORE181: canonicalize only the merchant display after verification and
    // ranking. This merges cosmetic aliases without creating/trusting offers.
    offers = offers.map(canonicalizeOfferStoreDisplayV34Core181);

    console.log("[AIShopping] V34.CORE120 coverage final:", {
      verifiedOffers: offers.length,
      uniqueStores: new Set(offers.map((offer) => normalizeOfferStoreKey(offer))).size,
      stores: Object.fromEntries(
        offers.reduce((map, offer) => {
          const store = offer.store || "unknown";
          map.set(store, (map.get(store) ?? 0) + 1);
          return map;
        }, new Map<string, number>())
      ),
      priceVerified: offers.filter((offer) => offer.priceVerified).length,
      lowRisk: offers.filter((offer) => offer.riskLevel === "low").length,
    });

    // Nadajemy stabilne ID dopiero po końcowym rankingu V21.
    offers = offers
      .slice(0, MAX_FINAL_OFFERS)
      .map((offer, index) => ({
        ...offer,
        id: index + 1,
      }));

    const cleanOffers = offers.map((offer) => {
      const { relevance, ...cleanOffer } = offer;
      return cleanOffer;
    });

    console.log(
      "[AIShopping] final offers:",
      cleanOffers.length
    );

    console.log(
      "[AIShopping] V34.CORE120 orchestrator: multi-store discovery + bound Product/Offer + deadline-aware verification"
    );

    console.log(
      "[AIShopping] V34.CORE120 final stores:",
      Object.fromEntries(
        cleanOffers.reduce((map, offer) => {
          map.set(
            offer.store,
            (map.get(offer.store) ?? 0) + 1
          );
          return map;
        }, new Map<string, number>())
      )
    );

    console.log(
      "[AIShopping] V34.CORE120 direct offer URLs:",
      cleanOffers.map((offer) => ({
        id: offer.id,
        store: offer.store,
        price: offer.price,
        url: offer.url,
      }))
    );

    const finalRetailerHealth = getRetailerRequestHealthBucket(parsed);
    console.log(
      "[AIShopping] V34.CORE120 source health:",
      finalRetailerHealth
        ? Object.fromEntries(
            [...finalRetailerHealth.hosts.entries()].map(([host, state]) => [
              host,
              {
                directAttempts: state.directAttempts,
                directHardFailures: state.directHardFailures,
                directBlockFailures: state.directBlockFailures,
                directSuccesses: state.directSuccesses,
                readerSuccesses: state.readerSuccesses,
                readerFailures: state.readerFailures,
                readerChallenges: state.readerChallenges,
                products: state.products,
                adapterTimedOut: state.adapterTimedOut,
                lastDirectStatus: state.lastDirectStatus,
                circuitBreakDirectCrawl: shouldCircuitBreakDirectRetailerCrawl(parsed, host),
              },
            ])
          )
        : {}
    );

    console.log(
      "[AIShopping] V34.CORE120 total time ms:",
      Date.now() - requestStartedAt
    );

    console.log(
      "[AIShopping] V34.CORE120 top offers:",
      cleanOffers.slice(0, 5).map((offer) => ({
        name: offer.name,
        price: offer.price,
        dealScore: offer.dealScore,
        riskLevel: offer.riskLevel,
        originalityConfidence:
          offer.originalityConfidence,
        bestOffer: offer.bestOffer,
        cheapestOffer: offer.cheapestOffer,
        safestOffer: offer.safestOffer,
      }))
    );

    const hasRecommendationQualityOffer = cleanOffers.some((offer) =>
      parsed.original !== true ||
      offer.originalityConfidence === "high" ||
      offer.originalityConfidence === "medium"
    );

    const resultStatus = cleanOffers.length > 0
      ? hasRecommendationQualityOffer
        ? "offers_found"
        : "offers_found_with_caution"
      : limitedResults.length > 0
        ? "no_matching_verified_offer"
        : "coverage_incomplete";

    return NextResponse.json({
      success: true,
      query,
      interpreted: {
        product: parsed.product,
        category: parsed.category,
        brand: parsed.brand,
        model: parsed.model,
        platform: parsed.platform,
        condition: parsed.condition,
        original: parsed.original,
        maxPrice: parsed.maxPrice,
        country: parsed.country,
        productPhrase: parsed.intent.productPhrase,
        requirements: parsed.intent.required.map((item) => ({
          key: item.key,
          label: item.label,
          value: item.value,
          hard: item.hard,
        })),
        forbiddenTerms: parsed.intent.forbiddenTerms,
        openWorld: parsed.intent.openWorld,
        normalizedQuery: parsed.intent.normalizedQuery,
        searchVariants: parsed.intent.searchVariants,
        intentConfidence: parsed.intent.confidence,
      },
      offers: cleanOffers,
      found: cleanOffers.length,
      resultStatus,
      coverage: {
        configuredCommerceDomains: getConfiguredCommerceDomains().length,
        discoveredCandidates: searchResults.length,
        verificationCandidates: limitedResults.length,
        verifiedPageOffers: cleanOffers.filter((offer) => offer.verificationTier === "page-verified").length,
        strongIndexOffers: cleanOffers.filter((offer) => offer.verificationTier === "strong-index").length,
      },
      message:
        cleanOffers.length > 0
          ? hasRecommendationQualityOffer
            ? "Znaleziono pasujące oferty."
            : "Znaleziono możliwe oferty, ale oryginalność nie jest wystarczająco potwierdzona."
          : limitedResults.length > 0
            ? "Znaleziono produkty, ale żadna zweryfikowana oferta nie spełnia wszystkich warunków."
            : "Nie udało się zdobyć wystarczającej liczby konkretnych ofert do weryfikacji.",
    });
  } catch (error) {
    console.error("[AIShopping] SEARCH API ERROR:", error);

    return NextResponse.json(
      {
        success: false,
        offers: [],
        found: 0,
        error: "Wystąpił błąd podczas wyszukiwania.",
      },
      { status: 500 }
    );
  }
}
